// ── CHRISTIANISME ──
// Sous-lexique de Sciences humaines & sociales. Vocabulaire descriptif, commun aux confessions sauf mention.
const terms_christianisme = [
  // Fondements
  {name:"Christianisme",        en:"Christianity",            cat:"fondements",   def:"Religion monothéiste fondée sur la vie, l'enseignement, la mort et la résurrection de Jésus de Nazareth, reconnu comme le Christ, Fils de Dieu. Première religion du monde par le nombre de fidèles (environ 2,4 milliards), divisée en catholicisme, orthodoxie et protestantisme.", ex:"Née en Judée au Ier siècle, religion de l'Empire romain à la fin du IVe", etymo:"Du grec khristianos, « partisan du Christ », nom d'abord donné aux disciples à Antioche (Actes 11, 26). Christ, du grec khristos, « oint », traduction de l'hébreu mashiah, messie."},
  {name:"Jésus",                en:"Jesus",                   cat:"fondements",   def:"Prédicateur juif de Galilée (v. 4 av. J.-C. – v. 30), crucifié à Jérusalem sous Ponce Pilate. Pour les chrétiens, il est le Christ annoncé par les prophètes, Dieu fait homme, mort et ressuscité pour le salut de l'humanité.", ex:"Naissance à Bethléem, vie à Nazareth, ministère public d'environ trois ans", etymo:"Du grec Iêsous, de l'hébreu Yeshua, forme abrégée de Yehoshua, « Dieu sauve »."},
  {name:"Christ",               en:"Christ",                  cat:"fondements",   def:"Titre donné à Jésus, signifiant « l'oint », c'est-à-dire le Messie : celui que Dieu a consacré et envoyé. « Jésus-Christ » n'est pas un nom de famille mais une profession de foi.", ex:"« Tu es le Christ, le Fils du Dieu vivant » (Matthieu 16, 16)", etymo:"Du grec khristos, « oint », de khriein, « oindre », traduisant l'hébreu mashiah (messie), l'onction d'huile consacrant rois et prêtres."},
  {name:"Dieu",                 en:"God",                     cat:"fondements",   def:"Être unique, créateur du monde, éternel et personnel, que les chrétiens confessent comme Père, Fils et Saint-Esprit. Il se révèle dans l'histoire d'Israël puis pleinement en Jésus.", ex:"« Je crois en un seul Dieu, le Père tout-puissant » (Credo)", etymo:"Du latin deus, apparenté au grec Zeus et au sanskrit deva, d'une racine indo-européenne signifiant « briller, ciel lumineux »."},
  {name:"Trinité",              en:"Trinity",                 cat:"fondements",   def:"Doctrine centrale : un seul Dieu en trois personnes, le Père, le Fils et le Saint-Esprit, égales et distinctes, d'une même substance. Formulée aux conciles de Nicée (325) et Constantinople (381).", ex:"Le signe de croix : « Au nom du Père, et du Fils, et du Saint-Esprit »", etymo:"Du latin trinitas, « triade, groupe de trois », terme forgé par Tertullien vers 200."},
  {name:"Saint-Esprit",         en:"Holy Spirit",             cat:"fondements",   def:"Troisième personne de la Trinité, souffle et présence agissante de Dieu, donné aux croyants depuis la Pentecôte. Il inspire les Écritures, sanctifie et unit l'Église.", ex:"Représenté par une colombe, des langues de feu, le vent", etymo:"Esprit, du latin spiritus, « souffle », traduisant le grec pneuma et l'hébreu ruah, « vent, souffle »."},
  {name:"Évangile",             en:"Gospel",                  cat:"fondements",   def:"Au singulier, la « bonne nouvelle » du salut en Jésus-Christ ; au pluriel, les quatre livres qui racontent sa vie et son enseignement : Matthieu, Marc, Luc, Jean.", ex:"Les trois premiers, dits synoptiques, se recoupent ; Jean est à part", etymo:"Du grec euangelion, « bonne nouvelle » : eu (bien) + angelia (message). Même racine que ange, « messager »."},
  {name:"Salut",                en:"Salvation",               cat:"fondements",   def:"Délivrance du péché et de la mort offerte par Dieu à travers le Christ, et vie éternelle avec lui. Le cœur de la foi chrétienne : l'humanité est sauvée, non par ses mérites, mais par grâce.", ex:"Le nom même de Jésus signifie « Dieu sauve »", etymo:"Du latin salus, « santé, conservation », de salvus, « sain et sauf »."},
  {name:"Foi",                  en:"Faith",                   cat:"fondements",   def:"Adhésion confiante à Dieu et à sa révélation, à la fois don de Dieu et acte libre de la personne. Avec l'espérance et la charité, l'une des trois vertus théologales.", ex:"« La foi est une façon de posséder ce qu'on espère » (Hébreux 11, 1)", etymo:"Du latin fides, « confiance, loyauté », de la racine de fidere, « se fier »."},
  {name:"Croix",                en:"Cross",                   cat:"fondements",   def:"Instrument du supplice de Jésus, devenu le symbole central du christianisme : signe de la mort acceptée par amour et de la victoire sur la mort par la résurrection.", ex:"Crucifix (avec le corps du Christ) chez les catholiques, croix nue chez les protestants, croix à trois traverses chez les orthodoxes", etymo:"Du latin crux, « gibet, potence », instrument romain d'exécution réservé aux esclaves et aux rebelles."},

  // Écritures
  {name:"Bible",                en:"Bible",                   cat:"ecriture",     def:"Ensemble des livres tenus pour inspirés par Dieu, en deux parties : l'Ancien Testament (hérité du judaïsme) et le Nouveau Testament (Évangiles, Actes, Épîtres, Apocalypse). Livre le plus traduit et diffusé au monde.", ex:"73 livres pour les catholiques, 66 pour les protestants, 76 pour les orthodoxes", etymo:"Du grec ta biblia, « les livres », pluriel de biblion, de bublos, le papyrus, d'après le port phénicien de Byblos qui l'exportait."},
  {name:"Ancien Testament",     en:"Old Testament",           cat:"ecriture",     def:"Première partie de la Bible, correspondant à la Bible hébraïque : Pentateuque (Torah), livres historiques, sapientiaux et prophétiques. Les chrétiens y lisent la préparation de la venue du Christ.", ex:"Genèse, Exode, Psaumes, Isaïe", etymo:"Testament, du latin testamentum, traduisant le grec diathêkê et l'hébreu berit, « alliance » : le mot désigne l'alliance de Dieu avec son peuple, pas un legs."},
  {name:"Nouveau Testament",    en:"New Testament",           cat:"ecriture",     def:"Seconde partie de la Bible, 27 livres écrits en grec au Ier siècle : quatre Évangiles, Actes des Apôtres, 21 Épîtres, Apocalypse. Témoignage sur Jésus et les premières communautés.", ex:"Rédigé entre 50 (première lettre de Paul) et 100 environ", etymo:"Testament, du latin testamentum, traduisant le grec diathêkê, « alliance ». Nouveau : l'alliance nouvelle annoncée par Jérémie et scellée par le Christ."},
  {name:"Épître",               en:"Epistle",                 cat:"ecriture",     def:"Lettre d'un apôtre à une communauté ou une personne, intégrée au Nouveau Testament. Treize portent le nom de Paul ; les autres sont attribuées à Pierre, Jean, Jacques, Jude.", ex:"Épître aux Romains, première aux Corinthiens (« l'hymne à la charité »)", etymo:"Du grec epistolê, « message envoyé », de epistellein, « envoyer à »."},
  {name:"Apocalypse",           en:"Book of Revelation",      cat:"ecriture",     def:"Dernier livre de la Bible, attribué à Jean, vision symbolique du combat final entre le bien et le mal et de la Jérusalem céleste. Le mot signifie « révélation », pas « catastrophe ».", ex:"Les quatre cavaliers, la bête au chiffre 666, la Jérusalem nouvelle", etymo:"Du grec apokalupsis, « dévoilement, révélation » : apo (loin de) + kaluptein (couvrir). Le sens de « fin du monde » est dérivé."},
  {name:"Parabole",             en:"Parable",                 cat:"ecriture",     def:"Court récit imagé par lequel Jésus enseigne, tiré de la vie quotidienne, dont le sens dépasse l'histoire racontée.", ex:"Le bon Samaritain, le fils prodigue, le semeur, les talents", etymo:"Du grec parabolê, « comparaison, rapprochement » : para (à côté) + ballein (jeter)."},
  {name:"Décalogue",            en:"Ten Commandments",        cat:"ecriture",     def:"Les dix commandements donnés par Dieu à Moïse au Sinaï (Exode 20), fondement de la morale juive et chrétienne : devoirs envers Dieu, puis envers le prochain.", ex:"« Tu ne tueras pas », « Honore ton père et ta mère »", etymo:"Du grec deka logoi, « dix paroles »."},
  {name:"Béatitudes",           en:"Beatitudes",              cat:"ecriture",     def:"Huit sentences ouvrant le Sermon sur la montagne (Matthieu 5), où Jésus déclare heureux les pauvres de cœur, les doux, les affligés, les artisans de paix… Renversement des valeurs du monde.", ex:"« Heureux les artisans de paix, car ils seront appelés fils de Dieu »", etymo:"Du latin beatitudo, « bonheur », de beatus, « heureux », premier mot de chaque sentence dans la Vulgate."},
  {name:"Canon biblique",       en:"Biblical Canon",          cat:"ecriture",     def:"Liste officielle des livres reconnus comme inspirés. Fixée progressivement jusqu'au IVe siècle ; les protestants écartent sept livres de l'Ancien Testament (deutérocanoniques) que gardent catholiques et orthodoxes.", ex:"Tobie, Judith, Maccabées, Sagesse : présents dans une Bible catholique, absents d'une Bible protestante", etymo:"Du grec kanôn, « règle, mesure », d'abord le roseau servant de règle."},
  {name:"Vulgate",              en:"Vulgate",                 cat:"ecriture",     def:"Traduction latine de la Bible réalisée par Jérôme à la fin du IVe siècle, texte de référence de l'Église d'Occident pendant plus de mille ans.", ex:"Base des liturgies et de l'art médiéval ; « Fiat lux »", etymo:"Du latin vulgata (editio), « édition répandue, commune », de vulgus, « le peuple »."},
  {name:"Exégèse",              en:"Exegesis",                cat:"ecriture",     def:"Étude et interprétation méthodique des textes bibliques : langue, contexte historique, genre littéraire, sens.", ex:"Lecture historico-critique, lecture typologique, lecture spirituelle", etymo:"Du grec exêgêsis, « explication, interprétation », de exêgeisthai, « conduire hors de, expliquer »."},

  // Théologie
  {name:"Incarnation",          en:"Incarnation",             cat:"theologie",    def:"Doctrine selon laquelle le Fils de Dieu s'est fait homme en Jésus, vrai Dieu et vrai homme, sans confusion ni séparation (concile de Chalcédoine, 451).", ex:"« Et le Verbe s'est fait chair » (Jean 1, 14)", etymo:"Du latin incarnatio, de in (dans) + caro, carnis (chair) : prise de chair."},
  {name:"Résurrection",         en:"Resurrection",            cat:"theologie",    def:"Retour à la vie de Jésus le troisième jour après sa mort, fondement de la foi chrétienne ; et, à la fin des temps, relèvement de tous les morts. « Si le Christ n'est pas ressuscité, notre foi est vaine » (Paul).", ex:"Célébrée à Pâques, et chaque dimanche", etymo:"Du latin resurrectio, de resurgere, « se relever » : re- + surgere (se lever)."},
  {name:"Rédemption",           en:"Redemption",              cat:"theologie",    def:"Rachat de l'humanité par le Christ, dont la mort et la résurrection libèrent du péché. Le Christ est appelé Rédempteur.", ex:"Le Christ Rédempteur de Rio de Janeiro", etymo:"Du latin redemptio, « rachat » (d'un esclave, d'un captif), de redimere : re- + emere (acheter)."},
  {name:"Péché",                en:"Sin",                     cat:"theologie",    def:"Acte, parole ou pensée qui rompt la relation avec Dieu et le prochain. Le péché originel désigne la condition blessée de l'humanité depuis la faute d'Adam, transmise à tous.", ex:"Péché mortel et véniel (catholicisme), les sept péchés capitaux", etymo:"Du latin peccatum, « faute, erreur », de peccare, « faire un faux pas »."},
  {name:"Grâce",                en:"Grace",                   cat:"theologie",    def:"Don gratuit de Dieu, qui sauve, pardonne et transforme sans que l'homme puisse le mériter. Le rôle respectif de la grâce et des œuvres a divisé catholiques et protestants.", ex:"« Sola gratia », par la grâce seule (Réforme)", etymo:"Du latin gratia, « faveur, reconnaissance », de gratus, « agréable, reconnaissant »."},
  {name:"Dogme",                en:"Dogma",                   cat:"theologie",    def:"Vérité de foi définie solennellement par l'Église comme révélée par Dieu et tenue pour certaine. Les dogmes sont peu nombreux et fixés par les conciles ou le pape.", ex:"Trinité, Incarnation, Immaculée Conception (1854), Assomption (1950)", etymo:"Du grec dogma, « opinion, décret », de dokein, « sembler bon »."},
  {name:"Hérésie",              en:"Heresy",                  cat:"theologie",    def:"Doctrine jugée contraire à la foi définie par l'Église, et sa défense obstinée. Les grandes hérésies anciennes ont conduit à préciser les dogmes.", ex:"Arianisme (le Fils n'est pas Dieu), nestorianisme, pélagianisme", etymo:"Du grec hairesis, « choix, école de pensée », de hairein, « choisir ». Sens péjoratif à partir du IIe siècle."},
  {name:"Eschatologie",         en:"Eschatology",             cat:"theologie",    def:"Partie de la théologie traitant des fins dernières : mort, jugement, résurrection, vie éternelle, retour du Christ, royaume de Dieu.", ex:"Paradis, enfer, purgatoire (catholicisme), Jugement dernier", etymo:"Du grec eskhatos, « dernier », et logos, « discours »."},
  {name:"Royaume de Dieu",      en:"Kingdom of God",          cat:"theologie",    def:"Cœur de la prédication de Jésus : règne de Dieu déjà commencé parmi les hommes et à venir dans sa plénitude, où justice, paix et amour l'emportent.", ex:"« Que ton règne vienne » (Notre Père), les paraboles du Royaume", etymo:"Royaume, du latin regimen, « direction », croisé avec roi (rex). Traduit le grec basileia tou theou, « règne de Dieu »."},
  {name:"Vertus théologales",   en:"Theological Virtues",     cat:"theologie",    def:"Foi, espérance et charité : les trois dispositions données par Dieu qui orientent la vie chrétienne vers lui. S'ajoutent aux quatre vertus cardinales (prudence, justice, force, tempérance).", ex:"« Ces trois-là demeurent, mais la plus grande est la charité » (1 Corinthiens 13)", etymo:"Théologal, du grec theos (Dieu) + logos : qui a Dieu pour objet."},
  {name:"Théologie",            en:"Theology",                cat:"theologie",    def:"Étude rationnelle de Dieu et de la foi à partir de la Révélation. Discipline universitaire depuis le Moyen Âge.", ex:"Augustin, Thomas d'Aquin, Luther, Barth, Rahner", etymo:"Du grec theologia, « discours sur les dieux » : theos (dieu) + logos (discours). Employé par Platon et Aristote avant les chrétiens."},

  // Confessions
  {name:"Catholicisme",         en:"Catholicism",             cat:"confessions",  def:"Branche la plus nombreuse du christianisme (1,3 milliard), en communion avec le pape, évêque de Rome. Sept sacrements, culte de Marie et des saints, tradition aux côtés de l'Écriture.", ex:"Église catholique romaine, Églises catholiques orientales", etymo:"Du grec katholikos, « universel » : kata (selon) + holos (tout). Ignace d'Antioche parle d'« Église catholique » vers 110."},
  {name:"Orthodoxie",           en:"Eastern Orthodoxy",       cat:"confessions",  def:"Branche issue de la séparation de 1054 entre Rome et Constantinople, majoritaire en Grèce, Russie, Europe de l'Est. Églises nationales autocéphales, liturgie byzantine, icônes, primauté d'honneur du patriarche de Constantinople.", ex:"Patriarcats de Constantinople, Moscou, Antioche ; Église grecque, roumaine, serbe", etymo:"Du grec orthodoxos, « qui pense droitement » : orthos (droit) + doxa (opinion, gloire)."},
  {name:"Protestantisme",       en:"Protestantism",           cat:"confessions",  def:"Ensemble des Églises nées de la Réforme du XVIe siècle (Luther, Calvin, Zwingli) : autorité de l'Écriture seule, salut par la grâce seule, sacerdoce de tous les croyants, deux sacrements, refus de l'autorité du pape.", ex:"Luthériens, réformés, anglicans, baptistes, méthodistes, évangéliques, pentecôtistes", etymo:"De la « protestation » des princes luthériens à la diète de Spire (1529) contre la restriction de leur liberté religieuse."},
  {name:"Anglicanisme",         en:"Anglicanism",             cat:"confessions",  def:"Église d'Angleterre et Églises sœurs (Communion anglicane), séparées de Rome sous Henri VIII (1534), à mi-chemin entre catholicisme (évêques, liturgie) et protestantisme (doctrine).", ex:"Archevêque de Canterbury, Book of Common Prayer, Église épiscopalienne aux États-Unis", etymo:"Du latin médiéval anglicanus, « d'Angleterre »."},
  {name:"Évangélisme",          en:"Evangelicalism",          cat:"confessions",  def:"Courant protestant mettant l'accent sur la conversion personnelle, l'autorité de la Bible, la mission et une piété vivante. En forte croissance en Afrique, Amérique latine et Asie.", ex:"Baptistes, Assemblées de Dieu, méga-églises américaines", etymo:"De évangile, du grec euangelion, « bonne nouvelle »."},
  {name:"Pentecôtisme",         en:"Pentecostalism",          cat:"confessions",  def:"Mouvement évangélique né en 1906 à Los Angeles (Azusa Street), centré sur l'expérience du Saint-Esprit : parler en langues, guérisons, louange expressive. Plusieurs centaines de millions de fidèles.", ex:"Assemblées de Dieu, Église universelle du royaume de Dieu", etymo:"De Pentecôte, jour où l'Esprit descend sur les apôtres (Actes 2)."},
  {name:"Œcuménisme",           en:"Ecumenism",               cat:"confessions",  def:"Mouvement de rapprochement entre les confessions chrétiennes en vue de l'unité, par le dialogue théologique, la prière commune et l'action partagée.", ex:"Conseil œcuménique des Églises (1948), Semaine de prière pour l'unité (janvier), Taizé", etymo:"Du grec oikoumenê (gê), « la terre habitée », de oikein, « habiter » : ce qui concerne le monde entier."},
  {name:"Schisme",              en:"Schism",                  cat:"confessions",  def:"Rupture de communion entre Églises, sans divergence de foi à l'origine, contrairement à l'hérésie. Le Grand Schisme de 1054 sépare Orient et Occident.", ex:"1054 (Rome/Constantinople), Grand Schisme d'Occident (1378-1417, deux puis trois papes)", etymo:"Du grec skhisma, « fente, division », de skhizein, « fendre »."},

  // Sacrements
  {name:"Sacrement",            en:"Sacrament",               cat:"sacrements",   def:"Rite institué par le Christ, signe visible d'une grâce invisible. Sept pour catholiques et orthodoxes (baptême, confirmation, eucharistie, pénitence, onction des malades, ordre, mariage), deux pour les protestants (baptême, cène).", ex:"L'eau du baptême, le pain et le vin de l'eucharistie", etymo:"Du latin sacramentum, « serment » (du soldat), puis « chose sacrée », traduisant le grec mustêrion, « mystère »."},
  {name:"Baptême",              en:"Baptism",                 cat:"sacrements",   def:"Premier sacrement, par l'eau, qui fait entrer dans l'Église, efface le péché et unit au Christ. Donné aux nourrissons (catholiques, orthodoxes, luthériens) ou aux seuls croyants adultes (baptistes, évangéliques).", ex:"Par immersion ou par aspersion, « au nom du Père, du Fils et du Saint-Esprit »", etymo:"Du grec baptisma, « immersion », de baptein, « plonger »."},
  {name:"Eucharistie",          en:"Eucharist",               cat:"sacrements",   def:"Sacrement central, mémorial du dernier repas de Jésus : le pain et le vin consacrés deviennent (catholiques, orthodoxes) ou signifient (protestants) le corps et le sang du Christ. Aussi appelée communion, cène, messe.", ex:"« Ceci est mon corps… faites ceci en mémoire de moi »", etymo:"Du grec eukharistia, « action de grâce » : eu (bien) + kharis (grâce)."},
  {name:"Confirmation",         en:"Confirmation",            cat:"sacrements",   def:"Sacrement qui achève le baptême par le don de l'Esprit, marqué d'une onction de saint chrême par l'évêque. Chez les orthodoxes (chrismation), il suit immédiatement le baptême.", ex:"Vers 12-16 ans chez les catholiques", etymo:"Du latin confirmatio, « affermissement », de firmus, « solide »."},
  {name:"Pénitence",            en:"Penance / Confession",    cat:"sacrements",   def:"Sacrement du pardon : le fidèle confesse ses péchés à un prêtre, qui donne l'absolution au nom du Christ. Aussi appelé réconciliation ou confession.", ex:"Confessionnal, secret absolu de la confession", etymo:"Du latin paenitentia, « regret, repentir », de paenitere, « se repentir »."},
  {name:"Onction des malades",  en:"Anointing of the Sick",   cat:"sacrements",   def:"Sacrement de réconfort et de guérison pour les malades et les mourants, par onction d'huile. Longtemps appelé extrême-onction.", ex:"« L'un de vous est malade ? Qu'il appelle les anciens de l'Église » (Jacques 5)", etymo:"Onction, du latin unctio, de ungere, « oindre »."},
  {name:"Ordre",                en:"Holy Orders",             cat:"sacrements",   def:"Sacrement qui consacre diacres, prêtres et évêques par l'imposition des mains, pour le service de l'Église. Réservé aux hommes dans le catholicisme et l'orthodoxie.", ex:"Ordination sacerdotale, ordination épiscopale", etymo:"Du latin ordo, « rang, classe » : le rang des clercs."},
  {name:"Mariage chrétien",              en:"Christian Marriage",    cat:"sacrements",   def:"Sacrement par lequel un homme et une femme s'engagent l'un envers l'autre pour la vie devant Dieu ; ce sont les époux qui se le donnent, le prêtre en est le témoin. Indissoluble pour l'Église catholique.", ex:"Consentement échangé, alliances bénies", etymo:"Du latin maritare, de maritus, « époux »."},

  // Liturgie & Prière
  {name:"Messe",                en:"Mass",                    cat:"liturgie",     def:"Célébration catholique de l'eucharistie, en deux parties : liturgie de la Parole (lectures, homélie) et liturgie eucharistique (consécration, communion). Les orthodoxes disent « divine liturgie », les protestants « culte ».", ex:"Messe dominicale, messe de minuit à Noël", etymo:"Du latin missa, du renvoi final Ite, missa est, « allez, c'est l'envoi », de mittere, « envoyer »."},
  {name:"Liturgie",             en:"Liturgy",                 cat:"liturgie",     def:"Ensemble des rites et prières du culte public de l'Église, réglés par des livres officiels. Elle rythme l'année et la journée.", ex:"Liturgie romaine, byzantine, liturgie des heures (prière des moines)", etymo:"Du grec leitourgia, « service public » : leitos (public) + ergon (œuvre)."},
  {name:"Notre Père",           en:"Lord's Prayer",           cat:"liturgie",     def:"Prière enseignée par Jésus lui-même (Matthieu 6), commune à tous les chrétiens : sept demandes, à Dieu comme Père.", ex:"« Notre Père qui es aux cieux, que ton nom soit sanctifié… »", etymo:"En latin Pater noster, d'où « patenôtre » et le chapelet (patenôtres)."},
  {name:"Credo",                en:"Creed",                   cat:"liturgie",     def:"Profession de foi récitée à la messe, résumant les dogmes : Symbole des apôtres (court, ancien) ou Symbole de Nicée-Constantinople (381), commun à presque toutes les Églises.", ex:"« Je crois en Dieu, le Père tout-puissant, créateur du ciel et de la terre… »", etymo:"Latin credo, « je crois », premier mot du texte."},
  {name:"Homélie",              en:"Homily / Sermon",         cat:"liturgie",     def:"Commentaire des lectures bibliques prononcé par le prêtre ou le pasteur pendant la célébration, pour en tirer un enseignement.", ex:"Le sermon protestant est souvent plus long et central", etymo:"Du grec homilia, « réunion, entretien familier », de homilos, « assemblée »."},
  {name:"Chapelet",             en:"Rosary",                  cat:"liturgie",     def:"Prière catholique répétitive sur un collier de grains : cinq dizaines de « Je vous salue Marie » entre des « Notre Père », en méditant des épisodes de la vie du Christ (mystères). Le rosaire en compte quatre chapelets.", ex:"Prié à Lourdes, en famille, en procession", etymo:"Diminutif de chapel, « couronne de fleurs » (chapeau), le rosaire étant une « couronne de roses » offerte à Marie."},
  {name:"Prière",               en:"Prayer",                  cat:"liturgie",     def:"Dialogue avec Dieu : louange, demande, action de grâce, intercession, silence. Personnelle ou communautaire, parlée, chantée ou intérieure.", ex:"Prière du matin et du soir, bénédicité, adoration", etymo:"Du latin precaria, « obtenue par prière », de precari, « prier, supplier »."},
  {name:"Icône",                en:"Icon",                    cat:"liturgie",     def:"Image sacrée peinte sur bois selon des règles fixes, centrale dans l'orthodoxie : on ne l'adore pas, on la vénère, comme une fenêtre sur le divin. La querelle iconoclaste (VIIIe-IXe siècles) en a fixé la théologie.", ex:"Trinité de Roublev, Vierge de Vladimir, iconostase", etymo:"Du grec eikôn, « image, portrait »."},

  // Fêtes & Calendrier
  {name:"Noël",                 en:"Christmas",               cat:"fetes",        def:"Fête de la naissance de Jésus, le 25 décembre (7 janvier pour les orthodoxes suivant le calendrier julien). Précédée de l'Avent, quatre semaines de préparation.", ex:"Messe de minuit, crèche, Nativité", etymo:"Du latin natalis (dies), « jour de naissance ». La date, fixée au IVe siècle, coïncide avec le solstice et la fête romaine du Soleil invaincu."},
  {name:"Pâques",               en:"Easter",                  cat:"fetes",        def:"Fête de la résurrection du Christ, la plus importante de l'année chrétienne, le dimanche qui suit la première pleine lune de printemps (entre le 22 mars et le 25 avril). Précédée du Carême et de la Semaine sainte.", ex:"Vigile pascale, cierge pascal, « Christ est ressuscité ! »", etymo:"Du latin pascha, du grec, de l'hébreu pessah, « passage » : la Pâque juive commémore la sortie d'Égypte, la Pâque chrétienne le passage de la mort à la vie."},
  {name:"Carême",               en:"Lent",                    cat:"fetes",        def:"Quarante jours de jeûne, de prière et de partage avant Pâques, du mercredi des Cendres au Jeudi saint, en mémoire des quarante jours de Jésus au désert.", ex:"Cendres sur le front, vendredi sans viande, efforts de Carême", etymo:"Du latin quadragesima (dies), « quarantième » jour avant Pâques."},
  {name:"Semaine sainte",       en:"Holy Week",               cat:"fetes",        def:"Dernière semaine du Carême, des Rameaux (entrée à Jérusalem) au Samedi saint, avec le Jeudi saint (dernier repas), le Vendredi saint (crucifixion) et la veillée pascale.", ex:"Chemin de croix du Vendredi saint, lavement des pieds du Jeudi saint", etymo:"Semaine, du latin septimana, « (période) de sept (jours) ». Sainte, du latin sanctus, « consacré »."},
  {name:"Pentecôte",            en:"Pentecost",               cat:"fetes",        def:"Cinquante jours après Pâques, fête de la descente du Saint-Esprit sur les apôtres, considérée comme la naissance de l'Église. Clôt le temps pascal.", ex:"Langues de feu, apôtres parlant toutes les langues (Actes 2)", etymo:"Du grec pentêkostê (hêmera), « cinquantième » jour."},
  {name:"Ascension",            en:"Ascension",               cat:"fetes",        def:"Quarante jours après Pâques, un jeudi, fête de la montée du Christ ressuscité au ciel, fin de sa présence visible sur terre.", ex:"Jour férié en France", etymo:"Du latin ascensio, de ascendere, « monter »."},
  {name:"Épiphanie",            en:"Epiphany",                cat:"fetes",        def:"Le 6 janvier (ou le dimanche proche), manifestation de Jésus aux nations, avec la visite des mages. En Orient, fête aussi du baptême du Christ.", ex:"Galette des rois, les rois mages Melchior, Gaspard, Balthazar", etymo:"Du grec epiphaneia, « apparition, manifestation », de phainein, « apparaître »."},
  {name:"Toussaint",            en:"All Saints' Day",         cat:"fetes",        def:"Le 1er novembre, fête de tous les saints, connus et inconnus. Suivie le 2 novembre de la commémoration des défunts, d'où la visite des cimetières.", ex:"Chrysanthèmes sur les tombes, vacances de la Toussaint", etymo:"Contraction de « tous les saints »."},
  {name:"Avent",                en:"Advent",                  cat:"fetes",        def:"Quatre semaines de préparation à Noël, début de l'année liturgique, dans l'attente de la venue du Christ.", ex:"Couronne à quatre bougies, calendrier de l'Avent", etymo:"Du latin adventus, « venue, arrivée », de advenire. Sans rapport avec « avant »."},
  {name:"Dimanche",             en:"Sunday",                  cat:"fetes",        def:"Jour du Seigneur, premier jour de la semaine, mémorial hebdomadaire de la résurrection, jour de l'assemblée et du repos. Il remplace le sabbat juif.", ex:"Messe ou culte dominical, repos dominical", etymo:"Du latin dies dominicus, « jour du Seigneur » (dominus)."},

  // Église & Institutions
  {name:"Église",               en:"Church",                  cat:"institution",  def:"Avec une majuscule, la communauté de tous les chrétiens, « corps du Christ » ; avec une minuscule, le bâtiment du culte. Aussi chacune des confessions (Église catholique, Églises orthodoxes).", ex:"Nef, chœur, autel, clocher ; cathédrale (siège de l'évêque), basilique, chapelle", etymo:"Du grec ekklêsia, « assemblée » (des citoyens), de ekkalein, « convoquer », traduisant l'hébreu qahal."},
  {name:"Pape",                 en:"Pope",                    cat:"institution",  def:"Évêque de Rome, successeur de Pierre, chef de l'Église catholique et chef d'État du Vatican. Élu à vie par les cardinaux réunis en conclave.", ex:"François (2013-2025), Léon XIV ; fumée blanche", etymo:"Du grec pappas, « papa », terme affectueux donné aux évêques, réservé à celui de Rome en Occident dès le VIe siècle."},
  {name:"Évêque",               en:"Bishop",                  cat:"institution",  def:"Successeur des apôtres à la tête d'un diocèse, qui ordonne prêtres et diacres, confirme et enseigne. Les évêques réunis forment le collège épiscopal.", ex:"Archevêque (métropole), cardinal (électeur du pape), crosse et mitre", etymo:"Du grec episkopos, « surveillant, gardien » : epi (sur) + skopein (regarder)."},
  {name:"Prêtre",               en:"Priest",                  cat:"institution",  def:"Ministre ordonné qui célèbre la messe, donne les sacrements et dirige une paroisse (curé). Célibataire dans l'Église latine, souvent marié chez les orthodoxes. Le pasteur protestant n'est pas prêtre : il est un fidèle formé et reconnu.", ex:"Curé, vicaire, aumônier ; soutane, col romain", etymo:"Du grec presbuteros, « ancien », d'où aussi presbytère. Distinct de hiereus, le prêtre sacrificateur."},
  {name:"Diacre",               en:"Deacon",                  cat:"institution",  def:"Ministre ordonné pour le service : liturgie, parole, charité. Étape vers le sacerdoce, ou diaconat permanent ouvert aux hommes mariés depuis Vatican II.", ex:"Baptise, marie, prêche, mais ne célèbre pas la messe", etymo:"Du grec diakonos, « serviteur »."},
  {name:"Paroisse",             en:"Parish",                  cat:"institution",  def:"Communauté locale de fidèles autour d'une église et d'un curé, cellule de base de l'Église. Les paroisses forment un diocèse.", ex:"Registre des baptêmes, catéchisme paroissial", etymo:"Du grec paroikia, « séjour à l'étranger, voisinage », de paroikos, « voisin » : les chrétiens, étrangers en ce monde."},
  {name:"Diocèse",              en:"Diocese",                 cat:"institution",  def:"Territoire placé sous l'autorité d'un évêque, avec sa cathédrale. La France en compte une centaine.", ex:"Diocèse de Marseille, archidiocèse de Paris", etymo:"Du grec dioikêsis, « administration », circonscription de l'Empire romain reprise par l'Église."},
  {name:"Concile",              en:"Council",                 cat:"institution",  def:"Assemblée des évêques du monde entier, convoquée pour définir la foi ou réformer l'Église. Vingt et un conciles œcuméniques pour les catholiques, sept reconnus par les orthodoxes.", ex:"Nicée (325), Chalcédoine (451), Trente (1545-1563), Vatican II (1962-1965)", etymo:"Du latin concilium, « assemblée », de calare, « convoquer »."},
  {name:"Moine",                en:"Monk",                    cat:"institution",  def:"Homme (moniale pour une femme) qui se retire du monde pour vivre en communauté selon une règle, dans la prière, le travail et le silence. Les vœux : pauvreté, chasteté, obéissance.", ex:"Bénédictins (« prie et travaille »), cisterciens, chartreux ; abbaye, monastère", etymo:"Du grec monakhos, « solitaire », de monos, « seul »."},
  {name:"Ordre religieux",      en:"Religious Order",         cat:"institution",  def:"Institut de vie consacrée avec sa règle, son fondateur et sa mission : contemplation, prédication, enseignement, soin des pauvres.", ex:"Bénédictins (VIe s.), franciscains et dominicains (XIIIe), jésuites (1540), sœurs de la Charité", etymo:"Ordre, du latin ordo, « rang ». Religieux, de religio, « scrupule, lien sacré »."},
  {name:"Vatican",              en:"Vatican",                 cat:"institution",  def:"Plus petit État du monde (44 hectares), enclavé dans Rome, siège du pape et du gouvernement de l'Église catholique (la Curie). Créé en 1929 par les accords du Latran.", ex:"Basilique Saint-Pierre, chapelle Sixtine, place Saint-Pierre", etymo:"Du latin Vaticanus (mons), la colline où Pierre fut, selon la tradition, crucifié et enterré."},

  // Figures
  {name:"Marie",                en:"Mary",                    cat:"figures",      def:"Mère de Jésus, jeune femme de Nazareth qui accueille l'annonce de l'ange. Vénérée comme Mère de Dieu (Theotokos, concile d'Éphèse, 431), figure de la foi ; le culte marial distingue catholiques et orthodoxes des protestants.", ex:"Annonciation, Assomption, Lourdes, Fatima, « Je vous salue Marie »", etymo:"Du grec Maria, de l'hébreu Miryam, sœur de Moïse ; sens discuté, peut-être « aimée » ou « rebelle »."},
  {name:"Apôtres",              en:"Apostles",                cat:"figures",      def:"Les douze disciples choisis par Jésus pour l'accompagner et porter son message, avec Pierre à leur tête ; puis Paul, « apôtre des nations ». Les évêques sont leurs successeurs.", ex:"Pierre, André, Jacques, Jean, Matthieu, Thomas, Judas (remplacé par Matthias)…", etymo:"Du grec apostolos, « envoyé », de apostellein, « envoyer au loin »."},
  {name:"Pierre",               en:"Peter",                   cat:"figures",      def:"Simon, pêcheur de Galilée, premier des apôtres, à qui Jésus donne le nom de Pierre et « les clés du Royaume ». Mort martyr à Rome vers 64 ; les papes se présentent comme ses successeurs.", ex:"« Tu es Pierre, et sur cette pierre je bâtirai mon Église » (Matthieu 16, 18)", etymo:"Du grec Petros, « pierre, rocher », traduisant l'araméen Kêpha (Céphas)."},
  {name:"Paul",                 en:"Paul",                    cat:"figures",      def:"Saul de Tarse, pharisien persécuteur des chrétiens, converti sur le chemin de Damas (v. 36). Missionnaire infatigable et auteur des premières épîtres, il ouvre le christianisme aux non-Juifs. Décapité à Rome vers 67.", ex:"Épîtres aux Romains, Corinthiens, Galates ; trois voyages missionnaires", etymo:"Du latin Paulus, « petit ». Il porte les deux noms, hébreu et romain, comme beaucoup de Juifs de la diaspora."},
  {name:"Saint",                en:"Saint",                   cat:"figures",      def:"Personne reconnue par l'Église comme ayant vécu l'Évangile de façon exemplaire et jouissant de la vie éternelle, proposée en modèle et en intercesseur. Le catholicisme la proclame par la canonisation.", ex:"Saint Augustin, sainte Thérèse de Lisieux, saint François d'Assise ; fête du saint patron", etymo:"Du latin sanctus, « consacré, inviolable », participe de sancire, « rendre sacré »."},
  {name:"Augustin",             en:"Augustine of Hippo",      cat:"figures",      def:"Évêque d'Hippone (354-430), le plus influent des Pères de l'Église en Occident : péché originel, grâce, cité de Dieu. Ses Confessions sont la première autobiographie.", ex:"« Tu nous as faits pour toi, et notre cœur est sans repos tant qu'il ne repose en toi »", etymo:"Du latin Augustinus, diminutif d'Augustus, « vénérable, consacré par les augures »."},
  {name:"Thomas d'Aquin",       en:"Thomas Aquinas",          cat:"figures",      def:"Dominicain (1225-1274), auteur de la Somme théologique, synthèse de la foi chrétienne et de la philosophie d'Aristote. Référence de la théologie catholique.", ex:"Les cinq voies pour prouver l'existence de Dieu", etymo:"Thomas, de l'araméen te'oma, « jumeau ». Aquin, de la ville d'Aquino, entre Rome et Naples, près de laquelle il est né."},
  {name:"Luther",               en:"Martin Luther",           cat:"figures",      def:"Moine augustin allemand (1483-1546) dont les 95 thèses contre les indulgences (1517) déclenchent la Réforme. Traduit la Bible en allemand, affirme le salut par la foi seule.", ex:"Wittenberg, diète de Worms (« Je ne puis autrement »)", etymo:"Du vieux haut allemand Liuthari, « armée du peuple » (liut, peuple + heri, armée). Luther latinisa d'abord son nom en Eleutherius, « le libre »."},
  {name:"François d'Assise",    en:"Francis of Assisi",       cat:"figures",      def:"Fils de marchand (1181-1226) qui renonce à tout pour vivre l'Évangile dans la pauvreté, fonde les franciscains, prêche aux oiseaux et compose le Cantique des créatures. Saint le plus populaire ; le pape François a pris son nom.", ex:"Crèche vivante de Greccio (1223), stigmates, patron de l'écologie", etymo:"François, du latin médiéval Franciscus, « le Français » : surnom donné par son père, marchand de draps en France, à son fils né Giovanni."},

  // Spiritualité & Vie chrétienne
  {name:"Charité",              en:"Charity / Love",          cat:"spiritualite", def:"Amour de Dieu et du prochain, la plus grande des vertus, qui se traduit en actes : nourrir, vêtir, visiter, pardonner. Le commandement central de Jésus.", ex:"« Aimez-vous les uns les autres comme je vous ai aimés »", etymo:"Du latin caritas, « cherté, affection », de carus, « cher », traduisant le grec agapê, l'amour désintéressé."},
  {name:"Conversion",           en:"Conversion",              cat:"spiritualite", def:"Retournement de la vie vers Dieu, changement de cœur et de conduite, initial ou renouvelé. Premier mot de la prédication de Jésus.", ex:"Paul sur le chemin de Damas, Augustin au jardin de Milan", etymo:"Du latin conversio, « action de se tourner », traduisant le grec metanoia, « changement d'esprit »."},
  {name:"Pardon",               en:"Forgiveness",             cat:"spiritualite", def:"Remise d'une offense, demandée à Dieu et accordée au prochain, sans limite (« soixante-dix fois sept fois »). Au cœur du Notre Père.", ex:"« Pardonne-nous nos offenses comme nous pardonnons aussi à ceux qui nous ont offensés »", etymo:"De par + donner : donner complètement."},
  {name:"Espérance",            en:"Hope",                    cat:"spiritualite", def:"Vertu théologale : confiance ferme que Dieu tiendra ses promesses, vie éternelle et royaume, qui soutient dans l'épreuve. Distincte de l'espoir, tourné vers les biens de ce monde.", ex:"L'ancre, symbole de l'espérance", etymo:"Du latin sperare, « espérer », de spes, « espoir »."},
  {name:"Vocation",             en:"Vocation",                cat:"spiritualite", def:"Appel de Dieu à une vie donnée : mariage, sacerdoce, vie religieuse, ou simplement à la sainteté dans son état. Chaque baptisé a une vocation.", ex:"Vocation sacerdotale, appel des premiers disciples", etymo:"Du latin vocatio, « appel », de vocare, « appeler »."},
  {name:"Pèlerinage",           en:"Pilgrimage",              cat:"spiritualite", def:"Voyage vers un lieu saint, démarche de foi, de pénitence ou de demande. Pratique de toutes les confessions, en essor.", ex:"Jérusalem, Rome, Saint-Jacques-de-Compostelle, Lourdes, Chartres", etymo:"Du latin peregrinus, « étranger, voyageur », de per ager, « à travers les champs »."},
  {name:"Jeûne",                en:"Fasting",                 cat:"spiritualite", def:"Privation volontaire de nourriture pour se tourner vers Dieu et faire place au partage. Prescrit le mercredi des Cendres et le Vendredi saint chez les catholiques, plus étendu chez les orthodoxes.", ex:"Carême, jeûne du vendredi", etymo:"Du latin jejunium, « abstinence », de jejunus, « à jeun »."},
  {name:"Martyr",               en:"Martyr",                  cat:"spiritualite", def:"Chrétien mis à mort pour sa foi. Les premiers siècles en comptent beaucoup sous les persécutions romaines ; le XXe siècle davantage encore.", ex:"Étienne (premier martyr), Blandine à Lyon (177), les moines de Tibhirine (1996)", etymo:"Du grec martus, « témoin » : le martyr témoigne de sa foi jusqu'au sang."},
  {name:"Catéchisme",           en:"Catechism",               cat:"spiritualite", def:"Enseignement des bases de la foi, aux enfants comme aux adultes ; aussi le livre qui l'expose par questions et réponses.", ex:"Catéchisme de l'Église catholique (1992), Petit catéchisme de Luther", etymo:"Du grec katêkhein, « faire retentir, instruire de vive voix » : kata (vers le bas) + êkhein (résonner), d'où écho."},

  // Histoire
  {name:"Église primitive",     en:"Early Church",            cat:"histoire",     def:"Communautés chrétiennes des trois premiers siècles, de la Pentecôte à la fin des persécutions : diffusion dans l'Empire romain, rédaction du Nouveau Testament, premiers martyrs, catacombes.", ex:"Jérusalem, Antioche, Rome, Alexandrie ; Actes des Apôtres", etymo:"Primitif, du latin primitivus, « qui naît le premier », de primus."},
  {name:"Édit de Milan",        en:"Edict of Milan",          cat:"histoire",     def:"Décision de l'empereur Constantin (313) accordant la liberté de culte aux chrétiens et mettant fin aux persécutions. En 380, Théodose fait du christianisme la religion de l'Empire.", ex:"Constantin, premier empereur chrétien, fonde Constantinople (330)", etymo:"Édit, du latin edictum, « proclamation », de edicere, « dire publiquement ». Milan, du latin Mediolanum, « au milieu de la plaine »."},
  {name:"Concile de Nicée",     en:"Council of Nicaea",       cat:"histoire",     def:"Premier concile œcuménique (325), convoqué par Constantin, qui condamne l'arianisme et proclame le Fils « de même substance » que le Père. Origine du Credo.", ex:"318 évêques selon la tradition ; fixe aussi la date de Pâques", etymo:"Concile, du latin concilium, « assemblée ». Nicée, aujourd'hui Iznik en Turquie, du grec Nikaia, « la victorieuse » (nikê)."},
  {name:"Schisme de 1054",      en:"East-West Schism",        cat:"histoire",     def:"Rupture entre l'Église de Rome et celle de Constantinople, après des siècles d'éloignement (langue, primauté du pape, Filioque). Naissance de la distinction catholiques/orthodoxes. Excommunications levées en 1965.", ex:"Le cardinal Humbert dépose la bulle d'excommunication sur l'autel de Sainte-Sophie", etymo:"Schisme, du grec skhisma, « fente, division », de skhizein, « fendre »."},
  {name:"Croisades",            en:"Crusades",                cat:"histoire",     def:"Expéditions militaires (1095-1291) prêchées par les papes pour reprendre Jérusalem et les Lieux saints aux musulmans. Huit croisades, des royaumes latins éphémères, un lourd héritage.", ex:"Prise de Jérusalem (1099), sac de Constantinople par les croisés (1204)", etymo:"De croix : les croisés cousaient une croix d'étoffe sur leur vêtement."},
  {name:"Réforme",              en:"Reformation",             cat:"histoire",     def:"Mouvement du XVIe siècle qui, voulant réformer l'Église, aboutit à la naissance du protestantisme : Luther (1517), Zwingli, Calvin à Genève, Henri VIII en Angleterre. Guerres de religion en Europe.", ex:"95 thèses, traduction de la Bible, Saint-Barthélemy (1572), édit de Nantes (1598)", etymo:"Du latin reformatio, « remise en forme », de reformare."},
  {name:"Contre-Réforme",       en:"Counter-Reformation",     cat:"histoire",     def:"Réponse catholique à la Réforme : concile de Trente (1545-1563), qui précise la doctrine et réforme le clergé ; jésuites, séminaires, art baroque, missions.", ex:"Ignace de Loyola, Charles Borromée, Thérèse d'Avila", etymo:"Terme forgé par les historiens protestants allemands (Gegenreformation, 1776) ; les catholiques préfèrent « Réforme catholique »."},
  {name:"Vatican II",           en:"Second Vatican Council",  cat:"histoire",     def:"Concile (1962-1965) convoqué par Jean XXIII pour ouvrir l'Église au monde moderne : messe en langue courante, dialogue œcuménique et interreligieux, liberté religieuse, rôle des laïcs.", ex:"Quatre constitutions, dont Lumen gentium (l'Église) et Gaudium et spes (l'Église dans le monde)", etymo:"Deuxième concile tenu au Vatican, après Vatican I (1869-1870), interrompu par la prise de Rome."},
  {name:"Laïcité",              en:"Secularism (French laïcité)", cat:"histoire", def:"Séparation des Églises et de l'État (loi de 1905 en France) : l'État ne reconnaît ni ne salarie aucun culte, garantit la liberté de conscience. Longtemps combattue, puis acceptée par l'Église.", ex:"Inventaires de 1906, régime concordataire maintenu en Alsace-Moselle", etymo:"De laïc, du grec laikos, « du peuple » (laos), par opposition aux clercs."},
];

// ── ISLAM ──
// Sous-lexique de Sciences humaines & sociales. Vocabulaire descriptif ; translittérations simplifiées, usage sunnite majoritaire sauf mention.
const terms_islam = [
  // Fondements
  {name:"Islam",                en:"Islam",                   cat:"fondements",   def:"Religion monothéiste fondée au VIIe siècle en Arabie sur la révélation reçue par Muhammad, consignée dans le Coran. Deuxième religion du monde (environ 1,9 milliard de fidèles), en deux grandes branches, sunnite (85-90 %) et chiite.", ex:"Née à La Mecque et Médine, étendue de l'Espagne à l'Inde en un siècle", etymo:"De l'arabe islâm, « soumission, remise de soi » (à Dieu), de la racine s-l-m, qui donne aussi salâm, « paix », et muslim, « celui qui se soumet »."},
  {name:"Allah",                en:"Allah / God",             cat:"fondements",   def:"Dieu, unique, créateur, sans associé ni égal. Le mot est celui des chrétiens et des juifs arabophones aussi. Le Coran lui donne 99 « beaux noms » : le Miséricordieux, le Tout-Puissant, le Juste…", ex:"« Au nom de Dieu, le Clément, le Miséricordieux » ouvre presque chaque sourate", etymo:"Arabe Allâh, contraction de al-ilâh, « le Dieu », apparenté à l'hébreu El, Elohim."},
  {name:"Muhammad",             en:"Muhammad",                cat:"fondements",   def:"Prophète de l'islam (v. 570-632), marchand de La Mecque qui reçoit la révélation à quarante ans, la prêche, émigre à Médine (622) et fonde la première communauté musulmane. Dernier des prophètes, « sceau des prophètes », il n'est pas divin.", ex:"Les musulmans font suivre son nom de « que la paix soit sur lui »", etymo:"Arabe Muhammad, « le loué, digne de louange », de la racine h-m-d, « louer ». Francisé en Mahomet."},
  {name:"Tawhid",               en:"Tawhid (Oneness of God)", cat:"fondements",   def:"Unicité absolue de Dieu, dogme central de l'islam : rien ne lui est associé, ni fils, ni intermédiaire, ni image. Son contraire, l'associationnisme (shirk), est le péché majeur.", ex:"« Dis : Il est Dieu, Unique » (sourate 112)", etymo:"Arabe tawhîd, « action de rendre un, d'affirmer l'unicité », de la racine w-h-d, « un »."},
  {name:"Prophètes",            en:"Prophets",                cat:"fondements",   def:"Envoyés de Dieu pour rappeler son message aux hommes, tous reconnus par l'islam : Adam, Noé, Abraham, Moïse, Jésus, et Muhammad, le dernier. Le Coran en nomme vingt-cinq.", ex:"Ibrahim (Abraham), Moussa (Moïse), Issa (Jésus), Maryam (Marie) très honorée", etymo:"Arabe nabî (prophète) et rasûl (messager porteur d'un Livre)."},
  {name:"Jour du Jugement",     en:"Day of Judgment",         cat:"fondements",   def:"Fin des temps où chacun, ressuscité, rend compte de ses actes devant Dieu et est destiné au paradis (janna) ou à l'enfer (jahannam). Croyance obligatoire, très présente dans le Coran.", ex:"La balance des actes, le pont, les jardins du paradis", etymo:"Arabe yawm al-dîn, « jour de la rétribution », ou yawm al-qiyâma, « jour de la résurrection »."},
  {name:"Anges",                en:"Angels",                  cat:"fondements",   def:"Créatures de lumière, serviteurs de Dieu sans libre arbitre : Gabriel (Jibril) transmet la révélation, Michel, Israfil sonnera la fin des temps, et deux anges notent les actes de chacun.", ex:"Croire aux anges est un article de foi", etymo:"Arabe malak, pluriel malâ'ika, apparenté à l'hébreu mal'akh, « messager »."},
  {name:"Umma",                 en:"Ummah",                   cat:"fondements",   def:"Communauté de tous les musulmans, par-delà les peuples et les États, unie par la foi. Fondée par Muhammad à Médine.", ex:"Le pèlerinage à La Mecque en est l'expression visible", etymo:"Arabe umma, « communauté, nation », de umm, « mère »."},
  {name:"Musulman",             en:"Muslim",                  cat:"fondements",   def:"Celui qui se soumet à Dieu, fidèle de l'islam. On le devient en prononçant sincèrement la profession de foi devant témoins.", ex:"Environ un quart de l'humanité ; l'Indonésie est le premier pays musulman", etymo:"Arabe muslim, participe de aslama, « se soumettre », même racine que islâm et salâm."},

  // Écritures
  {name:"Coran",                en:"Quran",                   cat:"ecriture",     def:"Livre sacré de l'islam, parole de Dieu révélée à Muhammad en arabe par l'ange Gabriel sur vingt-trois ans, fixée par écrit sous le calife Uthman (v. 650). 114 sourates, environ 6 200 versets. Récité, mémorisé, calligraphié ; les traductions n'en sont que des « sens ».", ex:"La Fatiha (ouverture) est récitée à chaque prière", etymo:"Arabe al-qur'ân, « la récitation, la lecture », de la racine q-r-', « lire, réciter »."},
  {name:"Sourate",              en:"Surah",                   cat:"ecriture",     def:"Chapitre du Coran, 114 au total, classés en gros de la plus longue à la plus courte (sauf la première). Chacune est dite mecquoise ou médinoise selon le lieu de sa révélation.", ex:"La Vache (2, la plus longue), Marie (19), la Lumière (24), l'Unicité (112)", etymo:"Arabe sûra, « rangée, rang d'un mur », peut-être du syriaque."},
  {name:"Verset",               en:"Ayah",                    cat:"ecriture",     def:"Unité de texte du Coran, un « signe » de Dieu. Le verset du Trône (2, 255) et la sourate de la Lumière sont parmi les plus récités.", ex:"« Nulle contrainte en religion » (2, 256)", etymo:"Arabe âya, « signe, miracle », puis verset."},
  {name:"Hadith",               en:"Hadith",                  cat:"ecriture",     def:"Parole, acte ou approbation attribué à Muhammad, rapporté par une chaîne de transmetteurs. Des milliers de hadiths, classés selon leur fiabilité, forment la deuxième source de l'islam après le Coran.", ex:"Recueils de Bukhari et Muslim (sunnites), al-Kafi (chiites)", etymo:"Arabe hadîth, « récit, propos, nouveauté »."},
  {name:"Sunna",                en:"Sunnah",                  cat:"ecriture",     def:"Tradition du Prophète, sa manière de vivre et d'agir, connue par les hadiths, modèle à imiter. Les sunnites tirent d'elle leur nom.", ex:"Manière de prier, de saluer, de manger", etymo:"Arabe sunna, « coutume, voie tracée, conduite »."},
  {name:"Tafsir",               en:"Tafsir (Quranic exegesis)", cat:"ecriture",   def:"Commentaire et interprétation du Coran, discipline majeure : contexte de révélation, langue, sens littéral et allégorique.", ex:"Tabari (Xe siècle), Ibn Kathir, Razi", etymo:"Arabe tafsîr, « explication », de la racine f-s-r, « expliquer »."},
  {name:"Basmala",              en:"Basmalah",                cat:"ecriture",     def:"Formule « Au nom de Dieu, le Clément, le Miséricordieux » (bismi-llâhi r-rahmâni r-rahîm), qui ouvre 113 sourates et tout acte de la vie : repas, voyage, travail.", ex:"Calligraphiée à l'entrée des maisons et des livres", etymo:"Mot forgé sur les premières syllabes de la formule, bism Allâh."},
  {name:"Gens du Livre",        en:"People of the Book",      cat:"ecriture",     def:"Juifs et chrétiens (et sabéens, zoroastriens), détenteurs d'une révélation antérieure, distingués des polythéistes. Ils ont historiquement un statut protégé (dhimmi) en terre d'islam, avec des droits et des charges.", ex:"Le mariage d'un musulman avec une femme des Gens du Livre est permis", etymo:"Arabe ahl al-kitâb, « les gens du Livre »."},

  // Piliers
  {name:"Cinq piliers",         en:"Five Pillars",            cat:"piliers",      def:"Les cinq obligations fondamentales de tout musulman : la profession de foi, la prière quotidienne, l'aumône légale, le jeûne du ramadan et le pèlerinage à La Mecque.", ex:"Shahada, salat, zakat, sawm, hajj", etymo:"Arabe arkân al-islâm, « les piliers de l'islam », de rukn, « pilier, support »."},
  {name:"Shahada",              en:"Shahada (Profession of Faith)", cat:"piliers", def:"Premier pilier : « Il n'y a de dieu que Dieu, et Muhammad est son messager ». La prononcer sincèrement fait entrer dans l'islam ; elle figure dans l'appel à la prière et sur des drapeaux.", ex:"Chuchotée à l'oreille du nouveau-né, dernière parole du mourant", etymo:"Arabe shahâda, « témoignage », de la racine sh-h-d, « témoigner », qui donne aussi shahîd, « martyr »."},
  {name:"Salat",                en:"Salah (Prayer)",          cat:"piliers",      def:"Deuxième pilier : les cinq prières quotidiennes à heures fixes (aube, midi, après-midi, coucher, nuit), tournées vers La Mecque, précédées des ablutions, faites de récitations, d'inclinaisons et de prosternations.", ex:"Fajr, dhuhr, asr, maghrib, isha ; prière du vendredi à la mosquée", etymo:"Arabe salât, « prière rituelle », probablement de l'araméen."},
  {name:"Zakat",                en:"Zakat (Almsgiving)",      cat:"piliers",      def:"Troisième pilier : aumône légale annuelle, en général 2,5 % de l'épargne au-delà d'un seuil, due aux pauvres et à des catégories définies. Purifie les biens ; distincte de l'aumône volontaire (sadaqa).", ex:"Versée en fin de ramadan (zakat al-fitr) ou tout au long de l'année", etymo:"Arabe zakât, « purification, croissance »."},
  {name:"Sawm",                 en:"Sawm (Fasting)",          cat:"piliers",      def:"Quatrième pilier : jeûne du mois de ramadan, de l'aube au coucher du soleil, sans manger, boire, fumer ni relations conjugales. Dispenses pour les malades, voyageurs, enfants, femmes enceintes.", ex:"Le repas de rupture du jeûne (iftar), souvent avec des dattes", etymo:"Arabe sawm, « abstinence, jeûne »."},
  {name:"Hajj",                 en:"Hajj (Pilgrimage)",       cat:"piliers",      def:"Cinquième pilier : pèlerinage à La Mecque, une fois dans sa vie pour qui en a les moyens, pendant le dernier mois de l'année. Tours de la Kaaba, station au mont Arafat, lapidation des stèles, sacrifice. Deux à trois millions de pèlerins par an.", ex:"Le pèlerin porte deux pièces de tissu blanc (ihram) ; la omra est le petit pèlerinage, possible toute l'année", etymo:"Arabe hajj, « pèlerinage », de la racine h-j-j, « se rendre vers »."},

  // Théologie
  {name:"Kalam",                en:"Kalam (Islamic theology)", cat:"theologie",   def:"Théologie spéculative de l'islam, discussion rationnelle des dogmes : attributs de Dieu, création du Coran, libre arbitre. Écoles mutazilite (rationaliste), asharite et maturidite (dominantes chez les sunnites).", ex:"Al-Ghazali, Ibn Rushd (Averroès) critiquant ou défendant la philosophie", etymo:"Arabe kalâm, « parole, discours »."},
  {name:"Fitra",                en:"Fitra",                   cat:"theologie",    def:"Nature originelle et saine de tout être humain, disposée à reconnaître Dieu. Tout enfant naît en état de fitra ; il n'y a pas de péché originel en islam.", ex:"« Tout nouveau-né naît selon la fitra » (hadith)", etymo:"Arabe fitra, « nature première, création », de la racine f-t-r, « fendre, créer »."},
  {name:"Prédestination",       en:"Qadar (Divine Decree)",   cat:"theologie",    def:"Croyance que tout ce qui arrive est décidé et connu par Dieu (qadar), sans que l'homme perde sa responsabilité. Sixième article de foi ; sa conciliation avec le libre arbitre a occupé les théologiens.", ex:"« Maktub », c'était écrit", etymo:"Arabe qadar, « mesure, décret », de la racine q-d-r, « mesurer, pouvoir »."},
  {name:"Miséricorde",          en:"Mercy (Rahma)",           cat:"theologie",    def:"Attribut premier de Dieu, invoqué dans chaque basmala (le Clément, le Miséricordieux). Le pardon divin est offert à qui se repent sincèrement.", ex:"« Ma miséricorde embrasse toute chose » (7, 156)", etymo:"Arabe rahma, de la racine r-h-m, qui donne aussi rahim, « matrice » : l'amour maternel."},
  {name:"Shirk",                en:"Shirk (Idolatry)",        cat:"theologie",    def:"Associer à Dieu un égal ou un partenaire : idolâtrie, polythéisme, mais aussi vénération excessive d'un homme ou d'un objet. Le seul péché impardonnable pour qui meurt sans s'en repentir.", ex:"Les polythéistes mecquois, opposants de Muhammad", etymo:"Arabe shirk, « association », de la racine sh-r-k, « partager, associer »."},
  {name:"Bid'a",                en:"Bid'ah (Innovation)",     cat:"theologie",    def:"Innovation en matière religieuse, sans fondement dans le Coran ou la Sunna. Condamnée par les courants rigoristes, distinguée par d'autres entre innovations blâmables et louables.", ex:"La célébration de la naissance du Prophète (mawlid), discutée", etymo:"Arabe bid'a, « nouveauté, innovation », de la racine b-d-', « créer sans modèle »."},

  // Droit & Éthique
  {name:"Charia",               en:"Sharia",                  cat:"droit_islam",  def:"La « voie » : ensemble des normes tirées du Coran et de la Sunna qui règlent la vie du musulman, du culte au commerce, du mariage à l'héritage. Idéal divin, distinct du fiqh, son interprétation humaine, et des lois des États.", ex:"Son application varie du droit de la famille (Maroc) au code pénal (Arabie saoudite) à rien du tout (Turquie)", etymo:"Arabe sharî'a, « chemin vers le point d'eau », puis « voie, loi »."},
  {name:"Fiqh",                 en:"Fiqh (Jurisprudence)",    cat:"droit_islam",  def:"Jurisprudence islamique : science de la déduction des règles pratiques à partir des sources. Quatre écoles sunnites (hanafite, malikite, shafiite, hanbalite) et une chiite principale (jafarite), qui divergent sur les détails.", ex:"Le Maghreb est malikite, la Turquie hanafite, l'Arabie hanbalite", etymo:"Arabe fiqh, « compréhension, intelligence »."},
  {name:"Halal et haram",       en:"Halal and Haram",         cat:"droit_islam",  def:"Le licite et l'illicite : les deux pôles de la qualification des actes, avec entre eux le recommandé, le neutre et le déconseillé. Le halal désigne couramment la nourriture permise, notamment la viande d'un animal abattu rituellement.", ex:"Porc et alcool sont haram ; viande halal, finance halal", etymo:"Arabe halâl, « délié, permis », et harâm, « interdit, sacré », même racine que harem (l'espace réservé)."},
  {name:"Fatwa",                en:"Fatwa",                   cat:"droit_islam",  def:"Avis juridique rendu par un savant (mufti) sur une question précise, à la demande d'un fidèle ou d'une autorité. Consultatif, non contraignant, sauf si un État lui donne force de loi.", ex:"Fatwas sur la finance, la bioéthique, les prières en avion", etymo:"Arabe fatwâ, « réponse, avis », de la racine f-t-w, « éclairer, répondre »."},
  {name:"Ijtihad",              en:"Ijtihad (Independent Reasoning)", cat:"droit_islam", def:"Effort d'interprétation personnelle des sources pour répondre à une question nouvelle. Son ouverture ou sa « fermeture » est un débat récurrent entre réformateurs et traditionalistes.", ex:"Les réformistes du XIXe siècle (Abduh) prônent sa réouverture", etymo:"Arabe ijtihâd, « effort », de la racine j-h-d, la même que jihad."},
  {name:"Jihad",                en:"Jihad",                   cat:"droit_islam",  def:"Effort sur le chemin de Dieu. Le « grand jihad » est le combat contre ses propres passions ; le « petit jihad », le combat armé, encadré par des règles (défense, proportion, protection des non-combattants). Détourné par les mouvements djihadistes contemporains.", ex:"« Nous revenons du petit jihad vers le grand jihad » (hadith)", etymo:"Arabe jihâd, « effort, lutte », de la racine j-h-d."},
  {name:"Riba",                 en:"Riba (Usury)",            cat:"droit_islam",  def:"Intérêt ou usure, interdit par le Coran. À l'origine de la finance islamique, qui remplace le prêt à intérêt par le partage des profits et des pertes et la vente à tempérament.", ex:"Banques islamiques, sukuk (obligations conformes)", etymo:"Arabe ribâ, « accroissement, surplus »."},

  // Courants
  {name:"Sunnisme",             en:"Sunni Islam",             cat:"courants",     def:"Branche majoritaire (85-90 %), qui reconnaît les quatre premiers califes et tient la communauté pour gardienne de la tradition, sans clergé ni autorité centrale. Quatre écoles juridiques.", ex:"Arabie, Maghreb, Turquie, Indonésie, Pakistan", etymo:"De sunna, la tradition du Prophète : « gens de la tradition et de la communauté »."},
  {name:"Chiisme",              en:"Shia Islam",              cat:"courants",     def:"Branche minoritaire (10-15 %) née de la contestation de la succession de Muhammad : le pouvoir devait revenir à Ali, son cousin et gendre, et à ses descendants, les imams, guides infaillibles. Majoritaire en Iran, Irak, Bahreïn, Azerbaïdjan.", ex:"Duodécimains (douze imams, le dernier caché), ismaéliens, zaydites ; commémoration de l'Achoura", etymo:"Arabe shî'at 'Alî, « le parti d'Ali »."},
  {name:"Soufisme",             en:"Sufism",                  cat:"courants",     def:"Voie mystique de l'islam, recherche de l'union avec Dieu par l'ascèse, la méditation, l'invocation (dhikr), sous la direction d'un maître au sein d'une confrérie. Grande source de poésie et de musique.", ex:"Rumi et les derviches tourneurs, Ibn Arabi, confréries Tijaniyya, Qadiriyya", etymo:"Arabe tasawwuf, de sûf, « laine », le vêtement grossier des premiers ascètes."},
  {name:"Salafisme",            en:"Salafism",                cat:"courants",     def:"Courant sunnite prônant le retour à la pratique des « pieux ancêtres », les trois premières générations, et une lecture littérale des textes. Du quiétisme piétiste au djihadisme, ses formes divergent radicalement.", ex:"Wahhabisme saoudien, salafisme quiétiste, salafisme djihadiste", etymo:"Arabe salaf, « ancêtres, prédécesseurs »."},
  {name:"Réformisme",           en:"Islamic Modernism",       cat:"courants",     def:"Mouvement né au XIXe siècle pour concilier islam et modernité (science, raison, institutions) face à la domination européenne, par la réouverture de l'ijtihad.", ex:"Al-Afghani, Muhammad Abduh, Rachid Rida ; aujourd'hui les « nouveaux penseurs de l'islam »", etymo:"Réforme, du latin reformare, « remettre en forme ». En arabe islâh, « réforme, amélioration », de la racine s-l-h, « être bon »."},
  {name:"Islamisme",            en:"Islamism",                cat:"courants",     def:"Idéologie politique moderne (XXe siècle) faisant de l'islam le fondement de l'ordre social et de l'État. À distinguer de l'islam comme religion et des musulmans pratiquants.", ex:"Frères musulmans (1928), révolution iranienne (1979)", etymo:"Mot français du XVIIIe siècle désignant d'abord l'islam lui-même ; sens politique depuis les années 1980."},

  // Pratique & Vie quotidienne
  {name:"Mosquée",              en:"Mosque",                  cat:"pratique",     def:"Lieu de prière et de rassemblement, orienté vers La Mecque, avec une niche (mihrab) marquant la direction, une chaire (minbar) pour le sermon et souvent un minaret. On y entre déchaussé, en état de pureté.", ex:"Grande Mosquée de La Mecque, mosquée du Prophète à Médine, mosquée de Cordoue", etymo:"De l'arabe masjid, « lieu où l'on se prosterne », de la racine s-j-d, via l'espagnol mezquita."},
  {name:"Imam",                 en:"Imam",                    cat:"pratique",     def:"Chez les sunnites, celui qui dirige la prière et prêche, sans ordination ni sacerdoce : tout musulman compétent peut l'être. Chez les chiites, titre des douze successeurs infaillibles d'Ali.", ex:"Imam de quartier, prêche du vendredi", etymo:"Arabe imâm, « celui qui est devant, guide », de la racine '-m-m, « précéder »."},
  {name:"Adhan",                en:"Adhan (Call to Prayer)",  cat:"pratique",     def:"Appel à la prière lancé cinq fois par jour par le muezzin, depuis le minaret ou par haut-parleur : « Dieu est le plus grand… venez à la prière ».", ex:"« Allahu akbar » répété, la shahada, « la prière vaut mieux que le sommeil » à l'aube", etymo:"Arabe adhân, « annonce », de la racine '-dh-n, « entendre, permettre ». Muezzin, mu'adhdhin, « celui qui annonce »."},
  {name:"Ablutions",            en:"Wudu (Ablutions)",        cat:"pratique",     def:"Purification à l'eau avant la prière : mains, bouche, nez, visage, avant-bras, tête, pieds. Ablutions majeures (bain complet) après certains états ; à défaut d'eau, avec du sable.", ex:"Fontaines à ablutions dans la cour des mosquées", etymo:"Arabe wudû', de la racine w-d-', « être pur, propre »."},
  {name:"Qibla",                en:"Qibla",                   cat:"pratique",     def:"Direction de La Mecque, vers laquelle on se tourne pour prier, indiquée par le mihrab dans la mosquée et par des boussoles ou applications ailleurs.", ex:"D'abord Jérusalem, puis La Mecque à partir de 624", etymo:"Arabe qibla, « direction », de la racine q-b-l, « faire face »."},
  {name:"Kaaba",                en:"Kaaba",                   cat:"pratique",     def:"Édifice cubique au centre de la Grande Mosquée de La Mecque, recouvert d'un voile noir, vers lequel prient tous les musulmans et autour duquel tournent les pèlerins. Selon le Coran, bâti par Abraham et Ismaël.", ex:"La Pierre noire enchâssée dans un angle", etymo:"Arabe ka'ba, « cube »."},
  {name:"Voile",                en:"Hijab (Veil)",            cat:"pratique",     def:"Couvre-chef des femmes musulmanes, du simple foulard (hijab) aux formes couvrantes (niqab, burqa). Son obligation, sa forme et son sens sont débattus entre écoles, pays et générations.", ex:"Hijab, tchador iranien, niqab ; interdit à l'école publique en France (2004)", etymo:"Arabe hijâb, « rideau, séparation », de la racine h-j-b, « cacher »."},
  {name:"Circoncision",         en:"Circumcision",            cat:"pratique",     def:"Ablation du prépuce, pratiquée sur les garçons, de la naissance à l'adolescence selon les pays. Non mentionnée dans le Coran, tenue pour sunna et signe d'appartenance.", ex:"Fêtée en famille dans le Maghreb et en Turquie", etymo:"Arabe khitân. Français du latin circumcisio, « coupure autour »."},
  {name:"Mariage (nikah)",              en:"Marriage (Nikah)",        cat:"pratique",     def:"Contrat entre époux, avec dot (mahr) versée par le mari, témoins et consentement. La polygamie (jusqu'à quatre épouses, à condition d'équité) est permise par le Coran, restreinte ou interdite dans plusieurs pays.", ex:"Interdite en Tunisie (1956), encadrée au Maroc (2004)", etymo:"Arabe nikâh, « union, contrat de mariage »."},
  {name:"Dattes",               en:"Dates",                   cat:"pratique",     def:"Fruit par lequel on rompt traditionnellement le jeûne, à l'exemple du Prophète, avec de l'eau ou du lait. Symbole d'hospitalité dans tout le monde musulman.", ex:"Deglet nour, medjool", etymo:"Du grec daktulos, « doigt », par la forme du fruit."},

  // Fêtes & Calendrier
  {name:"Calendrier hégirien",  en:"Hijri Calendar",          cat:"fetes",        def:"Calendrier lunaire de 354 jours, en douze mois de 29 ou 30 jours, commençant à l'Hégire (622). Les fêtes reculent d'onze jours par an dans le calendrier solaire. L'an 1447 correspond à 2025-2026.", ex:"Muharram, Rajab, Ramadan (9e mois), Dhu al-Hijja (12e)", etymo:"De Hégire, arabe hijra, « émigration », le départ de Muhammad pour Médine."},
  {name:"Ramadan",              en:"Ramadan",                 cat:"fetes",        def:"Neuvième mois du calendrier, mois du jeûne, de la prière nocturne et du Coran, dont la révélation a commencé pendant ce mois. Rythme de vie inversé, nuits animées, générosité.", ex:"Nuit du Destin (Laylat al-Qadr), vers le 27, « meilleure que mille mois »", etymo:"Arabe ramadân, de la racine r-m-d, « être brûlant », le mois tombant à l'origine en été."},
  {name:"Aïd el-Fitr",          en:"Eid al-Fitr",             cat:"fetes",        def:"Fête de la rupture du jeûne, premier jour du mois suivant le ramadan : prière collective du matin, aumône, vêtements neufs, visites, pâtisseries. Deux à trois jours de fête.", ex:"« Aïd moubarak », fête bénie", etymo:"Arabe 'îd al-fitr, « fête de la rupture (du jeûne) ». 'Îd, « fête, ce qui revient »."},
  {name:"Aïd el-Adha",          en:"Eid al-Adha",             cat:"fetes",        def:"Fête du sacrifice, la plus importante, au dixième jour du mois du pèlerinage : commémore la soumission d'Abraham prêt à sacrifier son fils. Un mouton est sacrifié et partagé en trois, famille, proches, pauvres.", ex:"Aïd el-Kébir (« grande fête ») au Maghreb, Tabaski en Afrique de l'Ouest", etymo:"Arabe 'îd al-adhâ, « fête du sacrifice »."},
  {name:"Vendredi",             en:"Friday (Jumu'ah)",        cat:"fetes",        def:"Jour de la prière collective de la mi-journée à la mosquée, avec sermon, obligatoire pour les hommes. Jour de repos hebdomadaire dans beaucoup de pays musulmans, sans être un « sabbat ».", ex:"« Ô croyants, quand on appelle à la prière du vendredi, accourez » (62, 9)", etymo:"Arabe yawm al-jum'a, « jour du rassemblement »."},
  {name:"Achoura",              en:"Ashura",                  cat:"fetes",        def:"Dixième jour du premier mois. Jour de jeûne facultatif chez les sunnites ; chez les chiites, deuil de la mort de Hussein, petit-fils du Prophète, tué à Kerbala (680), avec processions et représentations.", ex:"Processions de Kerbala, pèlerinage majeur chiite", etymo:"Arabe 'âshûrâ', de 'ashara, « dix »."},
  {name:"Mawlid",               en:"Mawlid",                  cat:"fetes",        def:"Anniversaire de la naissance du Prophète, le 12 du troisième mois, fêté par des chants, des récits et des veillées dans la plupart des pays ; rejeté par les salafistes comme innovation.", ex:"Férié au Maroc, en Égypte, en Turquie ; interdit en Arabie saoudite", etymo:"Arabe mawlid, « naissance, lieu de naissance », de la racine w-l-d, « enfanter »."},

  // Figures
  {name:"Compagnons",           en:"Companions (Sahaba)",     cat:"figures",      def:"Ceux qui ont connu Muhammad et cru en lui : premiers convertis, émigrés de La Mecque, alliés de Médine. Transmetteurs de la Sunna, modèles de piété chez les sunnites.", ex:"Abu Bakr, Omar, Uthman, Ali (les quatre premiers califes), Bilal le premier muezzin", etymo:"Arabe sahâba, « compagnons », de sâhib, « compagnon, ami »."},
  {name:"Ali",                  en:"Ali ibn Abi Talib",       cat:"figures",      def:"Cousin et gendre de Muhammad, époux de Fatima, quatrième calife (656-661), assassiné à Koufa. Pour les chiites, premier imam et successeur légitime ; pour tous, modèle de courage et de sagesse.", ex:"Son tombeau à Nadjaf, ville sainte chiite", etymo:"Arabe 'Alî, « élevé, sublime », de la racine '-l-w, « être haut », l'un des noms de Dieu (al-'Alî)."},
  {name:"Fatima",               en:"Fatimah",                 cat:"figures",      def:"Fille de Muhammad et de Khadija, épouse d'Ali, mère de Hassan et Hussein, ancêtre de tous les descendants du Prophète (chérifs). Vénérée, surtout chez les chiites, comme la première des femmes.", ex:"La « main de Fatima » (khamsa), amulette populaire", etymo:"Arabe Fâtima, « celle qui sèvre »."},
  {name:"Khadija",              en:"Khadijah",                cat:"figures",      def:"Riche commerçante de La Mecque, première épouse de Muhammad, de quinze ans son aînée, et première personne à croire en sa mission. Soutien décisif des débuts, morte en 619.", ex:"Muhammad n'a pas pris d'autre épouse de son vivant", etymo:"Arabe Khadîja, « née avant terme », de la racine kh-d-j."},
  {name:"Aïcha",                en:"Aisha",                   cat:"figures",      def:"Fille d'Abu Bakr et épouse préférée de Muhammad après Khadija, transmettrice de plus de deux mille hadiths, figure politique après sa mort (bataille du Chameau, 656). Autorité majeure chez les sunnites.", ex:"« Prenez la moitié de votre religion de cette rousse » (attribué au Prophète)", etymo:"Arabe 'Â'isha, « vivante, qui vit », de la racine '-y-sh, « vivre »."},
  {name:"Califes bien guidés",  en:"Rightly Guided Caliphs",  cat:"figures",      def:"Les quatre premiers successeurs de Muhammad (632-661) : Abu Bakr, Omar, Uthman, Ali. Époque de référence pour les sunnites, conquêtes fulgurantes, fixation du Coran.", ex:"Omar prend Jérusalem (638) ; Uthman fixe le texte coranique", etymo:"Arabe al-khulafâ' ar-râshidûn, « les califes bien dirigés »."},
  {name:"Al-Ghazali",           en:"Al-Ghazali",              cat:"figures",      def:"Théologien, juriste et mystique persan (1058-1111), qui réconcilie l'orthodoxie sunnite et le soufisme et critique les philosophes. Souvent tenu pour le plus grand penseur de l'islam classique.", ex:"Revivification des sciences de la religion, L'Incohérence des philosophes", etymo:"Nom de relation (nisba), soit de la ville de Ghazâla, soit du métier de fileur (ghazzâl) de son père. Latinisé en Algazel par les scolastiques."},
  {name:"Averroès",             en:"Averroes (Ibn Rushd)",    cat:"figures",      def:"Philosophe, juge et médecin de Cordoue (1126-1198), commentateur d'Aristote dont la pensée irrigue l'Europe médiévale. Défend l'accord de la raison et de la révélation.", ex:"Traduit en latin, lu à Paris ; Thomas d'Aquin le nomme « le Commentateur »", etymo:"Averroès, latinisation d'Ibn Rushd."},
  {name:"Rumi",                 en:"Rumi",                    cat:"figures",      def:"Poète mystique persan (1207-1273), fondateur de la confrérie des derviches tourneurs à Konya. Son Mathnawi est le grand poème du soufisme ; il est aujourd'hui le poète le plus lu aux États-Unis.", ex:"« Viens, viens, qui que tu sois »", etymo:"Rûmî, « de Roum » (l'Anatolie byzantine, terre des « Romains »)."},

  // Savoir & Institutions
  {name:"Ouléma",               en:"Ulama (Scholars)",        cat:"savoir",       def:"Savants religieux, juristes et théologiens formés aux sciences islamiques, autorités en matière de doctrine et de droit, faute de clergé. Leur consensus (ijma) est une source du droit.", ex:"Al-Azhar au Caire, Qarawiyyin à Fès, Zaytouna à Tunis", etymo:"Arabe 'ulamâ', pluriel de 'âlim, « savant », de la racine '-l-m, « savoir »."},
  {name:"Madrasa",              en:"Madrasa",                 cat:"savoir",       def:"École d'enseignement des sciences religieuses (Coran, hadith, droit, langue), apparue au XIe siècle, souvent adossée à une mosquée. Le mot désigne aussi simplement l'école dans plusieurs langues.", ex:"Madrasas de Fès, de Samarcande, de Boukhara", etymo:"Arabe madrasa, « lieu d'étude », de la racine d-r-s, « étudier »."},
  {name:"Mufti",                en:"Mufti",                   cat:"savoir",       def:"Juriste habilité à rendre des fatwas. Dans plusieurs pays, un grand mufti est nommé par l'État.", ex:"Grand mufti d'Égypte, d'Arabie saoudite", etymo:"Arabe muftî, « celui qui répond », même racine que fatwa."},
  {name:"Calife",               en:"Caliph",                  cat:"savoir",       def:"Successeur du Prophète à la tête de la communauté, chef politique et religieux. Institution des Omeyyades (Damas) aux Abbassides (Bagdad) puis aux Ottomans, abolie par la Turquie en 1924.", ex:"Haroun al-Rachid, calife des Mille et Une Nuits", etymo:"Arabe khalîfa, « successeur, lieutenant », de la racine kh-l-f, « venir après »."},
  {name:"Waqf",                 en:"Waqf (Endowment)",        cat:"savoir",       def:"Bien inaliénable dont les revenus sont affectés à perpétuité à une œuvre pieuse ou d'utilité publique : mosquée, école, hôpital, fontaine. Colonne vertébrale des villes musulmanes classiques.", ex:"Habous au Maghreb", etymo:"Arabe waqf, « arrêt, immobilisation » (du bien)."},
  {name:"Cadi",                 en:"Qadi (Judge)",            cat:"savoir",       def:"Juge appliquant le droit musulman, nommé par l'autorité, compétent en matière de famille, contrats, succession. Encore présent dans le droit de plusieurs pays.", ex:"Le cadi des contes, figure de la justice", etymo:"Arabe qâdî, « celui qui tranche, juge », de la racine q-d-y, « décider »."},

  // Civilisation
  {name:"Calligraphie",         en:"Calligraphy",             cat:"civilisation", def:"Art majeur de l'islam, l'écriture du Coran étant sacrée et l'image de Dieu ou du Prophète proscrite. Styles coufique, naskhi, thuluth, diwani ; orne mosquées, manuscrits, objets.", ex:"Frises coraniques de l'Alhambra, du Taj Mahal", etymo:"Du grec kallos, « beauté », et graphein, « écrire »."},
  {name:"Arabesque",            en:"Arabesque",               cat:"civilisation", def:"Ornement fait d'entrelacs végétaux et géométriques répétés à l'infini, sans figure humaine, qui couvre les surfaces de l'art islamique.", ex:"Zelliges du Maroc, coupoles d'Ispahan", etymo:"De l'italien arabesco, « à la manière arabe »."},
  {name:"Âge d'or",             en:"Islamic Golden Age",      cat:"civilisation", def:"VIIIe-XIIIe siècles, Bagdad, Cordoue, Le Caire : traduction du savoir grec, essor des mathématiques (algèbre, chiffres indiens), de la médecine (Avicenne), de l'astronomie, de l'optique, transmis ensuite à l'Europe.", ex:"Maison de la Sagesse de Bagdad, al-Khwarizmi (algorithme), Avicenne, Alhazen", etymo:"Algèbre, de l'arabe al-jabr, « réduction » ; chiffre, de sifr, « zéro » ; algorithme, d'al-Khwârizmî."},
  {name:"Al-Andalus",           en:"Al-Andalus",              cat:"civilisation", def:"L'Espagne musulmane (711-1492), de Cordoue à Grenade, foyer de sciences, de poésie et de coexistence, parfois idéalisée, entre musulmans, juifs et chrétiens.", ex:"Mosquée de Cordoue, Alhambra de Grenade, Averroès et Maïmonide", etymo:"Arabe al-Andalus, peut-être du nom des Vandales."},
  {name:"Empire ottoman",       en:"Ottoman Empire",          cat:"civilisation", def:"Empire turc (1299-1922) qui prend Constantinople en 1453, domine le monde arabe, les Balkans et la Méditerranée, et porte le califat jusqu'en 1924. Sa chute redessine le Moyen-Orient.", ex:"Soliman le Magnifique, Sainte-Sophie devenue mosquée, Istanbul", etymo:"Du nom d'Osman Ier, fondateur de la dynastie."},

  // Histoire
  {name:"Hégire",               en:"Hijra",                   cat:"histoire",     def:"Émigration de Muhammad et des premiers musulmans de La Mecque, hostile, vers Médine, en 622 : naissance de la communauté et point de départ du calendrier musulman.", ex:"Médine, « la ville du Prophète » (Madinat an-Nabi)", etymo:"Arabe hijra, « émigration, rupture », de la racine h-j-r, « quitter »."},
  {name:"Conquêtes",            en:"Early Muslim Conquests",  cat:"histoire",     def:"Expansion foudroyante après la mort du Prophète : Syrie, Égypte, Perse en vingt ans, Maghreb et Espagne avant 720, jusqu'à l'Indus. Conversion progressive des populations, souvent sur plusieurs siècles.", ex:"Bataille de Poitiers (732) marquant l'arrêt en Gaule", etymo:"Conquête, du latin populaire conquaesita, de conquirere, « chercher à prendre ». En arabe futûh, « ouvertures » (racine f-t-h, ouvrir) : les conquêtes « ouvrent » les pays à l'islam."},
  {name:"Omeyyades et Abbassides", en:"Umayyads and Abbasids", cat:"histoire",    def:"Les deux premières dynasties califales : les Omeyyades à Damas (661-750), puis les Abbassides à Bagdad (750-1258), sous lesquels fleurit l'âge d'or. Les Omeyyades survivent en Espagne.", ex:"Grande Mosquée de Damas, Bagdad fondée en 762, prise par les Mongols en 1258", etymo:"Omeyyades, de Umayya, ancêtre du clan mecquois de Muawiya. Abbassides, d'al-'Abbâs, oncle du Prophète, dont ils descendaient."},
  {name:"Colonisation et réveil", en:"Colonial Era and Revival", cat:"histoire",  def:"XIXe-XXe siècles : domination européenne sur presque tout le monde musulman, réponses réformistes, nationalistes puis islamistes, indépendances, pétrole, révolution iranienne (1979).", ex:"Algérie française (1830-1962), fin du califat (1924), Frères musulmans (1928)", etymo:"Colonisation, du latin colonia, « terre cultivée », de colere. Réveil, de veiller, du latin vigilare ; en arabe nahda, « renaissance, éveil »."},
  {name:"Islam en France",      en:"Islam in France",         cat:"histoire",     def:"Deuxième religion du pays, issue surtout de l'immigration maghrébine, ouest-africaine et turque depuis les années 1960 : environ cinq à six millions de personnes de culture musulmane, aux pratiques très diverses. Cadre laïque de la loi de 1905.", ex:"Grande Mosquée de Paris (1926), Conseil français du culte musulman (2003)", etymo:"France, du francique frank, « libre », le peuple des Francs."},
];

// ── CRYPTOMONNAIES ──
// Sous-lexique de Numérique. Descriptif : aucune recommandation d'investissement. La cryptographie sous-jacente est définie dans Sécurité.
const terms_crypto = [
  // Fondements
  {name:"Cryptomonnaie",        en:"Cryptocurrency",          cat:"fondements",   def:"Monnaie numérique sans banque centrale ni intermédiaire, dont les transactions sont validées par un réseau d'ordinateurs et enregistrées sur une blockchain. Sa valeur ne repose sur aucun État : elle est fixée par l'offre et la demande, d'où une forte volatilité.", ex:"Bitcoin (2009), Ether, des milliers d'autres, la plupart sans valeur", etymo:"De crypto-, du grec kruptos, « caché » (par la cryptographie qui la sécurise), et monnaie, du latin moneta."},
  {name:"Bitcoin",              en:"Bitcoin",                 cat:"fondements",   def:"Première cryptomonnaie, lancée en 2009 par un inconnu sous le nom de Satoshi Nakamoto. Émission plafonnée à 21 millions d'unités, sécurisée par la preuve de travail. Le mot désigne le réseau (Bitcoin) et l'unité (bitcoin, BTC).", ex:"Un bitcoin se divise en 100 millions de satoshis", etymo:"De bit (unité d'information) et coin, « pièce de monnaie »."},
  {name:"Ethereum",             en:"Ethereum",                cat:"fondements",   def:"Deuxième blockchain par la capitalisation, lancée en 2015 par Vitalik Buterin, conçue pour exécuter des programmes (smart contracts) et non seulement transférer de la monnaie. Sa monnaie est l'ether (ETH). Passée à la preuve d'enjeu en 2022.", ex:"Support de la plupart des NFT, de la DeFi et des stablecoins", etymo:"De l'éther, le milieu impalpable que les physiciens du XIXe siècle imaginaient partout, choisi par Buterin pour évoquer un réseau omniprésent."},
  {name:"Altcoin",              en:"Altcoin",                 cat:"fondements",   def:"Toute cryptomonnaie autre que le bitcoin. Des milliers existent, des projets sérieux aux copies sans usage.", ex:"Ether, Solana, Cardano, XRP, Dogecoin", etymo:"Anglais, contraction de alternative coin."},
  {name:"Stablecoin",           en:"Stablecoin",              cat:"fondements",   def:"Cryptomonnaie dont la valeur est arrimée à une monnaie classique, en général le dollar, par une réserve d'actifs ou un mécanisme algorithmique. Sert de refuge et de monnaie d'échange dans l'écosystème.", ex:"USDT (Tether), USDC ; l'effondrement de l'UST algorithmique (2022)", etymo:"Anglais, « pièce stable »."},
  {name:"Jeton (token)",                en:"Token",                   cat:"fondements",   def:"Jeton numérique émis sur une blockchain existante (surtout Ethereum) plutôt que doté de sa propre chaîne. Peut représenter une monnaie, un droit de vote, un accès, un objet unique (NFT).", ex:"Standards ERC-20 (fongible), ERC-721 (NFT)", etymo:"Anglais, « jeton », du vieil anglais tacen, « signe »."},
  {name:"Décentralisation",     en:"Decentralization",        cat:"fondements",   def:"Principe fondateur : aucune autorité ne contrôle le réseau, tenu par des milliers de nœuds indépendants. Personne ne peut geler un compte ni annuler une transaction, pour le meilleur et pour le pire.", ex:"Bitcoin fonctionne sans entreprise ni siège social", etymo:"De centre, du latin centrum, du grec kentron, « pointe du compas »."},
  {name:"Monnaie fiduciaire",   en:"Fiat Currency",           cat:"fondements",   def:"Monnaie classique émise par un État et sa banque centrale (euro, dollar), sans contre-valeur matérielle, qui repose sur la confiance. Le mot « fiat » désigne dans le milieu crypto tout ce qui n'est pas crypto.", ex:"Convertir des bitcoins en euros : « passer en fiat »", etymo:"Fiduciaire, du latin fiducia, « confiance ». Fiat, latin, « qu'il soit fait », le mot du décret."},

  // Blockchain
  {name:"Blockchain",           en:"Blockchain",              cat:"chaine",       def:"Registre de transactions partagé par tous les nœuds d'un réseau, organisé en blocs enchaînés par des empreintes cryptographiques : modifier un bloc invaliderait tous les suivants. Infalsifiable tant que le réseau est honnête à majorité.", ex:"Le registre Bitcoin pèse plusieurs centaines de gigaoctets et est copié sur des dizaines de milliers de machines", etymo:"Anglais, « chaîne de blocs ». Le concept est décrit dans le livre blanc de Bitcoin (2008), le mot lui-même apparaît un peu plus tard."},
  {name:"Bloc",                 en:"Block",                   cat:"chaine",       def:"Groupe de transactions validées ensemble et ajoutées à la chaîne, avec l'empreinte du bloc précédent et un horodatage. Un bloc toutes les dix minutes environ sur Bitcoin, douze secondes sur Ethereum.", ex:"Le bloc de genèse (3 janvier 2009) contient un titre du Times sur les banques", etymo:"Du néerlandais blok, « tronc abattu, bloc de bois »."},
  {name:"Hachage",              en:"Hashing",                 cat:"chaine",       ref:"securite"},
  {name:"Nœud",                 en:"Node",                    cat:"chaine",       def:"Ordinateur qui conserve une copie de la blockchain, vérifie les transactions et les relaie. Tout le monde peut en faire tourner un ; c'est ce qui rend le réseau décentralisé.", ex:"Un nœud Bitcoin complet tourne sur un simple ordinateur personnel", etymo:"Du latin nodus, « nœud », point de jonction d'un réseau."},
  {name:"Consensus",            en:"Consensus",               cat:"chaine",       def:"Mécanisme par lequel des milliers de nœuds qui ne se font pas confiance s'accordent sur l'état du registre. Les deux grandes familles : preuve de travail et preuve d'enjeu.", ex:"Une transaction est considérée définitive après six blocs sur Bitcoin", etymo:"Du latin consensus, « accord », de consentire, « sentir ensemble »."},
  {name:"Preuve de travail",    en:"Proof of Work",           cat:"chaine",       def:"Consensus où les mineurs rivalisent en calculant des milliards d'empreintes par seconde jusqu'à en trouver une répondant à une cible ; le gagnant ajoute le bloc et touche la récompense. Sûr, mais très gourmand en électricité.", ex:"Bitcoin, Litecoin ; Ethereum jusqu'en 2022", etymo:"Calque de l'anglais proof of work, concept antérieur à Bitcoin (Dwork et Naor, 1993, contre le spam)."},
  {name:"Preuve d'enjeu",       en:"Proof of Stake",          cat:"chaine",       def:"Consensus où les validateurs sont tirés au sort en proportion des jetons qu'ils ont mis en gage ; tricher fait perdre la mise. Consomme mille fois moins d'énergie que la preuve de travail.", ex:"Ethereum depuis The Merge (2022), Cardano, Solana", etymo:"Calque de l'anglais proof of stake. Stake, « enjeu, mise »."},
  {name:"Minage",               en:"Mining",                  cat:"chaine",       def:"Activité des nœuds qui valident les blocs en preuve de travail, contre une récompense en monnaie nouvellement créée et des frais. D'abord sur des ordinateurs personnels, puis des cartes graphiques, aujourd'hui des puces dédiées dans des fermes industrielles.", ex:"Fermes de minage au Texas, au Kazakhstan ; interdit en Chine depuis 2021", etymo:"Métaphore de la mine : on « extrait » de la monnaie par l'effort, comme l'or."},
  {name:"Halving",              en:"Halving",                 cat:"chaine",       def:"Division par deux de la récompense des mineurs de Bitcoin, tous les 210 000 blocs (environ quatre ans), jusqu'à l'épuisement des 21 millions vers 2140. Rend l'émission de plus en plus rare.", ex:"50 BTC par bloc en 2009, 3,125 depuis avril 2024", etymo:"Anglais, « réduction de moitié », de half."},
  {name:"Contrat intelligent",       en:"Smart contract",          cat:"chaine",       def:"Programme déposé sur une blockchain qui s'exécute automatiquement quand ses conditions sont remplies, sans intermédiaire ni possibilité de l'arrêter. Base de la DeFi et des NFT. Un bug y est définitif.", ex:"Un contrat qui libère un paiement à la livraison ; le piratage de The DAO (2016) par une faille de contrat", etymo:"Anglais, « contrat intelligent », concept de Nick Szabo (1994), bien avant la blockchain."},
  {name:"Gas",                  en:"Gas Fees",                cat:"chaine",       def:"Frais payés pour faire exécuter une transaction ou un contrat sur Ethereum, proportionnels au calcul demandé et à l'encombrement du réseau. Peuvent dépasser la valeur du transfert aux heures de pointe.", ex:"Quelques centimes la nuit, plusieurs dizaines d'euros lors d'une frénésie NFT", etymo:"Anglais, « carburant » : ce qui fait tourner la machine virtuelle d'Ethereum."},
  {name:"Bifurcation (fork)",                 en:"Fork",                    cat:"chaine",       def:"Scission d'une blockchain en deux chaînes, par mise à jour incompatible du protocole (hard fork) ou désaccord de la communauté. Chacune garde l'historique commun puis diverge.", ex:"Bitcoin Cash (2017) issu de Bitcoin, Ethereum Classic (2016) issu d'Ethereum", etymo:"Anglais, « fourche, embranchement »."},
  {name:"Layer 2",              en:"Layer 2",                 cat:"chaine",       def:"Réseau construit au-dessus d'une blockchain pour traiter les transactions plus vite et moins cher, en n'inscrivant sur la chaîne principale qu'un résumé. Réponse au problème de la montée en charge.", ex:"Lightning Network (Bitcoin), Arbitrum, Optimism, Base (Ethereum)", etymo:"Anglais, « couche 2 », la couche 1 étant la chaîne de base."},
  {name:"Oracle",               en:"Oracle",                  cat:"chaine",       def:"Service qui apporte à un smart contract une information du monde extérieur (prix, météo, résultat), que la blockchain ne peut pas connaître seule. Point de fragilité classique.", ex:"Chainlink ; un contrat d'assurance récolte déclenché par des données météo", etymo:"Du latin oraculum, « réponse des dieux », de orare, « parler, prier »."},
  {name:"Explorateur de blocs", en:"Block Explorer",          cat:"chaine",       def:"Site permettant de consulter publiquement toute la blockchain : transactions, adresses, soldes, contrats. Tout est visible par tous, à jamais.", ex:"mempool.space (Bitcoin), Etherscan (Ethereum)", etymo:"Explorer, du latin explorare, « observer, reconnaître » (terme de chasse : faire sortir le gibier par des cris)."},

  // Portefeuilles & Clés
  {name:"Portefeuille",         en:"Wallet",                  cat:"portefeuille", def:"Logiciel ou appareil qui conserve les clés privées et permet d'envoyer et recevoir des cryptomonnaies. Il ne contient pas les fonds, qui sont sur la blockchain : il contient ce qui permet d'en disposer.", ex:"Application mobile, extension de navigateur, boîtier physique", etymo:"Calque de l'anglais wallet, « portefeuille »."},
  {name:"Clé privée",           en:"Private Key",             cat:"portefeuille", def:"Nombre secret qui donne le contrôle total des fonds d'une adresse. Qui la possède possède les fonds ; qui la perd les perd, sans recours. « Pas tes clés, pas tes cryptos. »", ex:"256 bits, jamais à saisir sur un site ni à photographier", etymo:"Voir clé publique / clé privée dans Sécurité : c'est la même cryptographie asymétrique."},
  {name:"Phrase de récupération", en:"Seed Phrase",           cat:"portefeuille", def:"Suite de 12 ou 24 mots générée à la création d'un portefeuille, à partir de laquelle toutes ses clés peuvent être recalculées. La seule sauvegarde qui compte ; à écrire sur papier ou métal, jamais en ligne.", ex:"« abandon ability able about… » : les mots viennent d'une liste standard de 2 048 (BIP-39)", etymo:"Seed, anglais, « graine » : tout le portefeuille en germe."},
  {name:"Adresse",              en:"Address",                 cat:"portefeuille", def:"Identifiant public dérivé de la clé, sur lequel on reçoit des fonds. Longue chaîne de caractères, à copier-coller ou scanner (QR), une erreur envoie les fonds dans le vide.", ex:"bc1q… (Bitcoin), 0x… (Ethereum) ; les noms lisibles comme seb.eth", etymo:"De adresser, du latin populaire addirectiare, « diriger vers » (directus, droit)."},
  {name:"Portefeuille froid",          en:"Cold wallet",             cat:"portefeuille", def:"Portefeuille dont les clés ne touchent jamais internet : boîtier dédié, papier, ordinateur hors ligne. Le plus sûr pour conserver ; par opposition au hot wallet, connecté, pratique mais exposé.", ex:"Ledger, Trezor (boîtiers) ; un vieux téléphone en mode avion", etymo:"Anglais, « portefeuille froid », par opposition à hot, « chaud », connecté."},
  {name:"Plateforme d'échange", en:"Exchange",                cat:"portefeuille", def:"Entreprise où l'on achète, vend et échange des cryptomonnaies contre des euros ou entre elles, comme un courtier. Elle détient les clés à la place de l'utilisateur (custodial) : sa faillite ou son piratage emporte les fonds.", ex:"Coinbase, Binance, Kraken ; faillites de Mt. Gox (2014) et FTX (2022)", etymo:"Plateforme, de plat + forme. Échange, du latin populaire excambiare. L'anglais dit exchange."},
  {name:"Custodial / non custodial", en:"Custodial / Non-custodial", cat:"portefeuille", def:"Qui garde les clés : un tiers (custodial, comme une banque) ou l'utilisateur lui-même (non custodial, avec toute la responsabilité). Le cœur du compromis entre confort et souveraineté.", ex:"Compte sur une plateforme (custodial) contre portefeuille personnel (non custodial)", etymo:"Anglais custody, « garde », du latin custodia."},
  {name:"Transaction (blockchain)",          en:"Blockchain Transaction",             cat:"portefeuille", def:"Transfert signé avec la clé privée, diffusé au réseau, en attente dans la file (mempool) puis inscrit dans un bloc. Irréversible une fois confirmée : pas d'annulation, pas de service client.", ex:"Confirmée en dix minutes à une heure sur Bitcoin, quelques secondes sur Solana", etymo:"Du latin transactio, « accord », de transigere, « mener à terme »."},

  // Marchés & Trading
  {name:"Capitalisation",       en:"Market Cap",              cat:"marches",      def:"Valeur totale d'une cryptomonnaie : prix multiplié par le nombre d'unités en circulation. Sert à classer les projets ; Bitcoin en représente autour de la moitié.", ex:"Un jeton à 0,001 € peut valoir plus qu'un jeton à 100 € s'il y en a des milliards", etymo:"De capital, du latin capitalis, « de la tête » (caput). Calque de l'anglais market capitalization."},
  {name:"Volatilité",           en:"Volatility",              cat:"marches",      def:"Amplitude des variations de prix. Les cryptomonnaies peuvent perdre ou gagner 10 % en une journée et 80 % en un an, bien plus que les actions ou les devises.", ex:"Bitcoin : 69 000 $ en novembre 2021, 16 000 $ un an plus tard, 100 000 $ fin 2024", etymo:"Du latin volatilis, « qui vole, fugace », de volare, « voler »."},
  {name:"Bull et bear market",  en:"Bull / Bear Market",      cat:"marches",      def:"Marché haussier (le taureau frappe vers le haut) ou baissier (l'ours frappe vers le bas). Les cryptos alternent des cycles violents, souvent calés sur le halving de Bitcoin.", ex:"Bull run de 2017, de 2021 ; « crypto winter » de 2022", etymo:"Images boursières anglaises du XVIIIe siècle, par le geste des deux animaux."},
  {name:"HODL",                 en:"HODL",                    cat:"marches",      def:"Conserver ses cryptomonnaies quoi qu'il arrive, sans vendre dans les baisses. Devise des détenteurs de long terme.", ex:"« HODL ! » en réponse à toute chute", etymo:"Faute de frappe pour hold (« garder ») dans un message enflammé d'un forum en 2013, devenue un cri de ralliement, puis réinterprétée en Hold On for Dear Life."},
  {name:"ATH",                  en:"All-Time High",           cat:"marches",      def:"Plus haut historique du prix d'un actif. Souvent invoqué, rarement retrouvé pour la plupart des altcoins.", ex:"Bitcoin dépasse les 100 000 $ pour la première fois en décembre 2024", etymo:"Sigle de l'anglais all-time high."},
  {name:"Liquidité",            en:"Liquidity",               cat:"marches",      def:"Facilité à acheter ou vendre sans faire bouger le prix. Élevée sur Bitcoin, quasi nulle sur les petits jetons, où vendre fait s'effondrer le cours.", ex:"Un jeton avec 3 000 € de liquidité ne peut pas absorber une vente de 10 000 €", etymo:"Du latin liquidus, « fluide » : ce qui s'écoule facilement, comme l'argent liquide."},
  {name:"Effet de levier",      en:"Leverage",                cat:"marches",      def:"Emprunt permettant de miser plus que ce qu'on possède, multipliant gains et pertes. Avec un levier de 10, une baisse de 10 % efface tout : la liquidation. Cause principale des pertes des particuliers.", ex:"Plusieurs milliards de dollars de positions liquidées lors d'une chute brutale", etymo:"Levier, du latin levare, « soulever »."},
  {name:"DCA",                  en:"Dollar-Cost Averaging",   cat:"marches",      def:"Acheter un montant fixe à intervalles réguliers, quel que soit le prix, pour lisser le point d'entrée et éviter d'essayer de deviner le marché.", ex:"50 € tous les premiers du mois", etymo:"Sigle de l'anglais dollar-cost averaging, « moyenne du coût en dollars »."},
  {name:"Baleine (whale)",                en:"Whale",                   cat:"marches",      def:"Détenteur de très grandes quantités, dont un seul mouvement peut faire bouger le marché. Leurs adresses sont surveillées publiquement.", ex:"Les portefeuilles de Satoshi (un million de bitcoins jamais bougés)", etymo:"Anglais, « baleine », l'image du gros poisson venant des casinos."},

  // DeFi & Web3
  {name:"DeFi",                 en:"Decentralized Finance",   cat:"defi",         def:"Finance décentralisée : services financiers (prêt, emprunt, échange, épargne) fournis par des smart contracts sans banque ni intermédiaire, accessibles à quiconque a un portefeuille.", ex:"Uniswap (échange), Aave (prêt), MakerDAO (stablecoin DAI)", etymo:"Contraction de l'anglais decentralized finance."},
  {name:"DEX",                  en:"Decentralized Exchange",  cat:"defi",         def:"Plateforme d'échange sans intermédiaire, où l'on échange directement depuis son portefeuille grâce à des réserves de liquidité alimentées par les utilisateurs. Pas d'inscription, mais pas de recours.", ex:"Uniswap, PancakeSwap", etymo:"Sigle de l'anglais decentralized exchange."},
  {name:"NFT",                  en:"Non-Fungible Token",      cat:"defi",         def:"Jeton unique et non interchangeable, certifiant sur la blockchain la propriété d'un objet numérique : image, musique, objet de jeu, billet, nom de domaine. L'objet lui-même reste souvent hébergé ailleurs.", ex:"CryptoPunks, Bored Apes ; le collage de Beeple vendu 69 millions de dollars (2021), puis l'effondrement du marché", etymo:"Sigle de l'anglais non-fungible token. Fongible, du latin fungi, « s'acquitter » : un bien qu'on peut remplacer par un autre identique, comme un billet de 10 €."},
  {name:"Staking",              en:"Staking",                 cat:"defi",         def:"Immobiliser ses jetons pour participer à la validation d'une blockchain en preuve d'enjeu, contre une rémunération en jetons. L'équivalent d'un intérêt, avec le risque de pénalité et de blocage.", ex:"3 à 5 % par an sur Ethereum", etymo:"Anglais, de stake, « mise, enjeu »."},
  {name:"Yield farming",        en:"Yield Farming",           cat:"defi",         def:"Chasse au rendement en déplaçant ses jetons de protocole en protocole pour y fournir de la liquidité contre des récompenses. Rendements parfois délirants, risques à la hauteur.", ex:"L'été DeFi de 2020", etymo:"Anglais, « culture du rendement » : on « fait pousser » des intérêts."},
  {name:"DAO",                  en:"Decentralized Autonomous Organization", cat:"defi", def:"Organisation gouvernée par des smart contracts et les votes des détenteurs de jetons, sans direction ni statuts classiques : trésorerie, décisions et règles sur la blockchain.", ex:"MakerDAO ; ConstitutionDAO qui a tenté d'acheter une copie de la Constitution américaine (2021)", etymo:"Sigle de l'anglais decentralized autonomous organization."},
  {name:"Web 3.0",              en:"Web 3.0",                 cat:"defi",         ref:"numerique"},
  {name:"Airdrop",              en:"Airdrop",                 cat:"defi",         def:"Distribution gratuite de jetons à des utilisateurs, pour lancer un projet, récompenser les premiers venus ou faire parler de soi. Aussi un vecteur classique d'arnaque.", ex:"Uniswap a distribué 400 UNI à chaque ancien utilisateur (2020)", etymo:"Anglais, « largage aérien »."},
  {name:"Tokenisation d'actifs",         en:"Asset Tokenization",            cat:"defi",         def:"Représentation d'un actif réel (immobilier, action, obligation, œuvre) par des jetons sur une blockchain, pour le fractionner et l'échanger. Le chantier des institutions financières.", ex:"Fonds monétaires tokenisés de BlackRock, obligations émises sur blockchain", etymo:"Token, anglais, « jeton ». Actif, du latin activus ; en comptabilité, ce qu'on possède (par opposition au passif)."},

  // Risques & Arnaques
  {name:"Rug pull",             en:"Rug Pull",                cat:"risques",      def:"Arnaque où les créateurs d'un jeton ou d'un projet retirent brusquement toute la liquidité et disparaissent avec les fonds, laissant un jeton sans valeur.", ex:"Le jeton Squid Game (2021), de 0 à 2 800 $ puis à zéro en minutes", etymo:"Anglais, « tirer le tapis » sous les pieds."},
  {name:"Pump and dump",        en:"Pump and Dump",           cat:"risques",      def:"Manipulation où un groupe gonfle artificiellement le prix d'un petit jeton par des achats et du battage, puis vend d'un coup aux acheteurs attirés.", ex:"Groupes Telegram coordonnant l'achat d'un jeton obscur", etymo:"Anglais, « gonfler et larguer »."},
  {name:"Phishing",             en:"Phishing",                cat:"risques",      ref:"securite", refName:"Hameçonnage"},
  {name:"Ingénierie sociale",   en:"Social Engineering",      cat:"risques",      ref:"securite"},
  {name:"Arnaque à la crypto",  en:"Crypto Scam",             cat:"risques",      def:"Escroqueries profitant de l'irréversibilité et de l'anonymat : faux conseillers, faux sites, promesses de rendement garanti, « investissement » via une relation en ligne, doublement de mise. Aucune plateforme légitime ne demande vos clés.", ex:"Fausse vidéo d'Elon Musk promettant de doubler les bitcoins envoyés", etymo:"Arnaque, de l'argot arnaquer, « escroquer », d'origine incertaine (peut-être harnacher, « attraper »)."},
  {name:"Schéma de Ponzi",      en:"Ponzi Scheme",            cat:"risques",      def:"Montage où les « rendements » des anciens participants sont payés avec l'argent des nouveaux, jusqu'à ce que les entrées ne suffisent plus. Beaucoup de projets crypto en ont la structure.", ex:"OneCoin, BitConnect, dans une certaine mesure FTX", etymo:"Du nom de Charles Ponzi, escroc de Boston (1920)."},
  {name:"Attaque des 51 %",     en:"51% Attack",              cat:"risques",      def:"Prise de contrôle d'une blockchain par un acteur détenant la majorité de la puissance de calcul ou des jetons en jeu, qui peut alors annuler ou réécrire des transactions. Impraticable sur Bitcoin, arrivé sur de petites chaînes.", ex:"Ethereum Classic attaqué à plusieurs reprises (2019-2020)", etymo:"Le pourcentage désigne la majorité de la puissance de calcul. Risque décrit dès le livre blanc de Bitcoin (2008)."},
  {name:"Piratage de protocole", en:"Protocol Hack",          cat:"risques",      def:"Exploitation d'une faille de smart contract ou de pont entre chaînes pour vider un protocole de ses fonds, souvent en quelques minutes et sans recours.", ex:"Ronin (2022, 600 millions de dollars), Poly Network (2021)", etymo:"Pirate, du grec peiratês, « qui tente l'aventure », de peiran, « essayer ». Sens informatique depuis les années 1980."},
  {name:"Perte de clés",        en:"Lost Keys",               cat:"risques",      def:"Perte définitive des fonds par perte de la clé privée ou de la phrase de récupération : disque jeté, papier brûlé, mot de passe oublié. Aucun recours n'existe. On estime perdus 20 % des bitcoins.", ex:"Un Gallois cherchant depuis 2013 un disque dur à 8 000 bitcoins dans une décharge", etymo:"Clé, du latin clavis. Perte, du latin perdita."},

  // Régulation & Fiscalité
  {name:"MiCA",                 en:"MiCA Regulation",         cat:"regulation",   def:"Règlement européen (2023, appliqué en 2024-2025) encadrant les cryptoactifs : agrément des prestataires, règles pour les stablecoins, information des investisseurs, lutte contre les abus de marché.", ex:"Un prestataire agréé dans un pays de l'UE peut opérer dans toute l'Union", etymo:"Sigle de l'anglais Markets in Crypto-Assets."},
  {name:"PSAN",                 en:"Registered Crypto Service Provider (France)", cat:"regulation", def:"Prestataire de services sur actifs numériques : statut français (2019) obligatoire pour les plateformes d'échange et de conservation, délivré par l'AMF, en cours de remplacement par l'agrément MiCA.", ex:"Une plateforme sans enregistrement PSAN opère illégalement en France", etymo:"Sigle."},
  {name:"KYC",                  en:"Know Your Customer",      cat:"regulation",   def:"Obligation pour les plateformes de vérifier l'identité de leurs clients (pièce d'identité, justificatif) contre le blanchiment et le financement du terrorisme. Rompt l'anonymat à l'entrée et à la sortie.", ex:"Selfie avec sa carte d'identité à l'inscription", etymo:"Sigle de l'anglais know your customer, « connais ton client »."},
  {name:"Fiscalité (France)",   en:"Crypto Taxation (France)", cat:"regulation",  def:"Les plus-values des particuliers sont imposées au moment de la conversion en euros ou en biens, à la flat tax de 30 %, au-delà de 305 € de cessions par an. Les échanges crypto contre crypto ne sont pas taxés. Comptes sur plateformes étrangères à déclarer.", ex:"Formulaire 2086 pour les plus-values, 3916-bis pour les comptes à l'étranger", etymo:"Fiscalité, du latin fiscus, « panier de jonc », puis « caisse de l'État » (le panier où l'on recueillait l'argent)."},
  {name:"Anonymat et traçabilité", en:"Pseudonymity and Traceability", cat:"regulation", def:"Les blockchains publiques sont pseudonymes, pas anonymes : les adresses ne portent pas de nom, mais toutes les transactions sont visibles à jamais et les sociétés d'analyse remontent les flux. Des cryptos dédiées cherchent le vrai anonymat.", ex:"Monero, Zcash ; enquêtes résolues par l'analyse de chaîne (Silk Road)", etymo:"Anonyme, du grec anônumos, « sans nom ». Traçabilité, de trace, du latin populaire tractiare, de trahere, « tirer »."},
  {name:"MNBC",                 en:"Central Bank Digital Currency (CBDC)", cat:"regulation", def:"Monnaie numérique de banque centrale : version numérique de l'euro ou du yuan émise par l'État, centralisée, tout l'inverse d'une cryptomonnaie malgré la technique voisine.", ex:"Euro numérique à l'étude par la BCE, yuan numérique déjà déployé en Chine", etymo:"Sigle de monnaie numérique de banque centrale."},

  // Histoire
  {name:"Satoshi Nakamoto",     en:"Satoshi Nakamoto",        cat:"histoire",     def:"Pseudonyme de l'inventeur de Bitcoin, auteur du livre blanc (octobre 2008) et du premier logiciel, disparu des forums en 2011 sans jamais avoir été identifié. Ses bitcoins n'ont jamais bougé.", ex:"Le satoshi, plus petite unité du bitcoin, porte son nom", etymo:"Pseudonyme japonais ; Satoshi peut signifier « sage, clairvoyant », Nakamoto « au centre, à l'origine ». Aucune preuve de son identité."},
  {name:"Livre blanc de Bitcoin", en:"Bitcoin Whitepaper",    cat:"histoire",     def:"Document de neuf pages, « Bitcoin : un système de paiement électronique pair-à-pair », publié le 31 octobre 2008 sur une liste de diffusion de cryptographes, en pleine crise financière. Tout le protocole y est.", ex:"Le bloc de genèse cite un titre de presse sur le renflouement des banques", etymo:"Livre blanc, calque de l'anglais white paper, terme de l'administration britannique pour un document d'orientation officiel (1922)."},
  {name:"Cypherpunks",          en:"Cypherpunks",             cat:"histoire",     def:"Mouvement des années 1990 militant pour la vie privée par la cryptographie et la monnaie électronique anonyme. Bitcoin en est l'aboutissement : plusieurs tentatives (DigiCash, b-money, Hashcash) l'ont précédé.", ex:"Manifeste cypherpunk d'Eric Hughes (1993), liste de diffusion où Satoshi publie", etymo:"Mot-valise anglais de cipher (chiffre) et cyberpunk."},
  {name:"Pizza Day",            en:"Bitcoin Pizza Day",       cat:"histoire",     def:"Le 22 mai 2010, un développeur paie deux pizzas 10 000 bitcoins : première transaction commerciale connue, commémorée chaque année comme le rappel que le bitcoin ne valait alors rien.", ex:"Ces 10 000 bitcoins vaudraient aujourd'hui des centaines de millions de dollars", etymo:"Pizza, italien, d'origine discutée (grec pitta, « galette », ou langobard bizzo, « bouchée »). Day, anglais, « jour »."},
  {name:"Mt. Gox",              en:"Mt. Gox",                 cat:"histoire",     def:"Première grande plateforme d'échange (Tokyo), traitant 70 % des transactions Bitcoin, en faillite en 2014 après le vol de 850 000 bitcoins. Le premier grand traumatisme de l'écosystème.", ex:"Les créanciers ont commencé à être remboursés en 2024", etymo:"À l'origine Magic: The Gathering Online eXchange, un site d'échange de cartes à jouer."},
  {name:"The Merge",            en:"The Merge",               cat:"histoire",     def:"Passage d'Ethereum de la preuve de travail à la preuve d'enjeu, le 15 septembre 2022, réduisant sa consommation d'électricité de 99,9 %. Réalisé sans interruption du réseau.", ex:"Comparé à changer le moteur d'un avion en vol", etymo:"Anglais, « la fusion », des deux chaînes existantes."},
  {name:"FTX",                  en:"FTX",                     cat:"histoire",     def:"Deuxième plateforme mondiale, effondrée en novembre 2022 : les dépôts des clients avaient servi à financer les paris de son fonds jumeau. Huit milliards de dollars de trou, son fondateur Sam Bankman-Fried condamné à 25 ans de prison (2024).", ex:"Détonateur du « crypto winter » et accélérateur de la régulation", etymo:"Abréviation de Futures Exchange, « bourse de contrats à terme », fondée par Sam Bankman-Fried en 2019."},
  {name:"ETF Bitcoin",          en:"Bitcoin ETF",             cat:"histoire",     def:"Fonds cotés en Bourse détenant des bitcoins, approuvés aux États-Unis en janvier 2024, qui permettent d'y investir via un compte-titres classique. Entrée des gestionnaires traditionnels et record de prix dans la foulée.", ex:"IBIT de BlackRock, des dizaines de milliards de dollars collectés la première année", etymo:"ETF, sigle de l'anglais exchange-traded fund, « fonds négocié en Bourse »."},
];

// ── DROIT & ADMINISTRATION ──
// Sous-lexique de Connaissance. Droit français, vocabulaire des démarches courantes. Repères pratiques, pas un conseil juridique : les seuils et taux changent, vérifier sur service-public.fr.
const terms_droit = [
  // Fondements
  {name:"Droit",                     en:"Law",                        cat:"fondements",  def:"Ensemble des règles qui organisent la vie en société et dont l'État garantit le respect. Le droit public régit les rapports avec l'État (constitutionnel, administratif, pénal), le droit privé les rapports entre personnes (civil, commercial, du travail).", ex:"Un litige avec un voisin relève du civil, une amende du pénal, un permis de construire de l'administratif", etymo:"Du latin directum, « ce qui est droit, sans déviation », de dirigere, « aligner ». Le latin classique disait jus, d'où justice, juridique, juge."},
  {name:"Loi",                       en:"Statute / Act",              cat:"fondements",  def:"Règle votée par le Parlement (Assemblée nationale et Sénat), promulguée par le président et publiée au Journal officiel. Elle s'impose à tous et ne peut être contredite que par la Constitution ou le droit européen.", ex:"Loi de 1901 sur les associations, loi de 1905 sur la laïcité, loi Informatique et libertés (1978)", etymo:"Du latin lex, legis, « loi », de legere, « lire, choisir » : ce qui est lu publiquement."},
  {name:"Décret et arrêté",          en:"Decree and Order",           cat:"fondements",  def:"Textes du pouvoir exécutif qui appliquent la loi : le décret est signé par le président ou le Premier ministre, l'arrêté par un ministre, un préfet ou un maire. Un arrêté municipal peut interdire le stationnement dans une rue.", ex:"Décret d'application d'une loi, arrêté préfectoral de restriction d'eau, arrêté municipal", etymo:"Décret, du latin decretum, « décision », de decernere, « décider ». Arrêté, participe de arrêter, « fixer, décider »."},
  {name:"Code",                      en:"Legal Code",                 cat:"fondements",  def:"Recueil ordonné des lois et règlements d'une matière. Le Code civil (1804) est la base du droit privé français ; il en existe plus de soixante-dix, tous consultables sur Légifrance.", ex:"Code civil, Code pénal, Code du travail, Code de la consommation, Code de la route", etymo:"Du latin codex, « tablette de bois », puis « livre » (par opposition au rouleau), puis « recueil de lois » (Code de Justinien, VIe siècle)."},
  {name:"Jurisprudence",             en:"Case Law",                   cat:"fondements",  def:"Ensemble des décisions de justice rendues sur une question, qui fixent la manière dont les tribunaux interprètent la loi. Une décision de la Cour de cassation fait référence pour les juges suivants.", ex:"C'est la jurisprudence qui a défini le harcèlement moral avant que la loi ne le fasse", etymo:"Du latin jurisprudentia, « science du droit » : jus (droit) + prudentia (connaissance, sagesse)."},
  {name:"Personne physique et morale", en:"Natural and Legal Person", cat:"fondements",  def:"Le droit reconnaît deux sortes de personnes : l'être humain (personne physique) et le groupement doté d'une existence juridique propre (personne morale : société, association, commune, État), qui peut posséder, contracter, agir en justice.", ex:"Une SARL signe un bail en son nom, pas au nom de son gérant", etymo:"Personne, du latin persona, « masque de théâtre », puis « rôle, personnage ». Morale, au sens de « qui n'a pas de corps »."},
  {name:"Responsabilité civile",     en:"Civil Liability",            cat:"fondements",  def:"Obligation de réparer le dommage causé à autrui, par sa faute, par les choses ou les personnes dont on répond. Se traduit par des dommages et intérêts ; l'assurance responsabilité civile la couvre au quotidien.", ex:"Un enfant casse la vitre du voisin : les parents réparent, leur assurance habitation paie", etymo:"Du latin respondere, « se porter garant, répondre de »."},
  {name:"Majorité et capacité",      en:"Legal Age and Capacity",     cat:"fondements",  def:"À 18 ans, une personne acquiert la capacité juridique : elle peut contracter, voter, ester en justice. Les mineurs et les majeurs protégés (tutelle, curatelle) sont représentés ou assistés.", ex:"Un mineur ne peut pas signer un bail seul ; un majeur sous tutelle non plus", etymo:"Capacité, du latin capacitas, « faculté de contenir », de capere, « prendre »."},
  {name:"Prescription",              en:"Statute of Limitations",     cat:"fondements",  def:"Délai au-delà duquel on ne peut plus agir en justice ou être poursuivi. Cinq ans en droit civil par défaut ; deux ans pour les dettes de consommation ; six ans pour un délit, vingt pour un crime.", ex:"Une facture impayée de 2018 ne peut plus être réclamée en justice", etymo:"Du latin praescriptio, « inscription en tête », puis « exception opposée à une action »."},
  {name:"Nul n'est censé ignorer la loi", en:"Ignorance of the Law Is No Excuse", cat:"fondements", def:"Principe selon lequel on ne peut se défendre en invoquant qu'on ignorait la règle. Fiction nécessaire, personne ne connaît les 70 codes ; d'où Légifrance et service-public.fr, gratuits et officiels.", ex:"« Je ne savais pas que c'était interdit » n'annule pas l'amende", etymo:"Traduction de l'adage latin nemo censetur ignorare legem, hérité du droit romain."},

  // Justice
  {name:"Tribunal judiciaire",       en:"Judicial Court",             cat:"justice",     def:"Juridiction de première instance pour les affaires civiles (litiges entre particuliers, famille, logement) et pénales (tribunal correctionnel pour les délits). Un par département au moins, issu de la fusion des tribunaux d'instance et de grande instance (2020).", ex:"Divorce, litige de plus de 10 000 €, vol simple", etymo:"Tribunal, du latin tribunal, « estrade du tribun », le magistrat qui rendait la justice."},
  {name:"Cour d'appel",              en:"Court of Appeal",            cat:"justice",     def:"Juridiction qui rejuge entièrement une affaire quand une partie conteste le premier jugement. Trente-six en France. Au-dessus, la Cour de cassation ne juge que le droit, pas les faits.", ex:"Délai d'appel : un mois en civil, dix jours en pénal", etymo:"Appel, du latin appellare, « adresser la parole, invoquer » : on en appelle à un juge supérieur."},
  {name:"Cour de cassation",         en:"Court of Cassation",         cat:"justice",     def:"Plus haute juridiction de l'ordre judiciaire, à Paris. Elle ne rejuge pas l'affaire : elle vérifie que le droit a été correctement appliqué et, sinon, « casse » la décision et renvoie devant une autre cour d'appel.", ex:"Ses arrêts font jurisprudence pour tous les tribunaux", etymo:"Casser, du latin quassare, « secouer, briser » : annuler une décision."},
  {name:"Conseil d'État",            en:"Council of State",           cat:"justice",     def:"Plus haute juridiction administrative, qui juge les litiges contre l'État et les administrations, et conseille le gouvernement sur les projets de loi. En dessous : tribunaux administratifs et cours administratives d'appel.", ex:"Contester un refus de permis de construire, un décret, une décision de préfecture", etymo:"Conseil, du latin consilium, « délibération ». Institution créée par Bonaparte en 1799, héritière du Conseil du roi."},
  {name:"Conseil de prud'hommes",    en:"Labour Court",               cat:"justice",     def:"Tribunal des litiges entre salariés et employeurs (licenciement, salaires impayés, harcèlement), composé à parité de juges salariés et employeurs. Une conciliation précède le jugement.", ex:"Contestation d'un licenciement dans les douze mois", etymo:"Prud'homme, de l'ancien français prod home, « homme de valeur, sage », de prod (profit, vaillance)."},
  {name:"Procédure civile",          en:"Civil Procedure",            cat:"justice",     def:"Déroulement d'un procès entre personnes privées : assignation ou requête, échange d'écritures, audience, jugement, voies de recours. L'avocat est obligatoire au-delà de 10 000 € et devant la cour d'appel.", ex:"Un litige de 3 000 € peut se plaider seul devant le tribunal judiciaire", etymo:"Procédure, du latin procedere, « s'avancer ». Civil, du latin civilis, « du citoyen » (civis)."},
  {name:"Contravention, délit, crime", en:"Petty Offence, Misdemeanour, Felony", cat:"justice", def:"Les trois degrés de l'infraction pénale, par gravité : contravention (amende, tribunal de police), délit (jusqu'à dix ans de prison, tribunal correctionnel), crime (réclusion, cour d'assises ou cour criminelle).", ex:"Excès de vitesse : contravention ; vol : délit ; meurtre : crime", etymo:"Délit, du latin delictum, « faute », de delinquere, « manquer ». Crime, du latin crimen, « accusation »."},
  {name:"Avocat",                    en:"Lawyer / Attorney",          cat:"justice",     def:"Professionnel qui conseille, rédige et représente en justice. Tenu au secret professionnel. Ses honoraires sont libres ; l'aide juridictionnelle les prend en charge sous condition de ressources.", ex:"Consultation gratuite dans les maisons de justice et du droit, permanences du barreau", etymo:"Du latin advocatus, « appelé auprès de » (pour assister) : ad (vers) + vocare (appeler)."},
  {name:"Commissaire de justice",    en:"Bailiff",                    cat:"justice",     def:"Nouveau nom (2022) de l'huissier de justice, fusionné avec le commissaire-priseur : il signifie les actes, constate (état des lieux, troubles) et exécute les décisions (saisies, expulsions).", ex:"Constat de dégât des eaux, signification d'un jugement, saisie sur compte", etymo:"Huissier, de huis, « porte » (ancien français), le gardien de la porte du tribunal."},
  {name:"Notaire",                   en:"Notary",                     cat:"justice",     def:"Officier public qui authentifie les actes importants (vente immobilière, testament, contrat de mariage, donation, succession) et les conserve. Ses tarifs sont réglementés ; il perçoit aussi les taxes pour l'État.", ex:"Les « frais de notaire » d'un achat immobilier sont surtout des impôts (7 à 8 % dans l'ancien)", etymo:"Du latin notarius, « secrétaire, sténographe », de nota, « marque, signe »."},
  {name:"Médiation et conciliation", en:"Mediation and Conciliation", cat:"justice",     def:"Modes de règlement amiable d'un litige avec un tiers neutre, obligatoires avant le juge pour les petits litiges (moins de 5 000 €) et les conflits de voisinage. Le conciliateur de justice est gratuit.", ex:"Conciliateur en mairie pour une haie qui dépasse, médiateur de la consommation pour un opérateur", etymo:"Médiation, du latin mediare, « être au milieu ». Conciliation, de conciliare, « unir, assembler »."},
  {name:"Mise en demeure",           en:"Formal Notice",              cat:"justice",     def:"Lettre, souvent recommandée, sommant quelqu'un d'exécuter son obligation dans un délai, dernier avertissement avant l'action en justice. Elle fait courir les intérêts de retard et prouve la bonne foi.", ex:"« Je vous mets en demeure de me régler la somme de … sous quinze jours »", etymo:"Demeure, ici au sens ancien de « retard » (demeurer, « tarder »)."},
  {name:"Aide juridictionnelle",     en:"Legal Aid",                  cat:"justice",     def:"Prise en charge par l'État de tout ou partie des frais d'avocat et de procédure pour les personnes aux revenus modestes.", ex:"Totale sous environ 1 000 € de revenus mensuels pour une personne seule (barème révisé chaque année)", etymo:"Juridiction, du latin jurisdictio, « action de dire le droit » : jus (droit) + dicere (dire). Créée en 1991, succède à l'aide judiciaire (1972)."},

  // Contrats
  {name:"Contrat",                   en:"Contract",                   cat:"contrats",    def:"Accord de volontés qui crée des obligations. Il se forme par le consentement, sans formalité en général : un devis signé, un clic sur « commander », un accord oral valent contrat. L'écrit sert de preuve.", ex:"Bail, contrat de travail, vente, abonnement, CGV acceptées", etymo:"Du latin contractus, de contrahere, « resserrer, engager » : con (ensemble) + trahere (tirer)."},
  {name:"Obligation",                en:"Obligation",                 cat:"contrats",    def:"Lien de droit par lequel une personne (le débiteur) doit quelque chose à une autre (le créancier) : payer, livrer, faire, ne pas faire. Naît du contrat, de la loi ou d'un dommage causé.", ex:"Le locataire doit payer le loyer, le bailleur doit un logement décent", etymo:"Du latin obligatio, de obligare, « lier à » : ob (devant) + ligare (lier)."},
  {name:"Clause",                    en:"Clause",                     cat:"contrats",    def:"Disposition particulière d'un contrat. Certaines sont interdites ou réputées non écrites, notamment les clauses abusives dans les contrats entre professionnel et consommateur.", ex:"Clause de non-concurrence, clause pénale, clause de résiliation", etymo:"Du latin clausula, « fin de phrase, conclusion », de claudere, « fermer »."},
  {name:"Conditions générales",      en:"Terms and Conditions",       cat:"contrats",    def:"Clauses standard qu'un professionnel applique à tous ses clients (CGV pour la vente, CGU pour un service en ligne). Elles ne s'imposent que si le client a pu en prendre connaissance et les a acceptées.", ex:"Case « J'accepte les CGV » avant paiement ; une clause abusive y est sans effet", etymo:"Condition, du latin condicio, « convention ». Général, du latin generalis, « qui appartient au genre entier »."},
  {name:"Devis et facture",          en:"Quote and Invoice",          cat:"contrats",    def:"Le devis décrit et chiffre une prestation avant accord ; signé, il engage les deux parties. La facture, obligatoire entre professionnels et au-delà de 25 € pour un particulier qui la demande, constate la créance et déclenche le paiement.", ex:"Mentions obligatoires d'une facture : date, numéro, identité des parties, détail, TVA", etymo:"Devis, de deviser, « répartir, décrire ». Facture, du latin factura, « fabrication », de facere."},
  {name:"Garantie",                  en:"Warranty",                   cat:"contrats",    def:"Engagement de répondre des défauts d'un bien ou d'une prestation. Garantie légale de conformité (deux ans sur tout bien acheté à un professionnel), garantie des vices cachés, garantie commerciale facultative, garantie décennale des constructeurs.", ex:"Un lave-linge en panne à 18 mois : réparation ou remplacement gratuit, sans discuter", etymo:"Du francique warjan, « protéger, assurer », d'où aussi garer et garder."},
  {name:"Droit de rétractation",     en:"Right of Withdrawal",        cat:"contrats",    def:"Faculté d'annuler sans motif un achat à distance (internet, téléphone) ou un démarchage à domicile dans les quatorze jours suivant la réception, remboursement intégral compris. Pas de rétractation en magasin, sauf geste commercial.", ex:"Commande en ligne renvoyée sous 14 jours ; exclusions : produits personnalisés, scellés ouverts, voyages datés", etymo:"Du latin retractare, « retirer, revenir sur », de retrahere."},
  {name:"Caution",                   en:"Guarantor / Deposit",        cat:"contrats",    def:"Deux sens : la personne qui s'engage à payer à la place d'un débiteur défaillant (caution d'un locataire, d'un emprunt), et, par abus, la somme déposée en garantie (dépôt de garantie). La caution personne signe un engagement lourd, souvent solidaire.", ex:"Les parents se portent caution pour le bail de leur enfant étudiant", etymo:"Du latin cautio, « précaution, garantie », de cavere, « prendre garde »."},
  {name:"Résiliation",               en:"Termination",                cat:"contrats",    def:"Fin d'un contrat à durée indéterminée ou reconduit, à l'initiative d'une partie, en respectant le préavis prévu. Les abonnements souscrits en ligne doivent pouvoir être résiliés en ligne, en trois clics (2023).", ex:"Résilier une box internet, une assurance après un an (loi Hamon), un abonnement de salle de sport", etymo:"Du latin resilire, « sauter en arrière, se dédire »."},
  {name:"Signature électronique",    en:"Electronic Signature",       cat:"contrats",    def:"Procédé numérique qui identifie le signataire et garantit l'intégrité du document, avec la même valeur qu'une signature manuscrite s'il est fiable. Trois niveaux (simple, avancée, qualifiée) selon le règlement européen eIDAS.", ex:"Bail ou compromis signé via DocuSign ou Yousign, code reçu par SMS", etymo:"Signature, du latin médiéval signatura, de signare. Électronique, du grec êlektron, « ambre ». Reconnue en droit français depuis 2000."},

  // Entreprise & Association
  {name:"Association loi 1901",      en:"Non-profit Association",     cat:"entreprise",  def:"Groupement d'au moins deux personnes autour d'un but non lucratif. Se crée librement, acquiert la personnalité morale par déclaration en préfecture et publication au Journal officiel. Peut avoir des salariés, vendre, recevoir des dons ; ne peut pas partager de bénéfices.", ex:"1,5 million d'associations en France ; statuts, bureau, assemblée générale annuelle", etymo:"Du latin associare, « joindre à », de socius, « compagnon ». Loi du 1er juillet 1901 sur le contrat d'association."},
  {name:"Statuts",                   en:"Articles of Association",    cat:"entreprise",  def:"Acte fondateur d'une société ou d'une association : nom, objet, siège, durée, organes de direction, règles de décision. Tout ce que les statuts ne disent pas relève de la loi.", ex:"Modifier les statuts exige une assemblée générale extraordinaire", etymo:"Du latin statutum, « ce qui a été établi », de statuere, « fixer, décider »."},
  {name:"Bureau et conseil d'administration", en:"Board and Executive Committee", cat:"entreprise", def:"Organes de direction d'une association : le conseil d'administration élu par l'assemblée, le bureau (président, trésorier, secrétaire) qui gère au quotidien. Le président représente l'association et engage sa responsabilité.", ex:"Le trésorier tient les comptes, le président signe les contrats", etymo:"Bureau, de bure, l'étoffe de laine qui couvrait la table de travail, du latin burra, « bourre ». Administration, du latin administrare, « servir, gérer »."},
  {name:"Assemblée générale",        en:"General Meeting",            cat:"entreprise",  def:"Réunion des membres ou associés qui approuve les comptes, élit les dirigeants et prend les grandes décisions. Ordinaire (annuelle) ou extraordinaire (modification des statuts). Une convocation et un procès-verbal sont nécessaires.", ex:"AG annuelle avec rapport moral et rapport financier", etymo:"Assemblée, de assembler, du latin populaire assimulare, « mettre ensemble » (simul)."},
  {name:"Micro-entreprise",          en:"Sole Trader (Micro Scheme)", cat:"entreprise",  def:"Régime simplifié de l'entrepreneur individuel : inscription en ligne, cotisations et impôt calculés en pourcentage du chiffre d'affaires, pas de TVA sous un seuil, comptabilité réduite à un livre de recettes. Plafonds de chiffre d'affaires.", ex:"Environ 77 000 € de CA pour les services, 188 000 € pour la vente ; cotisations autour de 21 % en services (chiffres 2025, à vérifier)", etymo:"Ex « auto-entrepreneur » (2009), renommé en 2016."},
  {name:"SARL et SAS",               en:"Limited Companies",          cat:"entreprise",  def:"Les deux formes de société les plus courantes, à responsabilité limitée aux apports. La SARL est encadrée par la loi (gérant, parts sociales) ; la SAS laisse les statuts organiser librement (président, actions), d'où sa faveur chez les startups. Versions à un seul associé : EURL et SASU.", ex:"Capital minimum : 1 € ; le dirigeant de SAS est assimilé salarié, le gérant majoritaire de SARL est travailleur indépendant", etymo:"SARL, sigle de société à responsabilité limitée (loi de 1925, importée d'Allemagne, GmbH). SAS, société par actions simplifiée (1994)."},
  {name:"SIRET et Kbis",             en:"Company Registration",       cat:"entreprise",  def:"Le SIREN (9 chiffres) identifie l'entreprise, le SIRET (14) chacun de ses établissements ; les deux figurent sur les factures. L'extrait Kbis est la « carte d'identité » d'une société immatriculée au registre du commerce, demandée par les banques et les clients.", ex:"Une association a un SIREN si elle emploie ou facture, mais pas de Kbis", etymo:"Kbis, du formulaire K bis du greffe du tribunal de commerce."},
  {name:"Objet social",              en:"Corporate Purpose",          cat:"entreprise",  def:"Activité que les statuts autorisent la société ou l'association à exercer. Un acte hors objet peut être contesté ; d'où des objets rédigés larges.", ex:"« Toute activité de conseil et de formation en informatique et, plus généralement, toute opération s'y rattachant »", etymo:"Objet, du latin objectum, « placé devant » : ce que la société se donne pour but."},
  {name:"Reçu fiscal",               en:"Tax Receipt",                cat:"entreprise",  def:"Document délivré par une association d'intérêt général à un donateur, qui lui ouvre droit à une réduction d'impôt de 66 % du don (75 % pour l'aide aux personnes en difficulté). L'association doit remplir les critères : but non lucratif, gestion désintéressée, pas de cercle restreint.", ex:"Un don de 100 € coûte 34 € au donateur", etymo:"Reçu, participe de recevoir, du latin recipere. Fiscal, du latin fiscus, « panier », puis « trésor public »."},

  // Travail
  {name:"Contrat de travail",        en:"Employment Contract",        cat:"travail",     def:"Convention par laquelle une personne travaille sous la subordination d'un employeur contre rémunération. Le CDI est la forme normale ; le CDD et l'intérim sont limités à des cas précis et à dix-huit mois en général.", ex:"CDI, CDD, intérim, apprentissage, temps partiel", etymo:"Travail, du latin populaire tripaliare, « torturer avec le tripalium », instrument à trois pieux : le mot a d'abord signifié « tourment »."},
  {name:"Période d'essai",           en:"Probation Period",           cat:"travail",     def:"Début du contrat pendant lequel chacun peut rompre sans motif ni indemnité, avec un court délai de prévenance. Deux mois pour un employé, quatre pour un cadre, renouvelable une fois si la convention collective le prévoit.", ex:"Rupture par l'employeur au bout de trois semaines : 48 heures de prévenance", etymo:"Essai, du latin exagium, « pesée », de exigere, « peser » : mettre à l'épreuve de la balance."},
  {name:"Licenciement",              en:"Dismissal",                  cat:"travail",     def:"Rupture du CDI à l'initiative de l'employeur, qui doit avoir une cause réelle et sérieuse (motif personnel ou économique) et suivre une procédure : convocation, entretien, lettre motivée, préavis, indemnité. Contestable aux prud'hommes.", ex:"Indemnité légale : un quart de mois de salaire par année d'ancienneté", etymo:"Du latin licentia, « permission » : à l'origine, autorisation de partir donnée à un soldat."},
  {name:"Rupture conventionnelle",   en:"Mutual Termination",         cat:"travail",     def:"Fin du CDI d'un commun accord entre salarié et employeur, avec indemnité au moins égale à celle du licenciement et droit au chômage. Homologuée par l'administration ; un délai de rétractation de quinze jours protège les deux parties.", ex:"Plus de 500 000 par an en France", etymo:"Rupture, du latin ruptura, de rumpere, « rompre ». Créée par la loi du 25 juin 2008."},
  {name:"Démission et préavis",      en:"Resignation and Notice",     cat:"travail",     def:"Rupture du CDI à l'initiative du salarié, sans motif à donner, mais avec un préavis (souvent un à trois mois selon le poste et la convention). Pas de chômage, sauf démission légitime ou projet de reconversion validé.", ex:"Lettre de démission datée, préavis négociable avec l'employeur", etymo:"Démission, du latin dimissio, « renvoi », de dimittere, « laisser aller ». Préavis, de pré- + avis, du latin visum, « ce qui est vu »."},
  {name:"Convention collective",     en:"Collective Agreement",       cat:"travail",     def:"Accord négocié entre syndicats et employeurs d'une branche, qui complète le Code du travail : grille de salaires, primes, préavis, congés. Elle s'applique à tous les salariés de la branche et doit figurer sur le bulletin de paie.", ex:"Syntec (informatique), HCR (hôtels-cafés-restaurants), Métallurgie", etymo:"Convention, du latin conventio, « accord », de convenire, « venir ensemble ». Première loi sur les conventions collectives : 1919."},
  {name:"Bulletin de paie",          en:"Payslip",                    cat:"travail",     def:"Document mensuel obligatoire détaillant le salaire brut, les cotisations salariales et patronales, le net à payer et le net imposable. Le brut est le coût pour l'employeur moins les cotisations patronales ; le net, environ 78 % du brut pour un non-cadre.", ex:"Salaire brut 2 500 € → net ≈ 1 950 € → net après impôt selon le taux de prélèvement", etymo:"Bulletin, de l'italien bullettino, diminutif de bulla, « sceau, bulle » : d'abord un billet scellé. Paie, de payer, du latin pacare, « apaiser » (le créancier)."},
  {name:"URSSAF",                    en:"URSSAF (Social Contributions Agency)", cat:"travail", def:"Organisme qui collecte les cotisations sociales des employeurs et des indépendants pour financer la Sécurité sociale (maladie, retraite, famille, chômage). C'est aussi lui qui gère les micro-entrepreneurs et le CESU.", ex:"Déclaration sociale nominative (DSN) chaque mois par l'employeur", etymo:"Sigle d'Union de recouvrement des cotisations de sécurité sociale et d'allocations familiales."},
  {name:"Congés payés et RTT",       en:"Paid Leave and RTT",         cat:"travail",     def:"Cinq semaines de congés payés par an (2,5 jours ouvrables par mois travaillé), acquis même en arrêt maladie depuis 2024. Les RTT compensent les heures faites au-delà de 35 heures dans les entreprises qui les pratiquent.", ex:"Un temps plein à 39 heures donne environ 23 jours de RTT par an", etymo:"RTT, sigle de réduction du temps de travail (lois Aubry, 1998-2000)."},
  {name:"Harcèlement",               en:"Harassment",                 cat:"travail",     def:"Agissements répétés dégradant les conditions de travail, la dignité ou la santé (harcèlement moral), ou propos et comportements à connotation sexuelle imposés (harcèlement sexuel). Délits, et fautes de l'employeur qui doit les prévenir.", ex:"Signalement au CSE, à l'inspection du travail, au médecin du travail ; plainte", etymo:"De harceler, dérivé de herseler, « passer la herse », puis « tourmenter »."},

  // Impôts & Cotisations
  {name:"Impôt sur le revenu",       en:"Income Tax",                 cat:"fiscalite",   def:"Impôt annuel sur l'ensemble des revenus du foyer (salaires, pensions, revenus fonciers, plus-values), par tranches progressives de 0 à 45 %, après abattements et quotient familial. Déclaré au printemps, prélevé à la source.", ex:"Tranches 2025 : 0 % jusqu'à ~11 500 €, 11 %, 30 %, 41 %, 45 % (seuils indexés chaque année)", etymo:"Impôt, du latin impositum, « ce qui est imposé », participe de imponere, « placer sur »."},
  {name:"Prélèvement à la source",   en:"Withholding Tax",            cat:"fiscalite",   def:"Depuis 2019, l'impôt sur le revenu est retenu chaque mois sur le salaire ou la pension, selon un taux calculé par l'administration à partir de la dernière déclaration. La déclaration annuelle régularise l'écart.", ex:"Taux personnalisé, individualisé (couple) ou neutre (non transmis à l'employeur)", etymo:"Prélever, du latin praelevare, « lever avant ». Source, du latin populaire sursa, « ce qui jaillit ». Mis en place en France en 2019, après un siècle de débats."},
  {name:"TVA",                       en:"VAT",                        cat:"fiscalite",   def:"Taxe sur la valeur ajoutée, payée par le consommateur final et collectée par les entreprises, qui reversent la différence entre TVA encaissée et TVA payée sur leurs achats. Première recette de l'État.", ex:"20 % (normal), 10 % (restauration, travaux), 5,5 % (alimentation, livres), 2,1 % (médicaments remboursés)", etymo:"Inventée par l'inspecteur des finances Maurice Lauré en 1954, adoptée depuis par 170 pays."},
  {name:"Cotisations sociales",      en:"Social Security Contributions", cat:"fiscalite", def:"Prélèvements sur les salaires et les revenus d'activité qui financent la protection sociale : maladie, retraite, chômage, famille, accidents du travail. Part salariale (retenue sur le brut) et part patronale (en plus du brut).", ex:"Sur 100 € de salaire net, l'employeur débourse environ 180 € au total", etymo:"Cotiser, de cote, du latin médiéval quota (pars), « part attribuée à chacun », de quot, « combien »."},
  {name:"CSG et CRDS",               en:"CSG and CRDS",               cat:"fiscalite",   def:"Contributions prélevées sur presque tous les revenus (salaires, pensions, placements) pour financer la Sécurité sociale et rembourser sa dette. Environ 9,7 % sur les salaires, dont une partie non déductible de l'impôt.", ex:"Ligne « CSG/CRDS » du bulletin de paie", etymo:"Sigles de contribution sociale généralisée (1991) et contribution au remboursement de la dette sociale (1996)."},
  {name:"Taxe foncière et taxe d'habitation", en:"Property Taxes",    cat:"fiscalite",   def:"Impôts locaux au profit des communes. La taxe foncière est due par le propriétaire chaque année ; la taxe d'habitation ne subsiste que sur les résidences secondaires depuis 2023.", ex:"Avis reçu à l'automne, calculé sur une valeur locative cadastrale souvent ancienne", etymo:"Taxe, du latin taxare, « évaluer, estimer ». Foncier, de fonds, du latin fundus, « fond, propriété »."},
  {name:"Flat tax (PFU)",            en:"Flat Tax on Capital Income", cat:"fiscalite",   def:"Prélèvement forfaitaire unique de 30 % (12,8 % d'impôt + 17,2 % de prélèvements sociaux) sur les revenus du capital : intérêts, dividendes, plus-values mobilières, cryptos. Option possible pour le barème progressif si plus favorable.", ex:"1 000 € de dividendes → 300 € prélevés", etymo:"PFU, sigle de prélèvement forfaitaire unique (2018)."},
  {name:"Crédit et réduction d'impôt", en:"Tax Credit and Tax Reduction", cat:"fiscalite", def:"Avantages fiscaux pour certaines dépenses : la réduction diminue l'impôt dû (perdue si on n'en paie pas), le crédit est remboursé même aux non-imposables. Dons, emploi à domicile, garde d'enfant, travaux énergétiques.", ex:"Emploi à domicile : crédit de 50 % des sommes versées", etymo:"Crédit, de l'italien credito, du latin creditum, « chose confiée ». Réduction, du latin reductio, « action de ramener »."},
  {name:"Déclaration de revenus",    en:"Tax Return",                 cat:"fiscalite",   def:"Formulaire annuel, en ligne d'avril à juin, pré-rempli des salaires et pensions connus, à compléter (revenus fonciers, cryptos, comptes à l'étranger) et à vérifier. Obligatoire même sans impôt à payer.", ex:"Formulaire 2042 et ses annexes, avis d'imposition en été", etymo:"Déclarer, du latin declarare, « rendre clair » (clarus). Revenu, participe de revenir : ce qui « revient » chaque année."},

  // Démarches & Administration
  {name:"Service public",            en:"Public Service",             cat:"demarches",   def:"Activité d'intérêt général assurée ou contrôlée par une administration : école, hôpital, justice, poste, état civil. Le site service-public.fr en est le guichet officiel, avec les démarches, délais et formulaires.", ex:"Renouveler une carte d'identité, demander un acte de naissance, simuler ses droits", etymo:"Service, du latin servitium, « condition d'esclave », puis « fonction utile ». Notion juridique construite par le Conseil d'État (arrêt Blanco, 1873)."},
  {name:"Mairie",                    en:"Town Hall",                  cat:"demarches",   def:"Administration de la commune, premier guichet du citoyen : état civil, élections, urbanisme (permis de construire), école, cantine, cimetière. Le maire est aussi officier d'état civil et de police judiciaire.", ex:"Acte de naissance, inscription sur les listes électorales, déclaration de travaux", etymo:"De maire, du latin major, « plus grand », le principal officier d'une commune."},
  {name:"Préfecture",                en:"Prefecture",                 cat:"demarches",   def:"Représentation de l'État dans le département, dirigée par le préfet : titres de séjour, associations, permis de conduire et cartes grises (désormais en ligne à l'ANTS), ordre public, arrêtés.", ex:"Déclaration d'une association, titre de séjour, arrêté de restriction d'eau", etymo:"Du latin praefectura, de praefectus, « placé à la tête de » : prae (devant) + facere (faire)."},
  {name:"État civil",                en:"Civil Status",               cat:"demarches",   def:"Enregistrement officiel des naissances, mariages et décès par la mairie, et actes qui en résultent. L'acte de naissance est demandé pour la plupart des démarches d'identité et de famille.", ex:"Acte de naissance, livret de famille, acte de décès ; demande gratuite en ligne", etymo:"État, du latin status, « situation ». Civil, du latin civilis. Les registres passent des curés aux maires en 1792."},
  {name:"FranceConnect",             en:"FranceConnect (Digital ID)", cat:"demarches",   def:"Système de connexion unique aux services publics en ligne avec un compte existant (impots.gouv, Ameli, La Poste…). FranceConnect+ ajoute l'identité numérique certifiée pour les démarches sensibles.", ex:"Se connecter à l'ANTS ou à la CAF avec ses identifiants impots.gouv", etymo:"Nom du service de l'État lancé en 2016, de France et de l'anglais connect, « relier »."},
  {name:"Recours gracieux et contentieux", en:"Administrative Appeal", cat:"demarches", def:"Pour contester une décision administrative : d'abord le recours gracieux (demander à l'auteur de revoir) ou hiérarchique (à son supérieur), puis le recours contentieux devant le tribunal administratif, dans les deux mois de la décision.", ex:"Refus de permis de construire, amende contestée, décision de la CAF", etymo:"Recours, du latin recursus, « retour en arrière ». Gracieux, du latin gratiosus, « obligeant » : demandé comme une grâce. Contentieux, du latin contentiosus, « querelleur »."},
  {name:"Silence de l'administration", en:"Administrative Silence",   cat:"demarches",   def:"Depuis 2015, le silence gardé deux mois sur une demande vaut en principe acceptation ; mais les exceptions sont nombreuses (finances, étrangers, urbanisme…), où il vaut rejet. Toujours demander un accusé de réception.", ex:"Demande de subvention sans réponse : rejet implicite ; certaines autorisations : acceptation tacite", etymo:"Silence, du latin silentium, de silere, « se taire ». Le principe « silence vaut acceptation » date de la loi du 12 novembre 2013."},
  {name:"CNIL",                      en:"CNIL (Data Protection Authority)", cat:"demarches", def:"Autorité indépendante qui veille à la protection des données personnelles et applique le RGPD en France : conseils, contrôles, sanctions, réception des plaintes.", ex:"Plainte en ligne contre un site qui refuse d'effacer vos données", etymo:"Sigle de Commission nationale de l'informatique et des libertés (1978)."},
  {name:"Défenseur des droits",      en:"Defender of Rights (Ombudsman)", cat:"demarches", def:"Autorité indépendante saisissable gratuitement par toute personne en litige avec une administration, victime de discrimination, ou pour les droits de l'enfant et la déontologie des forces de l'ordre. Délégués dans chaque département.", ex:"Dossier de retraite bloqué, refus de logement discriminatoire", etymo:"Défenseur, du latin defensor, de defendere, « écarter, protéger ». Autorité créée par la réforme constitutionnelle de 2008, en place depuis 2011."},
  {name:"Lettre recommandée",        en:"Registered Letter",          cat:"demarches",   def:"Envoi postal daté et suivi, avec accusé de réception, qui prouve qu'un courrier a été envoyé et reçu. Exigée ou prudente pour résilier, mettre en demeure, contester. La version électronique a la même valeur.", ex:"Résiliation de bail, contestation d'une facture, démission", etymo:"Recommander, du latin médiéval recommendare, « confier à la garde de ». Service postal créé en France en 1829."},

  // Famille & Patrimoine
  {name:"Mariage civil et PACS",     en:"Civil Marriage and Civil Union", cat:"famille", def:"Deux unions reconnues par la loi. Le mariage, célébré en mairie, crée des devoirs mutuels, une protection du survivant et des droits à la succession ; le PACS, contrat enregistré en mairie ou chez un notaire, est plus léger à conclure et à rompre, sans droit successoral automatique.", ex:"Le partenaire pacsé n'hérite pas sans testament ; l'époux, si", etymo:"PACS, sigle de pacte civil de solidarité (1999)."},
  {name:"Régime matrimonial",        en:"Matrimonial Regime",         cat:"famille",     def:"Règles de propriété des biens entre époux. Sans contrat, c'est la communauté réduite aux acquêts : ce qui est acquis pendant le mariage est commun, ce qui vient d'avant ou d'un héritage reste propre. La séparation de biens se choisit par contrat chez le notaire.", ex:"Une maison achetée pendant le mariage appartient aux deux, même payée par un seul", etymo:"Régime, du latin regimen, « direction ». Matrimonial, du latin matrimonium, « mariage », de mater, « mère » : l'état qui fait la mère."},
  {name:"Divorce",                   en:"Divorce",                    cat:"famille",     def:"Dissolution du mariage. Par consentement mutuel, il se fait sans juge, par acte d'avocats déposé chez un notaire (2017). Sinon devant le juge aux affaires familiales, qui règle aussi la garde des enfants, la pension alimentaire et la prestation compensatoire.", ex:"Divorce amiable en quelques mois, contentieux en un à deux ans", etymo:"Du latin divortium, « séparation », de divertere, « se détourner »."},
  {name:"Autorité parentale",        en:"Parental Authority",         cat:"famille",     def:"Ensemble des droits et devoirs des parents envers l'enfant mineur : le protéger, l'éduquer, décider pour lui, gérer ses biens. Exercée en commun, même après séparation, sauf décision du juge.", ex:"Les deux parents signent pour un passeport, une opération, un changement d'école", etymo:"Autorité, du latin auctoritas, « garantie, pouvoir », de auctor. Remplace la « puissance paternelle » en 1970."},
  {name:"Succession",                en:"Inheritance",                cat:"famille",     def:"Transmission du patrimoine d'une personne décédée. Sans testament, la loi fixe l'ordre des héritiers (enfants, puis conjoint, parents, frères et sœurs). Les enfants ont une part réservée intouchable ; le reste, la quotité disponible, se lègue librement.", ex:"Deux enfants : réserve des deux tiers, un tiers disponible ; abattement fiscal de 100 000 € par enfant", etymo:"Du latin successio, « action de venir après », de succedere."},
  {name:"Testament",                 en:"Will",                       cat:"famille",     def:"Acte par lequel on décide du sort de ses biens après sa mort, dans la limite de la réserve des héritiers. Le testament olographe, écrit en entier à la main, daté et signé, est valable sans notaire ; le déposer chez lui évite qu'il se perde.", ex:"Léguer à son partenaire pacsé, à une association, désigner un tuteur pour ses enfants", etymo:"Du latin testamentum, de testari, « prendre à témoin »."},
  {name:"Donation",                  en:"Gift / Donation",            cat:"famille",     def:"Transmission de son vivant, irrévocable, par acte notarié pour les biens importants. Chaque parent peut donner 100 000 € par enfant tous les quinze ans sans droits ; les dons d'argent aux descendants bénéficient d'un abattement supplémentaire de 31 865 €.", ex:"Don manuel d'argent déclaré en ligne, donation-partage entre les enfants", etymo:"Du latin donatio, de donare, « donner », de donum, « don »."},
  {name:"Indivision",                en:"Joint Ownership",            cat:"famille",     def:"Situation où plusieurs personnes possèdent ensemble un même bien, chacune pour une quote-part, sans division matérielle. Fréquente après une succession ou un achat en couple non marié ; « nul n'est tenu de demeurer dans l'indivision ».", ex:"Une maison héritée par trois frères et sœurs, jusqu'au partage ou à la vente", etymo:"Du latin indivisus, « non divisé »."},
  {name:"Tutelle et curatelle",      en:"Guardianship",               cat:"famille",     def:"Mesures de protection d'un majeur dont les facultés sont altérées, décidées par le juge : la curatelle l'assiste pour les actes importants, la tutelle le représente. Le mandat de protection future permet de choisir à l'avance qui s'en chargera.", ex:"Parent âgé atteint d'Alzheimer, adulte handicapé", etymo:"Tutelle, du latin tutela, « protection », de tueri, « veiller sur ». Curatelle, du latin curator, « celui qui prend soin » (cura)."},

  // Logement
  {name:"Bail d'habitation",         en:"Residential Lease",          cat:"logement",    def:"Contrat de location d'un logement, très encadré (loi de 1989) : trois ans renouvelables pour un logement vide, un an pour un meublé, loyer et charges définis, obligations réciproques. Un état des lieux et des diagnostics l'accompagnent.", ex:"Le propriétaire ne peut donner congé qu'à l'échéance, pour vendre, habiter ou motif sérieux", etymo:"De bailler, « donner, remettre », du latin bajulare, « porter »."},
  {name:"Dépôt de garantie",         en:"Security Deposit",           cat:"logement",    def:"Somme versée à l'entrée dans les lieux pour couvrir d'éventuels manquements du locataire : un mois de loyer hors charges maximum pour un logement vide, deux pour un meublé. Rendue dans le mois (ou deux si retenues justifiées) après l'état des lieux de sortie.", ex:"Souvent appelé « caution » à tort", etymo:"Dépôt, du latin depositum, « chose déposée ». Garantie, du francique warjan, « protéger »."},
  {name:"État des lieux",            en:"Inventory of Fixtures",      cat:"logement",    def:"Description détaillée du logement, pièce par pièce, à l'entrée et à la sortie, signée par les deux parties. La comparaison des deux décide des retenues sur le dépôt de garantie ; l'usure normale reste à la charge du propriétaire.", ex:"Photos datées, relevé des compteurs, état des peintures et des sols", etymo:"Lieu, du latin locus. Locution attestée en droit depuis le XVIIIe siècle."},
  {name:"Préavis de location",       en:"Notice Period (Tenancy)",    cat:"logement",    def:"Délai à respecter par le locataire qui part : trois mois pour un logement vide, réduit à un mois en zone tendue, en meublé, ou pour mutation, perte d'emploi, santé. Le propriétaire, lui, doit six mois avant l'échéance du bail.", ex:"Lettre recommandée ou remise en main propre contre signature", etymo:"Location, du latin locatio, « louage », de locare, « placer, louer »."},
  {name:"Charges locatives",         en:"Service Charges",            cat:"logement",    def:"Dépenses du propriétaire que le locataire rembourse : entretien des parties communes, ascenseur, eau, chauffage collectif, taxe d'ordures ménagères. Payées par provisions mensuelles et régularisées chaque année sur justificatifs.", ex:"« Loyer 700 € + 80 € de provision sur charges »", etymo:"Charge, du latin populaire carricare, « charger un char ». Locatif, du latin locativus."},
  {name:"Copropriété",               en:"Co-ownership",               cat:"logement",    def:"Immeuble divisé en lots appartenant à des propriétaires différents, avec des parties communes gérées ensemble. Le syndicat des copropriétaires décide en assemblée générale, le syndic exécute et administre, le conseil syndical contrôle.", ex:"Vote des travaux de ravalement, charges de copropriété au tantième", etymo:"Du latin co- (ensemble) + proprietas, « propriété »."},
  {name:"Diagnostics immobiliers",   en:"Property Diagnostics",       cat:"logement",    def:"Documents obligatoires à la vente ou à la location : performance énergétique (DPE, de A à G), amiante, plomb, électricité, gaz, termites, risques naturels. Un logement classé G ne peut plus être loué depuis 2025, F à partir de 2028.", ex:"Le DPE est affiché dès l'annonce et engage le vendeur", etymo:"Diagnostic, du grec diagnôsis, « discernement », de diagignôskein, « distinguer »."},
  {name:"Compromis et acte de vente", en:"Preliminary and Final Sale Agreement", cat:"logement", def:"L'achat immobilier se fait en deux temps : le compromis (ou promesse) engage vendeur et acheteur, avec dix jours de rétractation pour l'acheteur et des conditions suspensives (prêt) ; l'acte authentique chez le notaire, environ trois mois après, transfère la propriété.", ex:"Dépôt de garantie de 5 à 10 % au compromis ; frais de notaire à l'acte", etymo:"Compromis, du latin compromissum, « engagement réciproque de s'en remettre à un arbitre » (cum + promittere). Acte, du latin actum, « chose faite »."},

  // Consommation
  {name:"Garantie légale de conformité", en:"Legal Guarantee of Conformity", cat:"consommation", def:"Tout bien acheté à un professionnel doit être conforme pendant deux ans (un an pour l'occasion) : en cas de défaut, réparation ou remplacement gratuits, sans avoir à prouver l'origine de la panne. S'applique aussi aux contenus et services numériques.", ex:"Téléphone en panne à 20 mois : c'est au vendeur d'agir, pas au fabricant", etymo:"Conformité, du latin conformis, « de même forme ». Garantie issue d'une directive européenne de 1999, renforcée en 2022."},
  {name:"Clause abusive",            en:"Unfair Term",                cat:"consommation", def:"Clause d'un contrat entre professionnel et consommateur qui crée un déséquilibre significatif au détriment de ce dernier. Réputée non écrite : elle ne s'applique pas, même signée. La Commission des clauses abusives en publie des listes.", ex:"Frais de résiliation disproportionnés, modification unilatérale du prix, exclusion de toute responsabilité", etymo:"Clause, du latin clausula, « fin de phrase ». Abusif, du latin abusivus, de abuti, « user jusqu'au bout, mésuser ». Notion de la loi Scrivener (1978)."},
  {name:"Démarchage",                en:"Doorstep Selling / Cold Calling", cat:"consommation", def:"Vente à domicile, par téléphone ou sur un lieu inhabituel. Très encadré : contrat écrit, quatorze jours de rétractation, interdiction d'encaisser avant sept jours pour le domicile. Le démarchage téléphonique est interdit sans accord préalable depuis août 2026.", ex:"Rénovation énergétique, alarmes, panneaux solaires : les secteurs les plus signalés", etymo:"De marcher : aller de porte en porte."},
  {name:"Médiateur de la consommation", en:"Consumer Ombudsman",      cat:"consommation", def:"Tiers gratuit que tout professionnel doit proposer pour régler un litige avec un consommateur avant le tribunal. Chaque secteur a le sien (énergie, télécoms, banque, assurance, e-commerce).", ex:"Médiateur des communications électroniques pour un litige avec un opérateur", etymo:"Médiateur, du latin mediator, « qui s'interpose », de medius, « milieu ». Consommation, du latin consummatio, « achèvement »."},
  {name:"DGCCRF",                    en:"DGCCRF (Consumer Protection Authority)", cat:"consommation", def:"Administration qui contrôle la loyauté des pratiques commerciales, la sécurité des produits et la concurrence. SignalConso permet de lui signaler un problème et d'en informer le professionnel.", ex:"Prix affiché non respecté, fausse promotion, produit dangereux", etymo:"Sigle de Direction générale de la concurrence, de la consommation et de la répression des fraudes."},
  {name:"Surendettement",            en:"Over-indebtedness",          cat:"consommation", def:"Impossibilité durable de faire face à ses dettes. La commission de surendettement de la Banque de France, saisie gratuitement, peut rééchelonner, geler ou effacer les dettes. Le dépôt du dossier suspend les poursuites.", ex:"Plus de 100 000 dossiers déposés par an", etymo:"Du préfixe sur- (excès) et endettement, de dette, du latin debita. Procédure créée par la loi Neiertz (1989)."},
  {name:"Crédit à la consommation",  en:"Consumer Credit",            cat:"consommation", def:"Prêt de 200 à 75 000 € pour un usage privé (voiture, travaux, trésorerie), encadré : fiche d'information, vérification de solvabilité, quatorze jours de rétractation, remboursement anticipé possible. Le crédit renouvelable est le plus coûteux.", ex:"Paiement en plusieurs fois, prêt personnel, crédit affecté à un achat", etymo:"Crédit, du latin creditum, « chose confiée ». Encadré par la loi Scrivener (1978) puis la loi Lagarde (2010)."},
];

// ── DÉVELOPPEMENT ──
// Sous-lexique d'Informatique. Les outils propres au web (bundler, frameworks front) restent dans Web.
const terms_developpement = [
  // Fondements
  {name:"Développement logiciel",  en:"Software Development",       cat:"fondements",  def:"Activité de conception, d'écriture, de test et de maintenance des programmes. Va de l'idée au code qui tourne, puis à sa correction et son évolution, qui représentent la majeure partie du coût d'un logiciel.", ex:"Une application mobile, un site, un script d'automatisation, un système d'exploitation", etymo:"Développement, de développer, « ôter de l'enveloppe » (des-veloper). Logiciel, mot créé en 1970 pour traduire software."},
  {name:"Code source",             en:"Source Code",                cat:"fondements",  def:"Texte écrit par le développeur dans un langage de programmation, lisible par un humain, à partir duquel le programme exécutable est produit. C'est lui qu'on versionne, relit et partage.", ex:"Un fichier .py, .js ou .c ; le code source de Linux fait plus de 30 millions de lignes", etymo:"Code, du latin codex, « livre » ; source, du latin populaire sursa, « ce qui jaillit »."},
  {name:"Programme",               en:"Program",                    cat:"fondements",  def:"Suite d'instructions qu'un ordinateur exécute pour accomplir une tâche. Le code source en est l'écriture, l'exécutable sa forme prête à tourner, le processus son exécution en cours.", ex:"Un navigateur, une calculatrice, un script de sauvegarde", etymo:"Du grec programma, « ce qui est écrit à l'avance » : pro- (avant) + graphein (écrire)."},
  {name:"Langage de programmation", en:"Programming Language",      cat:"fondements",  def:"Langage formel, à la syntaxe stricte, permettant d'écrire des instructions exécutables par un ordinateur. Chacun a ses forces : Python pour la simplicité et la donnée, JavaScript pour le web, C pour la performance, Rust pour la sûreté.", ex:"Python, JavaScript, C, Java, Rust, Go, SQL ; plusieurs milliers existent, une vingtaine comptent", etymo:"Langage, du latin lingua, « langue ». Programmation, du grec programma, « ce qui est écrit à l'avance » : pro- (avant) + graphein (écrire)."},
  {name:"Compilateur",             en:"Compiler",                   cat:"fondements",  def:"Programme qui traduit d'un coup le code source en code machine exécutable, en signalant les erreurs avant l'exécution. Par opposition à l'interpréteur, qui lit et exécute le code ligne à ligne.", ex:"GCC (C), javac (Java), rustc (Rust) ; Python et JavaScript sont interprétés, avec compilation à la volée", etymo:"Du latin compilare, « piller, entasser », de pila, « pile ». Sens informatique fixé par Grace Hopper (1952), qui « rassemblait » des sous-programmes."},
  {name:"Interpréteur",            en:"Interpreter",                cat:"fondements",  def:"Programme qui exécute le code source directement, instruction par instruction, sans produire d'exécutable. Plus souple, plus lent, idéal pour scripter et expérimenter.", ex:"python, node, bash lisent et exécutent un fichier à la volée", etymo:"Du latin interpres, « intermédiaire, traducteur »."},
  {name:"Bibliothèque logicielle",            en:"Software Library",                    cat:"fondements",  def:"Ensemble de fonctions prêtes à l'emploi qu'un programme appelle pour ne pas tout réécrire : dates, réseau, calcul, interface. On l'appelle ; un framework, lui, vous appelle.", ex:"requests (Python), lodash (JavaScript), la bibliothèque standard de chaque langage", etymo:"Du grec bibliothêkê, « dépôt de livres » ; calque de l'anglais library."},
  {name:"Framework",               en:"Framework",                  cat:"fondements",  def:"Cadre logiciel qui impose une structure et un fonctionnement à l'application, dans lequel le développeur insère son code. Il dicte l'architecture, gère le cycle de vie et fournit les briques courantes.", ex:"Django et Flask (Python), React et Next.js (JavaScript), Spring (Java), Laravel (PHP)", etymo:"Anglais, « charpente, ossature » : frame (cadre) + work (ouvrage). Sens logiciel depuis les années 1990."},
  {name:"Algorithme",              en:"Algorithm",                  cat:"fondements",  ref:"informatique"},
  {name:"Open source",             en:"Open Source",                cat:"fondements",  ref:"informatique"},
  {name:"Dépendance",              en:"Dependency",                 cat:"fondements",  def:"Bibliothèque ou paquet dont un projet a besoin pour fonctionner, déclaré dans un fichier de manifeste et installé par un gestionnaire de paquets. Un projet moderne en compte des centaines, elles-mêmes dépendantes d'autres.", ex:"package.json, requirements.txt ; l'incident left-pad (2016) : onze lignes retirées de npm cassent la moitié du web", etymo:"Du latin dependere, « pendre de, être suspendu à »."},

  // Langages
  {name:"Python",                  en:"Python",                     cat:"langages",    def:"Langage interprété, lisible, à tout faire : scripts, données, IA, web, automatisation. Premier langage enseigné et le plus utilisé au monde depuis les années 2020. L'indentation y structure le code.", ex:"print(\"Bonjour\") ; bibliothèques pandas, NumPy, Django", etymo:"Nommé par son créateur Guido van Rossum (1991) d'après les Monty Python, pas le serpent."},
  {name:"JavaScript",              en:"JavaScript",                 cat:"langages",    ref:"web"},
  {name:"TypeScript",              en:"TypeScript",                 cat:"langages",    ref:"web"},
  {name:"C",                       en:"C",                          cat:"langages",    def:"Langage compilé de bas niveau (1972), proche de la machine, rapide et sans filet : gestion manuelle de la mémoire. Base des systèmes d'exploitation, des langages qui l'ont suivi (C++, Java, C#…) et de l'embarqué.", ex:"Linux, Git, Python lui-même sont écrits en C", etymo:"Successeur du langage B, lui-même dérivé de BCPL. Créé par Dennis Ritchie aux Bell Labs."},
  {name:"Java",                    en:"Java",                       cat:"langages",    def:"Langage compilé vers une machine virtuelle (JVM), orienté objet, portable (« écrire une fois, exécuter partout »). Omniprésent dans les grandes entreprises, les banques, Android.", ex:"Applications bancaires, Minecraft, apps Android historiques", etymo:"Nommé (1995) d'après le café de Java, l'île indonésienne, que buvaient ses créateurs chez Sun ; d'abord appelé Oak."},
  {name:"Rust",                    en:"Rust",                       cat:"langages",    def:"Langage compilé (2015, Mozilla) aussi rapide que C mais qui garantit la sûreté de la mémoire à la compilation, sans ramasse-miettes. Adopté par Linux, Android, Windows pour le code critique.", ex:"Le compilateur refuse un programme qui pourrait avoir un accès mémoire invalide", etymo:"Anglais, « rouille », nom choisi d'après un champignon (la rouille) réputé robuste et distribué."},
  {name:"Go",                      en:"Go",                         cat:"langages",    def:"Langage compilé de Google (2009), simple et efficace pour les serveurs et les outils réseau, avec la concurrence intégrée (goroutines). Docker et Kubernetes sont écrits en Go.", ex:"Un binaire unique, sans dépendance, qui démarre instantanément", etymo:"Anglais, « aller » : un langage qui « va » vite. Créé par Robert Griesemer, Rob Pike et Ken Thompson chez Google (2009) ; aussi appelé Golang."},
  {name:"SQL",                     en:"SQL",                        cat:"langages", ref:"bdd"},
  {name:"Bash",                    en:"Bash",                       cat:"langages",    def:"Interpréteur de commandes et langage de script des systèmes Unix et Linux : enchaîner des commandes, automatiser, administrer. Le terminal par défaut de la plupart des serveurs.", ex:"for f in *.csv; do wc -l \"$f\"; done", etymo:"Sigle de Bourne-Again SHell (1989), jeu de mots sur le Bourne shell qu'il remplace et « born again »."},
  {name:"Typage",                  en:"Typing",                     cat:"langages",    def:"Manière dont un langage traite les types de données (nombre, texte, liste…). Statique (vérifié à la compilation : Java, Rust, TypeScript) ou dynamique (à l'exécution : Python, JavaScript) ; fort ou faible selon la tolérance aux mélanges.", ex:"\"3\" + 1 vaut \"31\" en JavaScript, erreur en Python", etymo:"Type, du grec tupos, « empreinte, modèle »."},

  // Notions de base
  {name:"Variable",                en:"Variable",                   cat:"notions",     def:"Nom donné à un emplacement de mémoire qui contient une valeur susceptible de changer pendant l'exécution. Une constante, elle, ne change pas.", ex:"let age = 42; — la valeur peut changer ensuite ; const PI = 3.14 ne le peut pas", etymo:"Du latin variabilis, « changeant », de variare, « diversifier ». Sens mathématique au XVIIIe siècle, informatique dès les premiers langages (années 1950)."},
  {name:"Fonction",                en:"Function",                   cat:"notions",     def:"Bloc de code nommé, réutilisable, qui reçoit des paramètres et renvoie un résultat. Découper un programme en fonctions courtes est la première règle de lisibilité.", ex:"function aire(largeur, hauteur) { return largeur * hauteur; }", etymo:"Du latin functio, « accomplissement », de fungi, « s'acquitter de ». Sens mathématique dû à Leibniz (1694)."},
  {name:"Condition",               en:"Conditional",                cat:"notions",     def:"Instruction qui exécute un bloc ou un autre selon qu'une expression est vraie ou fausse : if / else. C'est ce qui fait qu'un programme décide.", ex:"if (age >= 18) { … } else { … }", etymo:"Du latin condicio, « convention, clause », de condicere, « convenir »."},
  {name:"Boucle",                  en:"Loop",                       cat:"notions",     def:"Instruction qui répète un bloc de code tant qu'une condition tient (while) ou pour chaque élément d'une collection (for). Une boucle sans fin est une erreur classique.", ex:"for (const ligne of fichier) { … }", etymo:"De l'ancien français bocle, « anneau », du latin buccula, « petite bouche, bossette de bouclier »."},
  {name:"Type de données",         en:"Data Type",                  cat:"notions",     def:"Nature d'une valeur, qui détermine ce qu'on peut en faire : entier, nombre décimal, booléen (vrai/faux), chaîne de caractères, liste, dictionnaire, objet.", ex:"42, 3.14, true, \"texte\", [1, 2, 3], {nom: \"Seb\"}", etymo:"Type, du grec tupos, « empreinte, modèle ». Donnée, du latin datum, « ce qui est donné »."},
  {name:"Tableau et liste",        en:"Array / List",               cat:"notions",     def:"Collection ordonnée de valeurs accessibles par leur position (indice), qui commence à 0 dans la plupart des langages. Structure la plus courante du code.", ex:"const jours = [\"lun\", \"mar\", \"mer\"]; jours[0] → \"lun\"", etymo:"Tableau, diminutif de table, du latin tabula, « planche ». Liste, de l'italien lista, « bande, lisière », d'origine germanique."},
  {name:"Dictionnaire",            en:"Dictionary / Map / Object",  cat:"notions",     def:"Collection de paires clé → valeur, où l'on retrouve une valeur par sa clé plutôt que par sa position. Appelé objet en JavaScript, dict en Python, map ailleurs.", ex:"{ \"nom\": \"Dupont\", \"age\": 42 } ; personne[\"age\"] → 42", etymo:"Du latin médiéval dictionarium, de dictio, « action de dire, mot » : un recueil de mots. Sens informatique par analogie (clé → valeur comme mot → définition)."},
  {name:"Objet et classe",         en:"Object and Class",           cat:"notions",     def:"Dans la programmation orientée objet, la classe est le plan (attributs et méthodes), l'objet en est une instance concrète. Permet de modéliser le domaine : un client, une commande, une facture.", ex:"class Compte { solde = 0; deposer(m) { this.solde += m; } } ; const c = new Compte();", etymo:"Classe, du latin classis, « division ». Objet, du latin objectum, « placé devant »."},
  {name:"Paradigme de programmation",               en:"Programming Paradigm",       cat:"notions",     def:"Manière de penser et d'organiser le code. Impératif (suite d'instructions), orienté objet (objets qui interagissent), fonctionnel (fonctions pures sans état), déclaratif (dire quoi, pas comment, comme SQL). La plupart des langages en mélangent plusieurs.", ex:"Java : objet ; Haskell : fonctionnel ; SQL : déclaratif ; Python : un peu de tout", etymo:"Du grec paradeigma, « modèle, exemple »."},
  {name:"Récursivité",             en:"Recursion",                  cat:"notions",     def:"Technique où une fonction s'appelle elle-même sur un problème plus petit, jusqu'à un cas de base. Élégante pour les arbres et les structures imbriquées ; à limiter pour la mémoire.", ex:"factorielle(n) = n × factorielle(n − 1), avec factorielle(0) = 1", etymo:"Du latin recursus, « retour en arrière », de recurrere, « courir en arrière »."},
  {name:"Exception",               en:"Exception",                  cat:"notions",     def:"Événement anormal (fichier absent, division par zéro, réseau coupé) qui interrompt le déroulement normal ; le programme peut l'attraper (try / catch) et réagir plutôt que planter.", ex:"try { lire(fichier) } catch (e) { afficher(\"Fichier introuvable\") }", etymo:"Du latin exceptio, « restriction, réserve », de excipere, « prendre à part »."},
  {name:"Asynchrone",              en:"Asynchronous",               cat:"notions",     def:"Mode d'exécution où le programme lance une opération longue (requête réseau, lecture de fichier) et continue sans l'attendre, puis traite le résultat quand il arrive. Évite de figer l'interface.", ex:"const data = await fetch(url); — en JavaScript, tout le réseau est asynchrone", etymo:"Du grec a- (privatif) + sun (avec) + khronos (temps) : qui n'est pas en même temps."},
  {name:"Complexité algorithmique", en:"Algorithmic Complexity",    cat:"notions",     def:"Mesure de la croissance du temps (ou de la mémoire) d'un algorithme quand la taille des données augmente, notée O(…). Distingue ce qui tiendra la charge de ce qui s'effondrera.", ex:"Chercher dans une liste triée : O(log n) ; trier : O(n log n) ; comparer tout à tout : O(n²)", etymo:"Complexité, du latin complexus, « embrassé, entrelacé », de complecti. La notation O est due à Paul Bachmann (1894) et Edmund Landau."},
  {name:"Expression régulière",    en:"Regular Expression (Regex)", cat:"notions",     def:"Motif décrivant un ensemble de chaînes de caractères, pour chercher, valider ou remplacer du texte. Puissant, cryptique, présent dans tous les langages et éditeurs.", ex:"^[\\w.-]+@[\\w.-]+\\.\\w+$ valide grossièrement un e-mail", etymo:"Notion du mathématicien Stephen Kleene (1951), popularisée par les outils Unix (grep, sed) dans les années 1970."},

  // Qualité & Tests
  {name:"Bug",                     en:"Bug",                        cat:"qualite",     def:"Erreur ou défaut dans un programme causant un comportement inattendu ou incorrect. Inévitable ; l'enjeu est de le trouver tôt, par les tests, et de le reproduire pour le corriger.", ex:"Division par zéro, bouton qui ne répond pas, bug de l'an 2000, cas limite non prévu", etymo:"Anglais, « insecte, bestiole ». Employé pour un défaut technique dès Edison (1878) ; l'anecdote de la mite trouvée dans le Harvard Mark II (1947) a popularisé le mot en informatique."},
  {name:"Débogage",                en:"Debugging",                  cat:"qualite",     def:"Recherche et correction des erreurs d'un programme : reproduire, isoler, comprendre, corriger, vérifier. Le débogueur permet d'exécuter pas à pas et d'inspecter les variables.", ex:"Point d'arrêt dans l'IDE, console.log, lecture des logs, bissection", etymo:"De bug (insecte) et du préfixe privatif dé- : ôter les insectes. L'anglais debugging est attesté en 1945."},
  {name:"Test unitaire",           en:"Unit Test",                  cat:"qualite",     def:"Programme qui vérifie automatiquement qu'une fonction donne le résultat attendu pour des entrées données. Rapide, nombreux, relancés à chaque modification : le filet de sécurité du développeur.", ex:"expect(aire(2, 3)).toBe(6) ; frameworks pytest, Jest, JUnit", etymo:"Unitaire, du latin unitas, « unité » : le test d'une seule unité de code. Pratique généralisée par Kent Beck (SUnit, 1989 ; JUnit, 1997)."},
  {name:"Test d'intégration et de bout en bout", en:"Integration and End-to-End Tests", cat:"qualite", def:"Tests qui vérifient que les composants fonctionnent ensemble (intégration) ou qu'un parcours complet marche comme un utilisateur le ferait, dans un vrai navigateur (bout en bout). Plus lents, plus proches du réel.", ex:"Playwright ou Cypress remplissant un formulaire d'inscription et vérifiant l'e-mail reçu", etymo:"Intégration, du latin integratio, « renouvellement », de integer, « entier ». Bout en bout, calque de l'anglais end-to-end."},
  {name:"TDD",                     en:"Test-Driven Development",    cat:"qualite",     def:"Méthode où l'on écrit le test avant le code : un test qui échoue, le code minimal pour qu'il passe, puis on nettoie. Force à préciser ce qu'on veut avant de l'écrire.", ex:"Cycle rouge → vert → refactor", etymo:"Sigle de l'anglais test-driven development, formalisé par Kent Beck (2003)."},
  {name:"Revue de code",           en:"Code Review",                cat:"qualite",     def:"Relecture du code d'un développeur par un autre avant intégration : erreurs, lisibilité, cohérence, partage de connaissance. Se fait généralement sur une pull request.", ex:"Commentaire ligne par ligne, approbation requise avant fusion", etymo:"Revue, participe de revoir : l'action de revoir, d'inspecter. Calque de l'anglais code review ; pratique formalisée par Michael Fagan chez IBM (1976)."},
  {name:"Linter",                  en:"Linter",                     cat:"qualite",     def:"Outil d'analyse statique qui détecte, sans exécuter le code, les erreurs probables, les mauvaises pratiques et les écarts de style. Un formateur (Prettier, Black) uniformise la présentation.", ex:"ESLint (JavaScript), Ruff et Pylint (Python), Clippy (Rust)", etymo:"Du nom de lint (1978), l'outil Unix originel, lui-même nommé d'après la peluche (lint) qui s'accumule dans le filtre du sèche-linge : les petits défauts qu'on ramasse."},
  {name:"Refactoring",             en:"Refactoring",                cat:"qualite",     def:"Réécriture du code pour l'améliorer (lisibilité, structure, simplicité) sans changer ce qu'il fait. Les tests garantissent que rien n'a cassé.", ex:"Extraire une fonction, renommer une variable, supprimer une duplication", etymo:"Anglais, de factor, « facteur » : re-factoriser, comme on factorise une expression. Popularisé par Martin Fowler (1999)."},
  {name:"Dette technique",         en:"Technical Debt",             cat:"qualite",     def:"Coût futur des raccourcis pris aujourd'hui : code bâclé, tests absents, dépendances obsolètes. Comme une dette, elle porte intérêt, chaque évolution devenant plus lente, jusqu'à la paralysie.", ex:"« On corrigera plus tard » ; une semaine de nettoyage par trimestre pour la rembourser", etymo:"Métaphore de Ward Cunningham (1992)."},
  {name:"Documentation",           en:"Documentation",              cat:"qualite",     def:"Textes qui expliquent le code et son usage : README, commentaires, référence d'API, guides. La meilleure est courte, à jour et proche du code ; la pire est celle qui ment.", ex:"README avec installation et exemples, docstrings, site généré depuis le code", etymo:"Du latin documentum, « exemple, modèle, leçon », de docere, « enseigner »."},
  {name:"Code mort",               en:"Dead Code",                  cat:"qualite",     def:"Code qui n'est plus jamais exécuté ni appelé, mais reste dans le projet. À supprimer sans regret : le versionnage le garde en mémoire.", ex:"Fonction que plus rien n'appelle, ancienne version commentée « au cas où »", etymo:"Mort, du latin mortuus. Calque de l'anglais dead code, terme des compilateurs (élimination du code mort, années 1960)."},
  {name:"Journalisation (logs)",   en:"Logging",                    cat:"qualite",     def:"Écriture par le programme de messages datés sur ce qu'il fait et ce qui échoue, dans un fichier ou une console, avec des niveaux (debug, info, warning, error). Première source pour comprendre un incident.", ex:"2026-09-20 10:42:07 ERROR Connexion à la base refusée", etymo:"Journal, du latin diurnalis, « quotidien ». Log, anglais, « bûche », le journal de bord des navires."},

  // Outils
  {name:"IDE",                     en:"Integrated Development Environment", cat:"outils", def:"Éditeur de code enrichi : coloration, complétion, navigation, débogueur, terminal et intégration Git au même endroit. Le poste de travail du développeur.", ex:"VS Code, IntelliJ, Xcode, Android Studio ; les assistants IA s'y greffent", etymo:"Sigle de l'anglais Integrated Development Environment, « environnement de développement intégré ». Premier IDE reconnu : Turbo Pascal (1983)."},
  {name:"Terminal",                en:"Terminal / Shell",           cat:"outils",     def:"Interface en ligne de commande où l'on tape des instructions au système : lancer un programme, manipuler des fichiers, installer, déployer. Plus rapide et scriptable que l'interface graphique.", ex:"cd projet && npm install && npm run dev", etymo:"Du latin terminalis, « qui marque la fin » : à l'origine, le poste au bout du câble relié à l'ordinateur central."},
  {name:"Git",                     en:"Git",                        cat:"outils",     def:"Système de gestion de versions distribué : il enregistre l'historique complet du code, permet de revenir en arrière, de travailler à plusieurs en parallèle (branches) et de fusionner. Standard universel depuis les années 2010.", ex:"git commit -m \"Ajoute la recherche\" ; git log ; git checkout -b nouvelle-fonction", etymo:"Créé par Linus Torvalds en 2005 pour le noyau Linux. En argot britannique, git veut dire « crétin » ; Torvalds dit avoir nommé tous ses projets d'après lui-même."},
  {name:"Dépôt (repository)",      en:"Repository",                 cat:"outils",     def:"Dossier d'un projet suivi par Git, avec tout son historique. Local sur la machine du développeur, et distant sur un serveur (GitHub, GitLab) pour partager et sauvegarder.", ex:"git clone https://github.com/… copie un dépôt distant en local", etymo:"Du latin repositorium, « lieu où l'on dépose », de reponere."},
  {name:"Commit",                  en:"Commit",                     cat:"outils",     def:"Enregistrement d'un ensemble de modifications dans l'historique, avec un message qui dit pourquoi. Petit, cohérent, fréquent : c'est l'unité de travail et de lecture de l'histoire d'un projet.", ex:"« Corrige le calcul de TVA sur les remises » ; un commit = un changement", etymo:"Anglais, « confier, engager », du latin committere, « mettre ensemble, confier »."},
  {name:"Branche",                 en:"Branch",                     cat:"outils",     def:"Ligne de développement parallèle dans Git : on crée une branche pour une fonctionnalité, on y travaille sans toucher à la principale (main), puis on fusionne. Les conflits se règlent à la fusion.", ex:"main, develop, fonction/recherche-globale, correctif/bug-cache", etymo:"Du latin populaire branca, « patte », d'où « rameau »."},
  {name:"Pull request",            en:"Pull Request / Merge Request", cat:"outils",   def:"Demande de fusion d'une branche dans une autre, sur GitHub ou GitLab, qui déclenche la revue de code et les tests automatiques avant intégration. Le lieu de la discussion sur le code.", ex:"Ouvrir une PR, obtenir une approbation, fusionner, supprimer la branche", etymo:"Anglais, « demande de tirage » : on demande au mainteneur de « tirer » (pull) les modifications vers son dépôt. Terme de GitHub (2008)."},
  {name:"GitHub",                  en:"GitHub",                     cat:"outils",     def:"Plateforme d'hébergement de dépôts Git (Microsoft depuis 2018), avec pull requests, tickets, CI (Actions), pages web. Le plus grand dépôt de code open source au monde. GitLab et Bitbucket sont les alternatives.", ex:"Plus de 100 millions de développeurs, les sources de Linux, Python, VS Code", etymo:"De Git et hub, « moyeu », le centre de la roue : la plateforme au centre des dépôts. Fondé en 2008 par Tom Preston-Werner, Chris Wanstrath et PJ Hyett."},
  {name:"CI/CD",                   en:"Continuous Integration / Continuous Delivery", cat:"outils", def:"Chaîne automatique déclenchée à chaque commit : construire, tester, et livrer ou déployer si tout passe. L'intégration continue attrape les erreurs tôt, la livraison continue rend la mise en production banale.", ex:"GitHub Actions, GitLab CI, Jenkins ; déploiement automatique de main vers la production", etymo:"Sigles de l'anglais continuous integration (terme de Grady Booch, 1991, popularisé par l'Extreme Programming) et continuous delivery (Jez Humble, 2010)."},
  {name:"Gestionnaire de paquets", en:"Package Manager",            cat:"outils",     def:"Outil qui installe, met à jour et résout les dépendances d'un projet à partir d'un dépôt central, en fixant les versions dans un fichier de verrouillage pour des installations reproductibles.", ex:"npm et pnpm (JavaScript), pip et uv (Python), cargo (Rust), apt (Debian)", etymo:"Paquet, de l'ancien français pacque, « balle de marchandises », du néerlandais pak. Le premier gestionnaire de paquets est celui de Debian, dpkg (1994)."},
  {name:"Docker",                  en:"Docker",                     cat:"outils",     ref:"serveur"},
  {name:"Environnement de développement", en:"Development Environment", cat:"outils", def:"Configuration locale reproduisant ce qu'il faut pour faire tourner le projet : version du langage, dépendances, base de données, variables. Distinct des environnements de test (staging) et de production.", ex:"« Ça marche sur ma machine » : le problème que Docker et les fichiers .env résolvent", etymo:"Environnement, de environ, « autour », de viron, « tour »."},

  // Architecture
  {name:"Architecture logicielle", en:"Software Architecture",      cat:"architecture", def:"Organisation d'ensemble d'un logiciel : découpage en modules, responsabilités, communication entre parties, choix techniques structurants. Les décisions les plus coûteuses à changer après coup.", ex:"Monolithe, microservices, client-serveur, architecture en couches", etymo:"Architecture, du grec arkhitektôn, « maître constructeur ». Expression software architecture apparue dans les années 1960, discipline depuis les années 1990."},
  {name:"Modularité",              en:"Modularity",                 cat:"architecture", def:"Découpage du code en modules indépendants, chacun avec une responsabilité claire et une interface définie. Permet de comprendre, tester et remplacer une partie sans toucher au reste.", ex:"Un module « paiement », un module « e-mail », un module « authentification »", etymo:"Du latin modulus, « petite mesure », l'unité de base d'un ensemble."},
  {name:"Couplage et cohésion",    en:"Coupling and Cohesion",      cat:"architecture", def:"Deux mesures de la qualité d'un découpage : le couplage est la dépendance entre modules (à minimiser), la cohésion le degré auquel les éléments d'un module vont ensemble (à maximiser). Faible couplage, forte cohésion.", ex:"Un module qui doit connaître les détails internes d'un autre est trop couplé", etymo:"Couplage, de couple, du latin copula, « lien ». Cohésion, du latin cohaesum, de cohaerere, « être attaché ensemble ». Notions de Larry Constantine (années 1960)."},
  {name:"Design pattern",          en:"Design Pattern",             cat:"architecture", def:"Solution éprouvée et nommée à un problème de conception récurrent, qu'on adapte à son cas. Le vocabulaire commun des développeurs pour parler structure.", ex:"Singleton, Observateur, Fabrique, Stratégie ; le livre du Gang of Four (1994)", etymo:"Anglais, « motif de conception » ; notion empruntée à l'architecte Christopher Alexander (1977)."},
  {name:"MVC",                     en:"Model-View-Controller",      cat:"architecture", def:"Découpage classique d'une application en trois rôles : le modèle (données et règles), la vue (affichage), le contrôleur (qui relie les deux et traite les actions). Base de la plupart des frameworks web.", ex:"Rails, Django (MVT), Laravel, Angular", etymo:"Conçu par Trygve Reenskaug chez Xerox PARC (1979) pour Smalltalk."},
  {name:"Séparation des responsabilités", en:"Separation of Concerns", cat:"architecture", def:"Principe selon lequel chaque partie du code ne s'occupe que d'une chose : l'affichage ne calcule pas, le calcul n'accède pas à la base, la base ne formate pas. Rend le tout lisible et testable.", ex:"Une fonction qui lit un fichier, en calcule le total et l'affiche fait trois choses de trop", etymo:"Calque de l'anglais separation of concerns, expression d'Edsger Dijkstra (1974)."},
  {name:"DRY, KISS, YAGNI",        en:"DRY, KISS, YAGNI",           cat:"architecture", def:"Trois maximes du métier : ne pas se répéter (Don't Repeat Yourself), rester simple (Keep It Simple, Stupid), ne pas construire ce dont on n'a pas besoin (You Aren't Gonna Need It).", ex:"Copier-coller trois fois le même bloc viole DRY ; prévoir un mode multi-langue « au cas où » viole YAGNI", etymo:"DRY, de The Pragmatic Programmer (Hunt et Thomas, 1999). KISS, formule de l'ingénieur aéronautique Kelly Johnson (Lockheed, années 1960). YAGNI, de l'Extreme Programming (années 1990)."},
  {name:"Monolithe et microservices", en:"Monolith and Microservices", cat:"architecture", ref:"serveur", refName:"Architecture microservices"},
  {name:"API",                     en:"API",                        cat:"architecture", ref:"informatique"},
  {name:"Base de données",         en:"Database",                   cat:"architecture", ref:"bdd"},

  // Méthodes & Organisation
  {name:"Agilité",                 en:"Agile",                      cat:"agilite",     def:"Manière de développer par petites livraisons fréquentes, en s'adaptant au retour des utilisateurs plutôt qu'en suivant un plan figé. Le Manifeste agile (2001) en fixe les valeurs : individus, logiciel qui marche, collaboration, adaptation.", ex:"Scrum, Kanban, XP en sont les méthodes", etymo:"Du latin agilis, « qui se meut facilement », de agere, « faire, mener »."},
  {name:"Scrum",                   en:"Scrum",                      cat:"agilite",     def:"Cadre agile le plus répandu : une équipe livre à chaque sprint (une à quatre semaines) un incrément utilisable, à partir d'un backlog priorisé par le Product Owner, avec un daily, une revue et une rétrospective. Le Scrum Master veille au cadre.", ex:"Sprint de deux semaines, daily de quinze minutes debout", etymo:"Anglais, « mêlée » au rugby : l'équipe qui avance ensemble, image de Takeuchi et Nonaka (1986)."},
  {name:"Sprint",                  en:"Sprint",                     cat:"agilite",     def:"Période fixe et courte (souvent deux semaines) au terme de laquelle l'équipe livre quelque chose d'utilisable. Ce qui n'est pas fini retourne au backlog ; on ne prolonge pas un sprint.", ex:"Planification le lundi, revue et rétrospective le vendredi de la deuxième semaine", etymo:"Anglais, « course de vitesse », d'origine scandinave (spretta, « bondir »). Terme de Scrum (Schwaber et Sutherland, 1995)."},
  {name:"Backlog",                 en:"Backlog",                    cat:"agilite",     def:"Liste ordonnée de tout ce qui reste à faire sur le produit, du plus important au moins, entretenue en continu. Le haut est détaillé, le bas reste vague.", ex:"Fonctionnalités, corrections, dette technique, idées", etymo:"Anglais, « bûche du fond » de l'âtre, puis « arriéré, travail en attente »."},
  {name:"User story",              en:"User Story",                 cat:"agilite",     def:"Description courte d'un besoin du point de vue de l'utilisateur, qui tient sur une carte : « En tant que …, je veux …, afin de … ». Assortie de critères d'acceptation qui disent quand c'est fini.", ex:"« En tant que visiteur, je veux chercher un terme sans accents, afin de le trouver même mal orthographié »", etymo:"Anglais, « histoire d'utilisateur » : le besoin raconté comme une petite histoire. Terme de l'Extreme Programming (Kent Beck, 1998)."},
  {name:"Kanban",                  en:"Kanban",                     cat:"agilite",     def:"Méthode de flux continu : un tableau à colonnes (à faire, en cours, fait), une limite au nombre de tâches en cours, et l'on tire la suivante quand une se termine. Sans sprints, adapté au support et aux petites équipes.", ex:"Tableau Trello, colonnes avec limite de trois cartes en cours", etymo:"Japonais, « étiquette, panneau », du système de production de Toyota (années 1950)."},
  {name:"MVP",                     en:"Minimum Viable Product",     cat:"agilite",     ref:"design"},
  {name:"DevOps",                  en:"DevOps",                     cat:"agilite",     def:"Culture et pratiques rapprochant développement et exploitation : automatisation du déploiement, infrastructure décrite en code, surveillance, responsabilité partagée de la mise en production. « Vous le construisez, vous le faites tourner. »", ex:"CI/CD, conteneurs, Terraform, astreinte partagée", etymo:"Mot-valise anglais de development et operations (2009)."},
  {name:"Pair programming",        en:"Pair Programming",           cat:"agilite",     def:"Deux développeurs sur un même écran : l'un écrit, l'autre relit et réfléchit à voix haute, en alternant. Moins de bugs, plus de partage, au prix d'un temps doublé sur l'instant.", ex:"Pratique de l'Extreme Programming ; en visio avec partage d'écran", etymo:"Anglais, « programmation en binôme », de pair, « paire », du latin par, « égal ». Pratique de l'Extreme Programming (années 1990)."},
  {name:"Post-mortem",             en:"Post-mortem",                cat:"agilite",     def:"Analyse écrite d'un incident après coup, sans chercher de coupable : ce qui s'est passé, pourquoi, ce qu'on change pour que ça ne se reproduise pas.", ex:"Panne de production de deux heures : chronologie, causes, actions", etymo:"Latin, « après la mort », terme médical de l'autopsie."},

  // IA
  {name:"Assistant de code",       en:"Coding Assistant",           cat:"ia",          ref:"ia"},
  {name:"Vibe coding",             en:"Vibe Coding",                cat:"ia",          def:"Façon de programmer en décrivant ce qu'on veut à une IA et en acceptant son code sans le lire en détail, en jugeant au résultat. Rapide pour prototyper, risqué pour ce qui doit durer : personne ne comprend plus le code.", ex:"« Fais-moi une app qui… » et on itère sur ce qui s'affiche", etymo:"Expression d'Andrej Karpathy (février 2025), « coder à l'ambiance »."},
  {name:"Génération de code",      en:"Code Generation",            cat:"ia",          def:"Production de code par un modèle de langage à partir d'une description, d'un test ou d'un code existant. Change le métier : moins d'écriture, plus de spécification, de relecture et de vérification.", ex:"Écrire les tests, générer la fonction, relire, corriger", etymo:"Génération, du latin generatio, de generare, « engendrer ». La génération de code par IA date des années 2020 (Codex, 2021)."},
];

// ── AUTOMATISATION & NO-CODE ──
// Sous-lexique d'Informatique. Vocabulaire des outils de workflow (n8n, Make, Zapier) ; les notions d'API et d'IA sont définies chez elles.
const terms_automatisation = [
  // Fondements
  {name:"Automatisation",          en:"Automation",                 cat:"fondements",  def:"Faire exécuter par une machine, sans intervention, une tâche répétitive qu'un humain faisait à la main : copier une donnée, envoyer un message, vérifier un état, produire un rapport. Le gain n'est pas seulement du temps, c'est la régularité et l'absence d'oubli.", ex:"Chaque matin à 7 h, vérifier les cartes bancaires expirées et prévenir par mail", etymo:"Du grec automatos, « qui se meut de lui-même » : autos (soi-même) + une racine signifiant « penser, vouloir ». Automate est attesté en français dès le XVIe siècle."},
  {name:"No-code",                 en:"No-code",                    cat:"fondements",  def:"Construire des applications ou des automatisations sans écrire de code, par assemblage visuel de blocs et de formulaires. Rend la création accessible aux non-développeurs ; atteint vite ses limites sur le sur-mesure.", ex:"Un site avec Webflow, une base avec Airtable, un workflow avec Zapier", etymo:"Anglais, « sans code ». Expression des années 2010, dans la lignée du low-code (Forrester, 2014)."},
  {name:"Low-code",                en:"Low-code",                   cat:"fondements",  def:"Entre no-code et développement : une interface visuelle pour l'essentiel, et la possibilité d'insérer du code là où il faut (expression, fonction, script). C'est la voie de n8n ou de Make.", ex:"Un workflow visuel avec un nœud de code JavaScript pour la partie tordue", etymo:"Anglais, « peu de code »."},
  {name:"Workflow",                en:"Workflow",                   cat:"fondements",  def:"Enchaînement d'étapes automatisé : un déclencheur, puis des actions reliées, avec des conditions et des boucles, qui s'exécute de bout en bout à chaque événement. L'unité de travail des outils d'automatisation.", ex:"Nouveau formulaire reçu → créer la fiche → envoyer l'accusé → prévenir sur Slack", etymo:"Anglais, « flux de travail » : work (travail) + flow (flux). Terme de l'organisation industrielle (années 1920), repris par l'informatique."},
  {name:"Intégration",             en:"Integration",                cat:"fondements",  def:"Faire communiquer deux logiciels qui ne se connaissent pas, en général par leurs API : lire dans l'un, écrire dans l'autre, garder les deux cohérents. L'automatisation est presque toujours une intégration.", ex:"Relier la boutique en ligne à la comptabilité, le CRM à la messagerie", etymo:"Du latin integratio, « renouvellement », de integer, « entier » : rendre entier, réunir en un tout."},
  {name:"RPA",                     en:"Robotic Process Automation", cat:"fondements",  def:"Automatisation par imitation d'un utilisateur : le robot clique, tape, lit l'écran, pour piloter des logiciels sans API. Utile pour les vieux systèmes, fragile dès qu'un écran change.", ex:"Un robot qui saisit des factures dans un logiciel comptable sans interface programmable", etymo:"Sigle de l'anglais Robotic Process Automation (années 2010)."},
  {name:"Script",                  en:"Script",                     cat:"fondements",  def:"Petit programme écrit pour une tâche précise, souvent lancé à la main ou par un planificateur, sans interface. L'automatisation d'avant les outils visuels, toujours la plus souple.", ex:"Un script Python qui renomme mille photos, un script shell de sauvegarde", etymo:"Du latin scriptum, « chose écrite », de scribere, « écrire ». Sens informatique via le scénario de théâtre : la suite d'instructions à jouer."},

  // Briques d'un workflow
  {name:"Déclencheur",             en:"Trigger",                    cat:"briques",     def:"Événement qui lance le workflow : une heure programmée, un webhook reçu, un nouveau mail, une ligne ajoutée dans une table, un fichier déposé. Tout workflow commence par un déclencheur, et un seul.", ex:"« Tous les jours à 7 h », « à chaque paiement Stripe », « quand un formulaire est soumis »", etymo:"De déclencher, « libérer le cliquet » (clenche, du francique klinka, « loquet »). Calque de l'anglais trigger, « gâchette »."},
  {name:"Action",                  en:"Action",                     cat:"briques",     def:"Étape du workflow qui fait quelque chose : lire ou écrire dans un service, transformer une donnée, envoyer un message. Chaque action reçoit les données de la précédente et passe les siennes à la suivante.", ex:"Créer une ligne Google Sheets, envoyer un e-mail, appeler une API", etymo:"Du latin actio, « action, procès », de agere, « faire, mener »."},
  {name:"Nœud (workflow)",                    en:"Workflow Node",                       cat:"briques",     def:"Boîte visuelle représentant un déclencheur, une action ou une logique dans l'éditeur de workflow, reliée aux autres par des fils. Le vocabulaire de n8n ; Make dit « module », Zapier « étape ».", ex:"Nœud HTTP Request, nœud IF, nœud Code, nœud Gmail", etymo:"Du latin nodus, « nœud », point de jonction d'un réseau."},
  {name:"Connexion (fil)",         en:"Connection / Edge",          cat:"briques",     def:"Lien tracé entre deux nœuds, qui définit l'ordre d'exécution et fait passer les données de l'un à l'autre. Un nœud peut avoir plusieurs sorties (vrai / faux, succès / erreur).", ex:"La sortie « false » du nœud IF part vers un nœud de notification", etymo:"Connexion, du latin connexio, « liaison », de connectere, « lier ensemble ». Fil, du latin filum."},
  {name:"Webhook",                 en:"Webhook",                    cat:"briques",     ref:"api"},
  {name:"Planification",           en:"Schedule",                   cat:"briques",     def:"Déclencheur temporel : le workflow part à heure fixe, à intervalle régulier ou selon une expression cron. Le fuseau horaire est le piège classique.", ex:"0 7 * * 1-5 : du lundi au vendredi à 7 h", etymo:"Du latin planus, « plat », d'où plan, puis planifier (années 1930)."},
  {name:"Cron",                    en:"Cron",                       cat:"briques",     ref:"serveur"},
  {name:"Interrogation périodique", en:"Polling",                   cat:"briques",     def:"Quand un service ne sait pas prévenir (pas de webhook), le workflow va voir régulièrement s'il y a du nouveau. Simple mais avec du retard et des appels pour rien ; le webhook est préférable quand il existe.", ex:"Vérifier toutes les cinq minutes s'il y a de nouveaux mails", etymo:"Calque de l'anglais polling, « scrutin, sondage » : on interroge à tour de rôle."},
  {name:"Condition (branche)",     en:"Condition / Branch",         cat:"briques",     def:"Nœud qui aiguille le flux selon un test : si le montant dépasse 100 €, si le champ est vide, si le statut vaut « payé ». Le workflow se sépare en branches, qui peuvent se rejoindre.", ex:"IF montant > 100 → alerte ; sinon → archivage", etymo:"Du latin condicio, « convention, clause »."},
  {name:"Boucle sur les éléments",                  en:"Loop over Items",           cat:"briques",     def:"Traitement répété pour chaque élément d'une liste : chaque ligne d'un tableau, chaque pièce jointe, chaque résultat d'API. La plupart des outils bouclent implicitement sur les éléments reçus.", ex:"Pour chaque client de la liste, envoyer un rappel personnalisé", etymo:"De l'ancien français bocle, « anneau », du latin buccula."},
  {name:"Fusion et agrégation",    en:"Merge / Aggregate",          cat:"briques",     def:"Réunir des données venues de deux branches (fusion) ou rassembler plusieurs éléments en un seul (agrégation), par exemple pour envoyer un seul mail récapitulatif plutôt que cinquante.", ex:"Fusionner la liste des commandes avec celle des clients par identifiant", etymo:"Fusion, du latin fusio, « action de fondre ». Agrégation, du latin aggregare, « réunir en troupeau » (grex)."},
  {name:"Attente",                 en:"Wait / Delay",               cat:"briques",     def:"Nœud qui suspend le workflow un temps donné ou jusqu'à un événement (validation humaine, réponse d'un webhook). Permet les relances différées et les approbations.", ex:"Attendre 3 jours, puis relancer si pas de réponse", etymo:"De attendre, du latin attendere, « tendre vers, faire attention »."},
  {name:"Expression",              en:"Expression",                 cat:"briques",     def:"Petit bout de code inséré dans un champ pour calculer une valeur à partir des données précédentes : concaténer, formater une date, extraire un élément. Le moment où le no-code devient low-code.", ex:"{{ $json.prenom }} {{ $json.nom }} ; {{ $now.toFormat('dd/MM/yyyy') }}", etymo:"Du latin expressio, « action de faire sortir en pressant », de exprimere."},
  {name:"Correspondance des champs", en:"Field Mapping",            cat:"briques",     def:"Indiquer quel champ de la source va dans quel champ de la destination : « e-mail » du formulaire vers « adresse » du CRM. L'essentiel du travail d'intégration, et la source des erreurs silencieuses.", ex:"Prénom → first_name, Montant (texte) → amount (nombre)", etymo:"Calque de l'anglais mapping, « cartographie », de map."},
  {name:"Nœud de code",            en:"Code Node",                  cat:"briques",     def:"Étape où l'on écrit du vrai code (JavaScript, Python) pour ce que les nœuds standard ne savent pas faire : transformation complexe, calcul, appel exotique. À garder rare et court.", ex:"Dédoublonner une liste, parser un format maison", etymo:"Nœud, du latin nodus. Code, du latin codex, « livre »."},
  {name:"Sous-workflow",           en:"Sub-workflow",               cat:"briques",     def:"Workflow appelé par un autre, comme une fonction : on y met ce qui sert à plusieurs endroits (envoyer une alerte, écrire un journal) pour ne pas le dupliquer.", ex:"Un sous-workflow « notifier » appelé par tous les contrôles", etymo:"Sous-, du latin subtus, « en dessous ». Workflow, anglais, « flux de travail »."},

  // Données & Connexions
  {name:"API",                     en:"API",                        cat:"donnees",     ref:"informatique"},
  {name:"JSON",                    en:"JSON",                       cat:"donnees",     ref:"api"},
  {name:"Nœud Requête HTTP",            en:"HTTP Request Node",               cat:"donnees",     def:"Nœud générique qui appelle n'importe quelle API : méthode, adresse, en-têtes, corps. Ce qu'on utilise quand il n'existe pas de nœud dédié au service, c'est-à-dire souvent.", ex:"GET https://api.exemple.com/clients avec un en-tête d'autorisation", etymo:"Requête, du latin populaire requaesita, de requirere. HTTP, sigle de HyperText Transfer Protocol."},
  {name:"Identifiants (credentials)", en:"Credentials",             cat:"donnees",     def:"Clés, jetons et mots de passe qui permettent au workflow d'agir au nom d'un compte, stockés chiffrés dans l'outil et référencés par nom, jamais écrits dans les nœuds.", ex:"Identifiant Gmail (OAuth), clé API Stripe, jeton Notion", etymo:"Anglais credentials, « lettres de créance », du latin credere, « croire, confier »."},
  {name:"OAuth 2.0",               en:"OAuth 2.0",                  cat:"donnees",     ref:"api"},
  {name:"Clé API",                 en:"API Key",                    cat:"donnees",     ref:"api"},
  {name:"Table de données",        en:"Data Table",                 cat:"donnees",     def:"Base légère intégrée à l'outil ou en ligne (feuille de calcul, Airtable, table n8n) où le workflow lit et écrit : état d'avancement, historique, liste de référence. Le carnet de notes de l'automatisation.", ex:"Une table « contrôles » avec la date du dernier passage et le résultat", etymo:"Table, du latin tabula, « planche ». Donnée, du latin datum."},
  {name:"Pagination",              en:"Pagination",                 cat:"donnees",     ref:"api"},
  {name:"Limitation de débit",     en:"Rate limiting",              cat:"donnees",     ref:"api"},
  {name:"Transformation",          en:"Data Transformation",        cat:"donnees",     def:"Mettre les données au format attendu par la destination : renommer, convertir (texte → nombre, date), nettoyer, filtrer, découper. Entre la source et la cible, il y a presque toujours une transformation.", ex:"« 12,50 € » → 12.5 ; « Dupont Marie » → nom, prénom", etymo:"Du latin transformatio, « changement de forme »."},
  {name:"Formulaire",              en:"Form",                       cat:"donnees",     def:"Page de saisie qui alimente un workflow : chaque envoi devient un événement avec ses champs. Le point d'entrée le plus courant des automatisations tournées vers les gens.", ex:"Formulaire n8n, Tally, Google Forms, formulaire d'un site", etymo:"Du latin formula, « petite forme, règle », diminutif de forma."},

  // Outils
  {name:"n8n",                     en:"n8n",                        cat:"outils",      def:"Outil d'automatisation visuel, open source et auto-hébergeable, orienté techniciens : des centaines de nœuds, du code quand il faut, des workflows exportables en JSON et des nœuds d'IA intégrés. Version cloud payante ou installation chez soi.", ex:"Un serveur n8n personnel qui fait tourner les contrôles quotidiens", etymo:"Abréviation de nodemation (node + automation) : n, huit lettres, n. Créé par Jan Oberhauser (2019), Berlin."},
  {name:"Make",                    en:"Make (ex-Integromat)",       cat:"outils",      def:"Plateforme d'automatisation visuelle en ligne, réputée pour son éditeur de scénarios et sa gestion fine des données. Facturée à l'opération.", ex:"Un scénario Make qui synchronise Notion et Google Calendar", etymo:"Anciennement Integromat (Prague, 2012), renommé Make en 2022."},
  {name:"Zapier",                  en:"Zapier",                     cat:"outils",      def:"Pionnier de l'automatisation grand public (2011) : des « zaps » simples, déclencheur → actions, reliant des milliers d'applications. Le plus facile, le moins souple, le plus cher à volume.", ex:"Un zap : nouveau tweet → ligne dans un tableur", etymo:"De zap, onomatopée anglaise de l'éclair, du coup rapide."},
  {name:"IFTTT",                   en:"IFTTT",                      cat:"outils",      def:"Service d'automatisations élémentaires (2010), surtout pour la maison connectée et les réseaux sociaux : « si ceci, alors cela », une condition, une action.", ex:"Si la météo annonce la pluie, allumer la lampe en rouge", etymo:"Sigle de l'anglais If This Then That, « si ceci alors cela »."},
  {name:"Airtable",                en:"Airtable",                   cat:"outils",      def:"Base de données en ligne qui se présente comme un tableur : tables liées, vues, formulaires, automatisations intégrées. La base de choix des projets no-code.", ex:"Suivi de candidatures, inventaire, base de contacts", etymo:"De air (l'informatique « dans les airs », le cloud) et table. Fondé en 2012 par Howie Liu, Andrew Ofstad et Emmett Nicholas."},
  {name:"Notion",                  en:"Notion",                     cat:"outils",      def:"Espace de travail combinant pages, bases de données et documents, avec une API et des connecteurs : souvent la source ou la destination d'un workflow.", ex:"Une base Notion « tâches » alimentée automatiquement par les mails marqués", etymo:"Du latin notio, « connaissance, idée », de noscere, « connaître ». Fondé en 2013 par Ivan Zhao et Simon Last."},
  {name:"Google Sheets",           en:"Google Sheets",              cat:"outils",      def:"Tableur en ligne de Google, base de données du pauvre et pivot universel des automatisations : tout outil sait y lire et y écrire.", ex:"Un onglet par mois, une ligne par événement, un graphique qui se met à jour seul", etymo:"Sheet, anglais, « feuille », du vieil anglais scete. Lancé en 2006, issu du rachat de XL2Web."},
  {name:"Power Automate",          en:"Power Automate",             cat:"outils",      def:"Outil d'automatisation de Microsoft, intégré à Microsoft 365 : flux entre Outlook, Teams, SharePoint, Excel, et RPA de bureau. Le choix naturel en entreprise Microsoft.", ex:"Approbation d'une note de frais depuis Teams", etymo:"Anglais, « automatiser avec puissance ». Lancé par Microsoft en 2016 sous le nom de Flow, renommé en 2019."},
  {name:"Home Assistant",          en:"Home Assistant",             cat:"outils",      def:"Plateforme open source de domotique, auto-hébergée, qui relie les objets connectés de la maison quelle que soit leur marque et les automatise localement, sans cloud.", ex:"Éteindre le chauffage quand une fenêtre s'ouvre", etymo:"Anglais, « assistant domestique ». Projet open source lancé par Paulus Schoutsen (2013)."},
  {name:"Auto-hébergement",        en:"Self-hosting",               cat:"outils",      def:"Faire tourner l'outil sur sa propre machine ou son serveur plutôt que chez l'éditeur : gratuit, données chez soi, mais installation, mises à jour et sauvegardes à sa charge.", ex:"n8n dans un conteneur Docker sur un VPS ou un vieux PC", etymo:"Calque de l'anglais self-hosting. Héberger, du francique heribergôn, « loger une armée »."},

  // Fiabilité & Exploitation
  {name:"Exécution",               en:"Execution / Run",            cat:"fiabilite",   def:"Un passage complet du workflow, du déclencheur à la fin, avec ses données à chaque étape. Réussie, échouée ou en cours ; chaque exécution est journalisée et consultable.", ex:"Cent exécutions par jour, trois en erreur", etymo:"Du latin exsecutio, « achèvement », de exsequi, « suivre jusqu'au bout »."},
  {name:"Journal d'exécution",     en:"Execution Log",              cat:"fiabilite",   def:"Historique des exécutions avec, pour chacune, les données entrées et sorties de chaque nœud. Le premier endroit où regarder quand quelque chose a raté. Purgé après quelques jours par défaut : penser à garder une trace ailleurs.", ex:"n8n efface les exécutions après 14 jours si on ne change pas le réglage", etymo:"Journal, du latin diurnalis, « quotidien ». Exécution, du latin exsecutio, « achèvement »."},
  {name:"Gestion des erreurs",     en:"Error Handling",             cat:"fiabilite",   def:"Ce que fait le workflow quand une étape échoue : s'arrêter, continuer, réessayer, prévenir. Un workflow sans gestion d'erreur échoue en silence ; un workflow d'erreur dédié est la bonne pratique.", ex:"Workflow « erreur » qui envoie un message avec le nom du workflow fautif et le nœud", etymo:"Erreur, du latin error, « course à l'aventure, errance », de errare, « errer »."},
  {name:"Nouvelle tentative",      en:"Retry",                      cat:"fiabilite",   def:"Réexécuter automatiquement une étape qui a échoué pour une raison passagère (réseau, service surchargé), après un délai, un nombre limité de fois. Suppose que l'étape soit idempotente.", ex:"Trois tentatives espacées de 30 secondes", etymo:"Calque de l'anglais retry."},
  {name:"Idempotence",             en:"Idempotence",                cat:"fiabilite",   ref:"api"},
  {name:"File d'attente",          en:"Queue",                      cat:"fiabilite",   def:"Liste où les événements attendent leur tour quand ils arrivent plus vite qu'on ne les traite. Évite de perdre des déclenchements et lisse la charge.", ex:"Mode « queue » de n8n avec plusieurs exécutants", etymo:"File, du latin filum, « fil ». Queue, du latin cauda, « queue d'animal »."},
  {name:"Test d'un workflow",      en:"Workflow Testing",           cat:"fiabilite",   def:"Exécuter le workflow sur des données de test avant de l'activer, étape par étape, en regardant ce que chaque nœud produit. Épingler des données d'exemple évite d'appeler les vrais services à chaque essai.", ex:"Données épinglées sur le déclencheur, exécution manuelle, vérification nœud par nœud", etymo:"Test, du vieux français test, « pot de terre » servant à éprouver les métaux (latin testum)."},
  {name:"Activation",              en:"Activation",                 cat:"fiabilite",   def:"Passage d'un workflow en production : il écoute désormais son déclencheur et tourne seul. Un workflow inactif ne fait rien, même si son heure vient ; c'est l'oubli classique.", ex:"L'interrupteur « Actif » en haut de l'éditeur", etymo:"De activer, du latin activus, de agere, « faire, agir »."},
  {name:"Versionnage",             en:"Versioning",                 cat:"fiabilite",   ref:"api"},
  {name:"Secrets",                 en:"Secrets",                    cat:"fiabilite",   def:"Valeurs sensibles (clés, mots de passe, jetons) à ne jamais écrire dans un workflow ni dans un dépôt : on les met dans les identifiants de l'outil ou dans des variables d'environnement.", ex:"Un workflow exporté en JSON ne doit contenir aucun secret", etymo:"Du latin secretum, « chose mise à part », de secernere, « séparer »."},
  {name:"Surveillance",            en:"Monitoring",                 cat:"fiabilite",   def:"Vérifier que les automatisations tournent : un workflow qui ne s'est pas exécuté est aussi grave qu'un workflow en erreur, et plus discret. Un tableau de bord des derniers passages, ou un « contrôleur des contrôleurs ».", ex:"Une page qui liste chaque contrôle avec l'heure de son dernier passage et son résultat", etymo:"De surveiller, de sur + veiller, du latin vigilare."},

  // IA
  {name:"Agent IA",                en:"AI Agent",                   cat:"ia",          ref:"ia"},
  {name:"Appel d'outils",          en:"Tool Use",                   cat:"ia",          ref:"ia"},
  {name:"MCP",                     en:"MCP",                        cat:"ia",          ref:"ia"},
  {name:"Nœud IA",                 en:"AI Node",                    cat:"ia",          def:"Étape qui appelle un modèle de langage au milieu d'un workflow : résumer, classer, extraire, rédiger, décider. Le prompt est un champ comme un autre, les données précédentes s'y insèrent.", ex:"Classer chaque mail entrant en « facture / demande / spam » avant de l'aiguiller", etymo:"Nœud, du latin nodus. IA, sigle d'intelligence artificielle (1956)."},
  {name:"Extraction structurée",   en:"Structured Extraction",      cat:"ia",          def:"Demander au modèle de sortir non du texte libre mais des champs précis (JSON) : nom, montant, date, catégorie. Ce qui permet de brancher l'IA sur la suite du workflow.", ex:"D'une photo de ticket : { \"date\": …, \"montant\": …, \"commerçant\": … }", etymo:"Extraction, du latin extractio, de extrahere, « tirer hors de ». Structuré, du latin structura, « construction »."},
  {name:"Humain dans la boucle",   en:"Human in the Loop",          cat:"ia",          def:"Point du workflow où une personne valide avant que l'action ne parte : le brouillon généré par l'IA est relu, le paiement est approuvé. Indispensable dès que l'action est irréversible ou visible.", ex:"Le mail rédigé par l'IA attend un clic « envoyer » dans Slack", etymo:"Calque de l'anglais human in the loop, terme de l'aéronautique et de l'automatique (années 1950) : l'opérateur reste dans la boucle de commande."},

  // Cas d'usage
  {name:"Notification",            en:"Notification",               cat:"usages",      def:"Prévenir quelqu'un qu'un événement s'est produit : mail, message Slack ou Telegram, SMS, notification sur le téléphone. Le cas d'usage le plus simple et le plus utile.", ex:"« Un paiement a échoué », « le serveur ne répond plus », « nouveau candidat »", etymo:"Du latin notificatio, de notificare, « faire connaître » : notus (connu) + facere."},
  {name:"Synchronisation",         en:"Synchronization",            cat:"usages",      def:"Garder deux systèmes cohérents : ce qui est créé ou modifié dans l'un l'est dans l'autre. Dans un sens (simple) ou dans les deux (délicat : conflits, boucles infinies).", ex:"Contacts du CRM ↔ liste de diffusion", etymo:"Du grec sun (avec) + khronos (temps) : mettre au même temps."},
  {name:"Contrôle automatique",    en:"Automated Check",            cat:"usages",      def:"Vérifier à intervalle régulier qu'une règle est respectée ou qu'un état est normal, et signaler l'écart : données incohérentes, page en erreur, certificat qui expire, abonnement en retard.", ex:"Chaque nuit, chercher les comptes dont le plan ne correspond pas à l'abonnement", etymo:"Contrôle, de contre-rôle, le registre tenu en double pour vérifier l'autre (rôle, du latin rotulus, « rouleau »)."},
  {name:"Rapport automatique",     en:"Automated Report",           cat:"usages",      def:"Compiler des chiffres depuis plusieurs sources et les envoyer mis en forme, à date fixe, sans que personne n'ouvre un tableur.", ex:"Le lundi à 8 h : ventes de la semaine, nouveaux inscrits, tickets ouverts", etymo:"Rapport, de rapporter, « porter en retour » (re + apporter, du latin apportare)."},
  {name:"Enrichissement",          en:"Data Enrichment",            cat:"usages",      def:"Compléter une donnée par ce qu'on peut trouver ailleurs : à partir d'un e-mail, retrouver l'entreprise ; d'une adresse, les coordonnées GPS ; d'un SIREN, la raison sociale.", ex:"Nouveau contact → recherche de sa société → fiche complétée", etymo:"De enrichir, de riche, du francique rîki, « puissant ». Calque de l'anglais data enrichment."},
  {name:"Extraction web",          en:"Web Scraping",               cat:"usages",      def:"Lire automatiquement le contenu d'une page web pour en tirer des données quand il n'y a pas d'API : prix, disponibilités, annonces. Fragile (la page change), parfois interdit par les conditions du site.", ex:"Surveiller le prix d'un produit et prévenir quand il baisse", etymo:"Scraping, anglais, « grattage » : on racle la page."},
  {name:"Traitement de documents", en:"Document Processing",        cat:"usages",      def:"Recevoir des fichiers (factures, formulaires, photos), en extraire le contenu (OCR, IA), les classer et les ranger. Le passage du papier au flux.", ex:"Pièce jointe reçue → lecture du montant et de la date → ligne dans la comptabilité", etymo:"Traitement, de traiter, du latin tractare, « manier ». Document, du latin documentum, « exemple, leçon », de docere, « enseigner »."},
];

// ── DONNÉES & BASES DE DONNÉES ──
// Sous-lexique d'Informatique. Le tableur, le CSV et la donnée au sens large sont ici ; la donnée épistémique reste dans Connaissance.
const terms_bdd = [
  // Fondements
  {name:"Base de données",         en:"Database",                   cat:"fondements",  def:"Ensemble organisé de données, stocké de façon durable et accessible par des requêtes, géré par un logiciel dédié (SGBD). Là où vivent les clients, les commandes, les messages, les mesures de presque toute application.", ex:"La base d'une boutique en ligne, celle d'une app de finances, celle de ce lexique si elle n'était pas un simple fichier", etymo:"Base, du grec basis, « fondement ». Donnée, du latin datum, « ce qui est donné ». Traduit l'anglais database (années 1960)."},
  {name:"Donnée",                  en:"Data",                       cat:"fondements",  ref:"connaissance"},
  {name:"SGBD",                    en:"DBMS",                       cat:"fondements",  def:"Système de gestion de base de données : le logiciel qui stocke, protège, indexe et sert les données, et à qui l'on parle en SQL ou par une API. PostgreSQL, MySQL, SQLite, MongoDB en sont.", ex:"Un serveur PostgreSQL héberge plusieurs bases, chacune avec ses tables", etymo:"Sigle de système de gestion de base de données ; l'anglais dit DBMS, database management system."},
  {name:"Modèle relationnel",      en:"Relational Model",           cat:"fondements",  def:"Organisation des données en tables reliées entre elles par des clés, où chaque fait n'est stocké qu'une fois. Inventé par Edgar Codd chez IBM (1970), il domine depuis cinquante ans et SQL en est le langage.", ex:"Une table clients, une table commandes qui pointe vers le client par son identifiant", etymo:"Relationnel, du latin relatio, « rapport », au sens mathématique de relation entre ensembles."},
  {name:"Table",                   en:"Table",                      cat:"fondements",  def:"Structure de base d'une base relationnelle : une grille où chaque ligne est un enregistrement et chaque colonne un champ, tous les enregistrements ayant les mêmes colonnes. Comme un onglet de tableur, mais typé et sans cellule libre.", ex:"Table « clients » : id, nom, email, date_inscription", etymo:"Du latin tabula, « planche, tablette », sur laquelle on écrivait."},
  {name:"Enregistrement (ligne)",  en:"Record / Row",               cat:"fondements",  def:"Une ligne d'une table : un client, une commande, une mesure, avec une valeur pour chaque colonne. L'unité que l'on crée, lit, modifie et supprime.", ex:"(42, « Dupont », « marie@exemple.fr », 2026-09-20)", etymo:"Enregistrer, de registre, du latin médiéval registrum, altération de regesta, « choses rapportées ». Ligne, du latin linea, « fil de lin »."},
  {name:"Champ (colonne)",         en:"Field / Column",             cat:"fondements",  def:"Une colonne d'une table : un attribut avec un nom et un type (texte, nombre, date, booléen), le même pour toutes les lignes. Le type protège : on ne met pas de lettres dans un montant.", ex:"montant DECIMAL, date_naissance DATE, actif BOOLEAN", etymo:"Champ, du latin campus, « plaine, terrain » : un espace délimité. Colonne, du latin columna. L'anglais dit field."},
  {name:"Clé primaire",            en:"Primary Key",                cat:"fondements",  def:"Colonne (ou groupe de colonnes) qui identifie chaque ligne de façon unique et ne change jamais : le plus souvent un numéro auto-incrémenté ou un identifiant aléatoire (UUID). Deux lignes ne peuvent pas la partager.", ex:"id = 42 ; jamais l'e-mail ou le nom, qui peuvent changer ou se répéter", etymo:"Clé, du latin clavis. Primaire, du latin primarius, « du premier rang »."},
  {name:"Clé étrangère",           en:"Foreign Key",                cat:"fondements",  def:"Colonne qui contient la clé primaire d'une ligne d'une autre table, créant le lien : la commande porte l'identifiant de son client. Le SGBD peut refuser de supprimer un client qui a encore des commandes.", ex:"commandes.client_id → clients.id", etymo:"Étranger, de l'ancien français estrange, du latin extraneus, « du dehors » : la clé vient d'une autre table. Calque de foreign key (Codd, 1970)."},
  {name:"Schéma",                  en:"Schema",                     cat:"fondements",  def:"Structure de la base : les tables, leurs colonnes, leurs types, leurs clés et contraintes. Le plan de la maison ; il évolue par migrations.", ex:"Un schéma de dix tables pour une petite application, plusieurs centaines pour un ERP", etymo:"Du grec skhêma, « forme, figure »."},
  {name:"Métadonnées",             en:"Metadata",                   cat:"fondements",  ref:"informatique"},
  {name:"CRUD",                    en:"CRUD",                       cat:"fondements",  def:"Les quatre opérations élémentaires sur une donnée : créer, lire, mettre à jour, supprimer. Toute application, toute API, tout écran de gestion se ramène à du CRUD.", ex:"INSERT, SELECT, UPDATE, DELETE en SQL ; POST, GET, PUT, DELETE en REST", etymo:"Sigle de l'anglais Create, Read, Update, Delete (James Martin, 1983)."},

  // SQL & Relationnel
  {name:"SQL",                     en:"Structured Query Language",  cat:"sql",         def:"Langage standard pour interroger et manipuler les bases relationnelles : décrire ce qu'on veut (quelles colonnes, quelles lignes, quel ordre), le SGBD trouvant comment l'obtenir. Né chez IBM dans les années 1970, toujours incontournable.", ex:"SELECT nom, email FROM clients WHERE ville = 'Marseille' ORDER BY nom;", etymo:"Sigle de l'anglais Structured Query Language, « langage de requête structuré ». D'abord nommé SEQUEL chez IBM (1974), abrégé pour raison de marque déposée."},
  {name:"Requête",                 en:"Query",                      cat:"sql",         def:"Demande adressée à la base, en SQL ou via un outil : lire (SELECT), écrire (INSERT, UPDATE, DELETE), ou modifier la structure. Une requête lente est le premier suspect d'une application lente.", ex:"Combien de commandes ce mois-ci, par client, triées par montant ?", etymo:"Du latin populaire requaesita, de requirere, « rechercher, demander »."},
  {name:"Jointure",                en:"Join",                       cat:"sql",         def:"Opération qui combine les lignes de deux tables selon une correspondance de clés, pour lire d'un coup le client et ses commandes. INNER (les deux côtés existent), LEFT (garde tout à gauche même sans correspondance).", ex:"SELECT c.nom, o.montant FROM clients c JOIN commandes o ON o.client_id = c.id", etymo:"De joindre, du latin jungere, « atteler ensemble ». Calque de l'anglais join."},
  {name:"Index",                   en:"Index",                      cat:"sql",         def:"Structure annexe qui permet de retrouver des lignes sans parcourir toute la table, comme l'index d'un livre. Accélère les lectures, ralentit un peu les écritures ; à poser sur les colonnes qu'on cherche et qu'on joint.", ex:"Un index sur email fait passer une recherche de 3 secondes à 3 millisecondes sur un million de lignes", etymo:"Du latin index, « indicateur, doigt qui montre », d'où aussi l'index de la main."},
  {name:"Transaction",             en:"Transaction",                cat:"sql",         def:"Groupe d'opérations exécutées comme un tout : soit toutes réussissent, soit aucune n'est appliquée. Un virement débite un compte et crédite l'autre ; sans transaction, une panne entre les deux fait disparaître l'argent.", ex:"BEGIN ; débit ; crédit ; COMMIT — ou ROLLBACK si quelque chose échoue", etymo:"Du latin transactio, « accord conclu », de transigere, « mener à terme »."},
  {name:"ACID",                    en:"ACID",                       cat:"sql",         def:"Les quatre garanties d'une transaction fiable : atomicité (tout ou rien), cohérence (les règles sont respectées), isolation (les transactions simultanées ne se voient pas), durabilité (une fois validé, c'est écrit, même si le courant coupe).", ex:"PostgreSQL et SQLite sont ACID ; beaucoup de bases NoSQL relâchent l'une ou l'autre", etymo:"Sigle de l'anglais Atomicity, Consistency, Isolation, Durability (Härder et Reuter, 1983)."},
  {name:"Contrainte",              en:"Constraint",                 cat:"sql",         def:"Règle que le SGBD fait respecter lui-même : valeur obligatoire (NOT NULL), unique (UNIQUE), clé étrangère valide, condition (CHECK montant > 0). La base refuse la donnée fausse, quoi que fasse l'application.", ex:"UNIQUE (email) empêche deux comptes avec la même adresse", etymo:"Du latin constringere, « lier étroitement »."},
  {name:"Vue",                     en:"View",                       cat:"sql",         def:"Requête enregistrée sous un nom, utilisable comme une table virtuelle : simplifie les requêtes fréquentes, cache la complexité, restreint ce qu'un utilisateur voit.", ex:"Une vue « ventes_du_mois » que le tableau de bord interroge sans connaître les jointures", etymo:"Participe de voir, du latin videre. Calque de l'anglais view : une manière de « voir » les données."},
  {name:"Migration",               en:"Migration (Schema)",         cat:"sql",         def:"Script versionné qui fait évoluer le schéma d'une base (ajouter une colonne, une table, un index) de façon reproductible sur tous les environnements. Le Git de la structure.", ex:"migration 0042_ajout_colonne_telephone.sql, appliquée en test puis en production", etymo:"Du latin migratio, « changement de lieu »."},
  {name:"Valeur nulle",            en:"NULL",                       cat:"sql",         def:"Absence de valeur, distincte de zéro ou de la chaîne vide : « on ne sait pas ». Piège classique : NULL n'est égal à rien, même pas à NULL, et disparaît des comptages et des jointures.", ex:"WHERE telephone IS NULL, pas = NULL", etymo:"Du latin nullus, « aucun »."},
  {name:"Procédure stockée",       en:"Stored Procedure",           cat:"sql",         def:"Programme enregistré dans la base elle-même, exécuté par le SGBD : logique métier proche des données, rapide, mais difficile à versionner et à tester. Les déclencheurs (triggers) en sont la variante automatique.", ex:"Une procédure qui recalcule les soldes chaque nuit", etymo:"Procédure, du latin procedere, « s'avancer ». Stocker, de l'anglais stock, « réserve ». Calque de stored procedure (Sybase, années 1980)."},

  // Moteurs
  {name:"PostgreSQL",              en:"PostgreSQL",                 cat:"moteurs",     def:"SGBD relationnel open source, le plus complet et le plus respecté : standard SQL, JSON, extensions (géographie, vecteurs, recherche plein texte), fiabilité. Le choix par défaut d'un projet sérieux.", ex:"Supabase, Instagram, une base de finances personnelle", etymo:"De Postgres (« post-Ingres », successeur d'Ingres, Berkeley, 1986) et SQL. Prononcer « post-gress-cul-elle »."},
  {name:"MySQL et MariaDB",        en:"MySQL and MariaDB",          cat:"moteurs",     def:"SGBD relationnel open source le plus déployé, moteur historique du web (WordPress, PHP). MariaDB en est la branche communautaire, créée quand Oracle a racheté MySQL (2009).", ex:"Un hébergement mutualisé fournit presque toujours MySQL", etymo:"My et Maria sont les prénoms des filles du créateur, Michael Widenius."},
  {name:"SQLite",                  en:"SQLite",                     cat:"moteurs",     def:"Base relationnelle dans un seul fichier, sans serveur, embarquée dans le programme qui l'utilise. Le logiciel le plus déployé au monde : dans chaque téléphone, navigateur, appareil photo.", ex:"Le fichier .db d'une application locale ; parfait pour un outil personnel", etymo:"De SQL et lite, « léger ». Créé par D. Richard Hipp (2000)."},
  {name:"MongoDB",                 en:"MongoDB",                    cat:"moteurs",     def:"Base NoSQL orientée documents, la plus populaire : elle stocke des objets JSON de forme libre, sans schéma imposé, et s'étend sur plusieurs machines. Souple au départ, exigeante quand les données se structurent.", ex:"Un catalogue de produits aux attributs très variables", etymo:"De humongous, « énorme » en argot anglais."},
  {name:"Redis",                   en:"Redis",                      cat:"moteurs",     def:"Base clé-valeur en mémoire, ultra-rapide, utilisée comme cache, file d'attente, compteur, stockage de sessions. Les données tiennent en RAM et peuvent être perdues : ce n'est pas la base de référence.", ex:"Mettre en cache le résultat d'une requête lourde pendant dix minutes", etymo:"De REmote DIctionary Server, « serveur de dictionnaire distant » (Salvatore Sanfilippo, 2009)."},
  {name:"Elasticsearch",           en:"Elasticsearch",              cat:"moteurs",     def:"Moteur de recherche et d'analyse de texte, qui indexe des documents pour les retrouver par mots, avec tolérance aux fautes, pertinence et agrégations. Aussi le pilier de l'analyse de logs.", ex:"La recherche d'un site e-commerce, la recherche dans des millions de lignes de journaux ; Meilisearch en est une alternative légère", etymo:"Anglais, « recherche élastique » : qui s'étend à la demande. Créé par Shay Banon (2010), d'abord pour indexer les recettes de cuisine de sa femme."},
  {name:"DuckDB",                  en:"DuckDB",                     cat:"moteurs",     def:"Base analytique embarquée, sans serveur, qui interroge en SQL des fichiers CSV ou Parquet de plusieurs gigaoctets à grande vitesse. Le SQLite de l'analyse de données.", ex:"SELECT … FROM 'ventes-2025.csv' directement, sans import", etymo:"Duck, anglais, « canard » : le canard, dit-on, sait nager, voler et marcher, comme la base sait tout faire ; et Hannes Mühleisen, son créateur (2019), avait un canard domestique."},
  {name:"Tableur",                 en:"Spreadsheet",                cat:"moteurs",     def:"Grille de cellules libres, avec formules : la base de données de tout le monde, et souvent la bonne pour un besoin simple. Il montre ses limites quand il faut des types stricts, des liens entre tables, plusieurs utilisateurs ou un million de lignes.", ex:"Excel, Google Sheets, LibreOffice Calc ; passer à une base quand le tableur a trois onglets qui se recopient", etymo:"De table ; calque de l'anglais spreadsheet, « feuille étalée » (1979, VisiCalc)."},

  // NoSQL
  {name:"NoSQL",                   en:"NoSQL",                      cat:"nosql",       def:"Famille de bases qui s'écartent du modèle relationnel pour la souplesse du schéma ou la répartition sur de nombreuses machines : documents, clé-valeur, colonnes larges, graphes. « Pas seulement SQL » plutôt que « pas de SQL ».", ex:"MongoDB, Redis, Cassandra, Neo4j", etymo:"Anglais, d'abord « no SQL », réinterprété en Not only SQL. Terme relancé en 2009."},
  {name:"Base orientée documents", en:"Document Database",          cat:"nosql",       def:"Base qui stocke des documents autonomes (JSON), chacun avec sa propre structure, regroupés en collections. Naturel pour les objets imbriqués, coûteux pour les liens entre documents.", ex:"Un document « commande » qui contient ses lignes et l'adresse de livraison", etymo:"Document, du latin documentum, « exemple, leçon », de docere, « enseigner »."},
  {name:"Base clé-valeur",         en:"Key-Value Store",            cat:"nosql",       def:"La plus simple des bases : une clé, une valeur opaque, une lecture instantanée. Pas de requête sur le contenu ; idéale pour le cache, les sessions, les compteurs.", ex:"session:abc123 → { utilisateur: 42, expire: … }", etymo:"Clé, du latin clavis. Valeur, du latin valor, de valere, « être fort, valoir ». Calque de key-value store."},
  {name:"Base orientée graphe",    en:"Graph Database",             cat:"nosql",       def:"Base où les relations sont des données de premier rang : nœuds et arêtes, parcourus par des requêtes de chemin. Pour les réseaux sociaux, la détection de fraude, les recommandations.", ex:"« Amis d'amis qui ont acheté ce produit » en une requête ; Neo4j", etymo:"Graphe, du grec graphein, « dessiner » ; terme de Sylvester (1878)."},
  {name:"Base vectorielle",        en:"Vector Database",            cat:"nosql",       def:"Base qui stocke des vecteurs numériques (plongements produits par un modèle d'IA) et retrouve les plus proches d'un vecteur donné : recherche par le sens plutôt que par les mots. Brique du RAG.", ex:"pgvector (dans PostgreSQL), Pinecone, Qdrant ; « trouve les documents qui parlent de ça »", etymo:"Vecteur, du latin vector, « qui transporte », de vehere."},
  {name:"Plongement (embedding)",  en:"Embedding",                  cat:"nosql",       ref:"ia"},
  {name:"Cohérence à terme",       en:"Eventual Consistency",       cat:"nosql",       def:"Compromis des bases réparties : une écriture n'est pas visible immédiatement sur toutes les machines, mais le sera « à terme ». Accepte une lecture un peu ancienne contre la disponibilité et la vitesse.", ex:"Un like qui met quelques secondes à apparaître pour un autre utilisateur", etymo:"Cohérence, du latin cohaerentia, de cohaerere, « être attaché ensemble ». Calque de l'anglais eventual consistency (Werner Vogels, Amazon, 2008) ; eventual signifie « à terme », pas « éventuel »."},

  // Modélisation & Flux
  {name:"Normalisation",           en:"Normalization",              cat:"modelisation", def:"Découpage des tables pour que chaque information ne soit stockée qu'une fois : pas l'adresse du client dans chaque commande, mais un lien vers le client. Évite les incohérences ; les « formes normales » en sont les paliers.", ex:"Une table villes plutôt que le nom de la ville répété dans 10 000 lignes", etymo:"De norme, du latin norma, « équerre »."},
  {name:"Dénormalisation",         en:"Denormalization",            cat:"modelisation", def:"Recopier volontairement des données pour lire plus vite, au prix de leur maintien en cohérence. Pratique courante en analyse et à grande échelle, à éviter par défaut.", ex:"Stocker le total de la commande plutôt que le recalculer à chaque affichage", etymo:"Du préfixe dé- (privatif) et normalisation, de norme, du latin norma, « équerre »."},
  {name:"Modèle entité-association", en:"Entity-Relationship Model", cat:"modelisation", def:"Schéma qui dessine les objets du domaine (entités), leurs attributs et leurs liens (associations) avec leurs cardinalités, avant de créer les tables. Le plan avant le béton.", ex:"Un client passe zéro ou plusieurs commandes ; une commande a un seul client", etymo:"Notation de Peter Chen (1976)."},
  {name:"ORM",                     en:"Object-Relational Mapping",  cat:"modelisation", def:"Bibliothèque qui fait correspondre les tables à des classes et les lignes à des objets, pour manipuler la base dans le langage de programmation sans écrire de SQL. Confortable, parfois inefficace sans surveillance.", ex:"Prisma, SQLAlchemy, Django ORM ; client.commandes plutôt qu'une jointure", etymo:"Sigle de l'anglais object-relational mapping, « correspondance objet-relationnel »."},
  {name:"Entrepôt de données",     en:"Data Warehouse",             cat:"modelisation", def:"Base dédiée à l'analyse, distincte de celle de production : données de plusieurs sources, historisées, organisées pour les grosses requêtes agrégées plutôt que pour les écritures unitaires.", ex:"BigQuery, Snowflake ; le chiffre d'affaires par région sur cinq ans", etymo:"Calque de l'anglais data warehouse (Bill Inmon, années 1990)."},
  {name:"Lac de données",          en:"Data Lake",                  cat:"modelisation", def:"Stockage brut de toutes les données, structurées ou non (fichiers, logs, images), telles quelles, pour les exploiter plus tard. Sans discipline, il devient un marécage.", ex:"Des téraoctets de fichiers dans un stockage objet (S3), interrogés à la demande", etymo:"Calque de l'anglais data lake (James Dixon, 2010), par opposition à l'entrepôt, plus rangé."},
  {name:"ETL / ELT",               en:"ETL / ELT",                  cat:"modelisation", def:"Chaîne qui déplace les données d'un système à un autre : extraire, transformer, charger (ETL), ou charger d'abord et transformer dans la destination (ELT, l'usage moderne). Le plombier de la donnée.", ex:"Chaque nuit, copier les ventes de la boutique vers l'entrepôt et calculer les indicateurs", etymo:"Sigles de l'anglais Extract, Transform, Load."},
  {name:"Pipeline de données",     en:"Data Pipeline",              cat:"modelisation", def:"Suite d'étapes automatisées qui fait circuler et transformer la donnée, de la source à l'usage, avec ordonnancement, surveillance et reprise. L'ETL en est un cas.", ex:"Airflow, dbt ; un workflow n8n en est un petit", etymo:"Pipeline, anglais, « canalisation », de pipe (tuyau) + line."},

  // Exploitation & Performance
  {name:"Sauvegarde (backup)",     en:"Backup",                     cat:"exploitation", ref:"serveur"},
  {name:"Réplication",             en:"Replication",                cat:"exploitation", def:"Copie continue de la base sur une ou plusieurs autres machines (réplicas), pour survivre à une panne et répartir les lectures. La réplication n'est pas une sauvegarde : une suppression se réplique aussi.", ex:"Un serveur principal en écriture, deux réplicas en lecture", etymo:"Du latin replicare, « replier, répéter »."},
  {name:"Partitionnement (sharding)", en:"Sharding",                cat:"exploitation", def:"Découpage d'une table trop grosse en morceaux répartis sur plusieurs machines, selon une clé (par client, par date). Nécessaire à très grande échelle, source de complexité partout ailleurs.", ex:"Les utilisateurs A-M sur un serveur, N-Z sur un autre", etymo:"Shard, anglais, « éclat, tesson », du vieil anglais sceard."},
  {name:"Cache",                   en:"Cache",                      cat:"exploitation", ref:"informatique"},
  {name:"Plan d'exécution",        en:"Query Plan",                 cat:"exploitation", def:"Stratégie choisie par le SGBD pour répondre à une requête : quels index, quel ordre de jointure, parcours complet ou non. Le lire (EXPLAIN) est le moyen de comprendre pourquoi une requête est lente.", ex:"EXPLAIN ANALYZE SELECT … ; « Seq Scan » sur un million de lignes = il manque un index", etymo:"Plan, du latin planus, « plat ». Exécution, du latin exsecutio. Calque de query plan."},
  {name:"Verrou",                  en:"Lock",                       cat:"exploitation", def:"Mécanisme qui empêche deux transactions de modifier la même donnée en même temps. Nécessaire à la cohérence ; deux transactions qui s'attendent mutuellement forment un interblocage (deadlock).", ex:"Deux caissiers qui vendent le dernier exemplaire au même instant", etymo:"Du latin veruculum, « petite broche », diminutif de veru."},
  {name:"Pool de connexions",      en:"Connection Pool",            cat:"exploitation", def:"Réserve de connexions ouvertes à la base, réutilisées par l'application au lieu d'en ouvrir une par requête, ce qui est lent et limité. Indispensable dès qu'il y a du trafic.", ex:"Un pool de 20 connexions pour 2 000 utilisateurs", etymo:"Pool, anglais, « mise commune », du français poule, l'enjeu mis en commun au jeu."},
  {name:"Volumétrie",              en:"Data Volume",                cat:"exploitation", def:"Taille des données et rythme de croissance : lignes, gigaoctets, écritures par seconde. Le premier chiffre à connaître avant de choisir un moteur ou de s'inquiéter de la performance.", ex:"Un million de lignes, c'est petit ; un milliard demande de réfléchir", etymo:"De volume, du latin volumen, « rouleau » (de parchemin)."},

  // Analyse & Gouvernance
  {name:"Big Data",                en:"Big Data",                   cat:"analyse",     ref:"informatique"},
  {name:"CSV",                     en:"CSV",                        cat:"analyse",     def:"Format texte le plus simple pour échanger des données tabulaires : une ligne par enregistrement, des valeurs séparées par des virgules (ou des points-virgules en France). Universel, sans types, et piégeux dès qu'une valeur contient le séparateur.", ex:"nom;prenom;montant\nDupont;Marie;12,50 — l'encodage et le séparateur font toute la différence", etymo:"Sigle de l'anglais comma-separated values, « valeurs séparées par des virgules »."},
  {name:"JSON",                    en:"JSON",                       cat:"analyse",     ref:"api"},
  {name:"Données ouvertes",        en:"Open Data",                  cat:"analyse",     def:"Données publiées librement, réutilisables par tous, par les administrations et certaines entreprises : budgets, transports, cadastre, qualité de l'air. En France, data.gouv.fr en est le portail.", ex:"Horaires de bus, base Sirene des entreprises, adresses (BAN), résultats électoraux", etymo:"Ouvert, du latin apertus, de aperire. Calque de l'anglais open data, expression apparue en 1995 (données scientifiques), généralisée en 2009 (data.gov)."},
  {name:"Science des données",     en:"Data Science",               cat:"analyse",     def:"Tirer des connaissances des données par la statistique, la visualisation et l'apprentissage automatique : décrire, expliquer, prédire. L'ingénieur données prépare, le scientifique des données analyse.", ex:"Prévoir les ventes, segmenter les clients, détecter les anomalies ; Python, pandas, notebooks", etymo:"Calque de l'anglais data science, terme proposé par Peter Naur (1974), consacré par William Cleveland (2001)."},
  {name:"Qualité des données",     en:"Data Quality",               cat:"analyse",     def:"Degré auquel les données sont exactes, complètes, cohérentes, à jour et uniques. La cause première des analyses fausses et des automatisations qui déraillent : « déchets en entrée, déchets en sortie ».", ex:"Doublons de clients, dates au mauvais format, champs vides, villes écrites de six façons", etymo:"Qualité, du latin qualitas, « manière d'être », de qualis, « quel »."},
  {name:"Gouvernance des données", en:"Data Governance",            cat:"analyse",     def:"Organisation qui définit qui est responsable de quelles données, ce qu'on peut en faire, combien de temps on les garde, comment on les protège. Rendue obligatoire en pratique par le RGPD.", ex:"Un registre des traitements, un propriétaire par jeu de données, une durée de conservation", etymo:"Gouvernance, de gouverner, du latin gubernare, « tenir le gouvernail », du grec kubernan. Terme d'entreprise des années 2000."},
  {name:"Anonymisation",           en:"Anonymization",              cat:"analyse",     def:"Transformation irréversible qui empêche de réidentifier les personnes ; distincte de la pseudonymisation (remplacer le nom par un code, réversible avec la clé). Seules les données anonymisées sortent du RGPD.", ex:"Agréger par tranche d'âge et par département plutôt que garder les individus", etymo:"Du grec anônumos, « sans nom » : a- (privatif) + onoma (nom)."},
  {name:"RGPD",                    en:"GDPR",                       cat:"analyse",     ref:"numerique"},
];

// ── CORPS HUMAIN & MÉDECINE ──
// Sous-lexique de Sciences & Technologies. Repères de culture générale et de patient ; rien ici ne remplace un avis médical.
const terms_medecine = [
  // Corps & Organes
  {name:"Médecine",              en:"Medicine",               cat:"anatomie",    def:"Science et pratique qui visent à prévenir, diagnostiquer et traiter les maladies, et à soulager. Elle repose sur la biologie du corps humain et sur la preuve : un traitement vaut par ce qu'il démontre dans des essais.", ex:"Médecine générale, chirurgie, pédiatrie, psychiatrie, santé publique", etymo:"Du latin medicina, « art de guérir », de medicus, « médecin », de mederi, « soigner, remédier »."},
  {name:"Cellule",               en:"Cell",                   cat:"anatomie",    ref:"sciences"},
  {name:"Tissu",                 en:"Tissue",                 cat:"anatomie",    def:"Ensemble de cellules semblables assurant une même fonction : tissu musculaire, nerveux, osseux, épithélial (peau, muqueuses), conjonctif. Les organes sont faits de plusieurs tissus.", ex:"Une biopsie prélève un morceau de tissu pour l'examiner", etymo:"De tisser, du latin texere : les cellules « tissées » ensemble. Terme de Bichat (1800), fondateur de l'histologie."},
  {name:"Organe",                en:"Organ",                  cat:"anatomie",    def:"Partie du corps formée de tissus et remplissant une fonction définie : le cœur pompe, le foie filtre et fabrique, le rein épure. Les organes s'associent en systèmes (appareil digestif, système nerveux).", ex:"Cœur, poumons, foie, reins, cerveau, peau (le plus grand)", etymo:"Du grec organon, « instrument, outil »."},
  {name:"Squelette",             en:"Skeleton",               cat:"anatomie",    def:"Charpente de 206 os qui soutient le corps, protège les organes (crâne, cage thoracique), permet le mouvement avec les muscles et fabrique les cellules du sang dans la moelle osseuse. L'os est un tissu vivant, qui se renouvelle.", ex:"Fémur (le plus long), étrier de l'oreille (le plus petit) ; fracture, ostéoporose", etymo:"Du grec skeletos, « desséché », de skellein, « dessécher » : le corps desséché, la momie."},
  {name:"Muscle",                en:"Muscle",                 cat:"anatomie",    def:"Organe capable de se contracter pour produire un mouvement. Muscles squelettiques (volontaires, attachés aux os par les tendons), muscle cardiaque, muscles lisses des organes (involontaires : intestin, vaisseaux).", ex:"Environ 600 muscles, 40 % du poids du corps ; crampe, déchirure, courbature", etymo:"Du latin musculus, « petite souris » (diminutif de mus), par l'image du muscle qui bouge sous la peau."},
  {name:"Peau",                  en:"Skin",                   cat:"anatomie",    def:"Le plus grand organe (près de 2 m²) : barrière contre les microbes et la déshydratation, régulation de la température, toucher, fabrication de vitamine D. Trois couches : épiderme, derme, hypoderme.", ex:"Cicatrisation, coup de soleil, grain de beauté à surveiller, eczéma", etymo:"Du latin pellis, « peau d'animal, fourrure »."},
  {name:"Sang",                  en:"Blood",                  cat:"anatomie",    def:"Liquide qui circule dans les vaisseaux (environ 5 litres) : globules rouges (oxygène), globules blancs (défense), plaquettes (coagulation), plasma (transport). Le groupe sanguin (A, B, AB, O, rhésus) conditionne les transfusions.", ex:"Une prise de sang lit l'état de presque tous les organes", etymo:"Du latin sanguis. Le grec haima donne hémorragie, anémie, hématologie."},
  {name:"Cœur",                  en:"Heart",                  cat:"anatomie",    def:"Muscle creux qui pompe le sang : le côté droit l'envoie aux poumons, le côté gauche au reste du corps, environ 100 000 battements par jour. Quatre cavités, quatre valves, alimenté par les artères coronaires.", ex:"Pouls au repos : 60 à 100 par minute ; infarctus quand une coronaire se bouche", etymo:"Du latin cor, cordis. Le grec kardia donne cardiaque, cardiologie, tachycardie."},
  {name:"Poumons",               en:"Lungs",                  cat:"anatomie",    def:"Deux organes spongieux où le sang capte l'oxygène de l'air et rejette le gaz carbonique, à travers 300 millions d'alvéoles. Protégés par la cage thoracique, mus par le diaphragme.", ex:"Asthme, bronchite, pneumonie ; le tabac en est le premier ennemi", etymo:"Du latin pulmo. Le grec pneumôn donne pneumonie, pneumologie."},
  {name:"Foie",                  en:"Liver",                  cat:"anatomie",    def:"Le plus gros organe interne (1,5 kg), usine chimique du corps : il filtre le sang, transforme et stocke les nutriments, fabrique la bile et les protéines du sang, dégrade alcool et médicaments. Il se régénère.", ex:"Hépatite, cirrhose, foie gras (stéatose) lié au sucre et à l'alcool", etymo:"Du latin ficatum, « (foie) aux figues », le foie d'oie gavée de figues des Romains. Le grec hêpar donne hépatique, hépatite."},
  {name:"Reins",                 en:"Kidneys",                cat:"anatomie",    def:"Deux organes qui filtrent le sang (180 litres par jour) pour en éliminer les déchets dans l'urine, régulent l'eau, les sels et la tension. On peut vivre avec un seul ; leur défaillance impose la dialyse ou la greffe.", ex:"Calculs rénaux, insuffisance rénale, la créatinine comme indicateur", etymo:"Du latin ren, renis. Le grec nephros donne néphrologie, néphrite."},
  {name:"Cerveau",               en:"Brain",                  cat:"anatomie",    def:"Organe du système nerveux central (1,4 kg, 86 milliards de neurones) qui commande le corps, perçoit, pense, mémorise, ressent. Protégé par le crâne et les méninges, il consomme 20 % de l'énergie du corps.", ex:"AVC, commotion, Alzheimer, épilepsie ; l'IRM le montre en détail", etymo:"Du latin cerebrum. Le grec enkephalos (« dans la tête ») donne encéphale, encéphalite."},
  {name:"Système nerveux",       en:"Nervous System",         cat:"anatomie",    def:"Réseau de commande et de communication : cerveau et moelle épinière (système central), nerfs qui relient tout le corps (système périphérique). Une partie autonome règle sans nous le cœur, la digestion, la respiration.", ex:"Réflexe, sciatique (nerf comprimé), sclérose en plaques", etymo:"Nerf, du latin nervus, « tendon, corde ». Le grec neuron donne neurone, neurologie."},
  {name:"Système immunitaire",   en:"Immune System",          cat:"anatomie",    def:"Ensemble des défenses contre les microbes et les cellules anormales : globules blancs, anticorps, ganglions, rate, moelle osseuse. Il garde la mémoire des ennemis rencontrés, ce que le vaccin exploite. Déréglé, il attaque le corps (auto-immunité) ou l'inoffensif (allergie).", ex:"Fièvre et ganglions gonflés sont des signes qu'il travaille", etymo:"Immunité, du latin immunitas, « exemption de charge » : im- (non) + munus (charge, devoir)."},
  {name:"Système digestif",      en:"Digestive System",       cat:"anatomie",    def:"Tube de 9 mètres de la bouche à l'anus (œsophage, estomac, intestin grêle, côlon) et ses glandes (foie, pancréas), qui découpe les aliments en nutriments absorbables et élimine le reste. Abrite le microbiote, des milliards de bactéries utiles.", ex:"Reflux, ulcère, syndrome de l'intestin irritable, appendicite", etymo:"Digestion, du latin digestio, « distribution, répartition », de digerere, « porter çà et là »."},
  {name:"Hormones",              en:"Hormones",               cat:"anatomie",    def:"Messagers chimiques libérés dans le sang par les glandes (thyroïde, pancréas, surrénales, ovaires, testicules, hypophyse) pour régler croissance, métabolisme, reproduction, stress, sommeil. Le système endocrinien.", ex:"Insuline (sucre), cortisol (stress), thyroxine (métabolisme), mélatonine (sommeil), œstrogènes, testostérone", etymo:"Du grec hormân, « exciter, mettre en mouvement ». Terme de Starling (1905)."},
  {name:"ADN",                   en:"DNA",                    cat:"anatomie",    ref:"sciences"},

  // Fonctions vitales
  {name:"Respiration",           en:"Breathing",              cat:"physiologie", def:"Échange d'air par les poumons (12 à 20 mouvements par minute au repos), automatique mais contrôlable, qui apporte l'oxygène aux cellules et évacue le gaz carbonique. La respiration cellulaire, elle, est la production d'énergie à partir de l'oxygène.", ex:"Essoufflement, apnée du sommeil, saturation en oxygène mesurée au doigt (normale > 95 %)", etymo:"Du latin respiratio, de respirare, « souffler de nouveau »."},
  {name:"Circulation sanguine",  en:"Blood Circulation",      cat:"physiologie", def:"Trajet du sang propulsé par le cœur : artères (du cœur vers les organes, sous pression), capillaires (échanges), veines (retour). Découverte par William Harvey en 1628 ; avant, on croyait le sang produit et consommé.", ex:"Varices, phlébite (caillot dans une veine), artère bouchée", etymo:"Du latin circulatio, « mouvement circulaire », de circulus, « cercle »."},
  {name:"Métabolisme",           en:"Metabolism",             cat:"physiologie", def:"Ensemble des réactions chimiques qui transforment les aliments en énergie et en matière (construction, réparation, réserves). Le métabolisme de base est ce que le corps dépense au repos, environ 1 500 à 2 000 kcal par jour.", ex:"Maladies métaboliques : diabète, obésité, goutte", etymo:"Du grec metabolê, « changement », de metaballein, « transformer »."},
  {name:"Homéostasie",           en:"Homeostasis",            cat:"physiologie", def:"Maintien des constantes du corps (température à 37 °C, glycémie, pH, pression, eau) dans des limites étroites, par des boucles de régulation permanentes. La maladie est souvent une homéostasie qui ne tient plus.", ex:"Transpirer quand il fait chaud, frissonner quand il fait froid", etymo:"Du grec homoios, « semblable », et stasis, « position, arrêt ». Terme de Walter Cannon (1926)."},
  {name:"Sommeil",               en:"Sleep",                  cat:"physiologie", def:"État réversible de repos du corps et du cerveau, en cycles d'environ 90 minutes alternant sommeil lent (profond, réparateur) et paradoxal (rêves). Sept à neuf heures par nuit pour un adulte ; le manque chronique use le cœur, la mémoire et l'immunité.", ex:"Insomnie, apnée du sommeil, dette de sommeil", etymo:"Du latin somnus. Le grec hupnos donne hypnose, hypnotique."},
  {name:"Douleur",               en:"Pain",                   cat:"physiologie", def:"Signal d'alarme transmis par les nerfs au cerveau, utile quand il protège (retirer la main du feu), maladie en soi quand il dure (douleur chronique). Elle se mesure par le patient, de 0 à 10, et se traite.", ex:"Douleur aiguë après une entorse, douleur chronique du dos, migraine", etymo:"Du latin dolor, de dolere, « souffrir »."},
  {name:"Fièvre",                en:"Fever",                  cat:"physiologie", def:"Élévation de la température au-dessus de 38 °C, déclenchée par le corps lui-même pour combattre une infection. Utile et en général sans danger chez l'adulte ; à surveiller chez le nourrisson et au-delà de 40 °C.", ex:"Paracétamol pour le confort, pas pour « faire tomber » à tout prix", etymo:"Du latin febris. Le grec puretos donne antipyrétique."},
  {name:"Inflammation",          en:"Inflammation",           cat:"physiologie", def:"Réaction de défense des tissus à une agression (microbe, blessure, irritation) : rougeur, chaleur, gonflement, douleur. Nécessaire à la réparation ; nocive quand elle devient chronique (arthrite, athérosclérose).", ex:"Une entorse qui gonfle, une angine rouge, une tendinite", etymo:"Du latin inflammatio, de inflammare, « mettre le feu » : les quatre signes décrits par Celse au Ier siècle."},
  {name:"Tension artérielle",    en:"Blood Pressure",         cat:"physiologie", def:"Pression du sang dans les artères, mesurée par deux chiffres : quand le cœur se contracte (systolique) et quand il se relâche (diastolique). Normale autour de 12/8 ; trop haute en permanence, elle use le cœur, les reins, le cerveau, sans qu'on le sente.", ex:"14/9 et plus au repos, à plusieurs reprises : hypertension", etymo:"Tension, du latin tensio, « action de tendre ». Artère, du grec artêria, « conduit d'air » (on les croyait remplies d'air, étant vides sur les cadavres)."},
  {name:"Glycémie",              en:"Blood Sugar",            cat:"physiologie", def:"Taux de sucre (glucose) dans le sang, réglé par l'insuline, autour de 1 g/L à jeun. Trop élevé de façon durable, c'est le diabète ; trop bas, l'hypoglycémie (malaise, sueurs), à corriger vite.", ex:"À jeun : normale < 1,10 g/L, diabète ≥ 1,26 g/L à deux reprises", etymo:"Du grec glukus, « doux, sucré », et haima, « sang »."},
  {name:"Cholestérol",           en:"Cholesterol",            cat:"physiologie", def:"Graisse indispensable (membranes, hormones), fabriquée surtout par le foie. L'excès de « mauvais » cholestérol (LDL) se dépose dans les artères ; le « bon » (HDL) le ramène au foie. Se mesure par prise de sang, se traite par l'alimentation, l'exercice, les statines.", ex:"LDL à surveiller selon le risque cardiovasculaire global, pas seul", etymo:"Du grec kholê, « bile », et stereos, « solide » : découvert dans les calculs biliaires (1769)."},

  // Maladies
  {name:"Maladie",               en:"Disease",                cat:"maladies",    def:"Altération de la santé, aiguë (brève : grippe, fracture) ou chronique (durable : diabète, asthme), infectieuse, génétique, dégénérative, cancéreuse, mentale… La médecine la nomme (diagnostic), en cherche la cause et le traitement.", ex:"Une maladie n'est pas une faute ; on la soigne, on ne la juge pas", etymo:"De malade, du latin male habitus, « qui se porte mal »."},
  {name:"Infection",             en:"Infection",              cat:"maladies",    def:"Envahissement du corps par un microbe qui s'y multiplie : bactérie, virus, champignon, parasite. Contagieuse ou non, bénigne ou grave ; les antibiotiques n'agissent que sur les bactéries.", ex:"Angine, grippe, cystite, mycose, paludisme", etymo:"Du latin inficere, « imprégner, souiller » : in (dans) + facere (faire)."},
  {name:"Virus (biologie)",      en:"Virus",                  cat:"maladies",    def:"Agent infectieux minuscule, incapable de se reproduire seul : il entre dans une cellule et lui fait fabriquer ses copies. Insensible aux antibiotiques ; on le prévient par le vaccin, on le combat par quelques antiviraux et par l'immunité.", ex:"Grippe, rhume, COVID-19, VIH, hépatites, varicelle, papillomavirus", etymo:"Du latin virus, « poison, venin ». Sens biologique depuis Pasteur et la découverte des « virus filtrants » (1892)."},
  {name:"Bactérie",              en:"Bacterium",              cat:"maladies",    def:"Micro-organisme à une cellule, vivant partout, le plus souvent inoffensif ou utile (microbiote, yaourt), parfois pathogène. Les antibiotiques la tuent ; leur usage excessif sélectionne des bactéries résistantes, menace sanitaire majeure.", ex:"Angine à streptocoque, tuberculose, salmonelle, tétanos", etymo:"Du grec baktêrion, « petit bâton », par la forme des premières observées (1838)."},
  {name:"Cancer",                en:"Cancer",                 cat:"maladies",    def:"Multiplication incontrôlée de cellules anormales, qui envahissent les tissus voisins et peuvent essaimer (métastases). Des centaines de maladies différentes selon l'organe. Beaucoup se guérissent, surtout dépistés tôt ; première cause de décès en France.", ex:"Sein, prostate, poumon, côlon ; dépistages organisés ; chirurgie, chimiothérapie, radiothérapie, immunothérapie", etymo:"Du latin cancer, « crabe », traduisant le grec karkinos : Hippocrate compara la tumeur et ses veines gonflées aux pattes d'un crabe."},
  {name:"Diabète",               en:"Diabetes",               cat:"maladies",    def:"Excès chronique de sucre dans le sang. Type 1 : le pancréas ne fabrique plus d'insuline (enfant, jeune adulte, injections à vie). Type 2 (90 % des cas) : l'insuline agit mal, lié au surpoids et à la sédentarité, traité d'abord par le mode de vie.", ex:"Complications si mal contrôlé : yeux, reins, nerfs, cœur", etymo:"Du grec diabêtês, « qui traverse » (diabainein), à cause de l'urine abondante : l'eau « passe à travers » le corps."},
  {name:"Hypertension",          en:"Hypertension",           cat:"maladies",    def:"Tension artérielle durablement trop élevée (≥ 14/9), la maladie chronique la plus fréquente, silencieuse, qui multiplie AVC, infarctus et insuffisance rénale. Sel, poids, alcool, sédentarité la favorisent ; des médicaments efficaces existent.", ex:"Un adulte sur trois, la moitié l'ignore", etymo:"Du grec huper, « au-dessus », et tension."},
  {name:"AVC",                   en:"Stroke",                 cat:"maladies",    def:"Accident vasculaire cérébral : une artère du cerveau se bouche (80 %) ou se rompt, et la zone privée de sang meurt en quelques heures. Urgence absolue : chaque minute compte, un traitement existe dans les premières heures.", ex:"Signes : visage paralysé, bras faible, parole troublée → appeler le 15 immédiatement", etymo:"Sigle. Vasculaire, du latin vasculum, « petit vase »."},
  {name:"Infarctus",             en:"Heart Attack",           cat:"maladies",    def:"Mort d'une partie du muscle cardiaque, faute de sang, quand une artère coronaire se bouche par un caillot sur une plaque de cholestérol. Douleur dans la poitrine irradiant au bras ou à la mâchoire, urgence : déboucher l'artère au plus vite.", ex:"Appeler le 15 sans attendre ; tabac, cholestérol, diabète, hypertension en sont les causes", etymo:"Du latin infarcire, « bourrer, remplir » : le tissu « farci » de sang mort."},
  {name:"Allergie",              en:"Allergy",                cat:"maladies",    def:"Réaction excessive du système immunitaire à une substance inoffensive (pollen, acarien, aliment, médicament) : rhinite, asthme, urticaire, jusqu'au choc anaphylactique, qui peut tuer. Se teste, se traite, s'évite.", ex:"Rhume des foins, allergie à l'arachide, aux pénicillines ; stylo d'adrénaline pour les formes graves", etymo:"Du grec allos, « autre », et ergon, « action » : une réaction « autre ». Terme de Clemens von Pirquet (1906)."},
  {name:"Maladie auto-immune",   en:"Autoimmune Disease",     cat:"maladies",    def:"Maladie où le système immunitaire attaque les propres tissus du corps : thyroïde, articulations, intestin, nerfs, peau. Chroniques, plus fréquentes chez les femmes, contrôlées plutôt que guéries.", ex:"Diabète de type 1, polyarthrite rhumatoïde, sclérose en plaques, maladie de Crohn, lupus", etymo:"Du grec autos, « soi-même », et immunité."},
  {name:"Maladie chronique",     en:"Chronic Disease",        cat:"maladies",    def:"Maladie de longue durée, souvent à vie, qui se contrôle plus qu'elle ne se guérit : diabète, asthme, hypertension, insuffisance cardiaque, dépression. Vingt millions de personnes en France ; le suivi régulier est le traitement.", ex:"Affection de longue durée (ALD) : prise en charge à 100 %", etymo:"Du grec khronos, « temps »."},
  {name:"Épidémie et pandémie",  en:"Epidemic and Pandemic",  cat:"maladies",    def:"Propagation rapide d'une maladie infectieuse dans une population (épidémie) ou sur plusieurs continents (pandémie). Se combat par la surveillance, l'isolement, la vaccination, les gestes barrières.", ex:"Grippe saisonnière chaque hiver ; pandémies de 1918, du sida, de COVID-19 (2020)", etymo:"Du grec epi, « sur », dêmos, « peuple » ; pan, « tout »."},
  {name:"Dépression",            en:"Depression",             cat:"maladies",    def:"Maladie de l'humeur, non une faiblesse : tristesse durable, perte de plaisir et d'énergie, troubles du sommeil et de l'appétit, idées noires, pendant plus de deux semaines. Fréquente, se soigne par psychothérapie et, si besoin, médicaments.", ex:"Une personne sur cinq au cours de sa vie ; le 3114 pour les idées suicidaires", etymo:"Du latin depressio, « enfoncement », de deprimere, « presser vers le bas »."},
  {name:"Alzheimer",             en:"Alzheimer's Disease",    cat:"maladies",    def:"Maladie dégénérative du cerveau, première cause de démence : perte progressive de la mémoire récente, puis du langage, du raisonnement, de l'autonomie. Liée à l'âge, sans traitement curatif ; l'accompagnement fait la différence.", ex:"Un million de personnes en France ; oublier un mot est normal, oublier qu'on l'a demandé trois fois moins", etymo:"Du nom d'Alois Alzheimer, psychiatre allemand qui la décrivit en 1906."},
  {name:"Grippe et COVID-19",    en:"Flu and COVID-19",       cat:"maladies",    def:"Deux infections respiratoires virales, contagieuses, bénignes le plus souvent, graves chez les personnes âgées ou fragiles. Vaccins annuels recommandés pour ces publics. Le COVID-19, apparu fin 2019, a causé la pandémie de 2020-2022.", ex:"Fièvre, courbatures, toux ; rester chez soi, se laver les mains", etymo:"Grippe, de gripper, « saisir » (elle « attrape » brusquement). COVID, de coronavirus disease 2019."},

  // Examens & Diagnostic
  {name:"Symptôme",              en:"Symptom",                cat:"examens",     def:"Ce que le patient ressent et décrit (douleur, fatigue, nausée), par opposition au signe, que le médecin observe ou mesure (fièvre, éruption, souffle). L'ensemble oriente le diagnostic.", ex:"« J'ai mal au ventre depuis hier » ; le médecin note la fièvre et la douleur à droite", etymo:"Du grec sumptôma, « coïncidence, événement », de sumpiptein, « tomber ensemble »."},
  {name:"Diagnostic",            en:"Diagnosis",              cat:"examens",     def:"Identification de la maladie à partir de l'interrogatoire, de l'examen et des tests. Souvent probabiliste, parfois par élimination ; le diagnostic différentiel est la liste des possibilités à départager.", ex:"Une douleur thoracique : infarctus, embolie, pneumonie, ou simple contracture", etymo:"Du grec diagnôsis, « discernement », de diagignôskein, « distinguer »."},
  {name:"Prise de sang",         en:"Blood Test",             cat:"examens",     def:"Prélèvement dans une veine du bras, analysé en laboratoire : cellules (numération), sucre, cholestérol, fonctions du foie et des reins, hormones, inflammation, infections. L'examen le plus courant, souvent à jeun.", ex:"NFS, glycémie, créatinine, TSH, CRP ; résultats comparés aux valeurs de référence", etymo:"Prise, participe de prendre, du latin prehendere. La ponction veineuse à des fins d'analyse se généralise au début du XXe siècle."},
  {name:"Radiographie",          en:"X-ray",                  cat:"examens",     def:"Image obtenue par des rayons X traversant le corps : les os apparaissent en blanc, l'air en noir. Rapide, peu coûteuse, faiblement irradiante. Première image médicale (Röntgen, 1895).", ex:"Fracture, pneumonie, radio dentaire, mammographie", etymo:"Du latin radius, « rayon », et du grec graphein, « écrire »."},
  {name:"Scanner",               en:"CT Scan",                cat:"examens",     def:"Radiographie en coupes reconstituées par ordinateur, qui montre les organes en trois dimensions. Rapide, précis, plus irradiant qu'une radio ; souvent avec injection d'un produit de contraste.", ex:"Traumatisme, recherche de cancer, AVC en urgence", etymo:"Anglais, « qui balaie », de to scan, du latin scandere, « monter, scander ». On dit aussi tomodensitométrie."},
  {name:"IRM",                   en:"MRI",                    cat:"examens",     def:"Imagerie par résonance magnétique : un aimant puissant et des ondes radio, sans rayons X, donnent des images très fines des tissus mous (cerveau, moelle, articulations, organes). Long, bruyant, interdit avec certains métaux dans le corps.", ex:"Genou, hernie discale, sclérose en plaques, tumeur cérébrale", etymo:"Sigle. Résonance, du latin resonantia, « écho »."},
  {name:"Échographie",           en:"Ultrasound",             cat:"examens",     def:"Image formée par l'écho d'ultrasons envoyés par une sonde sur la peau. Sans danger, en temps réel, disponible partout : grossesse, cœur, abdomen, vaisseaux, thyroïde.", ex:"Échographies de grossesse, échographie cardiaque, Doppler des artères", etymo:"Du grec êkhô, « écho », et graphein, « écrire »."},
  {name:"Électrocardiogramme",   en:"Electrocardiogram (ECG)", cat:"examens",    def:"Enregistrement de l'activité électrique du cœur par des électrodes sur la peau, en quelques minutes. Détecte les troubles du rythme, l'infarctus, les anomalies de conduction.", ex:"Tracé aux urgences devant une douleur thoracique ; certaines montres en font un", etymo:"Du grec êlektron, kardia (cœur) et gramma (écrit). Inventé par Willem Einthoven (1903)."},
  {name:"Biopsie",               en:"Biopsy",                 cat:"examens",     def:"Prélèvement d'un fragment de tissu (à l'aiguille, en endoscopie ou en chirurgie) pour l'examiner au microscope. Le seul moyen de confirmer un cancer et d'en préciser le type.", ex:"Biopsie de la prostate, du sein, du foie, de la peau", etymo:"Du grec bios, « vie », et opsis, « vue » : voir le vivant."},
  {name:"Dépistage",             en:"Screening",              cat:"examens",     def:"Recherche d'une maladie chez des personnes sans symptôme, pour la traiter tôt. Organisé en France pour les cancers du sein, du côlon et du col de l'utérus ; tests recommandés selon l'âge et les risques.", ex:"Mammographie tous les deux ans de 50 à 74 ans, test immunologique des selles, frottis", etymo:"De dépister, « suivre à la piste » (le gibier), de piste, de l'italien pista, « trace »."},
  {name:"Bilan de santé",        en:"Health Check-up",        cat:"examens",     def:"Ensemble d'examens de contrôle sans symptôme particulier : mesures, prise de sang, questions sur les habitudes. Utile selon l'âge ; l'Assurance maladie en propose un gratuit tous les cinq ans.", ex:"Tension, poids, glycémie, cholestérol, vue, audition, vaccins à jour", etymo:"Bilan, de l'italien bilancio, « balance ». Santé, du latin sanitas, de sanus, « sain »."},

  // Traitements
  {name:"Médicament",            en:"Medication",             cat:"traitements", def:"Substance qui prévient, soulage ou guérit, autorisée après des essais prouvant son efficacité et sa sécurité. Toujours un rapport bénéfice/risque : pas de médicament sans effet secondaire possible. Sur ordonnance ou en vente libre.", ex:"Paracétamol, ibuprofène, amoxicilline, insuline ; la notice dit ce qu'il faut savoir", etymo:"Du latin medicamentum, « remède », de medicari, « soigner »."},
  {name:"Générique",             en:"Generic Drug",           cat:"traitements", def:"Copie d'un médicament dont le brevet a expiré, même substance, même dose, même effet, moins cher. Le pharmacien le substitue par défaut ; refuser fait avancer les frais.", ex:"Doliprane → paracétamol ; le nom du générique est celui de la molécule", etymo:"Du latin genus, generis, « genre, espèce » : le nom du genre, pas de la marque."},
  {name:"Antibiotique",          en:"Antibiotic",             cat:"traitements", def:"Médicament qui tue les bactéries ou bloque leur multiplication. Sans effet sur les virus (rhume, grippe, la plupart des angines). Chaque prise inutile favorise les résistances : « les antibiotiques, c'est pas automatique ».", ex:"Pénicilline (Fleming, 1928), amoxicilline ; toujours finir la cure prescrite", etymo:"Du grec anti, « contre », et bios, « vie »."},
  {name:"Vaccin",                en:"Vaccine",                cat:"traitements", def:"Préparation qui entraîne le système immunitaire à reconnaître un microbe sans provoquer la maladie, pour qu'il réponde vite à la vraie rencontre. L'intervention médicale qui a sauvé le plus de vies ; protège aussi ceux qui ne peuvent pas être vaccinés.", ex:"Onze vaccins obligatoires pour les enfants nés depuis 2018 ; rappels adultes (tétanos, grippe, COVID)", etymo:"Du latin vacca, « vache » : Jenner (1796) protégea de la variole en inoculant la vaccine, la variole des vaches. Pasteur généralisa le mot."},
  {name:"Anti-inflammatoire",    en:"Anti-inflammatory",      cat:"traitements", def:"Médicament qui réduit l'inflammation et la douleur : non stéroïdiens (ibuprofène, aspirine, kétoprofène), à éviter en cas d'ulcère, de problème rénal, de grossesse ; corticoïdes (cortisone), puissants, à encadrer.", ex:"Ibuprofène pour une entorse, cortisone pour une crise d'asthme", etymo:"Du grec anti, « contre », et inflammation, du latin inflammare, « mettre le feu ». L'aspirine (1899) est le premier de synthèse."},
  {name:"Antalgique",            en:"Painkiller",             cat:"traitements", def:"Médicament contre la douleur, par paliers : paracétamol (sûr aux doses respectées, toxique pour le foie au-delà), anti-inflammatoires, puis opioïdes (codéine, tramadol, morphine) pour les douleurs fortes, sous surveillance.", ex:"Paracétamol : 1 g au maximum quatre fois par jour, 4 g par jour au plus", etymo:"Du grec an- (privatif) + algos (douleur)."},
  {name:"Posologie",             en:"Dosage",                 cat:"traitements", def:"Dose, fréquence et durée d'un médicament, selon l'âge, le poids et l'état du patient. La respecter fait l'efficacité et la sécurité ; doubler ne soigne pas plus vite.", ex:"« 1 comprimé matin et soir pendant 7 jours »", etymo:"Du grec posos, « combien », et logos, « discours »."},
  {name:"Effet secondaire",      en:"Side Effect",            cat:"traitements", def:"Effet non voulu d'un médicament, du bénin (somnolence, nausée) au grave (allergie, hémorragie). Listé dans la notice avec sa fréquence ; à signaler au médecin, au pharmacien ou sur le portail de pharmacovigilance.", ex:"Somnolence avec un antihistaminique, saignement sous anticoagulant", etymo:"Effet, du latin effectus, « résultat », de efficere. Secondaire, du latin secundarius, « de second rang »."},
  {name:"Interaction médicamenteuse", en:"Drug Interaction",  cat:"traitements", def:"Effet d'un médicament modifié par un autre, un aliment ou une plante : renforcé, annulé, ou nouveau danger. D'où l'importance de dire tout ce qu'on prend, y compris sans ordonnance.", ex:"Pamplemousse et certains médicaments, millepertuis et pilule, anti-inflammatoire et anticoagulant", etymo:"Interaction, du latin inter (entre) + actio (action). Médicamenteux, du latin medicamentum, « remède »."},
  {name:"Ordonnance",            en:"Prescription",           cat:"traitements", def:"Document par lequel un médecin (ou une sage-femme, un dentiste) prescrit un médicament, un examen ou des soins, avec la posologie et la durée. Nécessaire pour les médicaments « à prescription obligatoire » et pour le remboursement.", ex:"Valable trois mois pour un médicament, un an renouvelable pour un traitement chronique", etymo:"De ordonner, du latin ordinare, « mettre en ordre »."},
  {name:"Chirurgie",             en:"Surgery",                cat:"traitements", def:"Traitement par intervention manuelle et instrumentale sur le corps, sous anesthésie : réparer, enlever, remplacer. De plus en plus par petites incisions (cœlioscopie) ou assistée par robot, avec sortie le jour même (ambulatoire).", ex:"Appendicite, prothèse de hanche, cataracte (la plus pratiquée), césarienne", etymo:"Du grec kheirourgia, « travail de la main » : kheir (main) + ergon (œuvre)."},
  {name:"Anesthésie",            en:"Anesthesia",             cat:"traitements", def:"Suppression de la douleur, locale (une zone, patient éveillé), locorégionale (péridurale, un membre) ou générale (sommeil artificiel, respiration assistée), surveillée par un médecin anesthésiste. Devenue très sûre.", ex:"Consultation d'anesthésie obligatoire avant une opération programmée", etymo:"Du grec an- (privatif) + aisthêsis (sensation). Première anesthésie à l'éther en 1846."},
  {name:"Placebo",               en:"Placebo",                cat:"traitements", def:"Substance sans effet propre, donnée comme un médicament, qui soulage pourtant une partie des patients par la seule attente d'un effet. Sert de comparaison dans les essais : un traitement doit faire mieux que le placebo.", ex:"Comprimé de sucre contre la douleur : 30 % de soulagement en moyenne", etymo:"Latin, « je plairai », première parole des vêpres des morts, chantées par des pleureurs payés : d'où l'idée de complaisance."},
  {name:"Kinésithérapie",        en:"Physiotherapy",          cat:"traitements", def:"Rééducation par le mouvement, les massages et les exercices, pour récupérer après une blessure, une opération, un AVC, ou soulager un dos douloureux. Sur ordonnance, remboursée.", ex:"Dix séances après une entorse, rééducation respiratoire, kiné du dos", etymo:"Du grec kinêsis, « mouvement », et therapeia, « soin »."},
  {name:"Greffe",                en:"Transplant",             cat:"traitements", def:"Remplacement d'un organe ou d'un tissu défaillant par celui d'un donneur (vivant ou décédé), avec un traitement à vie contre le rejet. Rein, foie, cœur, poumon, moelle osseuse, cornée. En France, tout le monde est donneur présumé sauf refus exprimé.", ex:"6 000 greffes par an, 20 000 personnes en attente", etymo:"Du grec grapheion, « poinçon », par l'image de la greffe des arbres : le greffon taillé en pointe."},

  // Soins & Professionnels
  {name:"Médecin traitant",      en:"General Practitioner",   cat:"soins",       def:"Médecin généraliste choisi et déclaré par le patient, premier interlocuteur pour tout problème de santé, qui coordonne les soins et oriente vers les spécialistes. Consulter sans passer par lui coûte plus cher (parcours de soins).", ex:"Déclaration à l'Assurance maladie ; une consultation autour de 30 €, remboursée à 70 %", etymo:"Médecin, du latin medicus. Traitant, de traiter, du latin tractare, « manier, s'occuper de »."},
  {name:"Spécialiste",           en:"Specialist",             cat:"soins",       def:"Médecin formé à un organe, une population ou une technique : cardiologue, dermatologue, pédiatre, psychiatre, radiologue, chirurgien… Une cinquantaine de spécialités ; accès sur orientation du médecin traitant, sauf quelques-uns (gynécologue, ophtalmologue, psychiatre pour les moins de 26 ans).", ex:"Délais d'attente de plusieurs mois dans certaines régions", etymo:"Du latin species, « aspect, espèce »."},
  {name:"Infirmier",             en:"Nurse",                  cat:"soins",       def:"Professionnel qui dispense les soins prescrits (injections, pansements, perfusions), surveille l'état du patient, éduque, accompagne, à l'hôpital, en cabinet ou à domicile. Métier le plus nombreux de la santé ; des compétences élargies (vaccination, renouvellements, pratique avancée).", ex:"Infirmière à domicile pour une prise de sang, infirmier de bloc, infirmière scolaire", etymo:"Du latin infirmus, « faible, malade » : celui qui s'occupe des infirmes."},
  {name:"Pharmacien",            en:"Pharmacist",             cat:"soins",       def:"Professionnel du médicament : délivre les ordonnances, vérifie les interactions, conseille pour les petits maux, vaccine, dépiste. Toujours accessible sans rendez-vous ; le premier recours de proximité.", ex:"Une pharmacie de garde par secteur la nuit et le dimanche", etymo:"Du grec pharmakon, « remède » et aussi « poison » : la dose fait la différence."},
  {name:"Urgences",              en:"Emergency Department",   cat:"soins",       def:"Service hospitalier ouvert en permanence pour les situations graves ou soudaines. Le 15 (SAMU) régule : conseil, médecin, ambulance ou hélicoptère. Pour ce qui ne presse pas, médecin traitant, maison médicale de garde ou pharmacie évitent des heures d'attente.", ex:"15 pour une urgence vitale, 112 depuis toute l'Europe, 116 117 pour un médecin de garde", etymo:"Du latin urgens, participe de urgere, « presser »."},
  {name:"Hôpital",               en:"Hospital",               cat:"soins",       def:"Établissement de soins avec hébergement, plateaux techniques et spécialités. Public (CHU, centres hospitaliers), privé à but non lucratif, ou clinique privée ; tarifs et dépassements varient, la qualité des soins est encadrée pour tous.", ex:"CHU pour les cas complexes, hôpital de proximité, clinique pour une opération programmée", etymo:"Du latin hospitalis, « hospitalier », de hospes, « hôte ». Même racine qu'hôtel, hospice, hospitalité."},
  {name:"Consultation",          en:"Consultation",           cat:"soins",       def:"Rencontre avec un professionnel de santé : le patient raconte, le médecin interroge, examine, explique, prescrit. Elle vaut par la parole autant que par l'examen ; préparer ses questions et sa liste de médicaments l'améliore.", ex:"Consultation de 15 à 20 minutes en médecine générale", etymo:"Du latin consultatio, « délibération », de consulere, « prendre conseil »."},
  {name:"Téléconsultation",      en:"Telemedicine Consultation", cat:"soins",    def:"Consultation à distance, par vidéo, remboursée comme une consultation classique sous conditions (patient connu du médecin ou orienté). Pratique pour un renouvellement, un conseil, un suivi ; pas pour ce qui demande un examen.", ex:"Renouvellement d'ordonnance, avis dermatologique sur photo, suivi psychologique", etymo:"Du grec têle, « au loin », et consultation."},
  {name:"Secret médical",        en:"Medical Confidentiality", cat:"soins",      def:"Obligation pour tout soignant de ne rien révéler de ce qu'il apprend sur un patient, même à sa famille, même après sa mort, sauf exceptions prévues par la loi (mineur en danger, certaines maladies à déclaration). Fondement de la confiance.", ex:"Le médecin ne dit pas à un employeur pourquoi un salarié est en arrêt", etymo:"Secret, du latin secretum, « mis à part ». Principe du serment d'Hippocrate (Ve siècle av. J.-C.)."},
  {name:"Consentement éclairé",  en:"Informed Consent",       cat:"soins",       def:"Aucun acte médical sans l'accord du patient, informé des bénéfices, des risques et des alternatives. Il peut refuser ou changer d'avis. Les directives anticipées disent ce qu'on veut si l'on ne peut plus s'exprimer.", ex:"Signer avant une opération après explication, désigner une personne de confiance", etymo:"Consentement, du latin consentire, « être d'accord » : cum (avec) + sentire (sentir)."},
  {name:"Soins palliatifs",      en:"Palliative Care",        cat:"soins",       def:"Soins qui, quand on ne peut plus guérir, visent à soulager la douleur et les symptômes, à accompagner le patient et ses proches, jusqu'à la fin. Un droit ; à l'hôpital, en unité dédiée ou à domicile.", ex:"Prise en charge de la douleur, soutien psychologique, présence", etymo:"Du latin palliare, « couvrir d'un manteau » (pallium) : couvrir le mal qu'on ne peut ôter."},

  // Système de santé
  {name:"Sécurité sociale",      en:"Social Security",        cat:"systeme_sante", def:"Système public de protection contre les risques de la vie (maladie, maternité, accident du travail, retraite, famille), créé en 1945, financé par les cotisations et la CSG. L'Assurance maladie en est la branche santé.", ex:"Prise en charge de l'hôpital, des médecins, des médicaments, des arrêts de travail", etymo:"Sécurité, du latin securitas, « absence de souci ». Ordonnances des 4 et 19 octobre 1945."},
  {name:"Assurance maladie",     en:"Health Insurance (Public)", cat:"systeme_sante", def:"Branche de la Sécurité sociale qui rembourse les soins : 70 % d'une consultation, 65 à 100 % des médicaments selon leur utilité, 80 % de l'hôpital, 100 % pour les maladies longues (ALD) et la maternité. Le compte ameli.fr suit les remboursements.", ex:"Reste à charge réglé par la mutuelle ; franchise de quelques euros par boîte et par acte", etymo:"Assurance, de assurer, du latin populaire assecurare, « rendre sûr »."},
  {name:"Carte Vitale",          en:"Carte Vitale (Health Card)", cat:"systeme_sante", def:"Carte à puce qui identifie l'assuré et permet le remboursement automatique (télétransmission) sans feuille de soins. Elle ne contient ni dossier médical ni argent ; une version sur smartphone existe.", ex:"À présenter chez le médecin, à la pharmacie, au laboratoire", etymo:"Vitale, du latin vitalis, « relatif à la vie ». Lancée en 1998."},
  {name:"Mutuelle",              en:"Complementary Health Insurance", cat:"systeme_sante", def:"Assurance complémentaire, privée, qui rembourse tout ou partie de ce que l'Assurance maladie laisse à charge : ticket modérateur, dépassements, lunettes, dentaire. Obligatoire par l'employeur pour les salariés ; complémentaire santé solidaire gratuite pour les revenus modestes.", ex:"Le « 100 % santé » impose des lunettes, prothèses dentaires et audioprothèses sans reste à charge", etymo:"De mutuel, du latin mutuus, « réciproque » : à l'origine, des sociétés de secours mutuel entre ouvriers."},
  {name:"Parcours de soins",     en:"Care Pathway",           cat:"systeme_sante", def:"Organisation des soins autour du médecin traitant, qui oriente vers les spécialistes. Le respecter donne le remboursement normal ; consulter directement un spécialiste hors parcours réduit le remboursement.", ex:"Médecin traitant → cardiologue → examens → retour au médecin traitant", etymo:"Parcours, du latin percursus, de percurrere. Soin, d'origine francique (sunni, « souci »). Dispositif créé par la loi du 13 août 2004."},
  {name:"Dossier médical partagé", en:"Shared Medical Record", cat:"systeme_sante", def:"Carnet de santé numérique de chaque assuré (Mon espace santé), où soignants et patient déposent comptes rendus, ordonnances, résultats, vaccins. Le patient contrôle qui y accède.", ex:"Retrouver un résultat d'analyse, partager son dossier avec un nouveau médecin", etymo:"Dossier, de dos : la liasse dont le dos porte l'étiquette. Partagé, de partager, du latin partire, « diviser »."},
  {name:"Arrêt de travail",      en:"Sick Leave",             cat:"systeme_sante", def:"Prescription médicale d'interruption du travail pour maladie ou accident, avec indemnités journalières de l'Assurance maladie (environ 50 % du salaire après trois jours de carence) souvent complétées par l'employeur.", ex:"À transmettre sous 48 heures ; sorties autorisées ou non selon le médecin", etymo:"Arrêt, de arrêter, du latin populaire arrestare, « s'arrêter », de restare, « rester »."},
  {name:"Espérance de vie",      en:"Life Expectancy",        cat:"systeme_sante", def:"Nombre moyen d'années qu'une personne peut espérer vivre : en France, environ 80 ans pour les hommes et 85 pour les femmes, parmi les plus élevées au monde. L'espérance de vie en bonne santé, sans incapacité, est d'environ 65 ans.", ex:"Écarts selon le revenu : jusqu'à treize ans entre les plus riches et les plus pauvres", etymo:"Espérance, du latin sperare, « espérer » : la vie « espérée » au sens statistique."},
  {name:"OMS",                   en:"WHO",                    cat:"systeme_sante", def:"Organisation mondiale de la santé, agence de l'ONU (1948) qui coordonne la santé publique mondiale : surveillance des épidémies, recommandations, programmes de vaccination, classification des maladies.", ex:"Éradication de la variole (1980), déclaration de la pandémie de COVID-19 (mars 2020)", etymo:"Sigle. Siège à Genève."},
  {name:"Déserts médicaux",      en:"Medical Deserts",        cat:"systeme_sante", def:"Territoires où trouver un médecin traitant, un spécialiste ou un rendez-vous rapide est devenu difficile, faute de praticiens : zones rurales, mais aussi banlieues et centres-villes. Six millions de Français sans médecin traitant.", ex:"Maisons de santé, télémédecine, assistants médicaux, infirmiers en pratique avancée comme réponses", etymo:"Désert, du latin desertum, « lieu abandonné », de deserere, « abandonner ». Expression apparue dans la presse française vers 2005."},

  // Prévention & Hygiène de vie
  {name:"Prévention",            en:"Prevention",             cat:"prevention",  def:"Tout ce qui évite la maladie ou la détecte tôt : hygiène de vie, vaccins, dépistages, sécurité. Primaire (avant), secondaire (dépister), tertiaire (limiter les conséquences). Le meilleur rapport coût-efficacité de la médecine.", ex:"Ne pas fumer, bouger, manger varié, dormir, se faire vacciner, se faire dépister", etymo:"Du latin praeventio, de praevenire, « devancer, prendre les devants »."},
  {name:"Nutrition",             en:"Nutrition",              cat:"prevention",  def:"Ce que le corps tire des aliments : énergie, protéines, glucides, lipides, vitamines, minéraux, fibres, eau. Les repères français : fruits et légumes, légumineuses, céréales complètes, peu de sucre, de sel, de viande rouge et d'ultra-transformé.", ex:"Le Nutri-Score pour comparer, l'assiette moitié légumes, boire de l'eau", etymo:"Du latin nutritio, de nutrire, « nourrir »."},
  {name:"Activité physique",     en:"Physical Activity",      cat:"prevention",  def:"Tout mouvement qui dépense de l'énergie : marche, vélo, escaliers, jardinage, sport. Trente minutes par jour d'activité modérée réduisent le risque de maladies cardiovasculaires, de diabète, de cancers, de dépression. La sédentarité (rester assis) est un risque en soi.", ex:"Marcher d'un bon pas, se lever toutes les heures, un peu de renforcement musculaire", etymo:"Physique, du grec phusis, « nature » : relatif au corps."},
  {name:"Tabac",                 en:"Tobacco",                cat:"prevention",  def:"Première cause de mort évitable : 75 000 décès par an en France (cancers, infarctus, AVC, bronchite chronique). Arrêter à tout âge profite dès les premiers jours ; substituts nicotiniques, accompagnement et Tabac info service (39 89) doublent les chances.", ex:"Le risque du fumeur rejoint presque celui du non-fumeur quinze ans après l'arrêt", etymo:"De l'espagnol tabaco, d'une langue des Caraïbes (Haïti), rapporté par Colomb."},
  {name:"Alcool",                en:"Alcohol",                cat:"prevention",  def:"Deuxième cause de mort évitable (41 000 décès par an) : cancers (dès le premier verre), foie, cœur, accidents, dépendance. Repère : pas plus de deux verres par jour, pas tous les jours, dix par semaine au maximum.", ex:"Un verre standard = 10 g d'alcool = un demi de bière, un ballon de vin, une dose de spiritueux", etymo:"De l'arabe al-kuhl, « le khôl », poudre fine d'antimoine, puis toute substance subtile obtenue par distillation."},
  {name:"IMC",                   en:"BMI",                    cat:"prevention",  def:"Indice de masse corporelle : poids divisé par la taille au carré. Normal entre 18,5 et 25, surpoids au-delà, obésité à partir de 30. Repère utile à l'échelle d'une population, grossier pour un individu (muscle, âge, tour de taille).", ex:"70 kg pour 1,75 m : 70 / 1,75² ≈ 22,9", etymo:"Sigle. Formule d'Adolphe Quetelet (1832)."},
  {name:"Stress",                en:"Stress",                 cat:"prevention",  def:"Réaction du corps à une pression : adrénaline, cortisol, cœur qui s'accélère, utile pour agir face à un danger bref. Chronique, il use : sommeil, immunité, tension, humeur, digestion. Activité physique, sommeil, relations et, si besoin, aide psychologique en sont les remèdes.", ex:"Burn-out, épuisement professionnel", etymo:"Anglais, « pression, contrainte », de l'ancien français destresse (détresse). Sens biologique dû à Hans Selye (1936)."},
  {name:"Hygiène",               en:"Hygiene",                cat:"prevention",  def:"Ensemble des pratiques qui préviennent les infections et entretiennent la santé : se laver les mains (le geste le plus efficace), brossage des dents, propreté des aliments, aération. L'hygiène a sauvé plus de vies que les médicaments.", ex:"Lavage des mains avant de manger et après les toilettes, deux brossages par jour, eau potable", etymo:"Du grec hugieinê (tekhnê), « art de la santé », de Hygie, déesse de la santé, fille d'Asclépios."},
  {name:"Santé mentale",         en:"Mental Health",          cat:"prevention",  def:"État de bien-être psychique qui permet de faire face aux difficultés, de travailler, d'être en lien. Elle se soigne comme le reste : anxiété, dépression, addictions, troubles du sommeil ont des traitements efficaces. Un enjeu de santé publique majeur, longtemps tabou.", ex:"Psychologue remboursé sur orientation (Mon soutien psy), 3114 (prévention du suicide), médecin traitant en premier recours", etymo:"Santé, du latin sanitas, de sanus, « sain ». Mental, du latin mens, mentis, « esprit »."},
];

// ── ÉCONOMIE & FINANCE ──
// Sous-lexique de Sciences humaines & sociales. Repères pour comprendre l'actualité et gérer son argent ; aucun conseil de placement.
const terms_economie = [
  // Fondements
  {name:"Économie",                en:"Economics",                cat:"fondements", def:"Science des choix face à la rareté : comment les individus, les entreprises et les États produisent, échangent, consomment et répartissent des ressources limitées. Descriptive (ce qui est) et normative (ce qui devrait être), elle nourrit le débat politique.", ex:"Pourquoi les prix montent, pourquoi il y a du chômage, à quoi sert un impôt", etymo:"Du grec oikonomia, « administration de la maison » : oikos (maison) + nomos (loi, règle). Sens moderne depuis le XVIIIe siècle."},
  {name:"Microéconomie",           en:"Microeconomics",           cat:"fondements", def:"Étude des comportements individuels : le consommateur qui arbitre, l'entreprise qui fixe un prix, un marché qui s'équilibre. La brique de base de l'analyse économique.", ex:"Combien de café achète-t-on si le prix double ? Combien une entreprise produit-elle ?", etymo:"Du grec mikros, « petit », et oikonomia. Terme de Ragnar Frisch (1933)."},
  {name:"Macroéconomie",           en:"Macroeconomics",           cat:"fondements", def:"Étude de l'économie dans son ensemble : croissance, inflation, chômage, commerce extérieur, dette, et les politiques qui agissent dessus. Née de la crise de 1929 avec Keynes.", ex:"Le PIB de la France, le taux de chômage, la politique de la BCE", etymo:"Du grec makros, « grand, long », et oikonomia. Terme de Ragnar Frisch (1933)."},
  {name:"Rareté",                  en:"Scarcity",                 cat:"fondements", def:"Point de départ de l'économie : les besoins sont illimités, les ressources (temps, argent, matières, travail) ne le sont pas. Il faut choisir, et tout choix a un coût.", ex:"Un budget, une journée de 24 heures, l'eau dans un pays sec", etymo:"Du latin raritas, « peu de densité », de rarus, « clairsemé »."},
  {name:"Coût d'opportunité",      en:"Opportunity Cost",         cat:"fondements", def:"Ce à quoi on renonce en faisant un choix : le vrai coût d'une chose est la meilleure alternative abandonnée. Étudier cinq ans coûte les frais, mais aussi cinq ans de salaire.", ex:"Garder 10 000 € sur un compte courant coûte les intérêts qu'ils auraient rapportés ailleurs", etymo:"Calque de l'anglais opportunity cost (Friedrich von Wieser, 1914)."},
  {name:"Offre et demande",        en:"Supply and Demand",        cat:"fondements", def:"Les deux forces d'un marché : ce que les vendeurs proposent à chaque prix (l'offre, qui monte avec le prix) et ce que les acheteurs veulent (la demande, qui baisse avec le prix). Leur rencontre fixe le prix et la quantité échangée.", ex:"Mauvaise récolte → moins d'offre → le prix du café monte ; canicule → plus de demande → le prix des ventilateurs monte", etymo:"Offre, de offrir, du latin offerre, « présenter ». Demande, de demander, du latin demandare, « confier », puis « réclamer ». Loi formalisée par Alfred Marshall (1890) avec ses courbes en croix."},
  {name:"Marché",                  en:"Market",                   cat:"fondements", def:"Lieu, réel ou abstrait, où se rencontrent une offre et une demande et où se forme un prix. Marché des biens, du travail, du logement, des capitaux ; concurrentiel ou dominé par quelques acteurs (oligopole, monopole).", ex:"Le marché du travail, celui de l'immobilier marseillais, la Bourse", etymo:"Du latin mercatus, « commerce, lieu de commerce », de mercari, « acheter », de merx, « marchandise »."},
  {name:"Prix",                    en:"Price",                    cat:"fondements", def:"Valeur d'un bien exprimée en monnaie. Sur un marché libre, il transmet l'information : un prix qui monte signale une rareté et attire l'offre. L'État en encadre certains (loyers, médicaments, électricité).", ex:"Prix du baril, du kilowattheure, du mètre carré", etymo:"Du latin pretium, « valeur, récompense »."},
  {name:"Externalité",             en:"Externality",              cat:"fondements", def:"Effet d'une activité sur des tiers qui n'y participent pas, sans compensation par le marché. Négative (pollution, bruit) ou positive (vaccination, recherche). L'État les corrige par des taxes, des subventions ou des règles.", ex:"Une usine qui pollue une rivière, un jardin qui embellit la rue", etymo:"De externe, du latin externus, « du dehors ». Concept d'Alfred Marshall (1890), terme fixé par Pigou."},
  {name:"Valeur ajoutée",          en:"Value Added",              cat:"fondements", def:"Richesse créée par une entreprise : ce qu'elle vend moins ce qu'elle a acheté pour produire. Elle rémunère le travail (salaires), le capital (profits) et l'État (impôts). Sa somme sur tout le pays fait le PIB.", ex:"Une boulangerie achète 30 € de farine et vend 100 € de pain : 70 € de valeur ajoutée", etymo:"Valeur, du latin valor, de valere, « valoir ». Ajouté, de ajouter, du latin populaire adjuxtare, « mettre auprès ». Notion diffusée avec la TVA (1954)."},
  {name:"PIB",                     en:"GDP",                      cat:"fondements", def:"Produit intérieur brut : la valeur de tout ce qui est produit dans un pays en un an. Mesure la taille de l'économie et, par sa variation, la croissance. Ne dit rien de la répartition, du bien-être ni de l'environnement.", ex:"France : environ 2 900 milliards d'euros, 40 000 € par habitant (2024)", etymo:"Sigle. Notion des années 1930 (Simon Kuznets). Nominal (en euros courants) ou réel (corrigé de l'inflation)."},
  {name:"Croissance",              en:"Economic Growth",          cat:"fondements", def:"Augmentation du PIB d'une année sur l'autre. Autour de 1 % par an en France depuis 2010, contre 5 % pendant les Trente Glorieuses. Débat sur ses limites écologiques et sur ce qu'elle mesure vraiment.", ex:"Récession : croissance négative pendant deux trimestres de suite", etymo:"Du latin crescere, « croître, grandir »."},
  {name:"Productivité",            en:"Productivity",             cat:"fondements", def:"Ce qu'on produit par heure de travail ou par salarié. Sa hausse, par la machine, l'organisation, la formation, est la source des gains de niveau de vie à long terme.", ex:"Un tracteur contre une charrue ; l'IA et la productivité du travail intellectuel", etymo:"Du latin producere, « mener en avant, faire paraître »."},

  // Monnaie & Banque
  {name:"Monnaie",                 en:"Money",                    cat:"monnaie",    def:"Ce que tout le monde accepte en paiement. Trois fonctions : échanger (plus de troc), compter (une unité commune), épargner (conserver de la valeur). Aujourd'hui pièces, billets, et surtout écritures sur des comptes bancaires.", ex:"93 % de la monnaie en circulation est de la monnaie scripturale, des lignes de compte", etymo:"Du latin moneta, surnom de Junon Moneta, dont le temple abritait l'atelier monétaire de Rome."},
  {name:"Monnaie fiduciaire",      en:"Fiat Currency",            cat:"monnaie",    ref:"crypto"},
  {name:"Banque",                  en:"Bank",                     cat:"monnaie",    def:"Entreprise qui reçoit les dépôts, prête, gère les paiements. En prêtant plus qu'elle ne détient, elle crée de la monnaie ; c'est pourquoi elle est surveillée et les dépôts garantis (100 000 € par personne et par banque en Europe).", ex:"BNP, Crédit agricole, banques en ligne, néobanques", etymo:"De l'italien banca, « banc, table du changeur » sur laquelle il faisait ses opérations. Banqueroute, de banca rotta, « banc brisé »."},
  {name:"Banque centrale",         en:"Central Bank",             cat:"monnaie",    def:"Banque des banques et de l'État, qui émet la monnaie, fixe les taux d'intérêt directeurs et veille à la stabilité des prix et du système financier. Indépendante des gouvernements dans la plupart des pays.", ex:"Banque centrale européenne (euro), Réserve fédérale (dollar), Banque de France (relais français)", etymo:"Banque, de l'italien banca, « banc du changeur ». Central, du latin centralis. La plus ancienne est la Banque de Suède (1668) ; la Banque de France date de 1800."},
  {name:"BCE",                     en:"ECB",                      cat:"monnaie",    def:"Banque centrale européenne, à Francfort, qui gère l'euro pour vingt pays. Son mandat : une inflation autour de 2 % par an. Ses outils : les taux directeurs et les achats d'actifs.", ex:"Hausse des taux de 0 à 4 % en 2022-2023 contre l'inflation, puis baisses", etymo:"Sigle. Créée en 1998, un an avant l'euro."},
  {name:"Taux directeur",          en:"Policy Rate",              cat:"monnaie",    def:"Taux auquel la banque centrale prête aux banques, qui répercutent sur tous les crédits. Le lever freine l'inflation en renchérissant l'emprunt ; le baisser relance l'activité. Le principal levier de la politique monétaire.", ex:"Taux directeur à 4 % → crédit immobilier à 4,5 %, épargne mieux rémunérée", etymo:"Taux, de tauxer, ancienne forme de taxer, du latin taxare, « évaluer ». Directeur, du latin director, de dirigere."},
  {name:"Taux d'intérêt",          en:"Interest Rate",            cat:"monnaie",    def:"Prix de l'argent prêté, en pourcentage par an : ce que paie l'emprunteur, ce que reçoit le prêteur. Dépend de la durée, du risque, de l'inflation et des taux directeurs. Le taux réel est le taux moins l'inflation.", ex:"Livret A à 2,4 %, prêt immobilier à 3,5 %, crédit à la consommation à 7 %, découvert à 15 %", etymo:"Intérêt, du latin interest, « il importe », de interesse, « être entre »."},
  {name:"Inflation",               en:"Inflation",                cat:"monnaie",    def:"Hausse générale et durable des prix, qui érode le pouvoir d'achat de la monnaie. Mesurée par l'indice des prix (INSEE). Cible des banques centrales : 2 %. Trop forte, elle ruine l'épargne ; négative (déflation), elle paralyse.", ex:"5,2 % en France en 2022 (énergie, alimentation), retour vers 2 % en 2024", etymo:"Du latin inflatio, « gonflement », de inflare, « souffler dans »."},
  {name:"Pouvoir d'achat",         en:"Purchasing Power",         cat:"monnaie",    def:"Quantité de biens et services qu'un revenu permet d'acheter. Il monte si les revenus augmentent plus vite que les prix, baisse dans le cas inverse. Le ressenti diverge souvent de la mesure, à cause des dépenses contraintes (loyer, énergie).", ex:"+3 % de salaire avec 5 % d'inflation = pouvoir d'achat en baisse", etymo:"Pouvoir, du latin populaire potere. Achat, de acheter, du latin populaire accaptare, « chercher à prendre ». Expression des années 1900, popularisée par les débats sur les salaires."},
  {name:"Crédit",                  en:"Credit / Loan",            cat:"monnaie",    def:"Argent prêté contre remboursement avec intérêts, sur une durée. Moteur de l'économie (investir, acheter un logement) et risque (surendettement). Le prêteur évalue la capacité de remboursement ; l'État encadre les taux (usure) et l'endettement (35 % des revenus).", ex:"Prêt immobilier sur 20 ans, crédit auto, découvert autorisé", etymo:"De l'italien credito, du latin creditum, « chose confiée », de credere, « croire, faire confiance »."},
  {name:"Dette",                   en:"Debt",                     cat:"monnaie",    def:"Somme due, par un ménage, une entreprise ou un État. Ni bonne ni mauvaise en soi : tout dépend de ce qu'elle finance (un logement, une machine, ou des dépenses courantes) et de la capacité à la rembourser.", ex:"Un ménage endetté à 35 % de ses revenus, un État à 110 % de son PIB", etymo:"Du latin debita, pluriel de debitum, « ce qui est dû », de debere, « devoir »."},
  {name:"Euro",                    en:"Euro",                     cat:"monnaie",    def:"Monnaie commune de vingt pays de l'Union européenne depuis 1999 (billets en 2002), gérée par la BCE. Deuxième monnaie du monde après le dollar. Supprime le risque de change entre membres, impose une politique monétaire unique.", ex:"1 € = 6,55957 francs, taux fixé pour toujours", etymo:"Nom choisi en 1995 au Conseil européen de Madrid ; le symbole € s'inspire de l'epsilon grec et des deux barres de stabilité."},
  {name:"Taux de change",          en:"Exchange Rate",            cat:"monnaie",    def:"Prix d'une monnaie dans une autre, fixé sur le marché des changes selon l'offre et la demande, les taux d'intérêt, la confiance. Un euro fort rend les importations moins chères et les exportations plus difficiles.", ex:"1 € = 1,08 $ ; un voyage aux États-Unis coûte plus cher quand l'euro baisse", etymo:"Change, de changer, du latin tardif cambiare, « troquer », d'origine gauloise."},

  // Travail & Emploi
  {name:"Chômage",                 en:"Unemployment",             cat:"emploi",     def:"Situation d'une personne sans emploi, disponible et qui en cherche un. Le taux (chômeurs / actifs) se mesure par enquête (INSEE, définition du BIT) ; France Travail compte, lui, les inscrits, chiffre différent. Autour de 7 % en France.", ex:"Chômage de longue durée (plus d'un an), chômage des jeunes, allocation chômage", etymo:"Du latin populaire caumare, « se reposer pendant la chaleur » (grec kauma, « chaleur brûlante ») : d'abord l'arrêt du travail à la canicule."},
  {name:"Salaire",                 en:"Wage / Salary",            cat:"emploi",     def:"Rémunération du travail salarié. Brut (avant cotisations), net (versé), super-brut (coût total pour l'employeur, cotisations patronales comprises). Le salaire médian net en France est d'environ 2 100 € par mois.", ex:"Brut 2 500 € → net ≈ 1 950 € → coût employeur ≈ 3 500 €", etymo:"Du latin salarium, « ration de sel » puis solde du soldat, de sal, « sel », denrée précieuse."},
  {name:"SMIC",                    en:"Minimum Wage",             cat:"emploi",     def:"Salaire minimum interprofessionnel de croissance, en dessous duquel on ne peut pas payer un salarié, revalorisé chaque année sur l'inflation. Environ 1 400 € net par mois pour un temps plein ; 17 % des salariés le touchent.", ex:"11,88 € brut de l'heure (2025)", etymo:"Sigle (1970), successeur du SMIG de 1950 (G pour garanti)."},
  {name:"Marché du travail",       en:"Labour Market",            cat:"emploi",     def:"Rencontre entre ceux qui cherchent un emploi et ceux qui en offrent, avec le salaire pour prix. Régulé par le droit du travail, les conventions collectives, le SMIC, l'assurance chômage. Pénuries dans certains métiers et chômage dans d'autres coexistent.", ex:"Tension sur les infirmiers, les développeurs, les métiers du bâtiment", etymo:"Marché, du latin mercatus. Travail, du latin populaire tripaliare, « torturer avec le tripalium »."},
  {name:"Population active",       en:"Labour Force",             cat:"emploi",     def:"Personnes en âge de travailler qui ont un emploi ou en cherchent un ; les autres (étudiants, retraités, personnes au foyer) sont inactives. Le taux d'emploi (emploi / population en âge de travailler) résume la santé du marché du travail.", ex:"30 millions d'actifs en France, taux d'emploi autour de 69 %", etymo:"Population, du latin populatio, « peuplement ». Actif, du latin activus, de agere. Catégorie statistique fixée par le Bureau international du travail (1982)."},
  {name:"Cotisations sociales",    en:"Social Contributions",     cat:"emploi",     ref:"droit"},
  {name:"Précarité",               en:"Job Insecurity",           cat:"emploi",     def:"Emploi instable ou insuffisant : CDD courts, intérim, temps partiel subi, auto-entrepreneuriat contraint. Touche d'abord les jeunes et les moins qualifiés ; un salarié sur huit.", ex:"Enchaîner des CDD d'un mois, livrer à vélo à la tâche", etymo:"Du latin precarius, « obtenu par prière », donc révocable, de precari, « prier »."},
  {name:"Retraite",                en:"Pension / Retirement",     cat:"emploi",     def:"Revenu versé après la vie active, en France surtout par répartition : les cotisations des actifs d'aujourd'hui paient les pensions d'aujourd'hui. Âge légal, durée de cotisation, régimes de base et complémentaires (Agirc-Arrco) ; l'épargne retraite (PER) complète.", ex:"Âge légal 64 ans, 172 trimestres pour le taux plein (réforme de 2023)", etymo:"De retirer : se retirer des affaires, du latin retrahere."},

  // État & Politique économique
  {name:"Budget de l'État",        en:"State Budget",             cat:"etat",       def:"Recettes (impôts, surtout TVA et impôt sur le revenu) et dépenses (éducation, défense, intérêts de la dette, transferts) de l'État pour l'année, votés au Parlement dans la loi de finances. Déficitaire chaque année depuis 1974.", ex:"Environ 500 milliards de dépenses, 350 de recettes nettes : 150 de déficit", etymo:"De l'anglais budget, lui-même du vieux français bougette, « petite bourse » : le sac du ministre des Finances britannique."},
  {name:"Déficit public",          en:"Public Deficit",           cat:"etat",       def:"Excès des dépenses publiques (État, Sécurité sociale, collectivités) sur les recettes, chaque année, financé par l'emprunt. Les règles européennes le limitent à 3 % du PIB ; la France est au-dessus.", ex:"5,8 % du PIB en 2024, plus de 170 milliards d'euros", etymo:"Déficit, latin, « il manque », de deficere, « faire défaut » : le mot inscrit en tête des postes manquants dans les inventaires."},
  {name:"Dette publique",          en:"Public Debt",              cat:"etat",       def:"Cumul des déficits passés, ce que les administrations doivent aux prêteurs (banques, assureurs, fonds, français à 50 %). Mesurée en pourcentage du PIB ; sa charge (les intérêts) est devenue le deuxième poste budgétaire.", ex:"Environ 3 300 milliards d'euros, 113 % du PIB (2025)", etymo:"Dette, du latin debita, « choses dues ». Public, du latin publicus, « du peuple »."},
  {name:"Impôt",                   en:"Tax",                      cat:"etat",       def:"Prélèvement obligatoire sans contrepartie directe, qui finance les services publics et redistribue. Direct (sur le revenu, la propriété) ou indirect (TVA, sur la consommation) ; progressif (le taux monte avec le revenu) ou proportionnel.", ex:"Impôt sur le revenu, TVA, impôt sur les sociétés, taxe foncière", etymo:"Du latin impositum, « ce qui est imposé », participe de imponere, « placer sur »."},
  {name:"TVA",                     en:"VAT",                      cat:"etat",       ref:"droit"},
  {name:"Impôt sur le revenu",     en:"Income Tax",               cat:"etat",       ref:"droit"},
  {name:"Prélèvements obligatoires", en:"Tax Burden",             cat:"etat",       def:"Ensemble des impôts et cotisations rapporté au PIB : environ 43 % en France, parmi les plus élevés du monde, en contrepartie d'une protection sociale et de services publics étendus.", ex:"Santé, retraites, école, routes, police, justice : ce que les prélèvements paient", etymo:"Prélever, du latin praelevare, « lever avant ». Obligatoire, du latin obligare, « lier ». Indicateur défini par l'OCDE (années 1960)."},
  {name:"Politique budgétaire",    en:"Fiscal Policy",            cat:"etat",       def:"Usage par l'État des impôts et des dépenses pour agir sur l'économie : relancer en dépensant plus (déficit), freiner en dépensant moins. L'outil de Keynes contre les crises.", ex:"Chèque énergie et « quoi qu'il en coûte » en 2020-2022", etymo:"Politique, du grec politikos, « de la cité ». Budgétaire, de budget, du vieux français bougette, « petite bourse »."},
  {name:"Politique monétaire",     en:"Monetary Policy",          cat:"etat",       def:"Action de la banque centrale sur la quantité de monnaie et les taux d'intérêt pour tenir l'inflation et soutenir l'activité. Indépendante du gouvernement, plus rapide que la politique budgétaire, mais aveugle aux territoires.", ex:"Baisser les taux en récession, les monter quand les prix s'emballent", etymo:"Monétaire, du latin monetarius, de moneta, « monnaie »."},
  {name:"Redistribution",          en:"Redistribution",           cat:"etat",       def:"Réduction des inégalités par l'impôt progressif et les prestations (allocations, minima sociaux, retraites, santé). En France, elle ramène l'écart entre les 10 % les plus riches et les 10 % les plus pauvres de 18 à 6.", ex:"RSA, allocations familiales, prime d'activité, APL", etymo:"De distribuer, du latin distribuere, « partager », de tribus, « tribu »."},
  {name:"Protection sociale",      en:"Social Protection",        cat:"etat",       def:"Ensemble des mécanismes collectifs contre les risques de la vie : maladie, vieillesse, chômage, famille, pauvreté, dépendance. Un tiers du PIB en France, financé par cotisations et impôts. La Sécurité sociale en est le cœur.", ex:"Remboursement des soins, pensions, allocations chômage, RSA", etymo:"Protection, du latin protectio, de protegere, « couvrir devant ». Social, du latin socius, « compagnon »."},
  {name:"Service public",          en:"Public Service",           cat:"etat",       ref:"droit"},
  {name:"Inégalités",              en:"Inequality",               cat:"etat",       ref:"shs", refName:"Inégalités sociales"},

  // Entreprise & Comptabilité
  {name:"Entreprise",              en:"Company / Business",       cat:"compta",     def:"Organisation qui produit des biens ou des services pour les vendre, en combinant travail et capital. De l'auto-entrepreneur à la multinationale ; 4 millions en France, dont 96 % de moins de dix salariés.", ex:"Boulangerie, cabinet d'architecte, startup, groupe du CAC 40", etymo:"De entreprendre, « prendre entre ses mains, se charger de », du latin populaire interprendere."},
  {name:"Chiffre d'affaires",      en:"Revenue / Turnover",       cat:"compta",     def:"Total des ventes sur une période, hors taxes. Mesure l'activité, pas la rentabilité : on peut vendre beaucoup et perdre de l'argent.", ex:"Une boutique qui vend 200 000 € par an ; le CA de LVMH, 85 milliards", etymo:"Chiffre, de l'arabe sifr, « zéro ». Affaires, de à faire : ce qu'on a « à faire ». Expression attestée au XIXe siècle."},
  {name:"Marge",                   en:"Margin",                   cat:"compta",     def:"Ce qui reste des ventes une fois les coûts déduits. Marge brute (ventes − coût des marchandises), marge nette (après tous les frais), en pourcentage du chiffre d'affaires. Le vrai indicateur de la santé d'une activité.", ex:"Un restaurant : 70 % de marge brute, 5 % de marge nette", etymo:"Du latin margo, marginis, « bord » : ce qui est en bordure, en plus."},
  {name:"Bénéfice",                en:"Profit",                   cat:"compta",     def:"Résultat positif : recettes moins toutes les charges (achats, salaires, loyers, amortissements, impôts). Le contraire est une perte. Distribué aux associés (dividendes) ou conservé pour investir.", ex:"100 000 € de ventes, 90 000 € de charges : 10 000 € de bénéfice", etymo:"Du latin beneficium, « bienfait, faveur » : bene (bien) + facere (faire)."},
  {name:"Bilan",                   en:"Balance Sheet",            cat:"compta",     def:"Photographie du patrimoine d'une entreprise à une date : ce qu'elle possède (actif : locaux, machines, stocks, créances, trésorerie) et ce qu'elle doit (passif : capital, dettes). Les deux colonnes sont toujours égales.", ex:"Établi chaque année par l'expert-comptable, déposé au greffe", etymo:"De l'italien bilancio, « balance », du latin bilanx, « à deux plateaux »."},
  {name:"Compte de résultat",      en:"Income Statement",         cat:"compta",     def:"Film de l'année : les produits (ventes) et les charges (achats, salaires, loyers, amortissements), dont la différence est le résultat, bénéfice ou perte. Avec le bilan, l'un des deux états financiers.", ex:"Lire le compte de résultat avant d'investir dans une société", etymo:"Compte, du latin computus, « calcul ». Résultat, du latin resultatum, de resultare, « rebondir »."},
  {name:"Trésorerie",              en:"Cash Flow",                cat:"compta",     def:"Argent disponible à l'instant. Une entreprise rentable peut mourir faute de trésorerie si ses clients paient tard et ses fournisseurs exigent tôt. Première cause de faillite des petites entreprises.", ex:"Délai de paiement client 60 jours, salaires le 30 : il faut avancer", etymo:"De trésor, du latin thesaurus, du grec thêsauros, « dépôt, réserve »."},
  {name:"Capital",                 en:"Capital",                  cat:"compta",     def:"Deux sens : l'argent et les biens apportés par les associés à la création (capital social), et plus largement tout ce qui sert à produire durablement (machines, bâtiments, brevets : le capital productif), par opposition au travail.", ex:"Capital social de 10 000 €, augmentation de capital pour financer la croissance", etymo:"Du latin capitalis, « de la tête » (caput) : le bien principal, la « tête » du troupeau."},
  {name:"Investissement",          en:"Investment",               cat:"compta",     def:"Dépense d'aujourd'hui pour produire ou gagner demain : machine, logiciel, formation, bâtiment. Pour un particulier, placement d'argent. Se juge par son rendement attendu et son risque.", ex:"Acheter un four à 20 000 € qui rapportera 5 000 € par an", etymo:"Du latin investire, « revêtir » : mettre l'argent « dans » quelque chose."},
  {name:"Amortissement",           en:"Depreciation",             cat:"compta",     def:"Étalement comptable du coût d'un investissement sur sa durée d'usage : une machine de 50 000 € prévue pour dix ans pèse 5 000 € par an dans les charges. Pour un emprunt, la part du capital remboursée à chaque échéance.", ex:"Un ordinateur s'amortit sur trois ans, un immeuble sur trente", etymo:"De amortir, « rendre mort », du latin populaire admortire : « éteindre » une dette ou une valeur."},
  {name:"Faillite",                en:"Bankruptcy",               cat:"compta",     def:"Impossibilité de payer ses dettes (cessation de paiements), constatée par le tribunal. Redressement (plan de continuation) ou liquidation (vente des actifs, fin de l'entreprise). Les salariés sont créanciers prioritaires.", ex:"Environ 60 000 défaillances d'entreprises par an en France", etymo:"De l'italien fallita, de fallire, « manquer, faillir », du latin fallere, « tromper »."},
  {name:"Startup",                 en:"Startup",                  cat:"compta",     ref:"numerique"},
  {name:"Levée de fonds",          en:"Fundraising",              cat:"compta",     def:"Apport d'argent par des investisseurs (business angels, fonds de capital-risque) en échange d'une part du capital, pour financer une croissance rapide avant la rentabilité. Le fondateur se dilue à chaque tour.", ex:"Amorçage, série A, série B ; Mistral AI a levé plus d'un milliard d'euros en un an", etymo:"Lever, du latin levare, « soulever ». Fonds, du latin fundus, « fond, bien-fonds ». Calque de l'anglais fundraising."},

  // Finances personnelles
  {name:"Budget personnel",        en:"Personal Budget",          cat:"perso",      def:"Rapprochement des revenus et des dépenses d'un ménage, par mois. Distinguer le contraint (loyer, énergie, crédits, assurances), le courant (alimentation, transport) et le choisi (loisirs, épargne). Le suivi vaut plus que la méthode.", ex:"Règle indicative 50 / 30 / 20 : besoins, envies, épargne", etymo:"Budget, du vieux français bougette, « petite bourse »."},
  {name:"Épargne",                 en:"Savings",                  cat:"perso",      def:"Part du revenu non dépensée. D'abord une réserve de précaution (trois à six mois de dépenses, disponible), puis des projets (apport immobilier), puis le long terme (retraite), sur des supports de plus en plus risqués et rémunérateurs.", ex:"Les Français épargnent environ 17 % de leurs revenus, un record en Europe", etymo:"Du francique sparanjan, « épargner, ménager », d'où aussi l'allemand sparen."},
  {name:"Livret A",                en:"Livret A (Savings Account)", cat:"perso",    def:"Livret d'épargne réglementé, disponible à tout moment, sans impôt, garanti par l'État, plafonné à 22 950 €. Le placement de précaution de 56 millions de Français. Son taux, fixé par l'État, suit l'inflation avec retard.", ex:"Taux 2,4 % (2025) ; le LDDS et le LEP (réservé aux revenus modestes, mieux rémunéré) le complètent", etymo:"Livret, diminutif de livre, du latin liber : le carnet où l'on inscrivait les dépôts. Créé en 1818."},
  {name:"Assurance-vie",           en:"Life Insurance (Savings)", cat:"perso",      def:"Placement le plus répandu en France : une enveloppe où l'on loge un fonds en euros (garanti) et des unités de compte (actions, immobilier, à risque), avec une fiscalité douce après huit ans et une transmission avantageuse. Rien à voir avec une assurance décès.", ex:"Fonds euros à 2,5 %, unités de compte plus risquées ; abattement de 152 500 € par bénéficiaire à la succession", etymo:"Assurance, de assurer, du latin populaire assecurare. Le premier contrat d'assurance sur la vie en France date de 1787 ; la Compagnie royale."},
  {name:"Intérêts composés",       en:"Compound Interest",        cat:"perso",      def:"Intérêts qui produisent à leur tour des intérêts : le capital croît de plus en plus vite. À 5 % par an, une somme double en quatorze ans, quadruple en vingt-huit. Le temps compte plus que le montant : commencer tôt.", ex:"100 € par mois à 5 % pendant 30 ans : 36 000 € versés, 83 000 € au bout", etymo:"Composé, du latin componere, « placer ensemble » : les intérêts s'ajoutent au capital."},
  {name:"Crédit immobilier",       en:"Mortgage",                 cat:"perso",      def:"Prêt pour acheter un logement, sur quinze à vingt-cinq ans, garanti par une hypothèque ou une caution, avec assurance emprunteur. L'endettement total ne doit pas dépasser 35 % des revenus ; le taux et la durée font le coût total.", ex:"200 000 € sur 20 ans à 3,5 % : 1 160 € par mois, 78 000 € d'intérêts", etymo:"Immobilier, du latin immobilis, « qui ne bouge pas » : les biens qu'on ne peut déplacer."},
  {name:"Taux d'endettement",      en:"Debt-to-Income Ratio",     cat:"perso",      def:"Part des revenus consacrée au remboursement des crédits. Les banques refusent au-delà de 35 % (assurance comprise) depuis 2022, sauf exceptions. Le reste à vivre compte aussi.", ex:"3 000 € de revenus → 1 050 € de mensualités au maximum", etymo:"Endettement, de dette, du latin debita. Plafond de 35 % fixé par le Haut Conseil de stabilité financière (2021)."},
  {name:"Frais bancaires",         en:"Bank Fees",                cat:"perso",      def:"Ce que la banque facture : tenue de compte, carte, virements hors zone euro, découvert (agios), incidents (commissions d'intervention, plafonnées), frais de dossier. Comparables et négociables ; les banques en ligne en facturent peu.", ex:"Environ 220 € par an en moyenne ; offre spécifique à 3 € par mois pour les clients fragiles", etymo:"Frais, de l'ancien français frait, « dépense », du latin fractum, « chose brisée » : ce qui est « cassé », dépensé."},
  {name:"Découvert",               en:"Overdraft",                cat:"perso",      def:"Solde négatif du compte, toléré jusqu'à un plafond (découvert autorisé) contre des intérêts élevés (agios), pénalisé au-delà par des frais d'incident. Un crédit permanent qui coûte cher ; le signe d'un budget à revoir.", ex:"Découvert autorisé de 500 € à 15 % par an, commission de 8 € par rejet", etymo:"Participe de découvrir : le compte est « à découvert », sans couverture. Calque de l'anglais overdraft, « tirage au-delà »."},
  {name:"Fiscalité de l'épargne",  en:"Savings Taxation",         cat:"perso",      ref:"droit", refName:"Flat tax (PFU)"},
  {name:"Score de crédit",         en:"Credit Score",             cat:"perso",      def:"En France, pas de score comme aux États-Unis : la banque juge sur les revenus, la stabilité, l'épargne, les relevés. Le fichier des incidents (FICP, Banque de France) bloque en revanche tout crédit pendant cinq ans.", ex:"Trois mois de relevés sans découvert avant une demande de prêt", etymo:"Score, anglais, « entaille, marque » (pour compter), du vieux norrois skor. Le système américain FICO date de 1989."},

  // Bourse & Placements
  {name:"Action (Bourse)",                  en:"Share / Stock",            cat:"bourse",     def:"Part du capital d'une société : son détenteur en est copropriétaire, vote en assemblée, touche les dividendes et gagne ou perd selon le cours. Le placement le plus rentable à long terme et le plus mouvementé à court terme.", ex:"Une action LVMH, TotalEnergies, Air Liquide ; cotée en Bourse ou non", etymo:"Du latin actio, « action, part » : la part d'action dans une entreprise commune."},
  {name:"Obligation (Bourse)",              en:"Bond",                     cat:"bourse",     def:"Titre de dette : on prête à un État ou une entreprise, qui verse un intérêt fixe (coupon) et rembourse à l'échéance. Moins risqué qu'une action, sauf faillite de l'émetteur ; son prix baisse quand les taux montent.", ex:"OAT de l'État français à 10 ans, obligation d'entreprise ; le fonds euros de l'assurance-vie en est plein", etymo:"Du latin obligatio, « engagement », de obligare, « lier »."},
  {name:"Dividende",               en:"Dividend",                 cat:"bourse",     def:"Part du bénéfice qu'une société verse à ses actionnaires, en général une fois par an. Un rendement de 2 à 4 % pour les grandes valeurs ; les sociétés en croissance préfèrent réinvestir.", ex:"3 € par action pour un cours de 100 € : 3 % de rendement", etymo:"Du latin dividendum, « ce qui doit être divisé »."},
  {name:"Bourse",                  en:"Stock Exchange",           cat:"bourse",     def:"Marché organisé où s'échangent actions, obligations et autres titres, à un prix qui change en continu. Permet aux entreprises de se financer et aux épargnants d'investir. Paris est intégrée à Euronext.", ex:"Euronext Paris, New York (NYSE, Nasdaq), Londres, Tokyo", etymo:"Du nom de la famille Van der Buerse, à Bruges, devant l'hôtel de laquelle les marchands se réunissaient au XIVe siècle."},
  {name:"Indice boursier",         en:"Stock Index",              cat:"bourse",     def:"Moyenne pondérée des cours d'un panier d'actions, qui résume un marché d'un chiffre. Le CAC 40 suit les quarante plus grandes valeurs françaises ; le S&P 500, cinq cents américaines ; le MSCI World, le monde développé.", ex:"CAC 40 à 7 500 points ; « la Bourse a monté de 1 % » veut dire l'indice", etymo:"CAC, de Cotation assistée en continu (1988), base 1 000 points."},
  {name:"ETF",                     en:"ETF (Index Fund)",         cat:"bourse",     def:"Fonds coté en Bourse qui réplique un indice à bas frais (0,1 à 0,3 % par an) : une part achète d'un coup des centaines d'entreprises. L'outil de l'épargnant qui veut le marché sans le choisir. Aussi appelé tracker.", ex:"Un ETF MSCI World dans un PEA ou une assurance-vie, alimenté chaque mois", etymo:"Sigle de l'anglais exchange-traded fund, « fonds négocié en Bourse »."},
  {name:"Fonds d'investissement",  en:"Investment Fund",          cat:"bourse",     def:"Portefeuille collectif géré par un professionnel, dans lequel les épargnants achètent des parts. Gestion active (le gérant choisit, frais de 1 à 2 %) ou passive (ETF). Peu de gérants actifs battent durablement leur indice.", ex:"OPCVM, SICAV, FCP ; fonds actions, obligataire, immobilier (SCPI)", etymo:"Fonds, du latin fundus. Investissement, du latin investire, « revêtir ». Le premier fonds collectif moderne date de 1774 (Pays-Bas)."},
  {name:"Risque et rendement",     en:"Risk and Return",          cat:"bourse",     def:"Le couple inséparable : plus un placement peut rapporter, plus il peut perdre. Un rendement élevé sans risque n'existe pas ; qui le promet est un escroc. La question n'est pas d'éviter le risque mais de le choisir selon son horizon.", ex:"Livret A : 2 %, aucun risque ; actions : 7 % par an en moyenne sur 30 ans, −40 % certaines années", etymo:"Risque, de l'italien risco, « écueil ». Rendement, de rendre, du latin populaire rendere."},
  {name:"Diversification",         en:"Diversification",          cat:"bourse",     def:"Répartir ses placements entre des actifs qui ne bougent pas ensemble (secteurs, pays, actions et obligations, immobilier), pour que la chute de l'un ne ruine pas le tout. « Ne pas mettre tous ses œufs dans le même panier », la seule règle gratuite.", ex:"Un ETF mondial diversifie sur 1 500 entreprises en un achat", etymo:"Du latin diversificare, « rendre divers », de diversus, « tourné dans des sens différents »."},
  {name:"PEA",                     en:"PEA (Equity Savings Plan)", cat:"bourse",    def:"Plan d'épargne en actions : enveloppe pour investir en actions européennes (et ETF mondiaux éligibles) sans impôt sur les gains après cinq ans, seuls les prélèvements sociaux restant dus. Plafond de versements 150 000 €.", ex:"Un PEA chez un courtier en ligne, des ETF, et le temps", etymo:"Sigle. Créé en 1992."},
  {name:"Bulle et krach",          en:"Bubble and Crash",         cat:"bourse",     def:"Bulle : hausse des prix nourrie par la seule croyance qu'ils monteront encore, loin de toute valeur réelle. Krach : son éclatement, chute brutale. Se répètent depuis la tulipe hollandaise (1637) ; l'investisseur de long terme les traverse.", ex:"1929, bulle internet (2000), subprimes (2008), COVID (mars 2020, −40 % en un mois puis récupération)", etymo:"Krach, de l'allemand Krach, « craquement, fracas », depuis le krach de Vienne (1873)."},
  {name:"Volatilité",              en:"Volatility",               cat:"bourse",     ref:"crypto"},
  {name:"Effet de levier",         en:"Leverage",                 cat:"bourse",     ref:"crypto"},

  // Commerce international
  {name:"Mondialisation",          en:"Globalization",            cat:"commerce",   ref:"shs"},
  {name:"Importations et exportations", en:"Imports and Exports", cat:"commerce",   def:"Ce qu'un pays achète à l'étranger et ce qu'il lui vend. La France exporte des avions, du luxe, des médicaments, du vin, des services ; elle importe de l'énergie, de l'électronique, des vêtements, des voitures.", ex:"Airbus et LVMH d'un côté, pétrole et smartphones de l'autre", etymo:"Du latin importare, « porter dans », et exportare, « porter hors »."},
  {name:"Balance commerciale",     en:"Trade Balance",            cat:"commerce",   def:"Différence entre exportations et importations de biens. Déficitaire en France depuis 2005 (environ 80 milliards d'euros en 2024), excédentaire en Allemagne. Les services (tourisme) et les revenus du capital complètent le tableau (balance courante).", ex:"Un déficit signifie qu'on consomme plus qu'on ne produit, financé par l'épargne ou la dette", etymo:"Balance, du latin populaire bilancia, « à deux plateaux » (bis + lanx). Commercial, du latin commercium, « négoce » (cum + merx, marchandise)."},
  {name:"Droits de douane",        en:"Tariffs",                  cat:"commerce",   def:"Taxe sur les produits importés, qui les renchérit pour protéger la production nationale ou faire pression sur un pays. Payés en fin de compte par les consommateurs. Baissés pendant soixante-dix ans, relevés massivement par les États-Unis depuis 2025.", ex:"10 à 50 % selon les pays et les produits ; l'Union européenne négocie pour ses membres", etymo:"Douane, de l'arabe dîwân, « registre, bureau », via l'italien dogana."},
  {name:"Délocalisation",          en:"Offshoring",               cat:"commerce",   def:"Transfert d'une production vers un pays à coûts plus bas (salaires, normes, impôts). A fait baisser les prix et l'emploi industriel en France (de 5 millions à 2,7 millions d'emplois depuis 1980) ; mouvement inverse de relocalisation depuis la pandémie.", ex:"Textile en Asie, centres d'appels au Maghreb, usines de semi-conducteurs rapatriées", etymo:"Du latin locus, « lieu » : déplacer le lieu."},
  {name:"Avantage comparatif",     en:"Comparative Advantage",    cat:"commerce",   def:"Théorie de Ricardo (1817) : chaque pays gagne à se spécialiser dans ce qu'il fait relativement le mieux et à échanger le reste, même s'il est moins bon en tout. Le fondement intellectuel du libre-échange, et ses limites (dépendance, emplois perdus).", ex:"Le Portugal fait le vin, l'Angleterre le drap, et les deux y gagnent", etymo:"Avantage, de avant, du latin abante. Comparatif, du latin comparare, « apparier » (par, égal). Théorie de David Ricardo (1817)."},
  {name:"OMC",                     en:"WTO",                      cat:"commerce",   def:"Organisation mondiale du commerce (1995, Genève) : fixe les règles des échanges entre 166 pays et arbitre leurs différends. Affaiblie par le blocage de son tribunal d'appel et le retour des guerres commerciales.", ex:"Un pays qui s'estime lésé par des droits de douane peut porter plainte", etymo:"Sigle. Successeur du GATT (1947)."},
  {name:"Pays émergents",          en:"Emerging Economies",       cat:"commerce",   def:"Pays en croissance rapide qui rattrapent les économies développées : Chine (devenue première puissance industrielle), Inde, Brésil, Indonésie, Vietnam. Les BRICS en sont le club politique.", ex:"La Chine produit 30 % des biens manufacturés du monde", etymo:"Émerger, du latin emergere, « sortir de l'eau ». Expression emerging markets forgée par Antoine van Agtmael (Banque mondiale, 1981)."},

  // Écoles & Auteurs
  {name:"Adam Smith",              en:"Adam Smith",               cat:"ecoles",     def:"Philosophe écossais (1723-1790), fondateur de l'économie moderne avec La Richesse des nations (1776) : la division du travail, le marché où l'intérêt de chacun sert celui de tous (la « main invisible »), la critique des monopoles et des privilèges.", ex:"L'exemple de la manufacture d'épingles : 18 opérations, 240 fois plus productives", etymo:"Smith, anglais, « forgeron », du vieil anglais smith, « celui qui frappe ». Adam, de l'hébreu adam, « homme », de adama, « terre »."},
  {name:"Libéralisme économique",  en:"Economic Liberalism",      cat:"ecoles",     def:"Courant qui fait confiance au marché et à la liberté d'entreprendre, et limite le rôle de l'État à ce que le marché ne fait pas (justice, sécurité, règles, biens publics). De Smith aux néolibéraux des années 1980 (Hayek, Friedman, Thatcher, Reagan).", ex:"Privatisations, dérégulation, baisses d'impôts", etymo:"Du latin liberalis, « digne d'un homme libre »."},
  {name:"Keynes",                  en:"John Maynard Keynes",      cat:"ecoles",     def:"Économiste britannique (1883-1946) qui, face à la crise de 1929, montre que le marché ne se corrige pas seul : quand la demande manque, l'État doit dépenser, quitte à s'endetter, pour relancer. Fondateur de la macroéconomie, inspirateur des politiques d'après-guerre.", ex:"Théorie générale de l'emploi, de l'intérêt et de la monnaie (1936) ; le New Deal, les plans de relance de 2009 et 2020", etymo:"Nom anglais d'origine normande, de la commune de Cahagnes (Calvados), venue avec la conquête de 1066."},
  {name:"Marx (économie)",         en:"Karl Marx (Economics)",    cat:"ecoles",     def:"Philosophe et économiste allemand (1818-1883) : le capitalisme repose sur l'exploitation du travail (la plus-value), engendre des crises et la concentration du capital, et sera dépassé. Le Capital (1867) reste une analyse lue, au-delà des régimes qui s'en réclamèrent.", ex:"Lutte des classes, aliénation, accumulation du capital", etymo:"Marx, forme allemande de Marcus, prénom romain dérivé de Mars, dieu de la guerre."},
  {name:"Monétarisme",             en:"Monetarism",               cat:"ecoles",     def:"École de Milton Friedman (années 1960-1970) : l'inflation vient d'abord de l'excès de monnaie, la banque centrale doit la contrôler, et les relances budgétaires font plus de mal que de bien. A inspiré l'indépendance des banques centrales.", ex:"« L'inflation est toujours et partout un phénomène monétaire »", etymo:"De monétaire, du latin moneta. Terme forgé par Karl Brunner (1968) pour désigner l'école de Milton Friedman."},
  {name:"Économie comportementale", en:"Behavioral Economics",    cat:"ecoles",     def:"Courant qui remplace l'homme parfaitement rationnel des modèles par l'humain réel, avec ses biais : aversion à la perte, court-termisme, effet de cadrage. Kahneman (prix Nobel 2002), Thaler (2017) et les « nudges », coups de pouce sans contrainte.", ex:"Inscrire par défaut les salariés à l'épargne retraite fait bondir la participation", etymo:"Comportement, du latin comportare, « porter ensemble ». Calque de l'anglais behavioral economics (années 1980)."},
  {name:"Économie circulaire",     en:"Circular Economy",         cat:"ecoles",     def:"Modèle qui remplace « extraire, fabriquer, jeter » par réduire, réparer, réutiliser, recycler, pour découpler l'activité de la consommation de ressources. Loi française de 2020 (indice de réparabilité, fin du plastique jetable).", ex:"Réparer plutôt que remplacer, seconde main, consigne, écoconception", etymo:"Circulaire, du latin circularis, de circulus, « cercle ». Expression apparue dans les années 1990, popularisée par la fondation Ellen MacArthur (2010)."},
  {name:"Prix Nobel d'économie",   en:"Nobel Prize in Economics", cat:"ecoles",     def:"Prix de la Banque de Suède en mémoire d'Alfred Nobel, créé en 1969, qui distingue chaque année des économistes. Ses lauréats récents dessinent les débats : pauvreté (Duflo, 2019), banques (Bernanke, 2022), inégalités et institutions (Acemoglu, 2024).", ex:"Trois Français : Allais (1988), Tirole (2014), Duflo (2019)", etymo:"Nobel, du nom d'Alfred Nobel, inventeur de la dynamite (1867), qui légua sa fortune aux prix. Celui d'économie n'est pas dans son testament : créé par la Banque de Suède en 1968."},
];

// ═════════════════════════════════════════════════════════════════════════════
// LEXIQUE CUISINE & GASTRONOMIE
// ═════════════════════════════════════════════════════════════════════════════

const terms_cuisine = [
  // Bases & Vocabulaire
  {name:"Cuisine",                   en:"Cooking / Cuisine",          cat:"bases",       def:"Art de préparer les aliments pour les rendre comestibles, sains et bons, et l'ensemble des pratiques propres à une culture ou une région. Désigne aussi la pièce où l'on cuisine.", ex:"La cuisine japonaise, la cuisine de ma grand-mère, une cuisine de restaurant", etymo:"Du latin populaire cocina, altération de coquina, dérivé de coquere, « cuire ». Attesté en français au XIIe siècle."},
  {name:"Gastronomie",               en:"Gastronomy",                 cat:"bases",       def:"Art de la bonne chère : connaissance et appréciation de tout ce qui touche au manger et au boire, de la production au service. En France, le repas gastronomique est inscrit au patrimoine immatériel de l'UNESCO depuis 2010.", ex:"Un guide gastronomique, une ville de gastronomie comme Lyon", etymo:"Du grec gastêr, « ventre », et nomos, « loi, règle ». Mot popularisé par le poème Gastronomie de Joseph Berchoux (1801)."},
  {name:"Recette",                   en:"Recipe",                     cat:"bases",       def:"Description écrite d'un plat : liste des ingrédients avec leurs quantités, puis les étapes de préparation, les temps et les températures. Une recette de cuisine ne garantit pas le résultat : le tour de main compte.", ex:"« Pour 4 personnes : 500 g de farine, 3 œufs… »", etymo:"Du latin recepta, « chose reçue », participe de recipere. D'abord ordonnance médicale (XIIIe siècle), sens culinaire au XVIe siècle."},
  {name:"Mise en place",             en:"Mise en place",              cat:"bases",       def:"Préparation de tout ce qui servira au service avant qu'il commence : ingrédients pesés, légumes taillés, sauces prêtes, ustensiles à portée. Le secret d'une cuisine calme.", ex:"Avant le coup de feu, chaque poste vérifie sa mise en place", etymo:"Expression française passée telle quelle dans le vocabulaire des cuisines du monde entier."},
  {name:"Brigade",                   en:"Kitchen brigade",            cat:"bases",       def:"Organisation hiérarchique d'une cuisine professionnelle, codifiée par Escoffier : chef, second, chefs de partie (saucier, poissonnier, rôtisseur, pâtissier…), commis, plongeur. Chaque poste a une tâche précise.", ex:"Une brigade de vingt personnes pour un restaurant trois étoiles", etymo:"De l'italien brigata, « troupe », de briga, « querelle ». Terme militaire appliqué à la cuisine à la fin du XIXe siècle."},
  {name:"Chef",                      en:"Chef",                       cat:"bases",       def:"Responsable d'une cuisine : il conçoit la carte, dirige la brigade, contrôle les envois et la qualité. Le chef n'est pas forcément aux fourneaux ; le second et les chefs de partie exécutent.", ex:"« Oui, chef ! » — la réponse rituelle en cuisine", etymo:"Du latin caput, « tête », par l'ancien français chief. Abréviation de « chef de cuisine », attestée au XIXe siècle."},
  {name:"Terroir",                   en:"Terroir",                    cat:"bases",       def:"Ensemble des caractéristiques d'un lieu — sol, climat, exposition, savoir-faire — qui donnent à un produit un goût qu'il n'aurait pas ailleurs. Fondement des appellations d'origine.", ex:"Le goût d'un comté d'alpage, d'un vin de Bourgogne, d'un piment d'Espelette", etymo:"Du latin populaire terratorium, croisement de territorium et terra. Sens agricole depuis le XIIIe siècle, sens gustatif au XXe."},
  {name:"Saisonnalité",              en:"Seasonality",                cat:"bases",       def:"Période de l'année où un produit est naturellement à maturité et à son meilleur : plus de goût, moins cher, moins d'énergie pour le produire. Cuisiner de saison, c'est suivre le calendrier des récoltes.", ex:"Les fraises en mai-juin, les courges en automne, les huîtres en hiver", etymo:"De saison, du latin satio, « semailles, époque des semailles »."},
  {name:"Cuisine du marché",         en:"Market cuisine",             cat:"bases",       def:"Cuisine qui compose sa carte selon ce que le marché offre le jour même : produits frais, de saison, carte courte et changeante. Portée par Paul Bocuse et la nouvelle cuisine.", ex:"Une ardoise réécrite chaque matin selon les arrivages", etymo:"Expression née dans les années 1970 avec la nouvelle cuisine."},
  {name:"Street food",               en:"Street food",                cat:"bases",       def:"Cuisine de rue : plats préparés et vendus dehors, à emporter, souvent bon marché et rapides. Tradition ancienne en Asie et en Amérique latine, devenue tendance en Europe avec les food trucks.", ex:"Un bánh mì à Hanoï, des tacos à Mexico, un kebab à Berlin", etymo:"De l'anglais street, « rue », et food, « nourriture »."},
  {name:"Cuisine fusion",            en:"Fusion cuisine",             cat:"bases",       def:"Cuisine qui mêle volontairement des traditions culinaires différentes : techniques, ingrédients ou présentations d'une culture appliqués à une autre. Réussie, elle crée ; ratée, elle brouille.", ex:"Un sushi au foie gras, un burger au kimchi", etymo:"De l'anglais fusion cuisine, apparu en Californie dans les années 1980."},

  // Techniques & Gestes
  {name:"Émincer",                   en:"To slice thinly",            cat:"gestes",      def:"Couper en tranches fines et régulières. Se dit des légumes, de la viande ou des champignons. Plus la tranche est fine, plus la cuisson est rapide et homogène.", ex:"Émincer un oignon pour une soupe, une échalote pour une vinaigrette", etymo:"De mince, du latin populaire minutiare, « rendre menu »."},
  {name:"Ciseler",                   en:"To finely dice / to chiffonade", cat:"gestes",  def:"Couper en tout petits dés (oignon, échalote) sans écraser, ou tailler des herbes en fines lanières. Le ciselage garde le jus dans le légume ; hacher l'en fait sortir.", ex:"Ciseler de l'échalote pour un beurre blanc, du basilic pour une salade de tomates", etymo:"De ciseau, du latin populaire cisellus, dérivé de caedere, « couper »."},
  {name:"Julienne",                  en:"Julienne",                   cat:"gestes",      def:"Taille en bâtonnets très fins (1 à 2 mm de côté, 5 à 6 cm de long). Base de la brunoise et présentation classique des légumes en garniture.", ex:"Une julienne de carotte, de céleri et de poireau pour un consommé", etymo:"Origine incertaine, sans doute du prénom Julien ou Jules ; attesté dans Le Cuisinier royal (1722)."},
  {name:"Brunoise",                  en:"Brunoise",                   cat:"gestes",      def:"Taille en dés minuscules (2 mm de côté), obtenue en recoupant une julienne. Sert de garniture, de base de sauce ou de farce.", ex:"Une brunoise de légumes dans un tartare de poisson", etymo:"De Brunoy, commune d'Essonne autrefois réputée pour ses cultures maraîchères."},
  {name:"Blanchir",                  en:"To blanch",                  cat:"gestes",      def:"Plonger un aliment quelques instants dans l'eau bouillante, puis le refroidir à l'eau glacée. Fixe la couleur des légumes verts, retire l'amertume, facilite l'épluchage, prépare la congélation. Se dit aussi de fouetter jaunes d'œufs et sucre jusqu'à ce qu'ils pâlissent.", ex:"Blanchir des haricots verts avant de les sauter, des tomates pour les peler", etymo:"De blanc, du germanique blank, « brillant, clair »."},
  {name:"Déglacer",                  en:"To deglaze",                 cat:"gestes",      def:"Verser un liquide (vin, bouillon, vinaigre) dans une poêle chaude pour dissoudre les sucs caramélisés au fond et en faire une sauce. Là où se cache tout le goût d'une cuisson.", ex:"Déglacer au vin blanc après avoir saisi une escalope", etymo:"De glace au sens de « sucs figés », du latin glacies."},
  {name:"Réduire",                   en:"To reduce",                  cat:"gestes",      def:"Faire bouillir un liquide pour en évaporer une partie de l'eau : la sauce épaissit et son goût se concentre. On dit « réduire de moitié » ou « à glace ».", ex:"Réduire un jus de viande jusqu'à ce qu'il nappe la cuillère", etymo:"Du latin reducere, « ramener », sens culinaire par l'idée de « ramener à un volume moindre »."},
  {name:"Monter au beurre",          en:"To mount with butter",       cat:"gestes",      def:"Incorporer du beurre froid en morceaux dans une sauce chaude hors du feu, en fouettant : elle devient brillante, onctueuse et liée. Elle ne doit plus bouillir ensuite.", ex:"Monter au beurre un jus de volaille juste avant de servir", etymo:"Monter au sens d'« émulsionner, faire prendre du volume », du latin populaire montare."},
  {name:"Mariner",                   en:"To marinate",                cat:"gestes",      def:"Laisser tremper un aliment dans un mélange aromatique (huile, acide, épices, herbes) pour le parfumer, l'attendrir ou le conserver. De quelques minutes pour un poisson à plusieurs jours pour un gibier.", ex:"Mariner un poulet au yaourt et aux épices avant de le griller", etymo:"De marine, « eau de mer », car la première marinade était la saumure ; du latin marinus."},
  {name:"Saisir",                    en:"To sear",                    cat:"gestes",      def:"Cuire à feu très vif et rapidement la surface d'un aliment pour la colorer et la rendre croustillante, avant de finir la cuisson plus doucement. Ne « ferme pas les pores » (mythe), mais crée les arômes de la réaction de Maillard.", ex:"Saisir un steak une minute de chaque côté dans une poêle fumante", etymo:"Du francique sakjan, « revendiquer », par « prendre vivement » ; sens culinaire au XVIIIe siècle."},
  {name:"Pocher",                    en:"To poach",                   cat:"gestes",      def:"Cuire doucement dans un liquide frémissant, jamais bouillant : œufs, poisson, fruits, quenelles. Cuisson douce qui préserve la tendreté.", ex:"Pocher un œuf 3 minutes dans une eau vinaigrée, des poires dans un sirop", etymo:"De poche, car le blanc d'œuf poché enveloppe le jaune comme une poche."},
  {name:"Flamber",                   en:"To flambé",                  cat:"gestes",      def:"Arroser un plat d'alcool fort et l'enflammer : l'alcool brûle, les arômes restent. Effet de salle autant que de goût.", ex:"Flamber des crêpes Suzette au Grand Marnier, des rognons au cognac", etymo:"De flambe, ancienne forme de flamme, du latin flammula."},
  {name:"Lier",                      en:"To bind / to thicken",       cat:"gestes",      def:"Épaissir une sauce ou un potage pour lui donner du corps : à la farine (roux), à la fécule, au jaune d'œuf, à la crème, au beurre ou au sang. La liaison change la texture et la tenue.", ex:"Lier une blanquette au jaune d'œuf et à la crème hors du feu", etymo:"Du latin ligare, « attacher »."},
  {name:"Émulsionner",               en:"To emulsify",                cat:"gestes",      def:"Mélanger deux liquides qui ne se mélangent pas (huile et eau) en gouttelettes si fines qu'ils forment une masse homogène, grâce à un émulsifiant (jaune d'œuf, moutarde) et à un fouettage énergique. Une émulsion qui « tourne » se sépare.", ex:"La mayonnaise, la vinaigrette, la hollandaise, le beurre blanc sont des émulsions", etymo:"Du latin emulsum, participe de emulgere, « traire » : le lait est l'émulsion naturelle par excellence."},
  {name:"Clarifier",                 en:"To clarify",                 cat:"gestes",      def:"Rendre limpide un liquide trouble : un bouillon ou un consommé avec des blancs d'œufs qui capturent les impuretés, un beurre en le faisant fondre pour séparer la matière grasse du petit-lait.", ex:"Clarifier un bouillon de bœuf pour obtenir un consommé transparent", etymo:"Du latin clarificare, « rendre clair »."},
  {name:"Tamiser",                   en:"To sift",                    cat:"gestes",      def:"Passer une poudre (farine, sucre glace, cacao) à travers un tamis pour retirer les grumeaux et l'aérer. Passer une purée ou une sauce au tamis fin en lisse la texture.", ex:"Tamiser la farine et la levure avant de les incorporer à une génoise", etymo:"De tamis, d'origine gauloise probable (tamisium)."},
  {name:"Chemiser",                  en:"To line",                    cat:"gestes",      def:"Tapisser l'intérieur d'un moule d'une couche (beurre et farine, papier cuisson, biscuits, gelée) pour éviter que la préparation n'attache ou pour la présentation.", ex:"Chemiser un moule à charlotte de biscuits à la cuillère", etymo:"De chemise, « enveloppe », du bas latin camisia."},
  {name:"Napper",                    en:"To coat",                    cat:"gestes",      def:"Recouvrir un mets d'une couche de sauce, de crème ou de glaçage. Une sauce « nappe la cuillère » quand elle est assez épaisse pour y rester en film sans couler.", ex:"Napper un gâteau de ganache, un poisson de sauce hollandaise", etymo:"De nappe, du latin mappa, « serviette, nappe »."},
  {name:"Zester",                    en:"To zest",                    cat:"gestes",      def:"Prélever la partie colorée de l'écorce d'un agrume, riche en huiles essentielles, sans la peau blanche amère (ziste). Se fait à la râpe fine ou au zesteur.", ex:"Zester un citron pour parfumer une crème, une orange pour un cake", etymo:"De zeste, d'origine incertaine, peut-être onomatopéique (XVIIe siècle)."},
  {name:"Suer",                      en:"To sweat",                   cat:"gestes",      def:"Cuire doucement des légumes dans un corps gras, à couvert, sans coloration, pour qu'ils rendent leur eau et concentrent leurs saveurs. Première étape de bien des soupes et sauces.", ex:"Faire suer les oignons avant d'ajouter le riz d'un risotto", etymo:"Du latin sudare : le légume « transpire » son eau."},
  {name:"Concasser",                 en:"To crush / to chop coarsely",cat:"gestes",      def:"Broyer ou hacher grossièrement : des tomates pelées et épépinées, des grains de poivre, des os pour un fond. Plus gros qu'un hachis, plus petit qu'un morceau.", ex:"Des tomates concassées pour une sauce, du poivre concassé pour un steak", etymo:"Du latin conquassare, « secouer fortement, briser »."},
  {name:"Singer",                    en:"To dust with flour",         cat:"gestes",      def:"Saupoudrer de farine des morceaux de viande ou de légumes rissolés avant de mouiller, pour lier la sauce pendant la cuisson. Geste de base des ragoûts.", ex:"Singer le bœuf après l'avoir fait revenir pour un bourguignon", etymo:"Origine discutée : de singe, la farine « singeant » une liaison, ou de l'ancien français singer, « saupoudrer »."},

  // Cuissons
  {name:"Rôtir",                     en:"To roast",                   cat:"cuissons",    def:"Cuire à la chaleur sèche d'un four ou d'une broche, sans liquide, en arrosant du jus. Croûte dorée dehors, tendre dedans. Se dit des viandes, volailles, légumes.", ex:"Un poulet rôti du dimanche, un gigot d'agneau, des légumes racines rôtis", etymo:"Du francique raustjan, « griller »."},
  {name:"Braiser",                   en:"To braise",                  cat:"cuissons",    def:"Cuire longuement et doucement, à couvert, avec peu de liquide, après avoir coloré l'aliment. Pour les pièces dures et gélatineuses qui deviennent fondantes.", ex:"Un bœuf braisé aux carottes, des endives braisées, un jarret de porc", etymo:"De braise, du germanique brasa : on cuisait autrefois dans une braisière posée sur des braises, avec des braises sur le couvercle."},
  {name:"Mijoter",                   en:"To simmer",                  cat:"cuissons",    def:"Cuire lentement à petits frémissements, dans un liquide, pendant longtemps. La cuisson des plats du dimanche : ragoûts, daubes, pot-au-feu.", ex:"Laisser mijoter le bourguignon trois heures à feu doux", etymo:"De l'ancien français mijot, « lieu où l'on fait mûrir les fruits », d'origine germanique."},
  {name:"Griller",                   en:"To grill",                   cat:"cuissons",    def:"Cuire par contact direct avec une source de chaleur vive : gril, barbecue, plancha, poêle-gril. Marquage, croûte, goût fumé.", ex:"Griller une côte de bœuf au barbecue, des sardines à la plancha", etymo:"De gril, du latin craticulum, « petit treillis »."},
  {name:"Frire",                     en:"To deep-fry",                cat:"cuissons",    def:"Cuire par immersion dans un bain d'huile à 160–190 °C. La croûte se forme instantanément, l'intérieur cuit à la vapeur. Une huile trop froide imbibe, trop chaude brûle.", ex:"Des frites en deux bains, des beignets, du poulet frit, des tempuras", etymo:"Du latin frigere, « faire griller, frire »."},
  {name:"Cuisson vapeur",            en:"Steaming",                   cat:"cuissons",    def:"Cuire au-dessus d'un liquide bouillant, dans la vapeur, sans contact avec l'eau. Préserve couleurs, vitamines et textures ; n'ajoute aucune matière grasse.", ex:"Des légumes au panier vapeur, un poisson au cuit-vapeur, des dim sum", etymo:"Vapeur, du latin vapor, « exhalaison, souffle »."},
  {name:"Sous-vide",                 en:"Sous-vide",                  cat:"cuissons",    def:"Cuire un aliment scellé dans un sachet hermétique, plongé dans un bain d'eau à température précise et basse (50 à 85 °C), parfois pendant des heures. Cuisson homogène, à cœur, sans perte. Développée en France dans les années 1970.", ex:"Un magret 55 °C pendant une heure, puis saisi 30 secondes pour la croûte", etymo:"Expression française adoptée telle quelle en anglais. Mise au point par Georges Pralus et Bruno Goussault (1974)."},
  {name:"Basse température",         en:"Low-temperature cooking",    cat:"cuissons",    def:"Cuisson longue à un four réglé entre 60 et 100 °C : les fibres se détendent sans se contracter, la viande reste rosée et juteuse de bord à bord. Exige un thermomètre à sonde.", ex:"Un rôti de bœuf à 80 °C pendant deux heures, cœur à 52 °C", etymo:"Expression descriptive, popularisée dans les années 1990-2000."},
  {name:"Confit",                    en:"Confit",                     cat:"cuissons",    def:"Cuire lentement et longuement un aliment dans sa propre graisse ou dans un corps gras à basse température, puis le conserver dedans. Méthode de conservation du Sud-Ouest devenue technique gastronomique. Pour les fruits, confire se fait dans le sucre.", ex:"Le confit de canard, l'ail confit, des tomates confites, des fruits confits", etymo:"Participe passé de confire, du latin conficere, « achever, préparer »."},
  {name:"Bain-marie",                en:"Bain-marie / water bath",    cat:"cuissons",    def:"Cuire ou chauffer un récipient posé dans un autre contenant de l'eau chaude, pour une chaleur douce et indirecte. Fondre du chocolat, cuire des flans, tenir une sauce au chaud.", ex:"Une crème brûlée cuite au four dans un bain-marie, un sabayon monté au bain-marie", etymo:"Du latin médiéval balneum Mariae, « bain de Marie », en référence à Marie la Juive, alchimiste d'Alexandrie (IIIe siècle) à qui l'on attribue le procédé."},
  {name:"Réaction de Maillard",      en:"Maillard reaction",          cat:"cuissons",    def:"Ensemble de réactions chimiques entre sucres et acides aminés, dès 120–140 °C, qui produisent la coloration brune et les centaines d'arômes des aliments grillés, rôtis ou toastés. C'est elle, pas la caramélisation, qui donne le goût de la croûte du pain et du steak.", ex:"La croûte d'un pain, la peau dorée d'un poulet, le café torréfié, le malt", etymo:"Du nom du chimiste français Louis-Camille Maillard, qui décrit la réaction en 1912."},
  {name:"Caramélisation",            en:"Caramelization",             cat:"cuissons",    def:"Transformation du sucre seul sous l'effet de la chaleur (dès 160 °C environ) : il fond, brunit et développe des arômes de caramel, puis d'amertume. Différente de la réaction de Maillard, qui exige des protéines.", ex:"Le caramel d'une crème brûlée, des oignons caramélisés, une tarte Tatin", etymo:"De caramel, de l'espagnol caramelo, peut-être du latin médiéval cannamella, « canne à sucre »."},
  {name:"Papillote",                 en:"En papillote",               cat:"cuissons",    def:"Cuire un aliment enfermé dans une feuille (papier cuisson, aluminium, feuille de bananier) qui retient la vapeur et les arômes. Cuisson douce, sans matière grasse, qui se sert dans son enveloppe.", ex:"Un filet de poisson en papillote avec citron, herbes et légumes", etymo:"De papillot, diminutif de papillon, pour la forme des papiers torsadés du XVIIIe siècle."},
  {name:"Sauter",                    en:"To sauté",                   cat:"cuissons",    def:"Cuire rapidement de petits morceaux à feu vif dans peu de matière grasse, en les faisant « sauter » dans la poêle pour les retourner. À découvert, sans liquide.", ex:"Des pommes de terre sautées, des champignons, un sauté de légumes au wok", etymo:"Du latin saltare, « danser, sauter » : le geste du cuisinier qui secoue la poêle."},
  {name:"Fumage",                    en:"Smoking",                    cat:"cuissons",    def:"Exposer un aliment à la fumée d'un bois pour le parfumer et le conserver. À froid (moins de 30 °C, le produit reste cru : saumon fumé) ou à chaud (il cuit en même temps : magret, maquereau).", ex:"Le saumon fumé au bois de hêtre, le jambon fumé, le whisky tourbé", etymo:"De fumer, du latin fumare."},
  {name:"Cuisson à l'anglaise",      en:"Boiling (English style)",    cat:"cuissons",    def:"Cuire des légumes dans un grand volume d'eau bouillante salée, à découvert, puis les rafraîchir. Conserve la couleur des légumes verts. Par extension, tout ce qui est simplement cuit à l'eau.", ex:"Des haricots verts à l'anglaise, bien verts et croquants", etymo:"Par référence à la cuisine anglaise, réputée cuire les légumes à l'eau."},

  // Fonds & Sauces
  {name:"Fond",                      en:"Stock",                      cat:"sauces",      def:"Bouillon de base obtenu en cuisant longuement des os, des parures et des aromates dans l'eau. Blanc (sans coloration) ou brun (os rôtis). Fondement des sauces de la cuisine classique.", ex:"Un fond de veau brun pour une sauce, un fond blanc de volaille pour un velouté", etymo:"Du latin fundus, « fond » : ce sur quoi la sauce est bâtie."},
  {name:"Fumet",                     en:"Fish stock",                 cat:"sauces",      def:"Fond de poisson ou de crustacés, cuit peu de temps (20 à 30 minutes) pour ne pas devenir amer. Base des sauces et soupes de la mer.", ex:"Un fumet d'arêtes de sole pour une sauce au vin blanc", etymo:"De fumer, au sens de « dégager une odeur » : le fumet est d'abord l'arôme qui s'élève d'un plat."},
  {name:"Bouillon",                  en:"Broth",                      cat:"sauces",      def:"Liquide dans lequel ont cuit viandes, légumes ou poissons. Se boit tel quel ou sert de base. Le bouillon de légumes se fait en 30 minutes, le bouillon de bœuf en plusieurs heures.", ex:"Le bouillon du pot-au-feu, un bouillon de poule contre le rhume, le dashi japonais", etymo:"De bouillir, du latin bullire, « former des bulles »."},
  {name:"Court-bouillon",            en:"Court-bouillon",             cat:"sauces",      def:"Liquide aromatisé (eau, vin ou vinaigre, carotte, oignon, bouquet garni, poivre) cuit rapidement, dans lequel on poche poissons et crustacés.", ex:"Une truite au bleu, un homard poché au court-bouillon", etymo:"Bouillon « court », c'est-à-dire cuit peu de temps."},
  {name:"Roux",                      en:"Roux",                       cat:"sauces",      def:"Mélange à parts égales de beurre et de farine cuit à la casserole, qui sert à lier les sauces. Blanc (à peine cuit), blond ou brun selon la durée de cuisson et le goût recherché.", ex:"Un roux blanc pour une béchamel, un roux brun pour une sauce espagnole ou un gombo", etymo:"Du latin russus, « rouge, roux », pour la couleur du roux brun."},
  {name:"Sauce mère",                en:"Mother sauce",               cat:"sauces",      def:"Sauce de base dont dérivent des dizaines d'autres. Escoffier en fixe cinq : béchamel, velouté, espagnole, tomate, hollandaise. On y ajoute parfois la mayonnaise.", ex:"De la béchamel naissent la Mornay (fromage) et la Soubise (oignon)", etymo:"Mère au sens de « qui engendre », comme dans « langue mère »."},
  {name:"Béchamel",                  en:"Béchamel sauce",             cat:"sauces",      def:"Sauce blanche obtenue en versant du lait chaud sur un roux blanc, puis en cuisant jusqu'à épaississement. Base des gratins, lasagnes, croque-monsieur et soufflés.", ex:"Un gratin de chou-fleur, des endives au jambon, une lasagne", etymo:"Du nom de Louis de Béchameil, marquis de Nointel, maître d'hôtel de Louis XIV, à qui la sauce fut dédiée."},
  {name:"Velouté",                   en:"Velouté",                    cat:"sauces",      def:"Sauce mère obtenue en mouillant un roux blond avec un fond blanc (volaille, veau, poisson). Désigne aussi un potage lié, à la texture veloutée.", ex:"Un velouté de volaille pour une blanquette, un velouté de potimarron", etymo:"De velours, du latin villosus, « velu »."},
  {name:"Hollandaise",               en:"Hollandaise sauce",          cat:"sauces",      def:"Émulsion chaude de jaunes d'œufs et de beurre clarifié, montée au bain-marie avec un peu d'eau et de citron. Fragile : trop chaude, elle tranche. Accompagne asperges, poissons et œufs bénédicte.", ex:"Des asperges sauce hollandaise, des œufs bénédicte", etymo:"Par référence aux Pays-Bas, peut-être pour le beurre hollandais ; codifiée en France au XIXe siècle."},
  {name:"Mayonnaise",                en:"Mayonnaise",                 cat:"sauces",      def:"Émulsion froide d'huile dans du jaune d'œuf, avec moutarde, vinaigre ou citron, sel. Le jaune contient la lécithine qui tient l'émulsion. Tous les ingrédients doivent être à la même température.", ex:"Une mayonnaise maison pour des œufs durs, un aïoli (à l'ail), une rémoulade", etymo:"Origine disputée : de Mahón (Minorque), prise par Richelieu en 1756, ou de l'ancien français moyeu, « jaune d'œuf »."},
  {name:"Vinaigrette",               en:"Vinaigrette",                cat:"sauces",      def:"Émulsion instable d'huile et de vinaigre (classiquement trois parts pour une), avec sel, poivre, souvent moutarde ou échalote. L'assaisonnement de base des salades et crudités.", ex:"Une vinaigrette à la moutarde pour la laitue, au citron pour le poisson", etymo:"Diminutif de vinaigre, « vin aigre »."},
  {name:"Beurre blanc",              en:"Beurre blanc",               cat:"sauces",      def:"Émulsion de beurre froid dans une réduction de vin blanc, vinaigre et échalote ciselée. Sauce nantaise et angevine, classique du brochet et des poissons de Loire.", ex:"Un sandre au beurre blanc, des Saint-Jacques", etymo:"Créé, selon la légende, par Clémence Lefeuvre, cuisinière à Saint-Julien-de-Concelles, au début du XXe siècle."},
  {name:"Jus",                       en:"Jus",                        cat:"sauces",      def:"En cuisine, le liquide qui s'écoule d'une viande à la cuisson, déglacé et réduit : plus léger et plus concentré qu'une sauce liée. Aussi le liquide extrait d'un fruit ou d'un légume.", ex:"Un jus de rôti, un jus de veau corsé, un jus d'orange pressé", etymo:"Du latin jus, « sauce, bouillon, jus »."},
  {name:"Glace de viande",           en:"Meat glaze",                 cat:"sauces",      def:"Fond brun réduit très longuement jusqu'à devenir sirupeux et brillant, puis gélatineux à froid. Un concentré de goût dont une cuillère suffit à corser une sauce.", ex:"Une cuillère de glace de viande pour lustrer un jus", etymo:"Glace au sens de « nappage brillant », par analogie avec la glace qui luit."},
  {name:"Bouquet garni",             en:"Bouquet garni",              cat:"sauces",      def:"Petit fagot d'aromates liés (thym, laurier, queues de persil, parfois vert de poireau) plongé dans un plat mijoté et retiré avant de servir.", ex:"Un bouquet garni dans le pot-au-feu, la blanquette, la ratatouille", etymo:"Bouquet, de l'ancien normand bosquet, « petit bois » ; garni au sens de « pourvu »."},
  {name:"Mirepoix",                  en:"Mirepoix",                   cat:"sauces",      def:"Mélange de carottes, oignons et céleri taillés en gros dés, revenus au beurre ou à l'huile, base aromatique des fonds, braisés et sauces. Le trio « oignon-carotte-céleri » de la cuisine française.", ex:"Une mirepoix sous un rôti, dans un fond brun, au départ d'une soupe", etymo:"Du nom du duc de Mirepoix (XVIIIe siècle), dont le cuisinier aurait mis la préparation au point."},
  {name:"Liaison",                   en:"Liaison / thickening",       cat:"sauces",      def:"Procédé qui épaissit un liquide : à la farine (roux, singer, beurre manié), à la fécule, aux œufs, à la crème, au beurre, au sang ou au corail. Chaque liaison a sa texture et ses contraintes de température.", ex:"Une liaison à la fécule pour une sauce aigre-douce, au jaune d'œuf pour une carbonara", etymo:"De lier, du latin ligare."},

  // Ingrédients & Produits
  {name:"Gluten",                    en:"Gluten",                     cat:"produits",    def:"Réseau de protéines (gliadines et gluténines) qui se forme quand la farine de blé, d'orge ou de seigle est hydratée et pétrie. Il donne à la pâte son élasticité et retient le gaz de la fermentation. Intolérance : maladie cœliaque.", ex:"Une pâte à pain bien pétrie a un réseau de gluten qui la rend élastique", etymo:"Du latin gluten, « colle, glu »."},
  {name:"Levure",                    en:"Yeast",                      cat:"produits",    def:"Champignon microscopique (Saccharomyces cerevisiae) qui transforme les sucres en gaz carbonique et en alcool : elle fait lever le pain et fermenter la bière et le vin. À ne pas confondre avec la levure chimique, une poudre à lever sans vivant.", ex:"Un cube de levure de boulanger pour une brioche, un sachet de levure chimique pour un cake", etymo:"De lever, du latin levare, « soulever »."},
  {name:"Levain",                    en:"Sourdough starter",          cat:"produits",    def:"Mélange de farine et d'eau fermenté par les levures et bactéries sauvages qui s'y installent, entretenu par des rafraîchis. Il fait lever le pain lentement et lui donne acidité, arômes et conservation.", ex:"Un pain au levain à la mie irrégulière et à la croûte épaisse", etymo:"Du latin populaire levamen, « ce qui soulève », de levare."},
  {name:"Épice",                     en:"Spice",                      cat:"produits",    def:"Substance aromatique d'origine végétale (graine, écorce, racine, fruit), souvent séchée et venue de loin : poivre, cannelle, cumin, curcuma, safran. Elle parfume, colore, conserve. Différente de l'herbe aromatique, qui est une feuille.", ex:"Le poivre, le safran, la cannelle, le piment, la vanille", etymo:"Du latin species, « espèce, denrée », qui désigne au Moyen Âge les marchandises précieuses."},
  {name:"Herbe aromatique",          en:"Culinary herb",              cat:"produits",    def:"Plante dont on utilise les feuilles, fraîches ou séchées, pour parfumer : persil, basilic, thym, ciboulette, coriandre, estragon. Les herbes tendres s'ajoutent en fin de cuisson, les herbes ligneuses (thym, romarin) au début.", ex:"Des fines herbes dans une omelette, du basilic sur des tomates, du thym dans un ragoût", etymo:"Herbe, du latin herba ; aromatique, du grec arôma, « parfum, épice »."},
  {name:"Condiment",                 en:"Condiment",                  cat:"produits",    def:"Préparation qui accompagne un plat pour en relever le goût, ajoutée à table ou en cuisine : moutarde, ketchup, sauce soja, cornichons, chutney, harissa.", ex:"De la moutarde avec le pot-au-feu, du wasabi avec les sushis", etymo:"Du latin condimentum, « assaisonnement », de condire, « confire, assaisonner »."},
  {name:"Sel de table",              en:"Table salt",                 cat:"produits",    def:"Chlorure de sodium, seul minéral que l'on mange tel quel : il assaisonne, conserve, fait dégorger et renforce les autres saveurs. Sel fin, gros sel, fleur de sel, sel gris de Guérande. Repère de santé : moins de 5 g par jour.", ex:"Saler l'eau des pâtes à 10 g par litre, une pincée de fleur de sel sur une viande", etymo:"Sel, du latin sal. Le mot salaire vient de la ration de sel des soldats romains."},
  {name:"Beurre clarifié",           en:"Clarified butter / ghee",    cat:"produits",    def:"Beurre fondu dont on a retiré l'eau et les protéines du petit-lait : il ne reste que la matière grasse pure. Supporte les hautes températures sans brûler et se conserve longtemps. Le ghee indien en est la version cuite.", ex:"Cuire une sole meunière au beurre clarifié, monter une hollandaise", etymo:"Clarifié, du latin clarificare, « rendre clair »."},
  {name:"Crème fraîche",             en:"Crème fraîche",              cat:"produits",    def:"Matière grasse du lait, épaisse quand elle a été ensemencée de ferments lactiques (goût acidulé), liquide sinon. Seule la crème à plus de 30 % de matière grasse monte en chantilly et supporte la réduction sans trancher.", ex:"Une crème épaisse d'Isigny sur une tarte aux pommes, de la crème liquide pour une chantilly", etymo:"Crème, du bas latin crama, d'origine gauloise, croisé avec chrisma, « onguent »."},
  {name:"Œuf",                       en:"Egg",                        cat:"produits",    def:"L'ingrédient le plus polyvalent de la cuisine : il lie, émulsionne, aère, colore, clarifie, coagule. Un blanc est de l'eau et des protéines, un jaune est gras et riche en lécithine. Le calibre moyen pèse 55 à 60 g.", ex:"Un œuf mollet 6 minutes, une omelette, une meringue avec les blancs, une mayonnaise avec le jaune", etymo:"Du latin ovum. Le pluriel « des œufs » se prononce sans le f, héritage de l'ancien français."},
  {name:"Légumineuse",               en:"Legume / pulse",             cat:"produits",    def:"Graine de plante à gousse : lentille, pois chiche, haricot sec, fève, soja. Riche en protéines et en fibres, elle remplace en partie la viande. À tremper (sauf lentilles) et à cuire longuement.", ex:"Un dhal de lentilles, un houmous de pois chiches, un cassoulet aux haricots", etymo:"Du latin legumen, « plante à gousse », de legere, « cueillir »."},
  {name:"Céréale",                   en:"Cereal / grain",             cat:"produits",    def:"Graine de graminée cultivée pour l'alimentation : blé, riz, maïs, orge, avoine, seigle, millet. Base de l'alimentation humaine depuis le néolithique, sous forme de pain, pâtes, semoule, bouillies.", ex:"Le riz en Asie, le maïs en Amérique, le blé en Europe", etymo:"Du latin cerealis, « relatif à Cérès », déesse romaine des moissons."},
  {name:"Affinage",                  en:"Cheese ripening",            cat:"produits",    def:"Maturation d'un fromage en cave, de quelques semaines à plusieurs années, pendant laquelle il est retourné, brossé, lavé ou piqué. C'est là que naissent la croûte, la texture et le goût.", ex:"Un comté 24 mois, un camembert affiné à cœur, un roquefort en cave de Combalou", etymo:"D'affiner, « rendre fin, achever », de fin au sens de « parfait »."},
  {name:"Charcuterie",               en:"Charcuterie / cured meats",  cat:"produits",    def:"Préparations à base de viande, surtout de porc, transformées par salage, séchage, fumage ou cuisson : jambon, saucisson, pâté, rillettes, boudin. Née pour conserver la viande, devenue un art régional.", ex:"Un jambon de Bayonne, un saucisson d'Auvergne, des rillettes du Mans", etymo:"De chair cuite, par l'ancien français charcuitier."},
  {name:"AOP",                       en:"PDO (Protected Designation of Origin)", cat:"produits", def:"Appellation d'origine protégée : label européen garantissant qu'un produit est entièrement produit, transformé et élaboré dans une zone géographique définie, selon un savoir-faire reconnu. Version européenne de l'AOC française.", ex:"Comté, roquefort, huile d'olive de Nyons, piment d'Espelette, vins de Bordeaux", etymo:"Sigle d'appellation d'origine protégée, créée par l'Union européenne en 1992."},
  {name:"IGP",                       en:"PGI (Protected Geographical Indication)", cat:"produits", def:"Indication géographique protégée : label européen plus souple que l'AOP, où au moins une étape (production, transformation ou élaboration) a lieu dans la zone définie.", ex:"Jambon de Bayonne, pruneaux d'Agen, volailles de Bresse (AOP) contre volailles du Gers (IGP)", etymo:"Sigle d'indication géographique protégée, règlement européen de 1992."},
  {name:"Label Rouge",               en:"Label Rouge",                cat:"produits",    def:"Signe officiel français garantissant une qualité supérieure au produit courant, par un cahier des charges sur l'élevage, l'alimentation et la durée de vie de l'animal. Ne dit rien de l'origine.", ex:"Un poulet fermier Label Rouge élevé 81 jours au lieu de 35", etymo:"Créé par la loi d'orientation agricole de 1960 ; le premier fut le poulet des Landes en 1965."},
  {name:"Agriculture biologique",    en:"Organic farming",            cat:"produits",    def:"Mode de production sans pesticides ni engrais de synthèse, sans OGM, respectant le bien-être animal et les cycles naturels. Certifié par le logo européen (feuille étoilée) et le label AB français. Ne garantit ni le goût ni la proximité.", ex:"Des légumes bio d'une AMAP, un vin bio, des œufs de poules élevées en plein air", etymo:"Biologique, du grec bios, « vie », et logos, « discours » ; sens agricole depuis les années 1930-1950."},
  {name:"Circuit court",             en:"Short supply chain",         cat:"produits",    def:"Vente d'un produit alimentaire avec au plus un intermédiaire entre le producteur et le consommateur : vente à la ferme, marché, AMAP, magasin de producteurs. Réduit les kilomètres et rémunère mieux le producteur.", ex:"Un panier d'AMAP hebdomadaire, le marché du samedi, une cueillette à la ferme", etymo:"Définition officielle du ministère de l'Agriculture (2009)."},

  // Goût & Saveurs
  {name:"Saveur",                    en:"Taste (basic)",              cat:"saveurs",     def:"Sensation perçue par les papilles de la langue. On en distingue cinq : sucré, salé, acide, amer, umami. Tout le reste de ce que l'on « goûte » vient en fait de l'odorat.", ex:"Le sucré d'un miel, l'amer d'un café, l'acide d'un citron", etymo:"Du latin sapor, « goût », de sapere, « avoir du goût » — qui donne aussi savoir."},
  {name:"Umami",                     en:"Umami",                      cat:"saveurs",     def:"Cinquième saveur, celle du glutamate et de certains nucléotides : ronde, profonde, « savoureuse ». Naturellement présente dans les tomates mûres, le parmesan, la sauce soja, le bouillon dashi, la viande, les champignons.", ex:"Le goût d'un parmesan vieux, d'un bouillon de bœuf, d'une sauce soja", etymo:"Du japonais umai, « délicieux », et mi, « goût ». Identifié par le chimiste Kikunae Ikeda en 1908."},
  {name:"Amertume",                  en:"Bitterness",                 cat:"saveurs",     def:"Saveur du café, du cacao, de l'endive, du houblon, des agrumes (ziste). Instinctivement rejetée (signal de toxicité), elle s'apprend et structure un plat ou une boisson. Le sel et le sucre l'atténuent.", ex:"L'amertume d'une bière IPA, d'un chocolat à 90 %, d'un tonic", etymo:"Du latin amaritudo, de amarus, « amer »."},
  {name:"Acidité",                   en:"Acidity",                    cat:"saveurs",     def:"Saveur du citron, du vinaigre, des fruits, du yaourt, du vin. Elle réveille un plat, coupe le gras, équilibre le sucre. Un plat plat manque souvent d'acidité, pas de sel.", ex:"Un trait de citron sur un poisson, du vinaigre dans une lentille, un vin blanc vif", etymo:"Du latin aciditas, de acidus, « aigre, piquant »."},
  {name:"Arôme",                     en:"Aroma",                      cat:"saveurs",     def:"Odeur perçue par le nez, directement ou par l'arrière-gorge en mangeant (rétro-olfaction). Ce que l'on appelle « goût » est à 80 % arôme : nez bouché, on ne distingue plus une pomme d'un oignon.", ex:"L'arôme de vanille, de pain grillé, de truffe", etymo:"Du grec arôma, « épice, plante aromatique »."},
  {name:"Flaveur",                   en:"Flavour",                    cat:"saveurs",     def:"Impression globale que laisse un aliment en bouche : saveurs, arômes, texture, température, piquant, tout ensemble. Le mot manquait en français, il a été emprunté à l'anglais.", ex:"La flaveur d'une fraise des bois : sucre, acidité, parfum, jus", etymo:"De l'anglais flavour, lui-même de l'ancien français flaur, « odeur »."},
  {name:"Rétro-olfaction",           en:"Retronasal olfaction",       cat:"saveurs",     def:"Perception des arômes par l'arrière de la bouche, quand les molécules odorantes des aliments mâchés remontent vers le nez. C'est elle qui fait la richesse du « goût », bien plus que la langue.", ex:"Le goût de fraise persiste après avoir avalé : c'est la rétro-olfaction", etymo:"Du latin retro, « en arrière », et olfaction, de olfacere, « sentir »."},
  {name:"Texture",                   en:"Texture / mouthfeel",        cat:"saveurs",     def:"Ce que la bouche sent au toucher : croquant, fondant, croustillant, crémeux, moelleux, gélatineux, granuleux. Un plat réussi joue les contrastes de textures autant que de saveurs.", ex:"Le croustillant d'une croûte contre le moelleux de la mie", etymo:"Du latin textura, « tissage », de texere, « tisser »."},
  {name:"Piquant",                   en:"Pungency / heat",            cat:"saveurs",     def:"Sensation de brûlure du piment (capsaïcine), du poivre (pipérine), du gingembre, du wasabi ou de la moutarde. Ce n'est pas une saveur mais une irritation des récepteurs de la douleur et de la chaleur. Se mesure en unités Scoville.", ex:"Un piment d'Espelette (4 000 Scoville), un habanero (300 000)", etymo:"De piquer, du latin populaire pikkare, d'origine onomatopéique."},
  {name:"Astringence",               en:"Astringency",                cat:"saveurs",     def:"Sensation de bouche sèche et râpeuse provoquée par les tanins (vin rouge jeune, thé fort, kaki pas mûr, noix fraîche). Une sensation tactile, pas une saveur.", ex:"Un vin rouge tannique qui « assèche » les gencives, un thé noir trop infusé", etymo:"Du latin astringere, « serrer, resserrer »."},
  {name:"Assaisonnement",            en:"Seasoning",                  cat:"saveurs",     def:"Ajout de sel, poivre, épices, herbes, acide ou gras pour révéler et équilibrer le goût d'un plat. Se fait en cours de cuisson et se rectifie à la fin, en goûtant. Un plat sous-assaisonné paraît fade, pas « léger ».", ex:"Rectifier l'assaisonnement d'une soupe : sel, poivre, un trait de vinaigre", etymo:"De saison : à l'origine, « mettre au point, faire mûrir », comme un fruit vient à sa saison."},
  {name:"Accord mets-vin",           en:"Food and wine pairing",      cat:"saveurs",     def:"Choix d'un vin qui va bien avec un plat, par ressemblance (un vin gras avec un plat riche) ou par contraste (un vin vif avec un plat gras). Règles classiques : blanc avec le poisson, rouge avec la viande — souvent contredites.", ex:"Un sancerre avec un crottin de Chavignol, un sauternes avec un roquefort", etymo:"Accord au sens musical, « harmonie », de accorder, du latin cor, « cœur »."},
  {name:"Équilibre des saveurs",     en:"Balance of flavours",        cat:"saveurs",     def:"Principe selon lequel un plat réussi tient en tension sucré, salé, acide, amer, umami, gras et piquant : chaque élément corrige un excès de l'autre. Le sucre adoucit l'acide, l'acide coupe le gras, le sel réveille tout.", ex:"Une sauce aigre-douce, un caramel au beurre salé, un citron sur une friture", etymo:"Équilibre, du latin aequilibrium, « égalité de poids »."},

  // Pâtisserie & Boulangerie
  {name:"Pâte brisée",               en:"Shortcrust pastry",          cat:"patisserie",  def:"Pâte à tarte de base : farine, beurre froid, un peu d'eau et de sel, travaillée le moins possible pour rester friable. Sablée quand on y ajoute sucre et jaune d'œuf.", ex:"Une quiche lorraine, une tarte aux pommes", etymo:"Brisée, de briser : le beurre est « brisé » dans la farine en petits morceaux."},
  {name:"Pâte feuilletée",           en:"Puff pastry",                cat:"patisserie",  def:"Pâte obtenue en enfermant du beurre dans une détrempe (farine et eau), puis en pliant et étalant six fois (les « tours ») : 729 couches qui gonflent à la cuisson quand la vapeur les sépare. Longue à faire, facile à acheter.", ex:"Un mille-feuille, une galette des rois, un vol-au-vent, des palmiers", etymo:"De feuillet, diminutif de feuille : la pâte se sépare en feuillets."},
  {name:"Pâte à choux",              en:"Choux pastry",               cat:"patisserie",  def:"Pâte cuite deux fois : d'abord sur le feu (eau, beurre, farine desséchée), puis au four après l'ajout d'œufs. Elle gonfle et se creuse, prête à être garnie.", ex:"Des éclairs, des profiteroles, un Paris-Brest, des gougères", etymo:"De chou, par analogie de forme avec le légume ; du latin caulis, « tige »."},
  {name:"Génoise",                   en:"Genoise sponge",             cat:"patisserie",  def:"Biscuit léger obtenu en fouettant œufs entiers et sucre au bain-marie jusqu'à tripler de volume, puis en incorporant délicatement la farine. Base des gâteaux à étages et des bûches.", ex:"Un fraisier, une forêt-noire, un gâteau roulé", etymo:"De Gênes, la ville italienne ; le biscuit de Savoie en est le cousin."},
  {name:"Meringue",                  en:"Meringue",                   cat:"patisserie",  def:"Blancs d'œufs montés en neige avec du sucre. Française (sucre à cru, séchée au four), italienne (sirop chaud versé sur les blancs, pour les tartes et macarons), suisse (montée au bain-marie).", ex:"Une pavlova, une tarte au citron meringuée, des macarons", etymo:"Origine incertaine ; peut-être de Meiringen, en Suisse, ou du polonais marzynka."},
  {name:"Crème pâtissière",          en:"Pastry cream",               cat:"patisserie",  def:"Crème épaisse cuite à base de lait, jaunes d'œufs, sucre et farine ou fécule, parfumée à la vanille. Elle garnit choux, éclairs, mille-feuilles et tartes aux fruits.", ex:"La garniture d'un éclair, d'un flan pâtissier, d'une tarte aux fraises", etymo:"Pâtissière, de pâtissier, de pâte, du bas latin pasta, du grec pastê, « bouillie »."},
  {name:"Crème anglaise",            en:"Custard sauce",              cat:"patisserie",  def:"Sauce sucrée obtenue en cuisant doucement du lait avec des jaunes d'œufs et du sucre jusqu'à ce qu'elle nappe la cuillère (82–84 °C), sans bouillir. Base des glaces et de l'île flottante.", ex:"Une île flottante, un fondant au chocolat avec sa crème anglaise", etymo:"Par référence à la custard anglaise."},
  {name:"Ganache",                   en:"Ganache",                    cat:"patisserie",  def:"Émulsion de chocolat fondu et de crème chaude, plus ou moins ferme selon les proportions : garniture de tarte, glaçage, cœur de truffe. Montée au fouet une fois froide, elle devient mousseuse.", ex:"Une tarte au chocolat, des truffes, le fourrage d'un macaron", etymo:"D'un mot signifiant « imbécile » au XIXe siècle : un apprenti aurait versé par erreur de la crème chaude sur du chocolat."},
  {name:"Tempérage",                 en:"Tempering (chocolate)",      cat:"patisserie",  def:"Cycle de températures précis (fondre à 50 °C, refroidir à 27 °C, remonter à 31 °C pour le noir) qui donne au chocolat, une fois pris, son brillant, son cassant et sa tenue. Sans tempérage, il blanchit et reste mou.", ex:"Tempérer du chocolat pour mouler des œufs de Pâques ou des bonbons", etymo:"De tempérer, du latin temperare, « mélanger dans de justes proportions, modérer »."},
  {name:"Pétrissage",                en:"Kneading",                   cat:"patisserie",  def:"Travail mécanique d'une pâte pour hydrater la farine, développer le réseau de gluten et incorporer de l'air. Trop court, le pain est dense ; trop long, la pâte chauffe et s'affaisse.", ex:"Pétrir une pâte à pain dix minutes à la main, jusqu'à ce qu'elle soit lisse et élastique", etymo:"De pétrir, du bas latin pistrire, de pistor, « celui qui broie le grain, boulanger »."},
  {name:"Pointage",                  en:"Bulk fermentation",          cat:"patisserie",  def:"Première fermentation d'une pâte à pain, en masse, après le pétrissage : la levure ou le levain produit le gaz, la pâte gonfle et développe ses arômes. Suivie du façonnage, puis de l'apprêt (deuxième pousse).", ex:"Un pointage long au froid, toute une nuit, donne un pain plus parfumé", etymo:"De pointer, « commencer à paraître » : la pâte « pointe », c'est-à-dire lève."},
  {name:"Façonnage",                 en:"Shaping",                    cat:"patisserie",  def:"Donner sa forme définitive à une pâte levée avant la dernière pousse : boule, bâtard, baguette, couronne. Le geste tend la surface pour que le pain se développe régulièrement.", ex:"Façonner une baguette en roulant et en serrant la pâte", etymo:"De façonner, de façon, du latin factio, « manière de faire »."},
  {name:"Caramel",                   en:"Caramel",                    cat:"patisserie",  def:"Sucre cuit jusqu'à brunir (160 à 180 °C), à sec ou avec un peu d'eau. Blond pour un flan, ambré pour une crème caramel, brun pour une sauce. Il cuit encore après le feu : le stopper avec de la crème ou du beurre.", ex:"Un caramel au beurre salé, une crème caramel, des pommes d'amour", etymo:"De l'espagnol caramelo, peut-être du latin médiéval cannamella, « canne à sucre »."},
  {name:"Sabler",                    en:"To rub in / to sand",        cat:"patisserie",  def:"Frotter du beurre froid et de la farine entre les doigts jusqu'à obtenir une texture de sable grossier, avant d'ajouter le liquide. Enrobe la farine de gras, limite le gluten : la pâte reste friable.", ex:"Sabler une pâte à crumble, une pâte sablée, des scones", etymo:"De sable, du latin sabulum."},
  {name:"Crémer",                    en:"To cream",                   cat:"patisserie",  def:"Fouetter du beurre mou avec du sucre jusqu'à obtenir une masse pâle et légère, qui emprisonne de l'air. Première étape des cakes, sablés et crèmes au beurre.", ex:"Crémer le beurre et le sucre pour un quatre-quarts", etymo:"De crème : la texture obtenue est crémeuse."},

  // Vins & Boissons
  {name:"Vin",                       en:"Wine",                       cat:"boissons",    def:"Boisson obtenue par la fermentation alcoolique du raisin : les levures transforment le sucre en alcool. Rouge (macération avec les peaux), blanc (jus seul), rosé (courte macération), effervescent, doux. La France en est le premier producteur avec l'Italie.", ex:"Un bourgogne, un bordeaux, un champagne, un vin nature", etymo:"Du latin vinum, apparenté au grec oinos."},
  {name:"Cépage",                    en:"Grape variety",              cat:"boissons",    def:"Variété de vigne cultivée : chardonnay, pinot noir, cabernet-sauvignon, syrah, sauvignon blanc, riesling. Chaque cépage a ses arômes ; les vins d'assemblage en mêlent plusieurs.", ex:"Le pinot noir de Bourgogne, le gamay du Beaujolais, le chenin de Loire", etymo:"De cep, du latin cippus, « pieu, tronc »."},
  {name:"Millésime",                 en:"Vintage",                    cat:"boissons",    def:"Année de récolte du raisin d'un vin, indiquée sur l'étiquette. Elle renseigne sur les conditions climatiques de l'année et sur l'âge du vin. Un champagne millésimé vient d'une seule année exceptionnelle.", ex:"Un bordeaux 2010 (grand millésime), un beaujolais nouveau (à boire dans l'année)", etymo:"Du latin millesimus, « millième », pour le chiffre des mille de l'année."},
  {name:"Tanin",                     en:"Tannin",                     cat:"boissons",    def:"Composé végétal des peaux, pépins et rafles du raisin (et du bois des fûts), qui donne au vin rouge sa structure, son astringence et sa capacité à vieillir. Jeune, il assèche ; avec le temps, il s'assouplit.", ex:"Un madiran très tannique, un pinot noir peu tannique", etymo:"De tan, écorce de chêne broyée pour tanner les cuirs, d'origine gauloise."},
  {name:"Œnologie",                  en:"Oenology",                   cat:"boissons",    def:"Science du vin : de la vigne à la bouteille, fermentation, élevage, analyse, dégustation. L'œnologue conseille le vigneron ; le sommelier, lui, sert et conseille le client.", ex:"Un cours d'œnologie pour apprendre à déguster", etymo:"Du grec oinos, « vin », et logos, « discours, science »."},
  {name:"Sommelier",                 en:"Sommelier",                  cat:"boissons",    def:"Professionnel de la salle chargé des vins et boissons d'un restaurant : cave, carte, conseil, service, accords avec les plats. Le meilleur sommelier du monde est élu tous les trois ans.", ex:"Le sommelier propose un accord pour chaque plat du menu dégustation", etymo:"De l'ancien provençal saumalier, « conducteur de bêtes de somme », qui transportait les provisions ; de somme, « charge »."},
  {name:"Méthode traditionnelle",    en:"Traditional method",         cat:"boissons",    def:"Élaboration des vins effervescents par seconde fermentation en bouteille : on ajoute sucre et levures à un vin tranquille, le gaz se forme dans la bouteille fermée, puis on dégorge le dépôt. Champagne, crémants, cava en relèvent.", ex:"Un champagne brut, un crémant d'Alsace, un cava", etymo:"Autrefois « méthode champenoise », appellation réservée au champagne depuis 1994."},
  {name:"Bière",                     en:"Beer",                       cat:"boissons",    def:"Boisson fermentée à base de céréale maltée (orge surtout), d'eau, de houblon et de levure. Le malt donne le sucre et la couleur, le houblon l'amertume et les arômes, la levure l'alcool et le style (ale ou lager).", ex:"Une lager blonde, une IPA houblonnée, une stout noire, une blanche de blé", etymo:"Du moyen néerlandais bier, qui a remplacé cervoise (gaulois) au XVe siècle."},
  {name:"Brassage",                  en:"Brewing",                    cat:"boissons",    def:"Fabrication de la bière : concassage du malt, empâtage dans l'eau chaude pour extraire les sucres, ébullition avec le houblon, fermentation, garde. Le brassage amateur s'est répandu avec les brasseries artisanales.", ex:"Un brassage de 20 litres dans sa cuisine, une microbrasserie de quartier", etymo:"De brasser, du latin populaire braciare, de braces, « sorte de céréale », mot gaulois."},
  {name:"Spiritueux",                en:"Spirits",                    cat:"boissons",    def:"Boisson alcoolisée obtenue par distillation d'un liquide fermenté : cognac et armagnac (vin), whisky (céréales), rhum (canne), vodka (céréales ou pomme de terre), gin (avec genièvre), calvados (cidre). Au moins 15 % d'alcool, souvent 40.", ex:"Un cognac XO, un whisky tourbé, un rhum agricole de Martinique", etymo:"Du latin spiritus, « souffle, esprit » : les alchimistes appelaient « esprit-de-vin » l'alcool distillé."},
  {name:"Distillation",              en:"Distillation",               cat:"boissons",    def:"Séparation de l'alcool d'un liquide fermenté en le chauffant : l'alcool s'évapore avant l'eau (78 °C contre 100), puis se condense dans l'alambic. Concentre l'alcool et les arômes.", ex:"Le vin distillé donne l'eau-de-vie, le cidre le calvados", etymo:"Du latin distillare, « tomber goutte à goutte », de stilla, « goutte »."},
  {name:"Torréfaction",              en:"Roasting (coffee)",          cat:"boissons",    def:"Grillage des grains de café vert à 200–230 °C, qui les brunit et développe leurs arômes par réaction de Maillard et caramélisation. Claire (acidulée) à foncée (amère). Se dit aussi du cacao.", ex:"Un café de torréfaction claire pour un filtre, foncée pour un expresso italien", etymo:"Du latin torrefacere, « sécher, rôtir », de torrere, « brûler »."},
  {name:"Infusion",                  en:"Infusion / steeping",        cat:"boissons",    def:"Extraction des arômes d'une plante en versant dessus de l'eau chaude et en laissant reposer, sans faire bouillir : thé, tisane, mais aussi vanille dans un lait ou herbes dans une huile.", ex:"Un thé vert infusé 3 minutes à 70 °C, une infusion de verveine", etymo:"Du latin infusio, « action de verser dans », de infundere."},
  {name:"Cidre",                     en:"Cider",                      cat:"boissons",    def:"Boisson obtenue par fermentation du jus de pommes à cidre (amères, douces-amères, acidulées), naturellement pétillante. Brut, demi-sec ou doux selon le sucre restant. Normandie, Bretagne, Pays basque.", ex:"Un cidre brut avec une galette de sarrasin, un cidre du Pays d'Auge", etymo:"Du latin sicera, « boisson fermentée », du grec sikera, de l'hébreu shekar."},
  {name:"Décantation",               en:"Decanting",                  cat:"boissons",    def:"Verser un vin dans une carafe pour le séparer de son dépôt (vieux vins) ou pour l'aérer (vins jeunes, on dit alors « carafer »). L'oxygène assouplit les tanins et libère les arômes.", ex:"Décanter un vieux bordeaux une heure avant, carafer un jeune syrah", etymo:"Du latin des alchimistes decanthare, de canthus, « bec de vase »."},
  {name:"Cocktail",                  en:"Cocktail",                   cat:"boissons",    def:"Boisson composée de plusieurs ingrédients mélangés, souvent alcoolisés : un spiritueux de base, un sucrant, un acide ou un amer, parfois dilués par la glace. Secoués au shaker ou remués à la cuillère.", ex:"Un mojito, un negroni, un old fashioned, un spritz", etymo:"De l'anglais cocktail, « queue de coq », d'origine obscure ; attesté aux États-Unis en 1806."},

  // Nutrition & Sécurité alimentaire
  {name:"Nutrition",                 cat:"alimentation", ref:"medecine"},
  {name:"Calorie",                   en:"Calorie",                    cat:"alimentation", def:"Unité d'énergie apportée par un aliment (en fait la kilocalorie, kcal). Les glucides et les protéines en fournissent 4 par gramme, les lipides 9, l'alcool 7. Besoins moyens : 2 000 à 2 500 kcal par jour, selon l'activité.", ex:"Une pomme : 80 kcal ; un croissant : 300 ; une part de pizza : 800", etymo:"Du latin calor, « chaleur » : une calorie élève d'un degré la température d'un gramme d'eau."},
  {name:"Macronutriment",            en:"Macronutrient",              cat:"alimentation", def:"Nutriment dont le corps a besoin en grande quantité et qui fournit l'énergie : glucides, lipides, protéines. Les micronutriments (vitamines, minéraux) sont nécessaires en quantités infimes et ne donnent pas d'énergie.", ex:"Un repas équilibré : moitié légumes, un quart féculents (glucides), un quart protéines", etymo:"Du grec makros, « grand », et nutriment, du latin nutrimentum, « nourriture »."},
  {name:"Glucide",                   en:"Carbohydrate",               cat:"alimentation", def:"Sucre au sens large : simples (glucose, fructose, saccharose), rapidement absorbés, ou complexes (amidon des féculents, fibres), digérés plus lentement. Première source d'énergie du corps et du cerveau.", ex:"Le pain, les pâtes, le riz, les pommes de terre, les fruits, le sucre", etymo:"Du grec glukus, « doux, sucré »."},
  {name:"Protéine",                  en:"Protein",                    cat:"alimentation", def:"Nutriment bâtisseur, fait d'acides aminés : muscles, enzymes, hormones, anticorps. Sources animales (viande, poisson, œuf, laitage) complètes ; sources végétales (légumineuses, céréales, noix) à associer entre elles.", ex:"Un œuf (7 g), 100 g de poulet (25 g), 100 g de lentilles cuites (9 g)", etymo:"Du grec prôteios, « de premier rang », de prôtos, « premier ». Terme de Berzelius (1838)."},
  {name:"Lipide",                    en:"Fat / lipid",                cat:"alimentation", def:"Graisse alimentaire : huiles, beurre, gras des viandes et poissons, oléagineux. Saturés (beurre, graisses animales), insaturés (huile d'olive, colza, poissons gras, dont les oméga-3). Indispensables, mais l'aliment le plus calorique.", ex:"Une cuillère d'huile d'olive, un avocat, une poignée de noix, du saumon", etymo:"Du grec lipos, « graisse »."},
  {name:"Fibre alimentaire",         en:"Dietary fibre",              cat:"alimentation", def:"Partie des végétaux que l'on ne digère pas : elle nourrit le microbiote, régule le transit, ralentit l'absorption des sucres et rassasie. Les Français en mangent 18 g par jour pour 30 recommandés.", ex:"Les légumineuses, les céréales complètes, les légumes, les fruits avec la peau", etymo:"Du latin fibra, « filament »."},
  {name:"Indice glycémique",         en:"Glycaemic index",            cat:"alimentation", def:"Mesure de la vitesse à laquelle un aliment fait monter le sucre dans le sang, sur une échelle de 0 à 100 (glucose pur). Élevé pour le pain blanc et les pommes de terre, bas pour les légumineuses. La cuisson et l'association avec des fibres ou du gras le modifient.", ex:"Baguette : 95 ; riz basmati : 50 ; lentilles : 30", etymo:"Glycémique, du grec glukus, « sucré », et haima, « sang ». Indice proposé par David Jenkins (1981)."},
  {name:"Allergène",                 en:"Allergen",                   cat:"alimentation", def:"Substance qui déclenche une allergie. La réglementation européenne impose d'indiquer quatorze allergènes majeurs sur les étiquettes et les cartes de restaurant : gluten, crustacés, œufs, poissons, arachide, soja, lait, fruits à coque, céleri, moutarde, sésame, sulfites, lupin, mollusques.", ex:"La mention « peut contenir des traces d'arachide » sur un paquet de biscuits", etymo:"D'allergie, du grec allos, « autre », et ergon, « action » ; terme de von Pirquet (1906)."},
  {name:"Intolérance alimentaire",   en:"Food intolerance",           cat:"alimentation", def:"Difficulté à digérer un aliment, sans réaction immunitaire (contrairement à l'allergie) : ballonnements, douleurs, diarrhée. La plus fréquente est l'intolérance au lactose, par manque de l'enzyme qui le digère.", ex:"Boire du lait sans lactose, éviter le gluten en cas de maladie cœliaque (qui, elle, est auto-immune)", etymo:"Du latin intolerantia, « impossibilité de supporter »."},
  {name:"Additif alimentaire",       en:"Food additive",              cat:"alimentation", def:"Substance ajoutée à un aliment industriel pour le conserver, le colorer, l'épaissir, l'émulsionner ou le sucrer, identifiée par un numéro E. Certains sont anodins (E300 = vitamine C), d'autres controversés (E171, dioxyde de titane, interdit en 2020).", ex:"E322 (lécithine), E621 (glutamate), E250 (nitrite de sodium des charcuteries)", etymo:"Du latin additivus, « qui s'ajoute »."},
  {name:"Nutri-Score",               en:"Nutri-Score",                cat:"alimentation", def:"Logo à cinq lettres et couleurs (A vert à E rouge) résumant la qualité nutritionnelle d'un produit pour 100 g : bons points pour fibres, protéines, fruits et légumes ; mauvais points pour calories, sucres, graisses saturées et sel. Facultatif en France depuis 2017.", ex:"Une huile d'olive notée C, un soda light noté B : le score compare dans une même famille", etymo:"Mot-valise de nutrition et score ; conçu par l'équipe de Serge Hercberg (2017)."},
  {name:"Étiquetage alimentaire",    en:"Food labelling",             cat:"alimentation", def:"Informations obligatoires sur un aliment emballé (règlement européen INCO, 2014) : dénomination, liste des ingrédients par ordre décroissant, allergènes, quantité, dates, origine, tableau nutritionnel, mode d'emploi.", ex:"Lire la liste d'ingrédients : le premier est le plus abondant", etymo:"D'étiquette, de l'ancien français estiquet, « pieu, marque », du germanique stikkan, « piquer »."},
  {name:"DLC et DDM",                en:"Use-by and best-before dates", cat:"alimentation", def:"Date limite de consommation (« à consommer jusqu'au ») : impérative, pour les produits frais périssables. Date de durabilité minimale (« à consommer de préférence avant ») : indicative, le produit reste sûr après, il perd seulement en qualité.", ex:"Un yaourt se mange quelques jours après sa DLC ; un paquet de pâtes des mois après sa DDM", etymo:"Sigles de date limite de consommation et date de durabilité minimale (ex-DLUO)."},
  {name:"Chaîne du froid",           en:"Cold chain",                 cat:"alimentation", def:"Maintien sans interruption d'un produit à basse température, de la production au réfrigérateur : moins de 4 °C pour le frais, moins de 18 °C pour le surgelé. Une rupture laisse les bactéries se multiplier ; un produit décongelé ne se recongèle pas.", ex:"Un sac isotherme pour les surgelés, la glacière du camion de livraison", etymo:"Chaîne au sens de « suite ininterrompue de maillons »."},
  {name:"Pasteurisation",            en:"Pasteurization",             cat:"alimentation", def:"Chauffage d'un aliment liquide entre 60 et 90 °C pendant quelques secondes à quelques minutes, pour détruire la plupart des microbes sans trop altérer le goût. Ne stérilise pas : le produit se garde au froid, quelques jours à quelques semaines.", ex:"Le lait pasteurisé, les jus de fruits, la bière, les œufs liquides", etymo:"Du nom de Louis Pasteur, qui met le procédé au point pour le vin en 1865."},
  {name:"Stérilisation",             en:"Sterilization",              cat:"alimentation", def:"Chauffage au-delà de 100 °C (115 à 140 °C) qui détruit tous les micro-organismes et leurs spores. Le produit se conserve des mois à température ambiante : conserves, lait UHT, bocaux.", ex:"Des haricots verts en conserve, une brique de lait UHT, des bocaux de confiture", etymo:"Du latin sterilis, « stérile, infécond »."},
  {name:"Fermentation",              en:"Fermentation",               cat:"alimentation", def:"Transformation d'un aliment par des micro-organismes (bactéries, levures, moisissures) qui en changent le goût, la texture et la conservation. La plus ancienne méthode de conservation : pain, fromage, yaourt, vin, bière, choucroute, kimchi, miso, sauce soja.", ex:"La choucroute, le kéfir, le kombucha, le fromage, le vin", etymo:"Du latin fermentatio, de fervere, « bouillir » : le liquide qui fermente semble bouillir."},
  {name:"HACCP",                     en:"HACCP",                      cat:"alimentation", def:"Méthode d'analyse des dangers et de maîtrise des points critiques, obligatoire dans la restauration : identifier à chaque étape (réception, stockage, cuisson, service) les risques sanitaires et fixer les contrôles (températures, durées, traçabilité).", ex:"Relever la température des frigos deux fois par jour, dater les préparations", etymo:"Sigle de l'anglais Hazard Analysis Critical Control Point, conçu par la NASA et Pillsbury dans les années 1960."},
  {name:"Contamination croisée",     en:"Cross-contamination",        cat:"alimentation", def:"Transfert de microbes ou d'allergènes d'un aliment à un autre par une planche, un couteau, une main ou un plan de travail. La première règle d'hygiène : séparer le cru et le cuit, la viande et les légumes.", ex:"Couper la salade sur la planche du poulet cru sans la laver", etymo:"Contamination, du latin contaminare, « souiller par contact »."},

  // Service & Restauration
  {name:"Restaurant",                en:"Restaurant",                 cat:"restauration", def:"Établissement où l'on sert des repas à la carte, à table, contre paiement. Né à Paris à la fin du XVIIIe siècle, avec la Révolution qui libère les cuisiniers des maisons aristocratiques.", ex:"Un restaurant de quartier, un étoilé, une cantine d'entreprise", etymo:"De restaurer, du latin restaurare : un « restaurant » est d'abord un bouillon fortifiant vendu par Boulanger vers 1765."},
  {name:"Bistrot",                   en:"Bistro",                     cat:"restauration", def:"Petit restaurant ou café simple et convivial, à la cuisine traditionnelle et aux prix modérés : œuf mayonnaise, bœuf bourguignon, tarte Tatin. Institution parisienne.", ex:"Un bistrot de quartier avec son ardoise et son comptoir en zinc", etymo:"Origine incertaine ; la légende du russe bystro, « vite », crié par les cosaques en 1814, est douteuse. Peut-être du poitevin bistraud, « petit domestique »."},
  {name:"Brasserie",                 en:"Brasserie",                  cat:"restauration", def:"Grand restaurant à service continu, à l'origine lié à une brasserie de bière (alsacienne). Choucroute, fruits de mer, plats classiques, service en tenue, longues heures d'ouverture.", ex:"La Coupole, Bofinger, Lipp à Paris", etymo:"De brasser : lieu où l'on brasse la bière, puis où on la sert avec des plats."},
  {name:"Bistronomie",               en:"Bistronomy",                 cat:"restauration", def:"Cuisine de haut niveau servie dans le cadre simple d'un bistrot, à prix raisonnable : produits soignés, carte courte, sans le décorum de la gastronomie. Née à Paris dans les années 1990.", ex:"La Régalade d'Yves Camdeborde (1992), point de départ du mouvement", etymo:"Mot-valise de bistrot et gastronomie, forgé par le critique Sébastien Demorand vers 2004."},
  {name:"Carte et menu",             en:"À la carte / set menu",      cat:"restauration", def:"La carte liste tous les plats avec leur prix, à composer librement ; le menu propose une formule fixe (entrée-plat-dessert) à prix global. Le menu dégustation enchaîne de nombreux petits plats choisis par le chef.", ex:"« Vous prenez la carte ou le menu du jour ? »", etymo:"Menu, du latin minutus, « petit, détaillé » ; carte, du grec khartês, « feuille de papyrus »."},
  {name:"Guide Michelin",            en:"Michelin Guide",             cat:"restauration", def:"Guide gastronomique créé en 1900 par le fabricant de pneus pour encourager les automobilistes à voyager. Ses étoiles (une : « très bonne table », deux : « vaut le détour », trois : « vaut le voyage ») sont la distinction la plus recherchée au monde.", ex:"La France compte une trentaine de trois-étoiles", etymo:"Du nom des frères André et Édouard Michelin, fondateurs de la marque de pneumatiques à Clermont-Ferrand."},
  {name:"Maître d'hôtel",            en:"Maître d'",                  cat:"restauration", def:"Responsable de la salle d'un restaurant : accueil, placement, prise de commande, coordination du service, parfois découpe ou flambage devant le client. Le pendant du chef côté salle.", ex:"Le maître d'hôtel découpe le canard au guéridon", etymo:"À l'origine, l'officier chargé de la maison (« hôtel ») d'un grand seigneur."},
  {name:"Dressage",                  en:"Plating",                    cat:"restauration", def:"Disposition des éléments d'un plat dans l'assiette avant l'envoi : volumes, couleurs, hauteur, sauce. La présentation fait partie du goût ; le premier contact est visuel.", ex:"Dresser un filet sur un lit de purée, la sauce en point, l'herbe posée à la pince", etymo:"De dresser, du latin populaire directiare, « rendre droit, mettre en place »."},
  {name:"Amuse-bouche",              en:"Amuse-bouche",               cat:"restauration", def:"Petite bouchée offerte par le chef avant le repas, hors carte, pour ouvrir l'appétit et donner le ton. Dans un restaurant gastronomique, il peut y en avoir plusieurs. Aussi appelé « mise en bouche ».", ex:"Une cuillère de velouté, un gougère tiède, une tartelette de la taille d'une pièce", etymo:"Forme polie de amuse-gueule, apparue dans les restaurants dans les années 1980."},
  {name:"Coup de feu",               en:"Rush / service peak",        cat:"restauration", def:"Moment le plus intense du service, quand toutes les commandes tombent en même temps et que la cuisine tourne à plein régime. Tout repose sur la mise en place et la coordination.", ex:"Entre 20 h 30 et 21 h 30, le coup de feu du samedi soir", etymo:"Expression militaire, « feu » désignant l'action, passée dans la cuisine au XIXe siècle."},
  {name:"Traiteur",                  en:"Caterer",                    cat:"restauration", def:"Professionnel qui prépare des plats à emporter ou livrés, et organise les repas de réceptions : mariage, séminaire, cocktail. Vend aussi en boutique des plats cuisinés.", ex:"Un buffet de mariage pour 150 personnes, des plateaux-repas pour une réunion", etymo:"De traiter, « recevoir à table », du latin tractare."},
  {name:"Repas gastronomique des Français", en:"Gastronomic meal of the French", cat:"restauration", def:"Pratique sociale inscrite au patrimoine culturel immatériel de l'humanité par l'UNESCO en 2010 : un repas festif qui suit une structure (apéritif, entrée, plat, fromage, dessert, digestif), avec de bons produits, des accords mets-vins, une belle table et la conversation.", ex:"Le repas de Noël ou de mariage, avec sa succession de plats et son temps long", etymo:"Première inscription d'une tradition culinaire par l'UNESCO, avec la cuisine mexicaine la même année."},
  {name:"Art de la table",           en:"Table setting / tableware",  cat:"restauration", def:"Tout ce qui entoure le repas sans être la nourriture : nappe, vaisselle, verres, couverts et leur disposition, décoration, ordre du service. Le service « à la française » présente tous les plats ensemble, le service « à la russe » les fait se succéder.", ex:"Le couteau à droite lame vers l'assiette, la fourchette à gauche dents vers la nappe", etymo:"Expression du XIXe siècle, apogée de la porcelaine de Limoges et de la cristallerie."},

  // Histoire & Figures
  {name:"Auguste Escoffier",         en:"Auguste Escoffier",          cat:"histoire",    def:"Cuisinier français (1846-1935), « roi des cuisiniers et cuisinier des rois ». Il codifie la cuisine classique dans le Guide culinaire (1903), invente la brigade et le service à l'assiette, fonde des palaces avec César Ritz. La pêche Melba est de lui.", ex:"Le Guide culinaire reste la référence des écoles hôtelières", etymo:"Né à Villeneuve-Loubet (Alpes-Maritimes)."},
  {name:"Antonin Carême",            en:"Marie-Antoine Carême",       cat:"histoire",    def:"Pâtissier et cuisinier français (1784-1833), fondateur de la grande cuisine française. Il sert Talleyrand, le tsar et les Rothschild, invente les pièces montées architecturales, la toque, et classe les sauces mères.", ex:"Ses croquembouches et ses ouvrages, Le Pâtissier royal, L'Art de la cuisine française", etymo:"Surnommé « le roi des chefs et le chef des rois » avant Escoffier."},
  {name:"Brillat-Savarin",           en:"Brillat-Savarin",            cat:"histoire",    def:"Magistrat et gastronome français (1755-1826), auteur de la Physiologie du goût (1825), premier traité de gastronomie, mêlant science, anecdotes et aphorismes. Un fromage triple crème et un gâteau portent son nom.", ex:"« Dis-moi ce que tu manges, je te dirai ce que tu es »", etymo:"Jean Anthelme Brillat-Savarin, né à Belley (Ain)."},
  {name:"Nouvelle cuisine",          en:"Nouvelle cuisine",           cat:"histoire",    def:"Mouvement des années 1970 (Bocuse, Troisgros, Guérard, Chapel) contre la lourdeur de la cuisine classique : cuissons courtes, sauces légères sans farine, produits frais, assiettes dressées en cuisine, carte courte. Ses excès (portions minuscules) ont été moqués, ses principes sont restés.", ex:"Le saumon à l'oseille des frères Troisgros (1962), emblème du mouvement", etymo:"Expression lancée par les critiques Henri Gault et Christian Millau en 1973, avec leurs « dix commandements »."},
  {name:"Paul Bocuse",               en:"Paul Bocuse",                cat:"histoire",    def:"Cuisinier français (1926-2018), trois étoiles Michelin de 1965 à sa mort à Collonges-au-Mont-d'Or, figure de la nouvelle cuisine et premier chef star médiatique. Il crée le concours Bocuse d'Or (1987) et la soupe VGE aux truffes pour l'Élysée (1975).", ex:"« Monsieur Paul », élu cuisinier du siècle par Gault et Millau en 1989", etymo:"Héritier d'une lignée de cuisiniers lyonnais depuis 1765."},
  {name:"Cuisine bourgeoise",        en:"Bourgeois cuisine",          cat:"histoire",    def:"Cuisine familiale soignée des maisons aisées du XIXe siècle, entre la grande cuisine des palaces et la cuisine paysanne : plats mijotés, sauces, bons produits, recettes transmises. Le fond de la cuisine des bistrots.", ex:"La blanquette, le pot-au-feu, le gratin dauphinois, la tarte Tatin", etymo:"De bourgeois, « habitant du bourg », par opposition à l'aristocratie et à la paysannerie."},
  {name:"Gastronomie moléculaire",   en:"Molecular gastronomy",       cat:"histoire",    def:"Discipline scientifique qui étudie les phénomènes physiques et chimiques de la cuisine, fondée par Hervé This et Nicholas Kurti en 1988. La « cuisine moléculaire » en est l'application par des chefs (Ferran Adrià, Heston Blumenthal) : sphérification, espumas, azote liquide.", ex:"Une sphère d'olive d'El Bulli, un œuf cuit à 65 °C, une mousse au siphon", etymo:"Moléculaire, de molécule, du latin moles, « masse »."},
  {name:"Cuisine régionale",         en:"Regional cuisine",           cat:"histoire",    def:"Ensemble des plats, produits et manières propres à une région, façonnés par le climat, le terroir et l'histoire : beurre et crème au Nord, huile d'olive au Sud, graisse d'oie au Sud-Ouest. La France en compte autant que de pays d'Europe.", ex:"La choucroute alsacienne, la bouillabaisse marseillaise, le cassoulet toulousain, la galette bretonne", etymo:"Régional, du latin regio, « direction, contrée »."},
  {name:"Slow food",                 en:"Slow food",                  cat:"histoire",    def:"Mouvement international né en Italie en 1986 contre la restauration rapide et la standardisation : défendre les produits locaux, les savoir-faire, la biodiversité alimentaire et le plaisir de manger. Symbole : l'escargot.", ex:"L'Arche du goût recense les produits en voie de disparition", etymo:"De l'anglais slow, « lent », par opposition à fast food ; fondé par Carlo Petrini à Bra (Piémont)."},
  {name:"CAP Cuisine",               en:"Culinary vocational diploma", cat:"histoire",   def:"Certificat d'aptitude professionnelle, premier diplôme du cuisinier en France : deux ans après la troisième, ou un an en reconversion adulte, en lycée hôtelier ou en apprentissage. Suivi du bac pro, du BTS et des écoles (Ferrandi, Institut Paul Bocuse).", ex:"Passer son CAP Cuisine en candidat libre après une reconversion", etymo:"Sigle de certificat d'aptitude professionnelle, créé en 1911."},
];

// ═════════════════════════════════════════════════════════════════════════════
// LEXIQUE MATÉRIEL & ÉLECTRONIQUE
// ═════════════════════════════════════════════════════════════════════════════

const terms_electronique = [
  // Électricité de base
  {name:"Tension électrique",        en:"Voltage",                    cat:"electricite", def:"Différence de potentiel entre deux points d'un circuit, en volts (V) : la « pression » qui pousse les électrons. Un port USB délivre 5 V, une prise murale 230 V alternatif, une pile 1,5 V.", ex:"Une carte Arduino fonctionne en 5 V, un ESP32 en 3,3 V : brancher l'un sur l'autre sans adaptation le grille", etymo:"Du latin tensio, « action de tendre ». Le volt vient d'Alessandro Volta, inventeur de la pile (1800)."},
  {name:"Courant électrique",        en:"Electric current",           cat:"electricite", def:"Flux d'électrons dans un conducteur, en ampères (A) : le « débit ». Une LED consomme 20 mA, un chargeur de téléphone fournit 2 à 3 A, un four 16 A. C'est le courant, pas la tension, qui chauffe les fils et tue.", ex:"Un fusible de 5 A coupe le circuit si le courant dépasse 5 ampères", etymo:"Du latin currere, « courir ». L'ampère vient d'André-Marie Ampère, fondateur de l'électrodynamique (1820)."},
  {name:"Résistance électrique",     en:"Electrical resistance",      cat:"electricite", def:"Opposition d'un matériau au passage du courant, en ohms (Ω). Faible pour le cuivre, énorme pour le plastique. Elle transforme l'énergie électrique en chaleur : c'est le principe du grille-pain et le problème du processeur.", ex:"Un fil de cuivre : quelques milliohms ; la peau sèche : 100 000 ohms", etymo:"Du latin resistere, « se tenir contre ». L'ohm vient de Georg Ohm, physicien allemand (1827)."},
  {name:"Loi d'Ohm",                 en:"Ohm's law",                  cat:"electricite", def:"U = R × I : la tension aux bornes d'une résistance est égale à la résistance multipliée par le courant qui la traverse. La formule de base de tout calcul de circuit : elle donne la résistance à mettre devant une LED.", ex:"Pour une LED (2 V, 20 mA) alimentée en 5 V : R = (5 − 2) / 0,02 = 150 Ω", etymo:"Formulée par Georg Ohm en 1827, d'abord rejetée par ses pairs."},
  {name:"Puissance électrique",      en:"Electric power",             cat:"electricite", def:"Énergie consommée ou fournie par seconde, en watts (W) : P = U × I. Une LED : 0,1 W ; un Raspberry Pi : 5 à 10 W ; un PC de jeu : 500 W ; un four : 2 500 W. Le kilowattheure de la facture est une puissance multipliée par un temps.", ex:"Un chargeur 20 W délivre 5 V × 4 A ou 9 V × 2,2 A", etymo:"Le watt vient de James Watt, ingénieur écossais de la machine à vapeur (XVIIIe siècle)."},
  {name:"Courant continu et alternatif", en:"DC and AC",              cat:"electricite", def:"Continu (DC) : les électrons vont toujours dans le même sens, comme dans une pile, un port USB ou un circuit électronique. Alternatif (AC) : le sens s'inverse 50 fois par seconde (50 Hz en Europe), comme dans le réseau électrique, plus facile à transporter. Un adaptateur convertit l'un en l'autre.", ex:"Le bloc d'alimentation d'un PC transforme le 230 V alternatif en 12 V, 5 V et 3,3 V continus", etymo:"DC : direct current ; AC : alternating current. La « guerre des courants » opposa Edison (continu) à Tesla et Westinghouse (alternatif) vers 1890."},
  {name:"Masse électrique",          en:"Ground (GND)",               cat:"electricite", def:"Point de référence d'un circuit, par convention à 0 V, auquel toutes les tensions sont comparées et vers lequel le courant retourne. Sur une carte, la broche GND. Deux circuits reliés doivent partager la même masse pour se comprendre.", ex:"Relier le GND de l'Arduino au GND du capteur avant de brancher le signal", etymo:"Masse, du latin massa : à l'origine, le châssis métallique de l'appareil. GND pour ground, « terre »."},
  {name:"Court-circuit",             en:"Short circuit",              cat:"electricite", def:"Liaison directe entre deux points de tension différente sans résistance entre eux : le courant devient énorme, échauffe, fond, enflamme. La première cause de composants grillés au montage et la raison des fusibles.", ex:"Deux pattes d'un composant qui se touchent sous une goutte de soudure", etymo:"Court au sens de « chemin le plus court » pour le courant."},
  {name:"Bloc d'alimentation",       en:"Power supply unit (PSU)",    cat:"electricite", def:"Boîtier qui transforme le courant alternatif du secteur en tensions continues stables pour l'électronique. Dans un PC, il alimente carte mère, disques et carte graphique ; sa puissance (500, 750, 1 000 W) doit couvrir tous les composants avec marge.", ex:"Une alimentation 750 W certifiée 80 Plus Gold pour un PC avec une grosse carte graphique", etymo:"Alimentation, du latin alimentum, « nourriture »."},
  {name:"Batterie",                  en:"Battery",                    cat:"electricite", def:"Réserve d'énergie chimique convertie en électricité, rechargeable (accumulateur) ou non (pile). Caractérisée par sa tension (3,7 V pour une cellule lithium) et sa capacité en milliampères-heure (mAh) : 5 000 mAh alimentent 500 mA pendant 10 heures.", ex:"La batterie d'un téléphone : 4 000 à 5 000 mAh ; d'une voiture électrique : 50 à 100 kWh", etymo:"Du français batterie, « ensemble de pièces d'artillerie » : Franklin nomme ainsi un ensemble de condensateurs (1748), Volta un ensemble de piles."},
  {name:"Lithium-ion",               en:"Lithium-ion",                cat:"electricite", def:"Technologie de batterie rechargeable dominante depuis les années 1990 : dense en énergie, légère, sans effet mémoire. Fragile : elle vieillit avec les cycles, craint la chaleur et le froid, et peut s'enflammer si elle est percée ou surchargée. Une charge entre 20 et 80 % la préserve.", ex:"Téléphones, ordinateurs portables, voitures électriques, trottinettes", etymo:"Lithium, du grec lithos, « pierre » ; élément découvert en 1817. Ion, du grec iôn, « qui va »."},
  {name:"Fusible",                   en:"Fuse",                       cat:"electricite", def:"Fil calibré qui fond et coupe le circuit quand le courant dépasse sa valeur : une protection à usage unique contre les surintensités. Le disjoncteur fait la même chose mais se réarme.", ex:"Un fusible de 3,15 A dans une multiprise, un fusible réarmable (polyfuse) sur un port USB", etymo:"Du latin fusus, « fondu », de fundere, « fondre »."},
  {name:"Chargeur",                  en:"Charger / power adapter",    cat:"electricite", def:"Adaptateur secteur qui fournit la tension continue d'un appareil et gère la recharge de sa batterie. La norme USB Power Delivery permet de négocier jusqu'à 240 W sur un câble USB-C : un même chargeur pour téléphone et ordinateur.", ex:"Un chargeur 65 W USB-C qui charge le portable, la tablette et le téléphone", etymo:"De charger, du bas latin carricare, de carrus, « char »."},

  // Composants
  {name:"Composant électronique",    en:"Electronic component",       cat:"composants",  def:"Élément de base d'un circuit : passif (résistance, condensateur, bobine, qui ne font que freiner, stocker, filtrer) ou actif (transistor, diode, circuit intégré, qui amplifient ou commutent). Traversant (pattes soudées à travers la carte) ou CMS (posé en surface).", ex:"Une carte mère porte des milliers de composants, la plupart CMS de la taille d'un grain de riz", etymo:"Du latin componere, « placer ensemble »."},
  {name:"Résistance (composant)",    en:"Resistor",                   cat:"composants",  def:"Composant qui oppose une résistance connue au courant, pour limiter une intensité, diviser une tension ou fixer un niveau. Sa valeur est indiquée par des anneaux de couleur. Le composant le plus courant d'un circuit.", ex:"Une résistance de 220 Ω en série avec une LED, une résistance de 10 kΩ de rappel sur un bouton", etymo:"Voir résistance électrique ; le composant est nommé d'après la grandeur qu'il incarne."},
  {name:"Condensateur",              en:"Capacitor",                  cat:"composants",  def:"Composant qui stocke une charge électrique entre deux plaques, en farads (le plus souvent micro ou nanofarads), et la restitue : il lisse une alimentation, filtre un signal, temporise. Les électrolytiques ont un sens de branchement et gonflent en vieillissant.", ex:"Les condensateurs autour d'un processeur absorbent les pics de consommation", etymo:"De condenser, du latin condensare, « rendre dense » : il « condense » la charge. Farad, de Michael Faraday."},
  {name:"Bobine",                    en:"Inductor / coil",            cat:"composants",  def:"Fil enroulé qui s'oppose aux variations de courant en stockant l'énergie dans un champ magnétique, en henrys (H). Sert dans les filtres, les alimentations à découpage, les transformateurs, les moteurs.", ex:"La bobine d'un convertisseur de tension, la self de filtrage d'une alimentation", etymo:"De l'ancien français bobine, peut-être onomatopéique. Henry, de Joseph Henry, physicien américain."},
  {name:"Diode",                     en:"Diode",                      cat:"composants",  def:"Composant qui ne laisse passer le courant que dans un sens (de l'anode vers la cathode), avec une chute de tension de 0,7 V environ. Redresse l'alternatif en continu, protège contre les inversions de polarité.", ex:"Le pont de diodes d'un chargeur, la diode de protection d'un relais", etymo:"Du grec di, « deux », et hodos, « chemin », sur le modèle d'électrode (deux électrodes)."},
  {name:"LED",                       en:"LED (Light-Emitting Diode)", cat:"composants",  def:"Diode qui émet de la lumière quand un courant la traverse. Consomme dix fois moins qu'une ampoule à incandescence, dure des dizaines de milliers d'heures. Toujours à alimenter à travers une résistance qui limite le courant.", ex:"Le voyant d'une carte, un ruban de LED RGB, un écran OLED, l'éclairage domestique", etymo:"Sigle de l'anglais light-emitting diode ; en français DEL. Première LED visible en 1962 (Nick Holonyak)."},
  {name:"Transistor",                en:"Transistor",                 cat:"composants",  def:"Composant à trois broches qui laisse passer ou non un courant entre deux d'entre elles selon la tension appliquée à la troisième : un interrupteur commandé électriquement, ou un amplificateur. La brique de toute l'électronique moderne ; un processeur en contient des milliards.", ex:"Un transistor pour commander un moteur depuis une broche d'Arduino, 20 milliards dans une puce Apple M-series", etymo:"Contraction de l'anglais transfer resistor. Inventé aux Bell Labs en 1947 (Bardeen, Brattain, Shockley), prix Nobel 1956."},
  {name:"MOSFET",                    en:"MOSFET",                     cat:"composants",  def:"Type de transistor commandé par une tension (et non un courant) sur sa grille, quasi sans consommation au repos : celui qui compose les processeurs et mémoires, et qui commute les fortes puissances dans les alimentations et les moteurs.", ex:"Un MOSFET de puissance pour commander un ruban de LED de 5 A", etymo:"Sigle de l'anglais metal-oxide-semiconductor field-effect transistor. Inventé en 1959 (Atalla et Kahng)."},
  {name:"Semi-conducteur",           en:"Semiconductor",              cat:"composants",  def:"Matériau, silicium en tête, dont la conductivité se situe entre l'isolant et le conducteur et se contrôle par dopage (ajout d'impuretés) et par tension. Le fondement des diodes, transistors et puces ; par extension, l'industrie qui les fabrique.", ex:"La pénurie de semi-conducteurs de 2021 a arrêté des chaînes automobiles", etymo:"Du latin semi, « à moitié », et conducteur, de conducere, « conduire »."},
  {name:"Circuit intégré",           en:"Integrated circuit (IC)",    cat:"composants",  def:"Puce : des milliers à des milliards de transistors et composants gravés sur une même pastille de silicium, enfermée dans un boîtier à broches. D'un simple amplificateur à un processeur complet.", ex:"Le 555 (temporisateur), un ATmega328 (microcontrôleur d'Arduino), un Ryzen (processeur)", etymo:"Inventé en 1958 par Jack Kilby (Texas Instruments), prix Nobel 2000, et Robert Noyce (Fairchild)."},
  {name:"Relais",                    en:"Relay",                      cat:"composants",  def:"Interrupteur commandé par un électroaimant : un petit courant de commande ferme un contact qui laisse passer un gros courant, isolé électriquement. Il fait « clic ». Permet à un microcontrôleur 5 V de commander une lampe 230 V.", ex:"Un module relais pour allumer un chauffage depuis un Raspberry Pi", etymo:"De relayer, « remplacer » : le relais transmet la commande à un autre circuit, comme les relais de poste."},
  {name:"Potentiomètre",             en:"Potentiometer",              cat:"composants",  def:"Résistance variable à trois broches, réglée par un bouton rotatif ou un curseur : elle délivre une tension proportionnelle à la position. Bouton de volume, réglage de luminosité, entrée analogique d'un montage.", ex:"Un potentiomètre de 10 kΩ lu sur l'entrée analogique A0 d'un Arduino", etymo:"De potentiel et mètre, « mesure » : il mesure ou fixe un potentiel."},
  {name:"Quartz",                    en:"Crystal oscillator",         cat:"composants",  def:"Cristal qui vibre à une fréquence très précise quand on lui applique une tension : il donne le tempo (l'horloge) des processeurs, montres et radios. 32 768 Hz pour une montre, 16 MHz sur un Arduino.", ex:"Le petit boîtier métallique ovale à côté du microcontrôleur", etymo:"De l'allemand Quarz, d'origine slave probable. Effet piézoélectrique découvert par les frères Curie en 1880."},
  {name:"Transformateur",            en:"Transformer",                cat:"composants",  def:"Deux bobines couplées par un noyau magnétique : la tension alternative entrant dans l'une ressort dans l'autre multipliée par le rapport du nombre de spires. Abaisse le 230 V du secteur, isole les circuits. Ne fonctionne qu'en alternatif.", ex:"Le gros bloc lourd d'un vieux chargeur, le transformateur d'un poste de quartier", etymo:"Du latin transformare, « changer de forme »."},
  {name:"Régulateur de tension",     en:"Voltage regulator",          cat:"composants",  def:"Composant qui délivre une tension de sortie fixe et stable quelle que soit la tension d'entrée ou la charge : le 7805 sort 5 V à partir de 7 à 25 V. Linéaire (simple, chauffe) ou à découpage (efficace, plus complexe).", ex:"Le régulateur 3,3 V d'une carte ESP32 alimentée en 5 V par USB", etymo:"Du latin regula, « règle »."},
  {name:"Optocoupleur",              en:"Optocoupler",                cat:"composants",  def:"Composant qui transmet un signal par la lumière entre une LED et un phototransistor enfermés dans le même boîtier : les deux côtés sont isolés électriquement. Protège un microcontrôleur d'un circuit haute tension ou bruyant.", ex:"L'entrée d'un variateur de lumière, l'isolation d'un port MIDI", etymo:"De opto, du grec optos, « visible », et coupleur."},

  // Circuits & Fabrication
  {name:"Circuit imprimé",           en:"Printed circuit board (PCB)", cat:"circuits",   def:"Plaque isolante (époxy) sur laquelle des pistes de cuivre gravées relient les composants soudés. Simple face, double face ou multicouche (une carte mère en a 8 à 12). Conçue avec un logiciel (KiCad), fabriquée à l'unité pour quelques euros.", ex:"La carte verte d'un Arduino, la carte mère d'un PC, le circuit d'une télécommande", etymo:"Imprimé car les premières pistes étaient déposées par un procédé d'impression (Paul Eisler, 1936)."},
  {name:"Breadboard",                en:"Breadboard",                 cat:"circuits",    def:"Plaque d'essai sans soudure : des rangées de trous reliés entre eux dans lesquels on enfiche composants et fils pour tester un montage, le modifier, le défaire. L'outil du prototype ; pas fiable pour du définitif.", ex:"Monter une LED, une résistance et un bouton sur breadboard avant de concevoir la carte", etymo:"De l'anglais bread board, « planche à pain » : les premiers bricoleurs radio clouaient leurs composants sur une planche de cuisine."},
  {name:"Soudure électronique",      en:"Soldering",                  cat:"circuits",    def:"Fixation d'un composant sur une carte par un alliage d'étain fondu au fer à souder (300 à 350 °C), qui assure le contact électrique et mécanique. Une bonne soudure est brillante et concave ; une soudure « sèche » (mate, grumeleuse) est une panne future.", ex:"Souder les broches d'un connecteur sur une carte, dessouder un condensateur gonflé", etymo:"Du latin solidare, « rendre solide »."},
  {name:"Schéma électronique",       en:"Schematic",                  cat:"circuits",    def:"Dessin normalisé d'un circuit : chaque composant a son symbole (zigzag pour la résistance, triangle et barre pour la diode), les traits sont les connexions. Il décrit la logique, pas la disposition physique, qui est le rôle du routage du circuit imprimé.", ex:"Lire le schéma d'un Arduino pour trouver quelle broche va au régulateur", etymo:"Du grec skhêma, « forme, figure »."},
  {name:"Fiche technique",           en:"Datasheet",                  cat:"circuits",    def:"Document du fabricant décrivant un composant : brochage, tensions et courants limites, caractéristiques, schémas d'application, boîtier. La première chose à lire avant de brancher quoi que ce soit ; « lire la datasheet » est le réflexe de l'électronicien.", ex:"La datasheet du capteur DHT22 donne son protocole et son délai entre deux lectures", etymo:"Fiche, du francique fikkjan, « ficher, planter » ; datasheet, de l'anglais data et sheet, « feuille »."},
  {name:"Multimètre",                en:"Multimeter",                 cat:"circuits",    def:"Appareil de mesure portable qui lit la tension, le courant, la résistance, et teste la continuité (bip si le circuit est fermé) et les diodes. Le premier outil de diagnostic : « est-ce que ça reçoit du 5 V ? ».", ex:"Mesurer la tension d'une pile, vérifier qu'une piste n'est pas coupée", etymo:"De multi, « plusieurs », et mètre, « mesure »."},
  {name:"Oscilloscope",              en:"Oscilloscope",               cat:"circuits",    def:"Appareil qui affiche l'évolution d'une tension dans le temps sous forme de courbe : on y voit la forme d'un signal, sa fréquence, son bruit, ses parasites. Indispensable dès que le multimètre ne suffit plus.", ex:"Visualiser le signal PWM d'un moteur, le bus I2C d'un capteur, l'ondulation d'une alimentation", etymo:"Du latin oscillare, « se balancer », et du grec skopein, « regarder »."},
  {name:"Composant CMS",             en:"Surface-mount device (SMD)", cat:"circuits",    def:"Composant monté en surface : soudé directement sur les pistes, sans pattes traversant la carte. Minuscule (jusqu'à 0,4 mm), posé par des machines, c'est la norme industrielle. Le composant traversant reste celui du bricolage et des connecteurs.", ex:"Les résistances 0603 d'un téléphone (1,6 × 0,8 mm)", etymo:"Sigle de composant monté en surface ; en anglais SMD, surface-mount device."},
  {name:"Finesse de gravure",        en:"Process node",               cat:"circuits",    def:"Dimension caractéristique des transistors d'une puce, en nanomètres : 3 nm pour les meilleurs processeurs actuels, 28 nm pour un microcontrôleur courant. Plus c'est fin, plus la puce est dense, rapide et économe — et plus l'usine coûte cher. Le chiffre est devenu un nom commercial plus qu'une mesure.", ex:"L'Apple M4 est gravé en 3 nm par TSMC ; un cheveu fait 80 000 nm", etymo:"Gravure, du grec graphein, « écrire, graver » : les transistors sont dessinés par photolithographie."},
  {name:"Fonderie de semi-conducteurs", en:"Semiconductor foundry",   cat:"circuits",    def:"Usine qui fabrique les puces conçues par d'autres : TSMC (Taïwan) produit celles d'Apple, AMD, Nvidia ; Samsung et Intel ont les leurs. Une usine de pointe coûte plus de 20 milliards de dollars, d'où la concentration extrême et l'enjeu géopolitique.", ex:"TSMC fabrique plus de 90 % des puces les plus avancées du monde", etymo:"Fonderie, de fondre, du latin fundere, par analogie avec la métallurgie ; en anglais fab, de fabrication plant."},

  // Signaux & Logique
  {name:"Signal analogique",         en:"Analog signal",              cat:"signaux",     def:"Grandeur électrique qui varie continûment, à l'image du phénomène qu'elle représente : la tension d'un micro suit la pression de l'air, celle d'un capteur de température suit la chaleur. Riche, mais sensible au bruit et impossible à copier sans perte.", ex:"Le sillon d'un vinyle, la sortie d'un thermistor, le son avant la carte son", etymo:"Du grec analogos, « proportionnel »."},
  {name:"Signal numérique",          en:"Digital signal",             cat:"signaux",     def:"Grandeur qui ne prend que des valeurs discrètes, en pratique deux : 0 (0 V) et 1 (3,3 ou 5 V). Robuste au bruit, copiable à l'infini, traitable par un processeur. Tout ce qui est numérique est une suite de 0 et de 1 échantillonnés dans le temps.", ex:"Un fichier MP3, une photo, le signal d'un bouton (appuyé ou non)", etymo:"Du latin numerus, « nombre » ; en anglais digital, de digit, « chiffre »."},
  {name:"Convertisseur analogique-numérique", en:"ADC / DAC",         cat:"signaux",     def:"Circuit qui mesure une tension et la traduit en nombre (ADC), ou l'inverse (DAC). Sa résolution en bits fixe la finesse : 10 bits = 1 024 niveaux (Arduino), 24 bits = 16 millions (audio studio). Sa fréquence d'échantillonnage fixe la vitesse : 44 100 fois par seconde pour un CD.", ex:"L'entrée A0 d'un Arduino (ADC 10 bits), la sortie casque d'un téléphone (DAC)", etymo:"ADC, de l'anglais analog-to-digital converter ; DAC, digital-to-analog converter."},
  {name:"PWM",                       en:"PWM (Pulse-Width Modulation)", cat:"signaux",   def:"Modulation de largeur d'impulsion : un signal numérique qui bascule très vite entre 0 et 1, dont on règle la proportion de temps à 1 (le rapport cyclique). En moyenne, cela simule une tension variable : variation de LED, vitesse de moteur, position de servomoteur.", ex:"analogWrite(9, 128) sur Arduino : la LED à 50 % de luminosité", etymo:"Sigle de l'anglais pulse-width modulation ; en français MLI, modulation de largeur d'impulsion."},
  {name:"Fréquence",                 en:"Frequency",                  cat:"signaux",     def:"Nombre de répétitions par seconde d'un phénomène périodique, en hertz (Hz). 50 Hz pour le secteur, 440 Hz pour le la du diapason, 2,4 GHz pour le Wi-Fi, 4 GHz pour un processeur (quatre milliards de cycles par seconde).", ex:"Un écran à 120 Hz affiche 120 images par seconde", etymo:"Du latin frequentia, « affluence, répétition ». Le hertz vient de Heinrich Hertz, qui prouva les ondes électromagnétiques (1887)."},
  {name:"Horloge",                   en:"Clock signal",               cat:"signaux",     def:"Signal carré régulier qui rythme un circuit numérique : à chaque front, les bascules changent d'état, le processeur avance d'une étape. Sa fréquence est la « vitesse » annoncée d'une puce, même si l'architecture compte autant.", ex:"Un processeur à 3,5 GHz, un bus I2C cadencé à 400 kHz", etymo:"Du latin médiéval clocca, « cloche », d'origine celtique."},
  {name:"Porte logique",             en:"Logic gate",                 cat:"signaux",     def:"Circuit élémentaire qui combine des bits selon une opération : ET (1 si toutes les entrées sont à 1), OU, NON, OU exclusif, NON-ET. Faite de quelques transistors, elle est la brique de tout calcul : additionneurs, mémoires, processeurs ne sont que des portes assemblées.", ex:"Un additionneur 1 bit tient en quelques portes XOR et ET", etymo:"Porte au sens de « passage contrôlé » ; logique, du grec logikê, « art du raisonnement »."},
  {name:"Bascule",                   en:"Flip-flop",                  cat:"signaux",     def:"Circuit qui mémorise un bit : il garde son état (0 ou 1) jusqu'à ce qu'un signal d'horloge lui en fasse prendre un nouveau. La cellule de base des registres, compteurs et mémoires statiques.", ex:"Un registre 64 bits est fait de 64 bascules", etymo:"De basculer, de bascule, de bas et cul : la planche qui penche d'un côté ou de l'autre."},
  {name:"Bit",                       cat:"signaux", ref:"informatique"},
  {name:"Octet",                     en:"Byte",                       cat:"signaux",     def:"Groupe de 8 bits, soit 256 valeurs possibles : l'unité de base de la mémoire et du stockage. Un caractère ASCII tient dans un octet. Kilo, méga, giga, téra : mille, million, milliard, mille milliards d'octets (ou puissances de 1 024 : kibi, mébi, gibi).", ex:"Une photo : 3 Mo ; un film : 4 Go ; un disque : 1 To", etymo:"Du latin octo, « huit » ; en anglais byte, forgé par Werner Buchholz chez IBM (1956)."},
  {name:"Hexadécimal",               en:"Hexadecimal",                cat:"signaux",     def:"Système de numération en base 16 (chiffres 0-9 puis A-F) : chaque chiffre code exactement 4 bits, un octet tient en deux chiffres. Plus lisible que le binaire pour les humains : adresses mémoire, couleurs, octets bruts.", ex:"La couleur #FF8800, l'adresse MAC 3C:22:FB:9A:12:00, 0xFF = 255", etymo:"Du grec hex, « six », et du latin decimus, « dixième » : hybride pour « seize »."},
  {name:"Bruit électronique",        en:"Electrical noise",           cat:"signaux",     def:"Fluctuations parasites qui se superposent à un signal : agitation thermique, interférences des moteurs et alimentations, rayonnement des câbles voisins. Il brouille l'analogique et, trop fort, fait basculer le numérique. On le combat par blindage, filtrage et masse commune.", ex:"Le grésillement d'un ampli, les lectures d'un capteur qui sautent quand un moteur démarre", etymo:"Du latin populaire brugere, croisement de rugire, « rugir », et bragere, « braire »."},
  {name:"Filtre électronique",       en:"Electronic filter",          cat:"signaux",     def:"Circuit qui laisse passer certaines fréquences et atténue les autres : passe-bas (élimine les aigus et le bruit), passe-haut, passe-bande. Un simple condensateur et une résistance en font un ; le numérique le fait par calcul.", ex:"Le passe-bas d'une alimentation, l'égaliseur d'une chaîne hi-fi, le filtre anti-repliement avant un ADC", etymo:"Du latin médiéval filtrum, « feutre », à travers lequel on filtrait les liquides."},

  // Processeurs & Puces
  {name:"CPU",                       cat:"processeurs", ref:"informatique"},
  {name:"GPU",                       cat:"processeurs", ref:"informatique"},
  {name:"Cache",                     cat:"processeurs", ref:"informatique"},
  {name:"Microprocesseur",           en:"Microprocessor",             cat:"processeurs", def:"Processeur complet sur une seule puce : il lit des instructions en mémoire et les exécute, une par cycle d'horloge ou plus. Le premier, l'Intel 4004 (1971), comptait 2 300 transistors ; un processeur actuel en compte des dizaines de milliards, sur plusieurs cœurs.", ex:"Intel Core, AMD Ryzen, Apple M-series, Qualcomm Snapdragon", etymo:"Du grec mikros, « petit », et processeur, du latin procedere, « avancer »."},
  {name:"Microcontrôleur",           en:"Microcontroller (MCU)",      cat:"processeurs", def:"Petit ordinateur complet sur une puce : processeur modeste, mémoire, entrées-sorties, convertisseurs, minuteries. Il exécute un seul programme en boucle, sans système d'exploitation, pour quelques centimes et quelques milliwatts. Il y en a des dizaines dans une voiture, un dans chaque machine à laver.", ex:"L'ATmega328 d'un Arduino, l'ESP32, les STM32, le RP2040 d'un Raspberry Pi Pico", etymo:"De micro et contrôleur, de contrôle, de l'ancien français contrerole, « registre tenu en double »."},
  {name:"SoC",                       en:"System on a Chip",           cat:"processeurs", def:"Système sur puce : processeur, cœurs graphiques, mémoire, modem, contrôleurs, processeur neuronal, tout intégré sur une seule puce. La norme des téléphones et tablettes, et depuis les puces Apple M, des ordinateurs.", ex:"L'Apple A18 d'un iPhone, le Snapdragon d'un Android, le Broadcom d'un Raspberry Pi", etymo:"Sigle de l'anglais system on a chip."},
  {name:"Cœur de processeur",        en:"CPU core",                   cat:"processeurs", def:"Unité de calcul indépendante à l'intérieur d'un processeur, capable d'exécuter son propre fil d'instructions. Un processeur à 8 cœurs traite 8 tâches en parallèle. Les puces mobiles mêlent cœurs performants et cœurs économes (big.LITTLE).", ex:"Un Ryzen 9 à 16 cœurs, un M4 à 4 cœurs performants et 6 économes", etymo:"Cœur, du latin cor, au sens de « partie centrale »."},
  {name:"Architecture x86",          en:"x86 architecture",           cat:"processeurs", def:"Famille de jeux d'instructions née avec l'Intel 8086 (1978), devenue le standard des PC et des serveurs : Intel et AMD. Riche et complexe (CISC), rétrocompatible depuis quarante ans, gourmande en énergie face à ARM.", ex:"Un PC Windows, un serveur Linux dans le cloud, une console Xbox ou PlayStation", etymo:"Du numéro des premières puces Intel : 8086, 80286, 80386, 80486."},
  {name:"Architecture ARM",          en:"ARM architecture",           cat:"processeurs", def:"Famille de processeurs à jeu d'instructions simplifié (RISC), sobres en énergie, conçus par la société britannique ARM et fabriqués sous licence par tous les autres. Dans tous les téléphones, les Raspberry Pi, les puces Apple M et de plus en plus de serveurs.", ex:"Apple M4, Snapdragon, les Graviton d'Amazon, le processeur d'un Raspberry Pi", etymo:"D'abord Acorn RISC Machine (1985), puis Advanced RISC Machines."},
  {name:"RISC et CISC",              en:"RISC vs CISC",               cat:"processeurs", def:"Deux philosophies de jeu d'instructions. CISC (x86) : des instructions nombreuses et complexes qui font beaucoup en une fois. RISC (ARM, RISC-V) : des instructions simples, régulières, exécutées vite, qui laissent le compilateur faire le travail. Le RISC a gagné sur l'efficacité énergétique.", ex:"RISC-V, jeu d'instructions ouvert et libre de droits, monte en puissance depuis 2015", etymo:"Sigles de l'anglais reduced et complex instruction set computer, forgés par David Patterson (1980)."},
  {name:"Jeu d'instructions",        en:"Instruction set architecture (ISA)", cat:"processeurs", def:"Liste des opérations élémentaires qu'un processeur sait exécuter (charger, additionner, comparer, sauter…) et leur codage binaire. C'est le contrat entre le matériel et le logiciel : un programme compilé pour x86 ne tourne pas sur ARM sans traduction.", ex:"Rosetta 2 traduit les programmes x86 pour les Mac ARM", etymo:"Instruction, du latin instructio, « arrangement, enseignement »."},
  {name:"Registre",                  en:"Register",                   cat:"processeurs", def:"Petite mémoire ultra-rapide à l'intérieur du processeur (quelques dizaines de cases de 64 bits) où sont posées les valeurs en cours de calcul. Les instructions opèrent sur des registres ; la mémoire vive est cent fois plus lente.", ex:"Le registre qui contient l'adresse de la prochaine instruction (compteur ordinal)", etymo:"Du latin médiéval registrum, « liste, recueil »."},
  {name:"Architecture de von Neumann", en:"Von Neumann architecture", cat:"processeurs", def:"Modèle de presque tous les ordinateurs depuis 1945 : une unité de calcul, une unité de contrôle, une mémoire unique qui contient à la fois les programmes et les données, des entrées-sorties. Le programme est une donnée comme une autre, ce qui permet de le charger et de le modifier.", ex:"Un ordinateur, un téléphone, un Arduino suivent ce modèle ; le cerveau non", etymo:"Du nom de John von Neumann, mathématicien américano-hongrois, qui le décrit dans un rapport de 1945."},
  {name:"FPGA",                      en:"FPGA",                       cat:"processeurs", def:"Puce dont les circuits logiques se reconfigurent par programmation : on y « câble » le circuit que l'on veut, portes, bus, processeur. Plus rapide qu'un logiciel, plus souple qu'une puce figée. Pour le prototypage de puces, le traitement de signal, la finance haute fréquence.", ex:"Émuler une console rétro à l'identique sur un FPGA (MiSTer)", etymo:"Sigle de l'anglais field-programmable gate array, « réseau de portes programmable sur site »."},
  {name:"ASIC",                      en:"ASIC",                       cat:"processeurs", def:"Puce conçue et gravée pour une seule tâche : elle la fait mieux et pour moins d'énergie que tout processeur générique, mais ne peut rien faire d'autre. Minage de bitcoin, décodage vidéo, accélération d'IA.", ex:"Un mineur Antminer, la puce de décodage H.265 d'un téléviseur, un TPU de Google", etymo:"Sigle de l'anglais application-specific integrated circuit."},
  {name:"NPU",                       en:"NPU (Neural Processing Unit)", cat:"processeurs", def:"Processeur neuronal : unité spécialisée dans les multiplications de matrices des réseaux de neurones, intégrée aux puces récentes pour exécuter l'IA sur l'appareil, sans le cloud. Mesuré en TOPS (billions d'opérations par seconde).", ex:"Le Neural Engine d'Apple, les puces « Copilot+ » à 40 TOPS", etymo:"Sigle de l'anglais neural processing unit, sur le modèle de CPU et GPU."},
  {name:"Loi de Moore",              en:"Moore's law",                cat:"processeurs", def:"Observation de Gordon Moore (1965) : le nombre de transistors par puce double tous les deux ans, à coût constant. Vérifiée cinquante ans, elle ralentit depuis 2015 : les transistors approchent la taille des atomes, les gains viennent désormais de l'architecture et de la spécialisation.", ex:"4 004 : 2 300 transistors (1971) ; Apple M2 Ultra : 134 milliards (2023)", etymo:"Du nom de Gordon Moore, cofondateur d'Intel."},
  {name:"Silicium",                  en:"Silicon",                    cat:"processeurs", def:"Élément chimique, deuxième plus abondant de la croûte terrestre (sable, quartz), semi-conducteur idéal une fois purifié à 99,9999999 %. Toutes les puces en sont faites, sur des galettes (wafers) de 30 cm découpées en centaines de puces. Silicon Valley, pas « silicone ».", ex:"Un wafer de 300 mm porte plusieurs centaines de puces", etymo:"Du latin silex, « caillou, silex ». Isolé par Berzelius en 1824."},
  {name:"Ordinateur quantique",      en:"Quantum computer",           cat:"processeurs", def:"Machine dont les unités (qubits) exploitent la superposition et l'intrication pour explorer un grand nombre d'états à la fois. Prometteuse pour la cryptanalyse, la chimie, l'optimisation ; encore expérimentale (quelques centaines de qubits fragiles, à −273 °C). Ne remplacera pas l'ordinateur classique.", ex:"Les machines d'IBM, Google, et les Français Pasqal et Alice & Bob", etymo:"Quantique, du latin quantum, « combien », terme de Planck (1900)."},

  // Mémoire & Stockage
  {name:"Mémoire RAM",               cat:"memoires", ref:"informatique"},
  {name:"Disque dur",                cat:"memoires", ref:"informatique"},
  {name:"SSD",                       cat:"memoires", ref:"informatique"},
  {name:"RAID",                      cat:"memoires", ref:"serveur"},
  {name:"Mémoire morte",             en:"ROM (Read-Only Memory)",     cat:"memoires",    def:"Mémoire dont le contenu est fixé à la fabrication ou rarement réécrit, et qui survit à l'extinction : elle contient le firmware, le BIOS, le programme d'un microcontrôleur. Ses descendantes (EPROM, EEPROM, flash) sont réinscriptibles.", ex:"La ROM d'une cartouche de console, le BIOS d'une carte mère", etymo:"Morte par opposition à vive : elle ne change pas. En anglais read-only, « lecture seule »."},
  {name:"Mémoire flash",             en:"Flash memory",               cat:"memoires",    def:"Mémoire non volatile réinscriptible électriquement, sans pièce mobile : clés USB, cartes SD, SSD, stockage des téléphones. Rapide en lecture, plus lente en écriture, et chaque cellule supporte un nombre limité d'effacements (mille à cent mille).", ex:"Les 256 Go d'un téléphone, une clé USB, le SSD d'un portable", etymo:"Flash, « éclair » : l'effacement d'un bloc entier en un instant rappela un flash photo à Toshiba (1984)."},
  {name:"Mémoire volatile",          en:"Volatile memory",            cat:"memoires",    def:"Mémoire qui perd son contenu sans alimentation. La RAM est volatile (d'où la perte du travail non sauvegardé en cas de coupure) ; disque, SSD, flash et ROM ne le sont pas. Hiérarchie : plus une mémoire est rapide, plus elle est volatile, petite et chère.", ex:"Registres → cache → RAM (volatiles) → SSD → disque → bande (non volatiles)", etymo:"Du latin volatilis, « qui vole, qui s'envole »."},
  {name:"DDR",                       en:"DDR SDRAM",                  cat:"memoires",    def:"Standard des barrettes de mémoire vive des PC : DDR4, DDR5 (depuis 2021), chaque génération doublant le débit. Se caractérise par sa capacité (16, 32 Go), sa fréquence (5 600 MT/s) et ses latences. Une barrette DDR5 ne rentre pas dans un emplacement DDR4.", ex:"32 Go de DDR5-6000 pour un PC de jeu, la LPDDR soudée d'un portable", etymo:"Sigle de l'anglais double data rate : deux transferts par cycle d'horloge."},
  {name:"NVMe",                      en:"NVMe",                       cat:"memoires",    def:"Protocole des SSD modernes, branchés directement sur les lignes PCI Express au lieu de l'ancienne interface SATA des disques durs : dix fois plus rapide (7 Go/s contre 550 Mo/s). Sous forme de barrette M.2 de la taille d'un chewing-gum.", ex:"Un SSD NVMe de 2 To en M.2 sur la carte mère", etymo:"Sigle de l'anglais non-volatile memory express."},
  {name:"SATA",                      en:"SATA",                       cat:"memoires",    def:"Interface de connexion des disques durs et des SSD 2,5 pouces à la carte mère, par un câble fin à 7 fils. Limitée à 600 Mo/s, elle suffit aux disques mécaniques mais bride les SSD, remplacés par le NVMe.", ex:"Un disque de 8 To en SATA pour le stockage, un SSD NVMe pour le système", etymo:"Sigle de l'anglais Serial ATA, ATA venant de AT Attachment, du PC/AT d'IBM (1984)."},
  {name:"Carte SD",                  en:"SD card",                    cat:"memoires",    def:"Petite carte de mémoire flash amovible des appareils photo, drones, consoles, Raspberry Pi. Formats SD et microSD, capacités SDHC (jusqu'à 32 Go), SDXC (2 To). Sa classe de vitesse (U3, V30, A2) compte autant que sa taille pour la vidéo et les systèmes.", ex:"Une microSD A2 de 64 Go comme disque système d'un Raspberry Pi", etymo:"Sigle de l'anglais Secure Digital, standard de 1999 (SanDisk, Panasonic, Toshiba)."},
  {name:"EEPROM",                    en:"EEPROM",                     cat:"memoires",    def:"Mémoire morte effaçable et reprogrammable électriquement, octet par octet, non volatile : les quelques centaines d'octets qu'un microcontrôleur garde entre deux extinctions (réglages, compteurs). Ancêtre de la flash, plus lente mais plus endurante.", ex:"Un Arduino Uno a 1 Ko d'EEPROM pour mémoriser une configuration", etymo:"Sigle de l'anglais electrically erasable programmable read-only memory."},

  // Anatomie d'un ordinateur
  {name:"Carte mère",                en:"Motherboard",                cat:"ordinateur",  def:"Grande carte de circuit imprimé qui relie tous les composants d'un ordinateur : support du processeur, emplacements de mémoire et de cartes, connecteurs de stockage, ports externes, chipset, firmware. Son format (ATX, micro-ATX, mini-ITX) fixe la taille du boîtier.", ex:"Changer de processeur impose souvent de changer de carte mère (support différent)", etymo:"Mère au sens de « qui porte les autres », comme une carte-fille s'y enfiche."},
  {name:"Chipset",                   en:"Chipset",                    cat:"ordinateur",  def:"Puce de la carte mère qui gère les communications entre le processeur et le reste : ports USB, SATA, réseau, lignes PCI Express secondaires. Il détermine ce que la carte sait faire (overclocking, nombre de ports).", ex:"Un chipset AMD X670 ou Intel Z790 pour une carte mère haut de gamme", etymo:"De l'anglais chip, « puce », et set, « ensemble »."},
  {name:"Bus",                       en:"Bus",                        cat:"ordinateur",  def:"Ensemble de lignes électriques partagées par lesquelles les composants échangent données, adresses et commandes. Un bus a une largeur (nombre de bits en parallèle) et une fréquence, qui font sa bande passante. Bus mémoire, PCI Express, USB, I2C sont des bus.", ex:"Le bus mémoire 128 bits d'une carte graphique", etymo:"Abréviation du latin omnibus, « pour tous » : la ligne partagée, comme le véhicule."},
  {name:"PCI Express",               en:"PCI Express (PCIe)",         cat:"ordinateur",  def:"Bus série à haute vitesse de la carte mère, par « lignes » (x1, x4, x16) : une carte graphique en prend 16, un SSD NVMe 4. Chaque génération double le débit (PCIe 5.0 : 4 Go/s par ligne).", ex:"Une carte graphique en PCIe 4.0 x16, un SSD en PCIe 4.0 x4", etymo:"Sigle de l'anglais peripheral component interconnect express (2003)."},
  {name:"Carte graphique",           en:"Graphics card",              cat:"ordinateur",  def:"Carte d'extension qui porte un GPU, sa mémoire dédiée (8 à 24 Go de GDDR), son refroidissement et les sorties vidéo. Pour le jeu, la 3D, la vidéo et l'IA. Souvent le composant le plus cher et le plus gourmand d'un PC ; les puces intégrées suffisent au reste.", ex:"Une Nvidia RTX ou une AMD Radeon ; l'iGPU intégré d'un portable bureautique", etymo:"Graphique, du grec graphikos, « relatif à l'écriture ou au dessin »."},
  {name:"BIOS et UEFI",              en:"BIOS / UEFI firmware",       cat:"ordinateur",  def:"Firmware de la carte mère, premier programme exécuté à l'allumage : il teste le matériel, configure les composants et lance le système d'exploitation. L'UEFI a remplacé le BIOS depuis 2010 : interface graphique, démarrage sécurisé, disques de plus de 2 To. On y entre avec Suppr ou F2.", ex:"Changer l'ordre de démarrage pour installer Linux depuis une clé USB", etymo:"BIOS, basic input/output system (1975) ; UEFI, unified extensible firmware interface."},
  {name:"Firmware",                  en:"Firmware",                   cat:"ordinateur",  def:"Logiciel intégré dans un matériel, stocké en mémoire non volatile, qui le fait fonctionner à bas niveau : BIOS d'une carte mère, programme d'un microcontrôleur, système d'une box, d'un SSD, d'un appareil photo. Se met à jour, rarement, avec précaution : un échec « brique » l'appareil.", ex:"Mettre à jour le firmware d'un routeur pour corriger une faille", etymo:"De l'anglais firm, « ferme », entre hard (matériel) et soft (logiciel) ; forgé par Ascher Opler (1967)."},
  {name:"Pilote",                    en:"Driver",                     cat:"ordinateur",  def:"Programme qui permet au système d'exploitation de dialoguer avec un matériel précis : carte graphique, imprimante, carte son, souris. Sans pilote, le matériel est muet ; un pilote obsolète ou bogué est une cause classique de plantage.", ex:"Installer le pilote Nvidia pour que le jeu utilise la carte graphique", etymo:"De piloter, de l'italien pilota, du grec pêdon, « gouvernail »."},
  {name:"Périphérique",              en:"Peripheral",                 cat:"ordinateur",  def:"Tout matériel connecté à l'unité centrale : d'entrée (clavier, souris, micro, scanner), de sortie (écran, imprimante, enceintes), de stockage (disque externe, clé USB). Interne ou externe, branché par USB, Bluetooth, PCIe.", ex:"Un écran, une webcam, une manette", etymo:"Du grec periphereia, « circonférence » : ce qui est autour du centre."},
  {name:"Refroidissement",           en:"Cooling",                    cat:"ordinateur",  def:"Évacuation de la chaleur produite par les composants, surtout le processeur et la carte graphique (100 à 400 W). Par dissipateur à ailettes et ventilateur (air), ou par circuit d'eau (watercooling). Au-delà de 90-100 °C, la puce ralentit (throttling) puis s'éteint.", ex:"Un ventirad sur le processeur, trois ventilateurs sur la carte graphique, la pâte thermique entre les deux", etymo:"De refroidir, de froid, du latin frigidus."},
  {name:"Overclocking",              en:"Overclocking",               cat:"ordinateur",  def:"Faire tourner un processeur, une carte graphique ou une mémoire au-delà de sa fréquence nominale, pour gagner en performance. Chauffe et consomme plus, réduit la durée de vie, peut rendre instable ; les gains sont devenus faibles, les puces modernes se « boostent » déjà seules.", ex:"Passer un processeur de 4,5 à 5 GHz en montant sa tension", etymo:"De l'anglais over, « au-delà », et clock, « horloge »."},
  {name:"Boîtier",                   en:"Case / chassis",             cat:"ordinateur",  def:"Châssis qui abrite et protège les composants d'un ordinateur, organise le flux d'air et porte les connecteurs de façade. Tour, mini-tour, compact ; en aluminium ou acier, souvent à panneau vitré. Son format doit correspondre à celui de la carte mère.", ex:"Un boîtier moyen-tour ATX avec deux ventilateurs à l'avant, un à l'arrière", etymo:"De boîte, du latin populaire buxida, du grec puxis, « boîte en buis »."},
  {name:"Connecteur",                en:"Connector",                  cat:"ordinateur",  def:"Pièce mécanique qui établit un contact électrique amovible : prise, fiche, embase, broche. Chaque standard a le sien (USB-C, HDMI, RJ45, jack, M.2) ; le connecteur est souvent ce qui casse en premier.", ex:"Le connecteur USB-C d'un téléphone, les 24 broches d'alimentation d'une carte mère", etymo:"Du latin connectere, « lier ensemble »."},

  // Connectique & Interfaces
  {name:"USB",                       en:"USB",                        cat:"connectique", def:"Bus série universel : le standard de connexion des périphériques depuis 1996, qui transporte données et alimentation. Les versions vont de 12 Mbit/s (USB 1) à 80 Gbit/s (USB4 v2) ; les connecteurs de l'ancien USB-A rectangulaire au USB-C réversible. Version et connecteur sont indépendants.", ex:"Un câble USB-C peut être USB 2 (480 Mbit/s) ou USB4 : ça ne se voit pas", etymo:"Sigle de l'anglais universal serial bus."},
  {name:"USB-C",                     en:"USB-C",                      cat:"connectique", def:"Connecteur ovale réversible (2014) devenu le port unique des téléphones, tablettes et ordinateurs, obligatoire en Europe depuis fin 2024. Il peut transporter USB, Thunderbolt, DisplayPort et jusqu'à 240 W — mais chaque port et chaque câble ne supportent pas tout.", ex:"Un seul câble USB-C pour brancher un portable à son écran, qui le recharge en retour", etymo:"C, troisième forme de connecteur USB après A et B."},
  {name:"Thunderbolt",               en:"Thunderbolt",                cat:"connectique", def:"Interface d'Intel et Apple sur connecteur USB-C, la plus rapide des connexions externes (40 Gbit/s, 80 en version 5) : elle transporte PCI Express, DisplayPort et alimentation. Pour les stations d'accueil, les écrans 4K multiples, les SSD externes rapides, les cartes graphiques externes.", ex:"Une station d'accueil Thunderbolt qui relie deux écrans, le réseau et les disques d'un seul câble", etymo:"Nom commercial d'Intel, « coup de tonnerre » ; d'abord Light Peak (2011)."},
  {name:"HDMI",                      en:"HDMI",                       cat:"connectique", def:"Connecteur audio-vidéo numérique des téléviseurs, consoles, box et ordinateurs (2003). HDMI 2.1 permet la 4K à 120 Hz et la 8K. Transporte aussi le son et la télécommande (CEC).", ex:"Brancher une console ou un ordinateur sur un téléviseur", etymo:"Sigle de l'anglais high-definition multimedia interface."},
  {name:"DisplayPort",               en:"DisplayPort",                cat:"connectique", def:"Connecteur vidéo numérique des écrans d'ordinateur, concurrent libre de droits du HDMI, préféré pour les hautes fréquences (240 Hz et plus) et le chaînage de plusieurs écrans. Il voyage aussi dans l'USB-C et le Thunderbolt (mode alternatif).", ex:"Un écran de jeu 1440p à 165 Hz relié en DisplayPort 1.4", etymo:"De l'anglais display, « affichage », et port ; standard VESA (2006)."},
  {name:"Ethernet",                  cat:"connectique", ref:"reseaux"},
  {name:"Câble RJ45",                cat:"connectique", ref:"reseaux"},
  {name:"Wi-Fi",                     cat:"connectique", ref:"numerique"},
  {name:"Bluetooth",                 cat:"connectique", ref:"numerique"},
  {name:"NFC",                       en:"NFC",                        cat:"connectique", def:"Communication sans contact à très courte portée (quelques centimètres), sans appairage : paiement par téléphone ou carte, badge, titre de transport, lecture d'une étiquette. Une puce passive est alimentée par le champ du lecteur.", ex:"Payer en approchant son téléphone du terminal, valider un pass Navigo", etymo:"Sigle de l'anglais near-field communication ; standard de 2004 (Sony, Philips, Nokia)."},
  {name:"RFID",                      en:"RFID",                       cat:"connectique", def:"Identification par radiofréquence : une étiquette (puce et antenne, sans pile) renvoie son identifiant quand un lecteur l'interroge, de quelques centimètres à quelques mètres. Logistique, antivol, puce d'animal, badge d'accès, passeport. Le NFC en est un sous-ensemble.", ex:"La puce sous la peau d'un chat, les étiquettes des vêtements en magasin", etymo:"Sigle de l'anglais radio-frequency identification."},
  {name:"GPIO",                      en:"GPIO",                       cat:"connectique", def:"Broches d'entrée-sortie à usage général d'un microcontrôleur ou d'un Raspberry Pi : chacune peut, par programme, lire un état (bouton, capteur) ou écrire un niveau (LED, relais). Le point de contact entre le code et le monde physique. Attention aux tensions et aux courants qu'elles supportent.", ex:"Les 40 broches d'un Raspberry Pi, les broches D2 à D13 d'un Arduino", etymo:"Sigle de l'anglais general-purpose input/output."},
  {name:"I2C",                       en:"I²C",                        cat:"connectique", def:"Bus série à deux fils (données SDA, horloge SCL) qui relie un microcontrôleur à des dizaines de capteurs et périphériques, chacun ayant une adresse. Lent (100 à 400 kHz) mais simple et économe en broches. Le bus standard des modules pour Arduino et Raspberry Pi.", ex:"Un écran OLED, un capteur de température et une horloge sur les deux mêmes fils", etymo:"Sigle de l'anglais inter-integrated circuit, créé par Philips en 1982."},
  {name:"SPI",                       en:"SPI",                        cat:"connectique", def:"Bus série à quatre fils, plus rapide que l'I2C (dizaines de MHz) : pour les écrans, cartes SD, mémoires flash et convertisseurs qui échangent beaucoup de données. Un fil de sélection par périphérique au lieu d'une adresse.", ex:"Un écran couleur TFT ou un lecteur de carte SD sur un ESP32", etymo:"Sigle de l'anglais serial peripheral interface, créé par Motorola dans les années 1980."},
  {name:"UART",                      en:"UART / serial port",         cat:"connectique", def:"Liaison série asynchrone à deux fils (TX émission, RX réception), la plus ancienne et la plus simple : elle relie un microcontrôleur au PC pour le déboguer (le « moniteur série » de l'Arduino), ou deux cartes entre elles, à une vitesse convenue (9 600, 115 200 bauds).", ex:"Serial.println() sur Arduino envoie du texte par UART vers l'ordinateur", etymo:"Sigle de l'anglais universal asynchronous receiver-transmitter."},
  {name:"Jack audio",                en:"Audio jack",                 cat:"connectique", def:"Connecteur audio analogique rond de 3,5 mm (ou 6,35 mm en studio et sur les guitares), à 2, 3 ou 4 contacts (mono, stéréo, stéréo + micro). En voie de disparition sur les téléphones au profit du Bluetooth et de l'USB-C.", ex:"Le casque filaire branché à un ordinateur, une guitare sur un ampli", etymo:"De l'anglais jack, « prise femelle », d'abord dans les standards téléphoniques (1878)."},

  // Makers & Objets connectés
  {name:"Arduino",                   en:"Arduino",                    cat:"makers",      def:"Carte à microcontrôleur open source (2005, Italie) et son environnement de programmation simplifié en C++ : la porte d'entrée de l'électronique pour les débutants, les artistes et les prototypes. On y branche capteurs et actionneurs sur des broches numérotées ; le programme boucle à l'infini.", ex:"Faire clignoter une LED (le « Hello world »), lire un capteur, piloter un moteur", etymo:"Du nom du bar d'Ivrea où ses créateurs se réunissaient, lui-même nommé d'après Arduin, roi d'Italie en 1002."},
  {name:"Raspberry Pi",              en:"Raspberry Pi",               cat:"makers",      def:"Ordinateur complet de la taille d'une carte de crédit (2012, Royaume-Uni), sous Linux, avec ports USB, HDMI, réseau et 40 broches GPIO, pour 40 à 90 €. Serveur domestique, média-center, borne d'arcade, cerveau d'un robot. Contrairement à l'Arduino, il fait tourner un vrai système.", ex:"Un Raspberry Pi 5 comme serveur Home Assistant ou bloqueur de publicités (Pi-hole)", etymo:"Raspberry, « framboise », dans la tradition des ordinateurs à noms de fruits (Apple, Acorn) ; Pi pour Python."},
  {name:"ESP32",                     en:"ESP32",                      cat:"makers",      def:"Microcontrôleur chinois (Espressif) à quelques euros, avec Wi-Fi et Bluetooth intégrés : le cœur de la plupart des objets connectés artisanaux et de beaucoup d'objets commerciaux. Se programme comme un Arduino ou en MicroPython.", ex:"Un capteur de température qui envoie ses mesures en Wi-Fi à Home Assistant", etymo:"ESP, du nom de la société Espressif Systems (Shanghai) ; successeur de l'ESP8266 (2014)."},
  {name:"Capteur",                   cat:"makers", ref:"sciences"},
  {name:"Actionneur",                en:"Actuator",                   cat:"makers",      def:"Composant qui transforme une commande électrique en action physique : moteur, servomoteur, relais, électrovanne, LED, haut-parleur. Le pendant du capteur : celui-ci lit le monde, l'actionneur agit dessus.", ex:"Le servomoteur qui ouvre une trappe, l'électrovanne qui arrose le jardin", etymo:"De actionner, de action, du latin actio."},
  {name:"Servomoteur",               en:"Servo motor",                cat:"makers",      def:"Petit moteur à position commandée : on lui envoie un angle (0 à 180°) par un signal PWM et il s'y place et s'y tient. Bras de robot, direction d'une voiture radiocommandée, volet. Le plus courant, le SG90, coûte deux euros.", ex:"Un servo qui tourne une caméra vers le bruit détecté", etymo:"De servo-, du latin servus, « esclave, qui obéit », et moteur."},
  {name:"Moteur pas à pas",          en:"Stepper motor",              cat:"makers",      def:"Moteur qui tourne par incréments précis (200 pas par tour, souvent), un pas par impulsion, sans capteur de position : il sait exactement où il est. Le moteur des imprimantes 3D, des machines à commande numérique, des scanners.", ex:"Les quatre moteurs NEMA 17 d'une imprimante 3D", etymo:"Pas au sens de « déplacement élémentaire », du latin passus."},
  {name:"Internet des objets",       en:"Internet of Things (IoT)",   cat:"makers",      def:"Ensemble des objets physiques équipés de capteurs et d'une connexion réseau, qui remontent des données et reçoivent des commandes : thermostat, compteur Linky, montre, caméra, machine industrielle. Des dizaines de milliards d'objets, souvent mal sécurisés.", ex:"Un thermostat connecté qui apprend les horaires de la maison", etymo:"Expression de Kevin Ashton (1999), chercheur au MIT travaillant sur la RFID."},
  {name:"Domotique",                 en:"Home automation",            cat:"makers",      def:"Automatisation de la maison : éclairage, chauffage, volets, alarme, arrosage commandés et programmés depuis un téléphone ou par des règles. Fondée sur des protocoles radio (Zigbee, Z-Wave, Thread, Wi-Fi) et une centrale, commerciale ou libre (Home Assistant).", ex:"« Si personne n'est là et qu'il fait nuit, éteindre tout et baisser le chauffage »", etymo:"Mot-valise du latin domus, « maison », et de (informa)tique ou (robo)tique (années 1980)."},
  {name:"Zigbee",                    en:"Zigbee",                     cat:"makers",      def:"Protocole radio basse consommation (2,4 GHz) pour les objets domotiques : ampoules, capteurs, prises, qui forment un réseau maillé où chaque appareil sur secteur relaie les autres. Un capteur à pile tient des années. Nécessite une passerelle. Thread/Matter en est le successeur ouvert.", ex:"Des ampoules Philips Hue et des capteurs Aqara sur une clé Zigbee branchée à Home Assistant", etymo:"De la danse en zigzag des abeilles (zig et bee), qui communiquent entre elles ; Zigbee Alliance (2002)."},
  {name:"LoRa",                      en:"LoRa / LoRaWAN",             cat:"makers",      def:"Radio longue portée (plusieurs kilomètres) et très basse consommation, à faible débit : quelques octets par heure suffisent à un capteur d'humidité en plein champ, un compteur d'eau, un traceur. Le réseau LoRaWAN maille des antennes publiques ou privées.", ex:"Un capteur de niveau de cuve qui émet une fois par heure pendant cinq ans sur une pile", etymo:"De l'anglais long range, « longue portée » ; technologie française (Cycleo, Grenoble, 2009), rachetée par Semtech."},
  {name:"MQTT",                      en:"MQTT",                       cat:"makers",      def:"Protocole de messagerie léger des objets connectés : les appareils publient des messages sur des « sujets » (maison/salon/temperature) auprès d'un serveur central (broker), et ceux qui s'y abonnent les reçoivent. Simple, économe, il tient sur un microcontrôleur.", ex:"Un ESP32 publie sa température toutes les minutes, Home Assistant s'y abonne", etymo:"Sigle de l'anglais message queuing telemetry transport, créé par IBM en 1999 pour des pipelines pétroliers."},
  {name:"Impression 3D",             en:"3D printing",                cat:"makers",      def:"Fabrication d'un objet couche par couche à partir d'un modèle numérique : par dépôt de fil plastique fondu (FDM, la plus courante, quelques centaines d'euros), ou par résine durcie à la lumière (plus précise). Prototypes, pièces de rechange, boîtiers, figurines.", ex:"Imprimer le boîtier d'un montage électronique conçu dans un logiciel de CAO", etymo:"Impression, du latin impressio, « action de presser » ; brevet de la stéréolithographie en 1984 (Charles Hull, et en France Le Méhauté, de Witte et André)."},
  {name:"Robotique",                 cat:"makers", ref:"sciences"},
  {name:"Prototypage électronique",  en:"Electronics prototyping",    cat:"makers",      def:"Réalisation rapide d'une première version fonctionnelle d'un montage pour valider l'idée avant la carte définitive : breadboard, modules tout faits, carte de développement, code d'essai. On itère vite, on jette beaucoup.", ex:"Un capteur, un ESP32 et un écran sur breadboard : le prototype d'une station météo", etymo:"Du grec prôtos, « premier », et tupos, « empreinte, modèle »."},
  {name:"Carte de développement",    en:"Development board",          cat:"makers",      def:"Carte prête à l'emploi construite autour d'un microcontrôleur ou d'un SoC, avec alimentation, port USB de programmation, broches accessibles et parfois capteurs : on code sans rien souder. Arduino, ESP32 DevKit, Raspberry Pi Pico, STM32 Nucleo.", ex:"Un ESP32 DevKit à 5 € branché en USB, prêt à programmer", etymo:"Développement au sens de « mise au point d'un produit »."},
  {name:"Open hardware",             en:"Open-source hardware",       cat:"makers",      def:"Matériel dont les plans (schémas, circuits imprimés, fichiers 3D, firmware) sont publiés sous licence libre : chacun peut les étudier, fabriquer, modifier, vendre. Arduino, RISC-V, l'imprimante RepRap, le projet Prusa en relèvent.", ex:"Les fichiers KiCad d'une carte publiés sur GitHub, reproductibles par n'importe quel fabricant", etymo:"De l'anglais open, « ouvert », et hardware, « quincaillerie », par analogie avec open source."},

  // Périphériques & Affichage
  {name:"Écran",                     en:"Display / monitor",          cat:"peripheriques", def:"Périphérique d'affichage. Se caractérise par sa diagonale (pouces), sa définition (pixels), sa technologie de dalle (LCD IPS, VA, TN, OLED), sa fréquence (60 à 360 Hz), sa luminosité et ses connecteurs. Un écran de bureau, de portable, de téléphone, un téléviseur.", ex:"Un 27 pouces 1440p IPS à 144 Hz pour le jeu et le travail", etymo:"De l'ancien français escran, du moyen néerlandais scherm, « paravent, protection »."},
  {name:"Définition d'écran",        en:"Screen resolution",          cat:"peripheriques", def:"Nombre de pixels affichés, largeur × hauteur : Full HD (1 920 × 1 080), 1440p (2 560 × 1 440), 4K UHD (3 840 × 2 160). La résolution, souvent confondue, est la densité de pixels par pouce (PPI), qui dépend aussi de la taille : la 4K sur 27 pouces est très fine, sur 65 pouces non.", ex:"Un téléphone 6 pouces en 1080p : 400 PPI ; un écran 27 pouces en 1080p : 82 PPI", etymo:"Définition, du latin definitio, « délimitation » : le degré de détail de l'image."},
  {name:"Dalle OLED",                en:"OLED panel",                 cat:"peripheriques", def:"Écran dont chaque pixel émet sa propre lumière (diodes organiques), sans rétroéclairage : noirs parfaits, contraste infini, couleurs vives, finesse, réactivité. Plus cher que le LCD, sensible au marquage (image fixe qui s'imprime). Téléphones haut de gamme, téléviseurs, écrans de jeu.", ex:"Un téléviseur OLED LG, l'écran d'un iPhone Pro, un moniteur QD-OLED", etymo:"Sigle de l'anglais organic light-emitting diode."},
  {name:"Dalle LCD",                 en:"LCD panel",                  cat:"peripheriques", def:"Écran à cristaux liquides, qui filtre la lumière d'un rétroéclairage à LED pixel par pixel. IPS (bonnes couleurs et angles), VA (bon contraste), TN (rapide, terne). Le « QLED » et le « mini-LED » sont des LCD au rétroéclairage amélioré. Économique, sans marquage, noirs grisâtres.", ex:"La plupart des moniteurs d'ordinateur et des téléviseurs d'entrée de gamme", etymo:"Sigle de l'anglais liquid crystal display ; cristaux liquides découverts en 1888 (Reinitzer)."},
  {name:"Taux de rafraîchissement",  en:"Refresh rate",               cat:"peripheriques", def:"Nombre de fois par seconde où l'écran redessine l'image, en hertz. 60 Hz suffit à la bureautique ; 120 Hz rend le défilement plus fluide ; 144 à 360 Hz servent au jeu. Sans intérêt si la carte graphique ne suit pas (les images par seconde du jeu).", ex:"Un écran 144 Hz avec un jeu qui tourne à 140 images par seconde", etymo:"Rafraîchir, au sens informatique de « redessiner », calque de l'anglais refresh."},
  {name:"Pixel",                     en:"Pixel",                      cat:"peripheriques", def:"Plus petit point d'une image numérique ou d'un écran, formé de trois sous-pixels rouge, vert et bleu dont l'intensité compose la couleur. Un écran 4K en compte 8,3 millions ; un capteur photo de 48 mégapixels, 48 millions.", ex:"Un pixel mort reste noir, un pixel bloqué reste allumé", etymo:"De l'anglais picture element, « élément d'image » (1965)."},
  {name:"Clavier mécanique",         en:"Mechanical keyboard",        cat:"peripheriques", def:"Clavier dont chaque touche a son propre interrupteur (switch) à ressort, contre une membrane de caoutchouc commune sur les claviers ordinaires : frappe plus nette, durée de vie de 50 à 100 millions de frappes, choix du toucher (linéaire, tactile, cliquant). Bruyant selon le switch.", ex:"Un clavier à switchs Cherry MX Brown, un 65 % sans pavé numérique", etymo:"Mécanique par opposition à membrane ; switch, de l'anglais « interrupteur »."},
  {name:"Souris",                    en:"Mouse",                      cat:"peripheriques", def:"Périphérique de pointage qui traduit le mouvement de la main en déplacement du curseur, par capteur optique ou laser. Sa sensibilité se mesure en DPI (points par pouce), sa fréquence de rapport en hertz. Filaire ou sans fil (Bluetooth ou récepteur 2,4 GHz).", ex:"Une souris de jeu à 25 000 DPI et 1 000 Hz, une souris ergonomique verticale", etymo:"Calque de l'anglais mouse, pour la forme et le fil-queue ; inventée par Douglas Engelbart en 1964."},
  {name:"Imprimante",                en:"Printer",                    cat:"peripheriques", def:"Périphérique qui reproduit textes et images sur papier. Jet d'encre (couleur, photos, encre chère, buses qui sèchent) ou laser (rapide, texte net, toner économique). Les réservoirs rechargeables ont remplacé les cartouches sur les modèles récents.", ex:"Une laser monochrome pour les documents, une jet d'encre à réservoirs pour les photos", etymo:"D'imprimer, du latin imprimere, « presser sur »."},
  {name:"Webcam",                    en:"Webcam",                     cat:"peripheriques", def:"Caméra numérique connectée à l'ordinateur pour la visioconférence et le streaming, intégrée à l'écran d'un portable ou externe en USB. Sa qualité dépend plus du capteur et de la lumière que de la définition annoncée.", ex:"Une webcam 1080p à 60 images par seconde avec micro intégré", etymo:"De l'anglais web et camera ; la première filmait une cafetière à Cambridge (1991)."},
  {name:"Casque audio",              en:"Headphones",                 cat:"peripheriques", def:"Écouteurs portés sur ou dans les oreilles. Fermés (isolants) ou ouverts (plus naturels), filaires (jack, USB-C) ou sans fil (Bluetooth), avec ou sans réduction de bruit active, qui annule les sons ambiants par contre-bruit. Le codec Bluetooth (SBC, AAC, LDAC) conditionne la qualité sans fil.", ex:"Un casque à réduction de bruit dans le train, des écouteurs intra-auriculaires", etymo:"Casque, de l'espagnol casco, « crâne, casque », de cascar, « briser »."},
  {name:"Station d'accueil",         en:"Docking station",            cat:"peripheriques", def:"Boîtier relié au portable par un seul câble USB-C ou Thunderbolt, qui lui apporte d'un coup écrans, réseau filaire, ports USB, lecteur de cartes et recharge. Le portable devient un poste fixe en un geste.", ex:"Poser le portable, brancher un câble : deux écrans, clavier, souris et Ethernet", etymo:"Accueil, de l'ancien français acueillir, du latin populaire accolligere, « recueillir »."},
];

// ═════════════════════════════════════════════════════════════════════════════
// LEXIQUE LANGUE FRANÇAISE
// ═════════════════════════════════════════════════════════════════════════════

const terms_francais = [
  // Histoire de la langue
  {name:"Latin vulgaire",            en:"Vulgar Latin",               cat:"histoire",    def:"Latin parlé par le peuple, les soldats et les marchands de l'Empire romain, différent du latin littéraire de Cicéron. C'est de lui, et non du latin classique, que viennent le français, l'italien, l'espagnol, le portugais, le roumain : les langues romanes.", ex:"Le latin classique dit equus (cheval), le vulgaire caballus, d'où cheval", etymo:"Vulgaire, du latin vulgaris, « du peuple », de vulgus, « foule »."},
  {name:"Serments de Strasbourg",    en:"Oaths of Strasbourg",        cat:"histoire",    def:"Premier texte écrit en langue romane, ancêtre du français : en 842, deux petits-fils de Charlemagne, Louis le Germanique et Charles le Chauve, se jurent assistance, chacun dans la langue des troupes de l'autre. L'acte de naissance officiel du français.", ex:"« Pro Deo amur et pro christian poblo et nostro commun salvament… »", etymo:"Serment, du latin sacramentum, « engagement sacré »."},
  {name:"Ancien français",           en:"Old French",                 cat:"histoire",    def:"État de la langue du IXe au XIVe siècle : déclinaison à deux cas, orthographe flottante, vocabulaire germanique abondant, dialectes multiples (picard, normand, champenois, francien). La Chanson de Roland, Chrétien de Troyes. Le moyen français (XIVe-XVIe) fait la transition vers le français classique.", ex:"« Li reis Marsilie esteit en Sarraguce » (La Chanson de Roland, vers 1100)", etymo:"Français, de France, du francique Frank, nom du peuple germanique qui conquit la Gaule."},
  {name:"Ordonnance de Villers-Cotterêts", en:"Ordinance of Villers-Cotterêts", cat:"histoire", def:"Texte de François Ier (1539) qui impose le français à la place du latin dans les actes de justice et d'administration. Le plus ancien texte législatif encore en vigueur en France, et le début de l'unification linguistique du royaume.", ex:"L'article 111 exige que les jugements soient « prononcez, enregistrez et delivrez… en langage maternel françois »", etymo:"Villers-Cotterêts, château de l'Aisne où l'ordonnance fut signée ; y siège depuis 2023 la Cité internationale de la langue française."},
  {name:"Académie française",        en:"Académie française",         cat:"histoire",    def:"Institution fondée par Richelieu en 1635 pour fixer la langue : quarante membres élus à vie (les « Immortels ») qui rédigent un dictionnaire (neuf éditions depuis 1694) et donnent des avis sur l'usage. Son autorité est morale, non légale ; elle est souvent en retard sur l'usage.", ex:"L'Académie a mis vingt ans à admettre « courriel », qu'elle recommande contre « e-mail »", etymo:"Académie, du grec Akadêmia, jardin d'Athènes où enseignait Platon."},
  {name:"Francophonie",              en:"Francophonie",               cat:"histoire",    def:"Ensemble des personnes et des pays qui parlent français : 320 millions de locuteurs sur cinq continents, dont la majorité en Afrique, cinquième langue mondiale. L'Organisation internationale de la Francophonie (1970) regroupe 88 États. Le français y prend des formes multiples.", ex:"Kinshasa est la plus grande ville francophone du monde", etymo:"Mot forgé par le géographe Onésime Reclus en 1880, de franco- et du grec phônê, « voix »."},
  {name:"Langues régionales",        en:"Regional languages",         cat:"histoire",    def:"Langues historiques de France autres que le français : breton (celtique), basque (isolée), alsacien et flamand (germaniques), occitan, catalan, corse (romanes), créoles d'outre-mer. Longtemps combattues par l'école, elles sont reconnues comme patrimoine depuis 2008, sans statut officiel.", ex:"Les écoles Diwan en breton, les calandretas en occitan", etymo:"Régional, du latin regio, « contrée »."},
  {name:"Langue d'oïl et langue d'oc", en:"Oïl and Oc languages",    cat:"histoire",    def:"Les deux grandes familles de parlers romans de la France médiévale, nommées d'après leur façon de dire « oui » : oïl au nord (d'où le français, le picard, le normand), oc au sud (l'occitan : provençal, gascon, languedocien). La frontière passe grossièrement de Bordeaux à Grenoble.", ex:"Le francien, parler d'oïl de l'Île-de-France, est devenu le français", etymo:"Oïl, du latin hoc ille, « c'est cela » ; oc, du latin hoc, « cela ». Classification de Dante (vers 1305)."},
  {name:"Emprunt lexical",           en:"Loanword",                   cat:"histoire",    def:"Mot pris à une autre langue et intégré au vocabulaire : à l'arabe (algèbre, sucre, café), à l'italien (banque, balcon), à l'anglais (week-end, sport), aux langues amérindiennes (chocolat, tomate). Le français a emprunté à toutes les langues et prêté à l'anglais un tiers de son vocabulaire.", ex:"« Bougie » vient de la ville algérienne de Béjaïa, « jean » de Gênes", etymo:"Emprunt, de emprunter, du latin populaire impromutuare, « prendre à titre de prêt »."},
  {name:"Anglicisme",                en:"Anglicism",                  cat:"histoire",    def:"Mot, tournure ou sens emprunté à l'anglais : parking, week-end, « faire sens » (calque), « supporter » au sens de soutenir (sens emprunté). Certains sont installés et inévitables, d'autres remplaçables ; la Commission d'enrichissement de la langue propose des équivalents (courriel, mot-dièse, infonuagique).", ex:"« Un mail, un feedback, un deadline » : trois anglicismes dans une phrase de bureau", etymo:"D'anglais, du latin médiéval Anglicus, du nom des Angles, peuple germanique."},
  {name:"Néologisme",                en:"Neologism",                  cat:"histoire",    def:"Mot nouveau, ou sens nouveau d'un mot existant, par création, dérivation, composition ou emprunt. La langue en produit sans cesse ; la plupart meurent, quelques-uns entrent au dictionnaire quand l'usage les a adoptés.", ex:"« Télétravail », « covoiturage », « infox », « écoanxiété »", etymo:"Du grec neos, « nouveau », et logos, « parole »."},
  {name:"Rectifications orthographiques de 1990", en:"1990 spelling reform", cat:"histoire", def:"Propositions du Conseil supérieur de la langue française, approuvées par l'Académie, pour simplifier certaines graphies : accent circonflexe facultatif sur i et u (cout, maitre), soudure de mots composés (portemonnaie), pluriels réguliers (des après-midis), « ognon », « nénufar ». Les deux orthographes sont admises ; l'école les enseigne depuis 2016.", ex:"« Évènement » avec accent grave, « il parait », « chariot » ou « charriot »", etymo:"Rectification, du latin rectificare, « redresser »."},
  {name:"Loi Toubon",                en:"Toubon Law",                 cat:"histoire",    def:"Loi de 1994 qui impose l'usage du français dans la publicité, les contrats de travail, les modes d'emploi, l'enseignement, les colloques en France. Une publicité en anglais doit être traduite. Ne s'applique pas aux marques ni aux conversations privées.", ex:"« Just do it » doit avoir sa traduction en petits caractères sur une affiche en France", etymo:"Du nom de Jacques Toubon, ministre de la Culture ; surnommée « loi Allgood » par ses détracteurs."},
  {name:"Langage",                   cat:"histoire", ref:"connaissance"},

  // Grammaire
  {name:"Nature et fonction",        en:"Word class and syntactic function", cat:"grammaire", def:"La nature d'un mot est sa catégorie, fixe (nom, verbe, adjectif, adverbe, pronom, déterminant, préposition, conjonction, interjection) ; sa fonction est son rôle dans la phrase, variable (sujet, complément, attribut, épithète). Un même nom peut être sujet ici et complément là.", ex:"Dans « Le chat dort », chat est un nom (nature) sujet (fonction)", etymo:"Nature, du latin natura, « caractère propre » ; fonction, du latin functio, « accomplissement »."},
  {name:"Nom",                       en:"Noun",                       cat:"grammaire",   def:"Mot qui désigne un être, une chose, une idée : commun (table, liberté) ou propre (Paris, Marie), avec un genre (masculin, féminin) et un nombre (singulier, pluriel). Il forme avec son déterminant le groupe nominal, cœur de la phrase avec le verbe.", ex:"Une maison, des idées, la Seine, le courage", etymo:"Du latin nomen, « nom, renom »."},
  {name:"Verbe",                     en:"Verb",                       cat:"grammaire",   def:"Mot qui exprime une action, un état ou un devenir, et qui se conjugue : il porte la personne, le nombre, le temps, le mode et la voix. Le seul mot qui varie autant ; le pivot de la phrase.", ex:"Manger, être, devenir, pleuvoir", etymo:"Du latin verbum, « parole, mot » : le mot par excellence."},
  {name:"Adjectif",                  en:"Adjective",                  cat:"grammaire",   def:"Mot qui qualifie un nom et s'accorde avec lui en genre et en nombre : épithète (à côté du nom) ou attribut (relié par un verbe d'état). Sa place change parfois le sens : un grand homme, un homme grand.", ex:"Une maison blanche, des enfants sages, il est heureux", etymo:"Du latin adjectivum (nomen), « (nom) qui s'ajoute »."},
  {name:"Adverbe",                   en:"Adverb",                     cat:"grammaire",   def:"Mot invariable qui modifie un verbe, un adjectif, un autre adverbe ou une phrase entière : manière (doucement), temps (hier), lieu (ici), quantité (très), négation (ne… pas), doute (peut-être). Beaucoup se forment en -ment.", ex:"Il court vite ; elle est très douée ; heureusement, il pleut peu", etymo:"Du latin adverbium, « qui se place près du verbe »."},
  {name:"Pronom",                    en:"Pronoun",                    cat:"grammaire",   def:"Mot qui remplace un nom ou un groupe nominal pour éviter la répétition : personnel (je, le, lui), possessif (le mien), démonstratif (celui-ci), relatif (qui, que, dont), interrogatif (qui ?), indéfini (on, rien).", ex:"« Marie lit le livre que je lui ai prêté » : que et lui sont des pronoms", etymo:"Du latin pronomen, « à la place du nom »."},
  {name:"Déterminant",               en:"Determiner",                 cat:"grammaire",   def:"Petit mot placé devant le nom, qui l'introduit et en indique le genre et le nombre : article défini (le, la, les), indéfini (un, des), partitif (du), possessif (mon), démonstratif (ce), numéral (trois), indéfini (chaque). Un nom commun en a presque toujours un.", ex:"Le livre, une idée, mes amis, cette maison, plusieurs raisons", etymo:"De déterminer, du latin determinare, « fixer les limites »."},
  {name:"Préposition",               en:"Preposition",                cat:"grammaire",   def:"Mot invariable qui relie un mot à son complément et marque le rapport entre eux : à, de, en, dans, pour, par, sur, sous, avec, sans, chez, vers. « De » et « à » sont les plus fréquents du français.", ex:"Le livre de Paul, aller à Paris, partir sans bruit", etymo:"Du latin praepositio, « placé devant »."},
  {name:"Conjonction",               en:"Conjunction",                cat:"grammaire",   def:"Mot invariable qui relie deux éléments. De coordination (mais, ou, et, donc, or, ni, car) entre éléments de même nature ; de subordination (que, quand, si, parce que, bien que…) qui introduit une proposition dépendante.", ex:"« Il pleut, mais je sors parce que j'ai promis »", etymo:"Du latin conjunctio, « liaison »."},
  {name:"Interjection",              en:"Interjection",               cat:"grammaire",   def:"Mot ou son invariable qui exprime une émotion ou une réaction, hors de la construction de la phrase : ah, oh, hélas, zut, chut, bravo, ouf. Souvent suivi d'un point d'exclamation. Les onomatopées (boum, miaou) en sont proches.", ex:"« Aïe ! », « Hélas, il est trop tard », « Chut ! »", etymo:"Du latin interjectio, « action de jeter entre »."},
  {name:"Sujet",                     en:"Subject",                    cat:"grammaire",   def:"Ce dont on parle, ce qui fait l'action ou subit l'état exprimé par le verbe, avec lequel il s'accorde. On le trouve en demandant « qui est-ce qui ? » devant le verbe. Il est parfois inversé (« Vient-il ? », « Ainsi parlait Zarathoustra »).", ex:"« Les enfants jouent » : qui est-ce qui joue ? les enfants", etymo:"Du latin subjectum, « ce qui est placé dessous », calque du grec hupokeimenon."},
  {name:"Complément d'objet",        en:"Object complement",          cat:"grammaire",   def:"Ce sur quoi porte l'action du verbe : direct (COD, sans préposition : « il mange une pomme », quoi ?) ou indirect (COI, avec à ou de : « il parle à Marie », à qui ?). Le COD commande l'accord du participe passé avec avoir quand il précède le verbe.", ex:"« La lettre que j'ai écrite » : que (= la lettre), COD placé avant, d'où « écrite »", etymo:"Complément, du latin complementum, « ce qui complète » ; objet, de objectum, « ce qui est placé devant »."},
  {name:"Complément circonstanciel", en:"Adverbial complement",       cat:"grammaire",   def:"Groupe qui précise les circonstances de l'action : temps (hier), lieu (à Paris), manière (avec soin), cause (à cause de la pluie), but (pour réussir), moyen (en train). Souvent déplaçable ou supprimable, contrairement au complément d'objet.", ex:"« Demain, je pars à Lyon en voiture pour le travail » : quatre compléments circonstanciels", etymo:"Circonstanciel, du latin circumstantia, « ce qui se tient autour »."},
  {name:"Épithète",                  en:"Attributive adjective",      cat:"grammaire",   def:"Fonction de l'adjectif directement rattaché au nom, sans verbe : « une maison blanche ». Par opposition à l'attribut, relié par un verbe d'état (« la maison est blanche »). L'épithète homérique est un qualificatif fixe (« Achille aux pieds légers »).", ex:"Un vieux chêne, une idée lumineuse, la Bretagne profonde", etymo:"Du grec epitheton, « ajouté »."},
  {name:"Attribut",                  en:"Predicative complement",     cat:"grammaire",   def:"Ce qui est dit du sujet (ou de l'objet) par l'intermédiaire d'un verbe d'état : être, sembler, devenir, paraître, rester, demeurer. « Elle est médecin », « il semble fatigué », « je le trouve beau ». S'accorde avec le sujet.", ex:"« Les jours deviennent courts » : courts, attribut du sujet", etymo:"Du latin attributum, « ce qui est attribué »."},
  {name:"Apposition",                en:"Apposition",                 cat:"grammaire",   def:"Mot ou groupe placé à côté d'un nom pour le préciser, séparé par une virgule ou juxtaposé : « Paris, capitale de la France » ; « le roi Louis XIV » ; « Pierre, fatigué, s'assit ». Il désigne la même réalité que le nom.", ex:"« Victor Hugo, poète et romancier, est mort en 1885 »", etymo:"Du latin appositio, « action de placer auprès »."},
  {name:"Proposition",               en:"Clause",                     cat:"grammaire",   def:"Unité de phrase organisée autour d'un verbe conjugué. Indépendante (se suffit), principale (commande une autre), subordonnée (dépend d'une principale : relative avec qui/que/dont, complétive avec que, circonstancielle avec quand/si/parce que). Une phrase compte autant de propositions que de verbes conjugués.", ex:"« Je pense [principale] qu'il viendra [subordonnée complétive] quand il pourra [subordonnée circonstancielle] »", etymo:"Du latin propositio, « énoncé, thème »."},
  {name:"Phrase",                    en:"Sentence",                   cat:"grammaire",   def:"Suite de mots qui a un sens complet, commence par une majuscule et finit par un point. Simple (une proposition) ou complexe (plusieurs) ; déclarative, interrogative, exclamative ou impérative ; à la forme affirmative ou négative. Une phrase sans verbe est nominale (« Quelle journée ! »).", ex:"« Il pleut. » est une phrase ; « Parce qu'il pleut » n'en est pas une", etymo:"Du grec phrasis, « expression, élocution », de phrazein, « expliquer »."},
  {name:"Accord",                    en:"Agreement",                  cat:"grammaire",   def:"Variation d'un mot pour s'harmoniser avec un autre : l'adjectif et le déterminant avec le nom (genre et nombre), le verbe avec son sujet (personne et nombre), le participe passé selon des règles particulières. La principale source de fautes du français écrit, car la plupart des accords ne s'entendent pas.", ex:"« Les petites filles sont parties » : quatre accords, dont trois muets", etymo:"De accorder, du latin populaire accordare, de cor, « cœur »."},
  {name:"Genre grammatical",         en:"Grammatical gender",         cat:"grammaire",   def:"Classement des noms en masculin et féminin, sans lien nécessaire avec le sexe (une sentinelle, un mannequin) ni avec les autres langues (le soleil est féminin en allemand). Le français n'a pas de neutre. Le genre commande l'accord des déterminants, adjectifs et participes.", ex:"Un après-midi ou une après-midi (les deux sont admis), une oasis, un pétale", etymo:"Genre, du latin genus, « origine, espèce »."},
  {name:"Voix active et passive",    en:"Active and passive voice",   cat:"grammaire",   def:"À la voix active, le sujet fait l'action (« le chat mange la souris ») ; à la voix passive, il la subit (« la souris est mangée par le chat »), avec l'auxiliaire être et un complément d'agent. Le passif met en avant l'objet, ou masque l'agent (« des erreurs ont été commises »).", ex:"« La loi a été votée » : par qui ? le passif permet de ne pas le dire", etymo:"Voix, du latin vox, au sens grammatical de « forme du verbe »."},

  // Conjugaison
  {name:"Mode verbal",               en:"Grammatical mood",           cat:"conjugaison", def:"Manière dont le verbe présente l'action : comme réelle (indicatif), souhaitée ou incertaine (subjonctif), soumise à condition (conditionnel), ordonnée (impératif), ou sans personne (infinitif, participe, gérondif). Chaque mode a ses temps.", ex:"« Il vient » (indicatif), « qu'il vienne » (subjonctif), « viens ! » (impératif)", etymo:"Du latin modus, « manière, mesure »."},
  {name:"Temps verbal",              en:"Tense",                      cat:"conjugaison", def:"Forme du verbe qui situe l'action dans le temps (passé, présent, futur) et en indique l'aspect (accompli ou en cours). Temps simples (présent, imparfait, passé simple, futur) et temps composés avec un auxiliaire (passé composé, plus-que-parfait, futur antérieur).", ex:"Je mange (présent), je mangeais, je mangeai, j'ai mangé, je mangerai", etymo:"Du latin tempus, « temps, durée »."},
  {name:"Indicatif",                 en:"Indicative",                 cat:"conjugaison", def:"Mode du réel et de l'affirmation, le plus employé : il présente l'action comme un fait. Huit temps : présent, imparfait, passé simple, futur simple, et leurs composés (passé composé, plus-que-parfait, passé antérieur, futur antérieur).", ex:"« Il pleut, il a plu, il pleuvra »", etymo:"Du latin indicativus, « qui indique »."},
  {name:"Subjonctif",                en:"Subjunctive",                cat:"conjugaison", def:"Mode du possible, du souhait, du doute, de l'ordre indirect et du sentiment, presque toujours dans une subordonnée introduite par que : « je veux qu'il vienne », « bien qu'il pleuve », « avant que tu partes ». Le présent et le passé sont vivants ; l'imparfait (« qu'il vînt ») ne survit qu'à l'écrit soutenu.", ex:"« Il faut que tu saches » (et non « que tu sais »)", etymo:"Du latin subjunctivus, « qui sert à subordonner »."},
  {name:"Conditionnel",              en:"Conditional",                cat:"conjugaison", def:"Forme du verbe qui exprime une action soumise à une condition (« s'il pleuvait, je resterais »), une hypothèse, un souhait poli (« je voudrais »), une information non confirmée (« le ministre démissionnerait »), ou un futur dans le passé (« il a dit qu'il viendrait »). Jamais après si.", ex:"« Si j'avais su, je ne serais pas venu » — et non « si j'aurais su »", etymo:"Du latin conditio, « condition, situation »."},
  {name:"Impératif",                 en:"Imperative",                 cat:"conjugaison", def:"Mode de l'ordre, du conseil, de la prière, sans sujet exprimé, à trois personnes seulement : tu, nous, vous. « Mange ! », « allons-y », « veuillez patienter ». Pas de s à la deuxième personne des verbes en -er (« mange », mais « manges-en »).", ex:"« Va » mais « vas-y » ; « donne-le-moi »", etymo:"Du latin imperativus, « qui commande »."},
  {name:"Infinitif",                 en:"Infinitive",                 cat:"conjugaison", def:"Forme du verbe qui n'est pas conjuguée, celle du dictionnaire : manger, finir, prendre, avoir. Il peut jouer le rôle d'un nom (« lire est un plaisir ») et suit les verbes de modalité (« je veux partir »). Ne pas le confondre avec le participe passé en -é : « il va manger » / « il a mangé ».", ex:"Pour savoir si on écrit -er ou -é, remplacer par « prendre » ou « pris »", etymo:"Du latin infinitivus, « indéfini », car il ne porte ni personne ni nombre."},
  {name:"Participe passé",           en:"Past participle",            cat:"conjugaison", def:"Forme du verbe employée dans les temps composés (j'ai fini) et le passif (il est pris), ou comme adjectif (une porte fermée). Mangé, fini, pris, ouvert, mis, dû. Son accord est le casse-tête du français : avec être, il s'accorde avec le sujet ; avec avoir, avec le COD s'il précède.", ex:"« Elles sont parties », « les pommes qu'il a mangées », « il a mangé des pommes »", etymo:"Participe, du latin participium, « qui participe » à la fois du verbe et de l'adjectif."},
  {name:"Gérondif",                  en:"Gerund (en + present participle)", cat:"conjugaison", def:"Forme en « en + participe présent » qui exprime une action simultanée, la manière ou le moyen : « il lit en mangeant », « on apprend en faisant ». Son sujet est celui du verbe principal, d'où les fautes classiques (« en attendant votre réponse, veuillez agréer » est correct ; « en sortant, la pluie tombait » ne l'est pas).", ex:"« C'est en forgeant qu'on devient forgeron »", etymo:"Du latin gerundium, de gerere, « porter, accomplir »."},
  {name:"Auxiliaire",                en:"Auxiliary verb",             cat:"conjugaison", def:"Verbe qui sert à conjuguer les autres aux temps composés : avoir (la plupart des verbes) ou être (verbes de mouvement et de changement d'état comme aller, venir, naître, mourir, et tous les verbes pronominaux). Certains prennent les deux avec un sens différent : « il a sorti la voiture », « il est sorti ».", ex:"« J'ai mangé », « je suis venu », « je me suis lavé »", etymo:"Du latin auxiliaris, « qui aide »."},
  {name:"Passé composé",             en:"Passé composé / present perfect", cat:"conjugaison", def:"Temps du passé formé de l'auxiliaire au présent et du participe passé : « j'ai vu », « elle est partie ». Le temps du récit à l'oral et dans l'écrit courant, pour une action achevée ; il a remplacé le passé simple dans la langue parlée.", ex:"« Hier, j'ai pris le train et je suis arrivé à midi »", etymo:"Composé car formé de deux mots, par opposition aux temps simples."},
  {name:"Imparfait",                 en:"Imperfect",                  cat:"conjugaison", def:"Temps du passé qui présente l'action en cours, répétée ou de durée indéfinie, sans en marquer la fin : description, habitude, arrière-plan du récit. « Il pleuvait, je lisais » ; l'action ponctuelle qui surgit est au passé composé ou au passé simple.", ex:"« Il faisait nuit quand le téléphone a sonné »", etymo:"Du latin imperfectus, « inachevé »."},
  {name:"Passé simple",              en:"Simple past / preterite",    cat:"conjugaison", def:"Temps du passé qui présente une action achevée, ponctuelle, coupée du présent : le temps du récit écrit, des romans et des contes. Disparu de l'oral, il survit à la troisième personne (« il vint », « ils allèrent ») ; les premières personnes (« nous vînmes ») semblent aujourd'hui pédantes.", ex:"« Il ouvrit la porte, entra et s'assit »", etymo:"Simple par opposition au passé composé ; on l'appelait aussi passé défini."},
  {name:"Plus-que-parfait",          en:"Pluperfect",                 cat:"conjugaison", def:"Temps composé du passé (auxiliaire à l'imparfait + participe passé) qui exprime une action antérieure à une autre action passée : « quand il est arrivé, j'avais fini ». Le passé du passé.", ex:"« Elle avait déjà lu le livre que je lui ai offert »", etymo:"Du latin plus quam perfectum, « plus qu'achevé »."},
  {name:"Futur",                     en:"Future tense",               cat:"conjugaison", def:"Temps de l'action à venir : futur simple (« je partirai »), futur proche avec aller (« je vais partir », plus fréquent à l'oral), futur antérieur pour une action achevée avant une autre (« quand j'aurai fini »). Après « si », c'est le présent : « si tu viens, je serai là ».", ex:"« Demain, il fera beau » ; « je te dirai quand j'aurai décidé »", etymo:"Du latin futurus, participe futur de esse, « être »."},
  {name:"Concordance des temps",     en:"Sequence of tenses",         cat:"conjugaison", def:"Règle qui ajuste le temps de la subordonnée à celui de la principale. Principale au présent : « je pense qu'il vient / qu'il viendra ». Principale au passé : « je pensais qu'il venait / qu'il viendrait ». Au subjonctif, l'imparfait (« qu'il vînt ») a cédé la place au présent (« qu'il vienne ») dans l'usage courant.", ex:"« Il a dit qu'il viendrait » (et non « qu'il viendra », sauf si c'est encore à venir)", etymo:"Concordance, du latin concordare, « être d'accord »."},
  {name:"Groupes de verbes",         en:"Verb groups (conjugation classes)", cat:"conjugaison", def:"Classement scolaire des verbes selon leur conjugaison. Premier groupe : infinitif en -er (chanter), 90 % des verbes, tous réguliers sauf aller. Deuxième : en -ir avec participe présent en -issant (finir, finissant). Troisième : tous les autres, irréguliers (prendre, voir, venir, dormir).", ex:"« Partir » est du troisième groupe (partant), « finir » du deuxième (finissant)", etymo:"Groupe, de l'italien gruppo, « nœud, assemblage »."},
  {name:"Verbe pronominal",          en:"Reflexive / pronominal verb", cat:"conjugaison", def:"Verbe conjugué avec un pronom de la même personne que le sujet : se laver, se souvenir, s'enfuir, se parler. Réfléchi (le sujet agit sur lui-même), réciproque (l'un l'autre), ou essentiellement pronominal (s'évanouir n'existe pas sans se). Toujours avec être aux temps composés.", ex:"« Ils se sont parlé » (parler à quelqu'un : pas d'accord), « ils se sont vus » (accord)", etymo:"Pronominal, de pronom."},
  {name:"Accord du participe passé", en:"Past participle agreement",  cat:"conjugaison", def:"La règle la plus redoutée du français. Avec être : accord avec le sujet (« elles sont venues »). Avec avoir : accord avec le complément d'objet direct seulement s'il est placé avant le verbe (« les fleurs que j'ai cueillies », mais « j'ai cueilli les fleurs »). Jamais d'accord avec en, ni devant un infinitif quand le COD n'en fait pas l'action (« les airs que j'ai entendu jouer »).", ex:"« La lettre qu'elle a écrite » / « elle a écrit la lettre » / « elle s'est lavé les mains »", etymo:"Règle fixée par Clément Marot au XVIe siècle, sur le modèle de l'italien."},

  // Orthographe & Ponctuation
  {name:"Orthographe",               en:"Spelling",                   cat:"orthographe", def:"Manière correcte d'écrire les mots. Lexicale (la forme de chaque mot : « pharmacie », « oignon ») et grammaticale (les accords). Le français en a une des plus difficiles, fixée au XVIIe siècle sur des bases étymologiques souvent fantaisistes, avec des lettres muettes partout.", ex:"« Doigt » garde un g du latin digitus qu'on ne prononce pas", etymo:"Du grec orthos, « droit, correct », et graphein, « écrire »."},
  {name:"Homophone",                 en:"Homophone",                  cat:"orthographe", def:"Mots qui se prononcent de la même façon mais s'écrivent différemment : a/à, ou/où, ce/se, ces/ses/c'est/s'est, sans/cent/sang, vert/vers/verre/ver. La première source de fautes en français, car l'oreille ne distingue rien.", ex:"« Il a mangé à midi », « ou bien, où ça ? »", etymo:"Du grec homos, « même », et phônê, « son »."},
  {name:"Accents",                   en:"Accents (diacritics)",       cat:"orthographe", def:"Signes placés sur une voyelle. L'aigu (é) marque le son fermé ; le grave (è, à, ù) le son ouvert ou distingue des homophones (a/à, ou/où) ; le circonflexe (â, ê, î, ô, û) rappelle souvent un s disparu (forêt, forestier ; hôpital, hospitalier) ou distingue (sur/sûr, du/dû). Les majuscules prennent l'accent : État, À bientôt.", ex:"« Un élève », « un père », « une fête » (feste en ancien français)", etymo:"Accent, du latin accentus, « intonation », calque du grec prosôdia."},
  {name:"Cédille",                   en:"Cedilla",                    cat:"orthographe", def:"Petit crochet sous le c (ç) qui lui donne le son [s] devant a, o, u, là où il se prononcerait [k] : façade, garçon, reçu. Inutile devant e et i, où le c est déjà doux. Le français est la langue qui l'a imposée, par l'imprimeur Geoffroy Tory (1529).", ex:"« Ça », « français », « leçon » ; mais « ceci », « merci »", etymo:"De l'espagnol cedilla, « petit z », car le signe vient d'un z minuscule placé sous le c."},
  {name:"Tréma",                     en:"Diaeresis",                  cat:"orthographe", def:"Deux points sur une voyelle (ï, ë, ü) qui indiquent qu'elle se prononce séparément de la précédente : naïf (na-if, et non « nèf »), maïs, Noël, ambiguë (ou ambigüe depuis 1990), aiguë. Il signale une voyelle qui ne fait pas diphtongue.", ex:"« Haïr » se prononce en deux syllabes grâce au tréma", etymo:"Du grec trêma, « trou, point sur un dé »."},
  {name:"Trait d'union",             en:"Hyphen",                     cat:"orthographe", def:"Petit trait qui soude des mots en un seul (arc-en-ciel, chef-d'œuvre, porte-monnaie), relie le verbe à son pronom inversé (dit-il, va-t-il), s'insère dans les nombres (vingt-trois, et tous les nombres depuis 1990), et coupe un mot en fin de ligne. Plus court que le tiret.", ex:"« Peut-être » (adverbe) mais « il peut être là »", etymo:"Union, du latin unio, « unité »."},
  {name:"Élision",                   en:"Elision",                    cat:"orthographe", def:"Suppression de la voyelle finale d'un mot devant une voyelle ou un h muet, marquée par l'apostrophe : le arbre → l'arbre, je ai → j'ai, si il → s'il, que elle → qu'elle. Obligatoire avec le, la, je, me, te, se, ce, de, ne, que, si (devant il). Pas devant un h aspiré : « le héros ».", ex:"« L'homme » (h muet) mais « le hibou » (h aspiré)", etymo:"Du latin elisio, « action d'écraser, de retrancher »."},
  {name:"Liaison phonétique",        en:"Liaison",                    cat:"orthographe", def:"Prononciation de la consonne finale muette d'un mot devant la voyelle du mot suivant : « les‿enfants » [lezãfã], « un petit‿homme », « vous‿avez ». Obligatoire dans certains cas, interdite dans d'autres (jamais après et, ni devant un h aspiré), facultative ailleurs, où elle marque le registre soutenu.", ex:"« Les haricots » sans liaison (h aspiré) ; « des‿amis » avec", etymo:"De lier, du latin ligare."},
  {name:"Ponctuation",               en:"Punctuation",                cat:"orthographe", def:"Signes qui organisent le texte écrit et en marquent les pauses, l'intonation et la logique : point, virgule, point-virgule, deux-points, points de suspension, d'interrogation, d'exclamation, parenthèses, guillemets, tirets. En français, les signes doubles (; : ? ! « ») prennent une espace avant et après.", ex:"« Il vient ? » et non « Il vient? » ; l'espace avant le point d'interrogation est française", etymo:"Du latin punctum, « point, piqûre »."},
  {name:"Virgule",                   en:"Comma",                      cat:"orthographe", def:"Le signe de la petite pause, qui sépare les éléments d'une énumération, isole une apposition ou une incise, détache un complément déplacé. Jamais entre le sujet et le verbe. Elle change le sens : « les élèves, qui étaient fatigués, sont sortis » (tous) / « les élèves qui étaient fatigués sont sortis » (certains).", ex:"« On va manger, les enfants » et « On va manger les enfants »", etymo:"Du latin virgula, « petite verge, petit trait »."},
  {name:"Point-virgule",             en:"Semicolon",                  cat:"orthographe", def:"Pause plus forte que la virgule, plus faible que le point : il sépare deux propositions liées par le sens mais grammaticalement complètes, ou les éléments longs d'une énumération. En recul, remplacé par le point ; le signe de l'écrivain soigneux.", ex:"« Il pleuvait ; personne ne sortit »", etymo:"Point et virgule : le signe combine les deux."},
  {name:"Deux-points",               en:"Colon",                      cat:"orthographe", def:"Signe qui annonce ce qui suit : une explication, une cause, une conséquence, une énumération ou une citation. Ce qui vient après les deux-points éclaire ce qui vient avant. Pas de majuscule ensuite, sauf citation ou nom propre. Un seul par phrase.", ex:"« Il n'est pas venu : il était malade »", etymo:"Le signe se compose de deux points superposés."},
  {name:"Guillemets",                en:"Quotation marks",            cat:"orthographe", def:"Signes qui encadrent une citation, un dialogue, un titre d'article, un mot employé avec distance. Les guillemets français sont des chevrons « » avec espaces insécables intérieures ; les anglais “ ” servent pour une citation dans la citation. Les guillemets droits \" \" sont ceux du clavier, non de la typographie.", ex:"« Il m'a dit : “je reviens” et il n'est jamais revenu »", etymo:"Diminutif de Guillaume, prénom supposé de l'imprimeur qui les aurait inventés (XVIe siècle)."},
  {name:"Tiret",                     en:"Dash",                       cat:"orthographe", def:"Trait plus long que le trait d'union. Le tiret cadratin (—) ouvre les répliques d'un dialogue et encadre une incise ; le demi-cadratin (–) sert d'incise plus discrète, de puce et d'intervalle (1914–1918). Ne pas le confondre avec le trait d'union (-), plus court, qui soude.", ex:"« — Tu viens ? — Non. » ; « la réunion – enfin – a commencé »", etymo:"De tirer, au sens de « tracer un trait »."},
  {name:"Espace insécable",          en:"Non-breaking space",         cat:"orthographe", def:"Espace qui empêche le passage à la ligne entre deux éléments qui doivent rester ensemble : avant ; : ? ! et », après «, entre un nombre et son unité (10 km), dans les nombres (1 000), avant % et €. En typographie française, « espace » est féminin.", ex:"Sans elle, un point d'interrogation peut se retrouver seul en début de ligne", etymo:"Insécable, du latin insecabilis, « qui ne peut être coupé »."},
  {name:"Majuscule",                 en:"Capital letter",             cat:"orthographe", def:"Lettre grande initiale, en début de phrase et pour les noms propres. En français, moins qu'en anglais : les jours, les mois, les langues et les adjectifs de nationalité restent en minuscule (« un lundi de janvier, un écrivain français »), mais les peuples en prennent une (« les Français »). L'État, l'Église (institution) ; l'état, l'église (bâtiment).", ex:"« Le président de la République » : majuscule à République seulement", etymo:"Du latin majusculus, « un peu plus grand »."},
  {name:"Sigle et acronyme",         en:"Initialism and acronym",     cat:"orthographe", def:"Le sigle est une suite d'initiales prononcées lettre par lettre (SNCF, TGV, PDG) ; l'acronyme, un sigle prononcé comme un mot (OTAN, UNESCO, ovni, sida, laser). Un acronyme devenu nom commun s'écrit en minuscules et prend le pluriel (des radars). Sans points ni accents : CEE, pas C.E.E.", ex:"« Un CD » (sigle), « la NASA » (acronyme), « un cégep » (acronyme lexicalisé)", etymo:"Sigle, du latin sigla, « signes abréviatifs » ; acronyme, du grec akros, « extrémité », et onoma, « nom »."},
  {name:"Abréviation",               en:"Abbreviation",               cat:"orthographe", def:"Réduction d'un mot à quelques lettres. Par retranchement final avec un point (« p. », « etc. », « M. » pour Monsieur) ; par contraction sans point si la dernière lettre est conservée (« Mme », « Dr », « bd », « nos »). Les unités de mesure ne prennent ni point ni pluriel (10 km, 3 h, 5 kg).", ex:"« M. » (Monsieur) mais « Mr » est anglais ; « Mme », « Mlle », « MM. »", etymo:"Du latin abbreviatio, de brevis, « court »."},

  // Vocabulaire & Sens
  {name:"Étymologie",                en:"Etymology",                  cat:"vocabulaire", def:"Étude de l'origine des mots : leur langue source (latin, grec, francique, arabe…), leur forme ancienne, leurs changements de sens. Elle explique l'orthographe (le p de « sept », de septem), les familles de mots et les faux amis. Le français vient à 80 % du latin, souvent par des chemins tortueux.", ex:"« Travail » vient de tripalium, instrument de torture à trois pieux", etymo:"Du grec etumos, « vrai », et logos, « discours » : le « sens vrai » des mots."},
  {name:"Synonyme",                  en:"Synonym",                    cat:"vocabulaire", def:"Mots de sens proche : maison, demeure, logis, habitation, pavillon. Jamais parfaitement équivalents : ils diffèrent par la nuance, le registre, la connotation ou l'emploi. Le choix du bon synonyme est le cœur du style ; le dictionnaire des synonymes donne des candidats, pas la réponse.", ex:"« Peur, crainte, frayeur, terreur, effroi, angoisse » : six intensités", etymo:"Du grec sun, « avec », et onoma, « nom »."},
  {name:"Antonyme",                  en:"Antonym",                    cat:"vocabulaire", def:"Mot de sens contraire : grand/petit, chaud/froid, monter/descendre. Formé parfois par un préfixe (heureux/malheureux, possible/impossible, faire/défaire). Un mot polysémique a plusieurs antonymes selon le sens : le contraire de « doux » est « dur », « amer » ou « violent ».", ex:"« Clair » a pour contraires « sombre » (lumière) et « confus » (idée)", etymo:"Du grec anti, « contre », et onoma, « nom »."},
  {name:"Homonyme",                  en:"Homonym",                    cat:"vocabulaire", def:"Mots de même forme et de sens différents. Homophones s'ils se prononcent pareil (vert/verre/vers), homographes s'ils s'écrivent pareil (le fils / les fils de laine ; il est content / le contenu). Source de calembours et d'ambiguïtés.", ex:"« Louer » (donner en location) et « louer » (faire l'éloge) sont deux mots d'origine différente", etymo:"Du grec homos, « même », et onoma, « nom »."},
  {name:"Paronyme",                  en:"Paronym",                    cat:"vocabulaire", def:"Mots proches par la forme mais différents par le sens, qu'on confond : éminent/imminent, conjecture/conjoncture, infecter/infester, allocation/allocution, effraction/infraction, collision/collusion. Le piège des dictées et des discours officiels.", ex:"« Un danger imminent », « un savant éminent »", etymo:"Du grec para, « à côté », et onoma, « nom »."},
  {name:"Polysémie",                 en:"Polysemy",                   cat:"vocabulaire", def:"Propriété d'un mot qui a plusieurs sens liés entre eux : « bureau » (meuble, pièce, service, direction), « pied » (du corps, de la table, de la montagne, du vers). La plupart des mots courants sont polysémiques ; c'est le contexte qui tranche.", ex:"« Carte » : de crédit, routière, à jouer, du restaurant, graphique", etymo:"Du grec polus, « nombreux », et sêma, « signe »."},
  {name:"Champ lexical",             en:"Lexical field",              cat:"vocabulaire", def:"Ensemble des mots d'un texte qui se rapportent à un même thème : le champ lexical de la mer (vague, écume, marée, port, large…), de la guerre, de la peur. Le repérer révèle ce dont un texte parle vraiment, au-delà de son sujet apparent.", ex:"Un poème d'amour saturé du champ lexical de la maladie dit quelque chose de cet amour", etymo:"Champ au sens de « domaine » ; lexical, du grec lexis, « mot »."},
  {name:"Connotation et dénotation", en:"Connotation and denotation", cat:"vocabulaire", def:"La dénotation est le sens objectif d'un mot, celui du dictionnaire ; la connotation, ce qu'il évoque en plus : valeur affective, sociale, culturelle. « Flic », « policier », « agent de police » dénotent la même personne avec des connotations opposées. Le vocabulaire n'est jamais neutre.", ex:"« Maigre » et « svelte » dénotent la même chose ; l'un est un reproche, l'autre un compliment", etymo:"Du latin notare, « marquer » : denotare, « désigner » ; connotare, « marquer en plus »."},
  {name:"Registre de langue",        en:"Language register",          cat:"vocabulaire", def:"Niveau de langue adapté à la situation. Familier (bouffer, bagnole, « j'sais pas ») entre proches ; courant (manger, voiture, « je ne sais pas ») dans la vie quotidienne ; soutenu (se sustenter, automobile, « je l'ignore ») à l'écrit formel et dans les discours. Le vocabulaire, la syntaxe et la prononciation changent ensemble.", ex:"« Il s'est cassé » / « il est parti » / « il s'est retiré »", etymo:"Registre au sens musical, « étendue de la voix », du latin médiéval registrum."},
  {name:"Argot",                     en:"Slang",                      cat:"vocabulaire", def:"Vocabulaire propre à un groupe social, d'abord pour ne pas être compris des autres (malfaiteurs, soldats, écoliers, métiers), devenu marqueur d'appartenance. L'argot parisien du XIXe siècle (Vidocq, Hugo, Bruant) a fourni au français courant « boulot », « fric », « flic », « mec ».", ex:"« Louchébem », l'argot des bouchers ; « ripou », verlan de pourri", etymo:"Origine obscure ; d'abord « corporation des mendiants » (XVIIe siècle), puis leur langage."},
  {name:"Verlan",                    en:"Verlan (back slang)",        cat:"vocabulaire", def:"Argot qui inverse les syllabes des mots : femme → meuf, louche → chelou, fête → teuf, arabe → beur → rebeu (verlan de verlan). Né dans les banlieues des années 1970-1980, il a fait entrer plusieurs mots dans le dictionnaire.", ex:"« Ouf » (fou), « relou » (lourd), « zarbi » (bizarre), « cimer » (merci)", etymo:"Verlan est lui-même le verlan de « l'envers »."},
  {name:"Jargon",                    en:"Jargon",                     cat:"vocabulaire", def:"Vocabulaire technique d'une profession ou d'un domaine, précis pour les initiés, opaque pour les autres : jargon médical, juridique, informatique, administratif. Légitime entre spécialistes, il devient un défaut quand il s'adresse au public ou sert à impressionner.", ex:"« Nous allons benchmarker les KPI du Q3 en mode agile »", etymo:"De l'ancien français jargon, « gazouillis des oiseaux », d'origine onomatopéique."},
  {name:"Mot-valise",                en:"Portmanteau word",           cat:"vocabulaire", def:"Mot formé de la fusion de deux autres, dont l'un perd sa fin et l'autre son début : franglais (français + anglais), courriel (courrier + électronique), alicament, infox (information + intoxication), adulescent, modem, brunch. Un procédé favori des publicitaires et de Lewis Carroll.", ex:"« Bureautique », « vélorution », « clavardage » (clavier + bavardage)", etymo:"Calque de l'anglais portmanteau word, de Lewis Carroll (1871), qui compare le mot à une valise à deux compartiments."},
  {name:"Expression idiomatique",    en:"Idiom",                      cat:"vocabulaire", def:"Tournure figée propre à une langue, dont le sens ne se déduit pas des mots : « poser un lapin », « tomber dans les pommes », « avoir le cafard », « prendre la mouche », « coûter les yeux de la tête ». Intraduisible mot à mot ; chaque langue a les siennes.", ex:"« Il pleut des cordes » se dit « it's raining cats and dogs » en anglais", etymo:"Idiomatique, du grec idiôma, « particularité propre »."},
  {name:"Faux ami",                  en:"False friend",               cat:"vocabulaire", def:"Mot d'une langue étrangère qui ressemble à un mot français mais n'a pas le même sens. En anglais : actually (en fait, pas actuellement), library (bibliothèque, pas librairie), eventually (finalement), sensible (raisonnable), deception (tromperie). Le piège classique de la traduction.", ex:"« To attend a meeting » : assister, non « attendre »", etymo:"Expression de Maxime Kœssler et Jules Derocquigny, Les Faux Amis (1928)."},
  {name:"Barbarisme",                en:"Barbarism (malformed word)", cat:"vocabulaire", def:"Faute qui consiste à employer un mot déformé ou inexistant : « aréoport » pour aéroport, « infractus » pour infarctus, « dilemne » pour dilemme, « il faut qu'il croive », « nominer » pour nommer. À distinguer du solécisme, faute de construction.", ex:"« Un rénumération » pour rémunération, « pécunier » pour pécuniaire", etymo:"Du grec barbarismos, « façon de parler des barbares », c'est-à-dire des étrangers."},
  {name:"Solécisme",                 en:"Solecism",                   cat:"vocabulaire", def:"Faute de syntaxe ou de construction, avec des mots corrects : « je vais au coiffeur » (chez), « si j'aurais su », « pallier à un problème » (pallier un problème), « malgré que », « la personne que je vous ai parlé » (dont). Le barbarisme est une faute sur le mot, le solécisme sur la phrase.", ex:"« Se rappeler de quelque chose » est un solécisme (on se rappelle quelque chose)", etymo:"Du grec soloikismos, du nom de Soles, colonie de Cilicie dont les habitants parlaient un grec fautif."},
  {name:"Pléonasme",                 en:"Pleonasm",                   cat:"vocabulaire", def:"Répétition inutile d'une idée dans des mots différents : « monter en haut », « prévoir à l'avance », « au jour d'aujourd'hui », « voire même », « applaudir des deux mains », « un petit nain ». Défaut le plus souvent, mais figure d'insistance chez les écrivains (« je l'ai vu de mes yeux vu »).", ex:"« Un tri sélectif », « une opportunité à saisir », « un hasard imprévu »", etymo:"Du grec pleonasmos, « surabondance »."},
  {name:"Doublet lexical",           en:"Etymological doublet",       cat:"vocabulaire", def:"Deux mots issus du même mot latin, l'un par évolution populaire ancienne, l'autre par emprunt savant tardif : hôtel/hôpital (hospitale), frêle/fragile, écouter/ausculter, chose/cause, raide/rigide, nager/naviguer, chaire/chaise. Le mot populaire est usé, le mot savant reste proche du latin.", ex:"« Entier » et « intègre » viennent tous deux de integer", etymo:"Doublet, diminutif de double, du latin duplus."},
  {name:"Dictionnaire de langue",    en:"Language dictionary",        cat:"vocabulaire", def:"Ouvrage qui recense les mots d'une langue avec leur sens, leur prononciation, leur étymologie, leurs emplois. Le Littré (1872), le Robert et le Larousse (annuels), le Trésor de la langue française (gratuit en ligne, le plus complet), celui de l'Académie. Il décrit l'usage plus qu'il ne le prescrit.", ex:"Le Petit Robert entre 150 mots nouveaux chaque année", etymo:"Du latin médiéval dictionarium, de dictio, « action de dire, mot »."},
  {name:"Traduction",                cat:"vocabulaire", ref:"connaissance"},

  // Figures de style
  {name:"Figure de style",           en:"Figure of speech",           cat:"figures_style", def:"Procédé d'expression qui s'écarte de l'usage ordinaire pour produire un effet : image (métaphore, comparaison), insistance (anaphore, hyperbole), atténuation (litote, euphémisme), opposition (antithèse, oxymore), son (allitération). Présentes dans la poésie comme dans la publicité et la conversation.", ex:"« Je meurs de faim » est une hyperbole quotidienne", etymo:"Figure, du latin figura, « forme » ; style, du latin stilus, le poinçon pour écrire sur la cire."},
  {name:"Métaphore",                 en:"Metaphor",                   cat:"figures_style", def:"Image qui désigne une chose par une autre, sans outil de comparaison : « cet homme est un lion », « la fleur de l'âge », « un torrent de larmes ». Filée quand elle se prolonge sur plusieurs phrases. La langue en est pleine de mortes (le pied de la table, une idée lumineuse).", ex:"« Le temps est un grand sculpteur » (Marguerite Yourcenar)", etymo:"Du grec metaphora, « transport » : en Grèce, un camion de déménagement s'appelle metaphora."},
  {name:"Comparaison",               en:"Simile",                     cat:"figures_style", def:"Rapprochement de deux réalités par un mot outil : comme, tel, pareil à, ainsi que, ressembler à. « Il est fort comme un bœuf ». Plus explicite que la métaphore, qui supprime le « comme ».", ex:"« Les parfums, les couleurs et les sons se répondent » est une métaphore ; « comme de longs échos » une comparaison (Baudelaire)", etymo:"Du latin comparatio, « action d'apparier »."},
  {name:"Métonymie",                 en:"Metonymy",                   cat:"figures_style", def:"Désignation d'une chose par une autre qui lui est liée : le contenant pour le contenu (boire un verre), l'auteur pour l'œuvre (lire un Zola), le lieu pour l'institution (l'Élysée a réagi), la cause pour l'effet, le signe pour la chose (les cols blancs). Omniprésente dans la presse.", ex:"« Paris a froid, Paris a faim » (Éluard) : la ville pour ses habitants", etymo:"Du grec metônumia, « changement de nom »."},
  {name:"Synecdoque",                en:"Synecdoche",                 cat:"figures_style", def:"Métonymie particulière : la partie pour le tout ou l'inverse. « Une voile à l'horizon » (un bateau), « les pieds nus », « la France a gagné » (l'équipe), « payer par tête », « le fer » (l'épée). Le singulier pour le pluriel en est une (« le Français est râleur »).", ex:"« Trente voiles » pour trente navires, dans les récits de bataille", etymo:"Du grec sunekdokhê, « compréhension simultanée »."},
  {name:"Hyperbole",                 en:"Hyperbole",                  cat:"figures_style", def:"Exagération volontaire pour frapper : « mourir de rire », « un géant de la littérature », « je te l'ai dit mille fois », « c'est le meilleur film de tous les temps ». Le registre naturel de la publicité, de l'épopée et de l'adolescence.", ex:"« Un océan de larmes », « une éternité d'attente »", etymo:"Du grec huperbolê, « jet au-delà, excès »."},
  {name:"Litote",                    en:"Litotes",                    cat:"figures_style", def:"Dire moins pour faire entendre plus, souvent par une négation : « ce n'est pas mauvais » (c'est excellent), « il n'est pas bête », « je ne te hais point » (je t'aime, chez Corneille). L'inverse de l'hyperbole ; la figure de la retenue et de l'ironie.", ex:"« Va, je ne te hais point » (Chimène à Rodrigue, Le Cid)", etymo:"Du grec litotês, « simplicité »."},
  {name:"Euphémisme",                en:"Euphemism",                  cat:"figures_style", def:"Atténuation d'une réalité désagréable, choquante ou triste par un mot plus doux : « il nous a quittés » (mort), « les seniors », « un plan social » (licenciements), « les non-voyants », « une frappe chirurgicale ». Politesse ou langue de bois selon l'usage.", ex:"« Il a des difficultés » pour « il échoue »", etymo:"Du grec euphêmismos, « emploi d'un mot favorable », de eu, « bien », et phêmê, « parole »."},
  {name:"Oxymore",                   en:"Oxymoron",                   cat:"figures_style", def:"Alliance de deux mots contradictoires dans un même groupe : « une obscure clarté » (Corneille), « un silence assourdissant », « le soleil noir », « un mort-vivant », « une douce violence ». Elle crée une réalité paradoxale.", ex:"« Cette obscure clarté qui tombe des étoiles » (Le Cid)", etymo:"Du grec oxumôron, de oxus, « aigu, fin », et môros, « sot » : le mot est lui-même un oxymore."},
  {name:"Antithèse",                 en:"Antithesis",                 cat:"figures_style", def:"Opposition de deux idées ou de deux mots dans une même phrase, pour les faire ressortir : « Paris outragé, Paris brisé… mais Paris libéré » ; « Je vis, je meurs ; je me brûle et me noie » (Louise Labé). Plus large que l'oxymore, qui soude les contraires dans une expression.", ex:"« Ici c'est le combat du jour et de la nuit » (Hugo, mourant)", etymo:"Du grec antithesis, « opposition »."},
  {name:"Anaphore",                  en:"Anaphora",                   cat:"figures_style", def:"Répétition d'un mot ou d'un groupe en tête de phrases ou de vers successifs, pour marteler : « Moi président de la République, je… » (Hollande, 2012, quinze fois), « Rome, l'unique objet de mon ressentiment ! Rome… » (Corneille). La figure de l'éloquence politique.", ex:"« Paris ! Paris outragé ! Paris brisé ! Paris martyrisé ! » (de Gaulle, 1944)", etymo:"Du grec anaphora, « action de reporter »."},
  {name:"Allitération",              en:"Alliteration",               cat:"figures_style", def:"Répétition d'une même consonne pour créer un effet sonore : « Pour qui sont ces serpents qui sifflent sur vos têtes ? » (Racine, le s du serpent). L'assonance est la même chose avec une voyelle (« Tout m'afflige et me nuit et conspire à me nuire », le i plaintif). Le fondement des slogans et des virelangues.", ex:"« Les chaussettes de l'archiduchesse sont-elles sèches ? »", etymo:"Du latin ad, « vers », et littera, « lettre »."},
  {name:"Ironie",                    en:"Irony",                      cat:"figures_style", def:"Dire le contraire de ce que l'on pense, en laissant entendre qu'on le pense : « Quel temps magnifique ! » sous la pluie. L'antiphrase en est la forme élémentaire ; l'ironie de Voltaire (« le meilleur des mondes possibles ») ou de Montesquieu est une arme. Repose sur la complicité du lecteur.", ex:"« Si le Roi m'avait donné Paris… » : Molière ; « C'est du propre ! »", etymo:"Du grec eirôneia, « interrogation feinte », l'attitude de Socrate."},
  {name:"Périphrase",                en:"Periphrasis",                cat:"figures_style", def:"Remplacement d'un mot par une expression qui le décrit : « la Ville lumière » (Paris), « le billet vert » (le dollar), « l'or noir » (le pétrole), « le septième art » (le cinéma), « la langue de Molière ». Elle évite la répétition, embellit ou contourne un mot tabou.", ex:"« Le roi des animaux », « l'Hexagone », « le pays du Soleil-Levant »", etymo:"Du grec periphrasis, « expression qui tourne autour »."},
  {name:"Personnification",          en:"Personification",            cat:"figures_style", def:"Attribution de traits humains à une chose, un animal ou une idée : « la nature pleure », « la mort frappe à la porte », « le vent hurle », « la Justice a tranché ». Les fables en font leur matière ; l'allégorie la prolonge en image complète (la Liberté guidant le peuple).", ex:"« L'automne, la saison qui s'excuse d'exister »", etymo:"Du latin persona, « masque de théâtre, personnage », et facere, « faire »."},
  {name:"Gradation",                 en:"Climax (gradation)",         cat:"figures_style", def:"Succession de termes d'intensité croissante (ou décroissante) : « Va, cours, vole et nous venge » (Corneille) ; « C'est un roc ! c'est un pic ! c'est un cap ! Que dis-je, c'est un cap ? c'est une péninsule ! » (Cyrano). Elle construit l'emphase pas à pas.", ex:"« Je le vis, je rougis, je pâlis à sa vue » (Racine, Phèdre)", etymo:"Du latin gradatio, « montée par degrés », de gradus, « marche »."},
  {name:"Chiasme",                   en:"Chiasmus",                   cat:"figures_style", def:"Croisement de deux expressions en miroir (A B / B A) : « Il faut manger pour vivre et non vivre pour manger » ; « Un roi chantait en bas, en haut mourait un dieu » (Hugo). Il oppose ou renverse une idée avec élégance.", ex:"« Ces murs, ces plafonds, ce plancher, tout est de bois, tout est de bois, plancher, plafonds, murs »", etymo:"Du grec khiasmos, « disposition en croix », de la lettre khi (χ)."},
  {name:"Ellipse",                   en:"Ellipsis",                   cat:"figures_style", def:"Omission de mots que le sens permet de rétablir : « Pierre aime le thé, Marie le café » (aime), « Chacun son métier », « Pas de bras, pas de chocolat ». Elle resserre et accélère. Au cinéma et dans le récit, saut dans le temps qui passe sous silence une période.", ex:"« Dix ans plus tard… » : ellipse narrative", etymo:"Du grec elleipsis, « manque »."},
  {name:"Antiphrase",                en:"Antiphrasis",                cat:"figures_style", def:"Emploi d'un mot ou d'une phrase dans le sens contraire de son sens propre, par ironie : « Bravo ! » à qui vient de casser un vase, « c'est malin », « quel génie ». Le procédé élémentaire de l'ironie, reconnu au ton et au contexte.", ex:"« Ah, tu es d'une aide précieuse ! » à qui ne fait rien", etymo:"Du grec antiphrasis, « expression contraire »."},
  {name:"Prétérition",               en:"Paralipsis (preterition)",   cat:"figures_style", def:"Dire quelque chose en affirmant qu'on ne le dira pas : « Je ne parlerai pas de ses nombreuses condamnations », « inutile de rappeler que… », « je ne vous dirai pas à quel point ». La figure de l'avocat et du polémiste, pour attaquer en gardant les mains propres.", ex:"« Je ne m'abaisserai pas à répondre à ces accusations, qui sont d'ailleurs fausses »", etymo:"Du latin praeteritio, « action de passer outre »."},
  {name:"Zeugma",                    en:"Zeugma",                     cat:"figures_style", def:"Attelage de deux compléments de nature différente au même verbe, souvent l'un concret, l'autre abstrait : « vêtu de probité candide et de lin blanc » (Hugo), « il prit son chapeau et la porte », « elle a perdu son mari et ses illusions ». Effet comique ou poétique.", ex:"« Les marchands de boisson et d'amour » (Apollinaire)", etymo:"Du grec zeugma, « joug, lien »."},

  // Rhétorique & Argumentation
  {name:"Rhétorique",                en:"Rhetoric",                   cat:"rhetorique",  def:"Art de persuader par le discours, codifié par les Grecs (Aristote) et les Romains (Cicéron, Quintilien) : trouver les arguments (invention), les ordonner (disposition), les formuler (élocution), les mémoriser, les prononcer (action). Enseignée jusqu'en 1902 dans les lycées français ; « ce n'est que de la rhétorique » en dit le discrédit.", ex:"Un plaidoyer, un discours politique, une publicité relèvent de la rhétorique", etymo:"Du grec rhêtorikê (tekhnê), « art de l'orateur », de rhêtôr, « orateur »."},
  {name:"Ethos, pathos, logos",      en:"Ethos, pathos, logos",       cat:"rhetorique",  def:"Les trois moyens de persuader selon Aristote. L'ethos : la crédibilité et le caractère que l'orateur donne à voir. Le pathos : les émotions qu'il suscite chez l'auditoire. Le logos : les arguments et les preuves. Un bon discours joue des trois.", ex:"Un médecin qui parle de santé (ethos), montre une photo (pathos), cite une étude (logos)", etymo:"Grec : êthos, « caractère » ; pathos, « ce qu'on éprouve » ; logos, « raison, discours »."},
  {name:"Thèse",                     en:"Thesis (claim)",             cat:"rhetorique",  def:"Idée que l'on défend, position soutenue par un texte argumentatif, énoncée clairement puis étayée par des arguments et des exemples. L'antithèse est la position adverse ; la synthèse les dépasse. Dans une dissertation, elle répond à la question posée.", ex:"« La lecture rend libre » : thèse à défendre en trois arguments", etymo:"Du grec thesis, « action de poser »."},
  {name:"Argument",                  en:"Argument",                   cat:"rhetorique",  def:"Raison avancée pour soutenir une thèse : d'autorité (un expert le dit), par l'exemple, par analogie, de cause à effet, par les conséquences, ad hominem (contre la personne, déloyal), a fortiori (à plus forte raison). Un argument s'appuie sur un exemple, qui l'illustre sans le remplacer.", ex:"« Le tabac tue : 75 000 morts par an en France » — argument par les chiffres", etymo:"Du latin argumentum, « preuve, sujet », de arguere, « montrer, prouver »."},
  {name:"Syllogisme",                en:"Syllogism",                  cat:"rhetorique",  def:"Raisonnement en trois propositions où la conclusion découle de deux prémisses : « Tous les hommes sont mortels ; Socrate est un homme ; donc Socrate est mortel ». Valide si la forme est bonne, vrai si les prémisses le sont : « Tout ce qui est rare est cher ; un cheval bon marché est rare ; donc il est cher » est valide et faux.", ex:"L'enthymème est un syllogisme dont une prémisse est sous-entendue : « Il est humain, donc il se trompe »", etymo:"Du grec sullogismos, « calcul, raisonnement », de sun, « avec », et logos."},
  {name:"Sophisme",                  cat:"rhetorique", ref:"connaissance"},
  {name:"Paradoxe",                  cat:"rhetorique", ref:"connaissance"},
  {name:"Concession",                en:"Concession",                 cat:"rhetorique",  def:"Mouvement qui admet un point de l'adversaire pour mieux le dépasser : « Certes, le projet coûte cher, mais il rapportera dix fois plus ». Marquée par certes, bien que, il est vrai que, sans doute… mais. Elle donne une impression d'honnêteté et désarme l'objection.", ex:"« Je reconnais que j'ai eu tort sur la date ; il n'en reste pas moins que… »", etymo:"Du latin concessio, « action d'accorder »."},
  {name:"Réfutation",                en:"Rebuttal",                   cat:"rhetorique",  def:"Démonstration qu'une thèse ou un argument adverse est faux ou faible : par les faits, par la logique (contradiction interne), par les conséquences absurdes, par un contre-exemple. Une bonne argumentation anticipe les objections et les réfute avant qu'on les fasse.", ex:"« On dit que le travail rend libre ; mais l'esclave travaille »", etymo:"Du latin refutatio, « action de repousser »."},
  {name:"Dialectique",               en:"Dialectic",                  cat:"rhetorique",  def:"Art de raisonner par le dialogue et la confrontation des thèses : chez Platon, l'ascension vers l'idée par questions et réponses ; chez Hegel, le mouvement thèse-antithèse-synthèse. Dans la dissertation française, le plan qui expose une position, son contraire, puis les dépasse.", ex:"Le plan dialectique du bac : « oui / mais / en fait »", etymo:"Du grec dialektikê (tekhnê), « art de la discussion », de dialegesthai, « converser »."},
  {name:"Éloquence",                 en:"Eloquence",                  cat:"rhetorique",  def:"Talent de bien parler et d'émouvoir, dans un discours, une plaidoirie, un débat. Elle tient à la voix, au rythme, aux images, à la présence autant qu'aux idées. Les concours d'éloquence (Conférence du barreau, Eloquentia) l'ont remise à la mode.", ex:"Le « J'accuse » de Zola, les discours de Badinter contre la peine de mort", etymo:"Du latin eloquentia, de eloqui, « parler avec facilité »."},
  {name:"Question rhétorique",       en:"Rhetorical question",        cat:"rhetorique",  def:"Question qui n'attend pas de réponse, parce qu'elle est évidente ou contenue dans la question : « Qui peut le nier ? », « N'est-ce pas ce que nous voulons tous ? », « Combien de temps allons-nous supporter cela ? ». Elle affirme sous forme interrogative et associe l'auditoire.", ex:"« Que serait la France sans ses paysans ? »", etymo:"Aussi appelée interrogation oratoire."},
  {name:"Captatio benevolentiae",    en:"Captatio benevolentiae",     cat:"rhetorique",  def:"Ouverture d'un discours destinée à gagner la bienveillance de l'auditoire : compliment, modestie affichée, anecdote, remerciement. « Je ne suis pas un orateur, mais… » ; « Vous qui connaissez ce sujet mieux que moi… ». Le premier moment de l'exorde.", ex:"Un conférencier qui commence par flatter la ville qui l'accueille", etymo:"Latin : « recherche de la bienveillance », de captare, « chercher à prendre »."},
  {name:"Discours",                  en:"Speech / discourse",         cat:"rhetorique",  def:"Prise de parole construite devant un public, avec un plan classique : exorde (ouverture), narration (les faits), confirmation (les arguments), réfutation, péroraison (conclusion qui emporte). En linguistique, tout énoncé situé dans une situation de communication.", ex:"Le discours de réception à l'Académie, la plaidoirie, le toast de mariage", etymo:"Du latin discursus, « action de courir çà et là », puis « conversation »."},

  // Textes & Genres
  {name:"Prose",                     en:"Prose",                      cat:"textes",      def:"Forme ordinaire du discours écrit ou parlé, sans vers ni rime ni mètre : celle des romans, des essais, des lettres, de la conversation. « Par ma foi ! il y a plus de quarante ans que je dis de la prose sans que j'en susse rien » (M. Jourdain). Le poème en prose la travaille sans la versifier.", ex:"Un roman, un article de journal, un discours", etymo:"Du latin prosa (oratio), « (discours) qui va droit devant », de prorsus."},
  {name:"Poésie",                    en:"Poetry",                     cat:"textes",      def:"Art du langage qui travaille le rythme, les sons, les images et la forme autant que le sens, en vers ou en prose. Lyrique (le moi et ses émotions), épique (les héros), engagée, didactique, satirique. « De la musique avant toute chose » (Verlaine).", ex:"Les Fleurs du mal, Les Contemplations, Alcools, Paroles", etymo:"Du grec poiêsis, « création, fabrication », de poiein, « faire »."},
  {name:"Vers",                      en:"Verse (line)",               cat:"textes",      def:"Ligne de poésie, définie en français par son nombre de syllabes : octosyllabe (8), décasyllabe (10), alexandrin (12). Vers libre : sans mètre fixe ni rime, depuis la fin du XIXe siècle. Le e muet compte devant une consonne, pas en fin de vers ni devant une voyelle.", ex:"« Je fais souvent ce rêve étrange et pénétrant » : douze syllabes", etymo:"Du latin versus, « sillon, ligne », de vertere, « tourner » : le laboureur qui tourne au bout du champ."},
  {name:"Alexandrin",                en:"Alexandrine",                cat:"textes",      def:"Vers de douze syllabes, le vers noble de la poésie et du théâtre classiques, coupé en deux hémistiches de six par la césure : « Je le vis, je rougis, // je pâlis à sa vue ». Le romantisme le désarticule (trimètre : 4/4/4), le vers libre l'abandonne, mais il reste l'oreille du français.", ex:"« Ô rage ! ô désespoir ! ô vieillesse ennemie ! » (Le Cid)", etymo:"Du Roman d'Alexandre (XIIe siècle), première grande œuvre en vers de douze syllabes."},
  {name:"Rime",                      en:"Rhyme",                      cat:"textes",      def:"Retour du même son en fin de vers. Pauvre (une seule voyelle : ami/parti), suffisante (deux sons : amour/toujours), riche (trois et plus : image/hommage). Disposées en rimes plates (AABB), croisées (ABAB), embrassées (ABBA). Le classicisme alterne rimes masculines et féminines (finissant par un e muet).", ex:"« Mon enfant, ma sœur, / Songe à la douceur » (Baudelaire) : rimes plates", etymo:"Du latin rhythmus, « rythme », par l'ancien français rime."},
  {name:"Sonnet",                    en:"Sonnet",                     cat:"textes",      def:"Poème à forme fixe de quatorze vers : deux quatrains et deux tercets, le plus souvent en alexandrins, avec des rimes réglées (ABBA ABBA CCD EDE ou EED). Le dernier vers, la « chute », renverse ou couronne. Venu d'Italie (Pétrarque), acclimaté par Du Bellay et Ronsard, magnifié par Baudelaire.", ex:"« Heureux qui, comme Ulysse, a fait un beau voyage » (Du Bellay)", etymo:"De l'italien sonetto, « petite chanson », de l'ancien provençal sonet, diminutif de son."},
  {name:"Strophe",                   en:"Stanza",                     cat:"textes",      def:"Groupe de vers formant une unité, séparé des autres par un blanc : distique (2 vers), tercet (3), quatrain (4), quintil (5), sizain (6), huitain, dizain. L'équivalent du paragraphe en poésie ; dans une chanson, le couplet.", ex:"Un sonnet compte quatre strophes : deux quatrains, deux tercets", etymo:"Du grec strophê, « tour, évolution du chœur » dans le théâtre antique."},
  {name:"Roman",                     en:"Novel",                      cat:"textes",      def:"Récit en prose, long et fictif, qui raconte des personnages dans une intrigue. Genre roi depuis le XIXe siècle : d'apprentissage, historique, policier, d'aventures, épistolaire, réaliste, d'anticipation, autofiction. Né des récits en langue « romane » du Moyen Âge, contre le latin.", ex:"Madame Bovary, Les Misérables, La Recherche, L'Étranger", etymo:"De l'ancien français romanz, « langue vulgaire romane », puis « récit écrit en cette langue »."},
  {name:"Nouvelle",                  en:"Short story",                cat:"textes",      def:"Récit en prose court, resserré sur un événement, peu de personnages, souvent une chute finale. Maupassant, Mérimée, Zola, Marcel Aymé. À la différence du roman, elle se lit d'une traite ; à la différence du conte, elle est vraisemblable.", ex:"Boule de suif, La Parure, Carmen, Le Passe-muraille", etymo:"De l'italien novella, « récit d'une chose nouvelle », de Boccace (Le Décaméron)."},
  {name:"Essai",                     en:"Essay",                      cat:"textes",      def:"Texte en prose où un auteur expose librement sa réflexion sur un sujet, sans prétendre l'épuiser : « Que sais-je ? ». Inventé par Montaigne (1580), entre la philosophie, la littérature et l'opinion. Pascal, Rousseau, Camus, Barthes ; aujourd'hui, tout ouvrage d'idées.", ex:"Les Essais de Montaigne, Le Mythe de Sisyphe, Mythologies", etymo:"Du latin exagium, « pesée » : Montaigne « essaie » (pèse) son jugement."},
  {name:"Fable",                     en:"Fable",                      cat:"textes",      def:"Court récit, souvent en vers, mettant en scène des animaux ou des objets qui parlent, et se terminant par une morale. Ésope (Grèce, VIe siècle av. J.-C.), Phèdre, et La Fontaine (1668-1694), qui en fit un chef-d'œuvre de satire et de poésie.", ex:"Le Corbeau et le Renard, La Cigale et la Fourmi, Le Loup et l'Agneau", etymo:"Du latin fabula, « récit, conte », de fari, « parler »."},
  {name:"Conte",                     en:"Tale",                       cat:"textes",      def:"Récit court d'événements imaginaires, hors du temps (« il était une fois »), venu de la tradition orale : merveilleux (fées, ogres, métamorphoses, Perrault, Grimm), philosophique (Voltaire, Candide), fantastique (Maupassant). Il enseigne par l'invraisemblable.", ex:"Le Petit Chaperon rouge, Candide, Les Contes du chat perché", etymo:"De conter, du latin computare, « compter », puis « raconter »."},
  {name:"Théâtre",                   en:"Theatre / drama",            cat:"textes",      def:"Texte écrit pour être joué : dialogues et didascalies (indications de mise en scène), en actes et en scènes. Tragédie (Racine, Corneille), comédie (Molière), drame (Hugo), vaudeville (Feydeau), théâtre de l'absurde (Beckett, Ionesco). Les trois unités classiques : temps, lieu, action.", ex:"Phèdre, Le Misanthrope, Hernani, En attendant Godot", etymo:"Du grec theatron, « lieu d'où l'on regarde », de theasthai, « contempler »."},
  {name:"Tragédie et comédie",       en:"Tragedy and comedy",         cat:"textes",      def:"Les deux grands genres du théâtre depuis la Grèce. La tragédie : des personnages nobles, un destin fatal, la mort, la pitié et la terreur qui purgent le spectateur (catharsis). La comédie : des bourgeois et des valets, des ridicules corrigés par le rire, un mariage à la fin. Molière les mêle dans le grand comique, Hugo dans le drame.", ex:"Phèdre finit par un suicide, Tartuffe par un mariage", etymo:"Tragédie, du grec tragôidia, « chant du bouc » (sacrifié à Dionysos) ; comédie, de kômôidia, « chant du cortège festif »."},
  {name:"Épopée",                    en:"Epic",                       cat:"textes",      def:"Long poème narratif qui célèbre les exploits d'un héros et le destin d'un peuple, avec du merveilleux : L'Iliade, L'Odyssée, L'Énéide, La Chanson de Roland, La Légende des siècles. Par extension, toute aventure grandiose.", ex:"L'épopée napoléonienne, l'épopée de l'Everest", etymo:"Du grec epopoiia, « composition d'un poème épique », de epos, « parole, récit »."},
  {name:"Autobiographie",            en:"Autobiography",              cat:"textes",      def:"Récit qu'une personne fait de sa propre vie, à la première personne, avec un pacte de sincérité (Philippe Lejeune). Fondée par Rousseau (Les Confessions), illustrée par Chateaubriand, Sartre, Sarraute. L'autofiction (Doubrovsky) y mêle la fiction ; les mémoires racontent l'époque plutôt que le moi.", ex:"Les Confessions, Mémoires d'outre-tombe, Les Mots, Enfance", etymo:"Du grec autos, « soi-même », bios, « vie », et graphein, « écrire »."},
  {name:"Narrateur",                 en:"Narrator",                   cat:"textes",      def:"Celui qui raconte, à ne pas confondre avec l'auteur : personnage de l'histoire (« je », narrateur interne) ou extérieur à elle (« il », narrateur externe). Son point de vue : interne (il sait ce que sait le personnage), externe (il ne voit que l'extérieur), omniscient (il sait tout). Il peut mentir.", ex:"Dans L'Étranger, Meursault raconte ; dans Madame Bovary, un narrateur omniscient", etymo:"Du latin narrator, de narrare, « raconter »."},
  {name:"Incipit",                   en:"Incipit (opening line)",     cat:"textes",      def:"Premiers mots ou première page d'un texte, qui fixent le ton, le cadre, le pacte de lecture. Certains sont célèbres à eux seuls : « Longtemps, je me suis couché de bonne heure », « Aujourd'hui, maman est morte », « Je forme une entreprise qui n'eut jamais d'exemple ». L'explicit est la fin.", ex:"« Nous étions à l'étude, quand le Proviseur entra » (Madame Bovary)", etymo:"Latin : « il commence », premier mot des manuscrits médiévaux."},
  {name:"Registre littéraire",       en:"Literary register (tone)",   cat:"textes",      def:"Tonalité d'un texte et l'émotion qu'il cherche : comique (rire), tragique (fatalité), pathétique (pitié), lyrique (sentiments), épique (grandeur), fantastique (hésitation entre réel et surnaturel), satirique (moquerie critique), polémique (attaque), didactique (enseignement). À ne pas confondre avec le registre de langue.", ex:"Un même sujet, la mort, peut être traité au registre tragique, comique ou lyrique", etymo:"Registre, du latin médiéval registrum ; ici au sens de « ton, gamme »."},

  // Phonétique & Oral
  {name:"Phonème",                   en:"Phoneme",                    cat:"oral",        def:"Plus petite unité de son qui distingue des mots : « pain » et « bain » ne diffèrent que par /p/ et /b/. Le français en compte 36 environ (16 voyelles, 17 consonnes, 3 semi-voyelles) pour 26 lettres : d'où les combinaisons (ch, ou, an) et les ambiguïtés de l'orthographe.", ex:"Le son [o] s'écrit o, au, eau, ô, ot, aux…", etymo:"Du grec phônêma, « son de voix »."},
  {name:"Syllabe",                   en:"Syllable",                   cat:"oral",        def:"Unité de prononciation formée autour d'une voyelle, avec ou sans consonnes : « ma-ga-sin » (3), « strict » (1). Le français découpe en syllabes ouvertes (finissant par une voyelle) autant que possible : « a-mi », « pa-ris ». Le compte des syllabes fait le vers.", ex:"« Ordinateur » : or-di-na-teur, quatre syllabes", etymo:"Du grec sullabê, « ce qui est pris ensemble »."},
  {name:"E muet",                    en:"Silent e (schwa)",           cat:"oral",        def:"Le e sans accent qui ne se prononce pas, ou à peine, en fin de mot ou entre consonnes : « table », « petit » (p'tit), « samedi » (sam'di). Il compte en poésie devant une consonne (« Je fai-s(e) souvent… »), s'élide devant une voyelle, et distingue le sud (« un-e pomm-e ») du nord de la France.", ex:"« Je ne le sais pas » se prononce « j'le sais pas »", etymo:"Aussi appelé e caduc ou schwa (de l'hébreu shva, signe de voyelle brève)."},
  {name:"H aspiré et h muet",        en:"Aspirated and silent h",     cat:"oral",        def:"Le h ne se prononce jamais en français, mais il y en a deux. Muet (d'origine latine) : il permet élision et liaison, « l'homme, les‿hommes, l'hôtel ». Aspiré (souvent germanique) : il les interdit, « le héros, les | haricots, la hache, le hibou ». Le dictionnaire le signale par un astérisque.", ex:"« Les zaricots » est la faute la plus connue du français", etymo:"Aspiré car, en ancien français, il était encore soufflé, comme en allemand."},
  {name:"Accent tonique",            en:"Stress",                     cat:"oral",        def:"Syllabe prononcée plus fort ou plus long dans un mot. En français, toujours sur la dernière syllabe prononcée du mot ou du groupe (« un caFÉ », « un café CHAUD ») : d'où l'impression de langue « plate » pour les étrangers, et la difficulté des Français à placer l'accent en anglais ou en espagnol.", ex:"« Photo », « photographe », « photographie » : l'accent se déplace toujours à la fin", etymo:"Tonique, du grec tonos, « tension, ton »."},
  {name:"Intonation",                en:"Intonation",                 cat:"oral",        def:"Mélodie de la phrase : montante pour la question (« Tu viens ? »), descendante pour l'affirmation, suspendue pour l'inachèvement. Elle porte le sens que la syntaxe ne dit pas : la même phrase peut être une question, une menace ou une plaisanterie.", ex:"« C'est bon. » / « C'est bon ? » / « C'est bon ! »", etymo:"Du latin intonare, « faire retentir »."},
  {name:"Voyelles nasales",          en:"Nasal vowels",               cat:"oral",        def:"Voyelles prononcées avec l'air qui passe aussi par le nez : [ɑ̃] (an, en), [ɔ̃] (on), [ɛ̃] (in, ain, ein), et [œ̃] (un), en voie de disparition au profit de [ɛ̃] (brin/brun). Une particularité du français, redoutée des apprenants : « un bon vin blanc » contient les quatre.", ex:"« Sans », « son », « sain », « sein » ; « un bon vin blanc »", etymo:"Nasal, du latin nasus, « nez »."},
  {name:"Prosodie",                  en:"Prosody",                    cat:"oral",        def:"Ensemble des traits sonores qui dépassent le mot : accent, rythme, intonation, pauses, débit, hauteur. C'est elle qui rend une lecture vivante ou monotone, qui distingue l'ironie du sérieux, et qui marque l'accent régional.", ex:"Un texte lu par une voix de synthèse manque de prosodie", etymo:"Du grec prosôidia, « chant accompagnant », d'où « accent »."},
  {name:"Diction",                   en:"Diction / elocution",        cat:"oral",        def:"Manière d'articuler et de prononcer en parlant ou en lisant : netteté, respiration, rythme, liaisons, e muets. L'art du comédien et de l'orateur ; les exercices de virelangues (« un chasseur sachant chasser ») l'entraînent. Une diction soignée fait paraître le propos plus sûr.", ex:"« Les chemises de l'archiduchesse… » comme échauffement", etymo:"Du latin dictio, « action de dire »."},
  {name:"Accent régional",           en:"Regional accent",            cat:"oral",        def:"Prononciation propre à une région : le « e » prononcé du Midi (« un-e pomm-e »), les voyelles longues du Nord, le r roulé de Bourgogne, l'intonation chantante de Marseille, celle du Québec. Le français « standard » est l'accent de Paris et des médias ; les autres subissent une discrimination (la glottophobie) que la loi interdit depuis 2020.", ex:"« Pain » et « pin » se prononcent pareil à Paris, différemment à Toulouse", etymo:"Accent, du latin accentus, « chant ajouté »."},
  {name:"Phonologie",                cat:"oral", ref:"shs"},

  // Bon usage & Écriture
  {name:"Norme et usage",            en:"Prescription and usage",     cat:"usage",       def:"Tension permanente de la langue : la norme (grammaires, Académie, école) dit ce qu'il faut dire ; l'usage, ce que les gens disent. À terme, l'usage gagne toujours (« je vais au coiffeur » entrera un jour au dictionnaire, comme « aujourd'hui », pléonasme devenu norme). Le bon usage, selon Grevisse, est celui des « gens cultivés d'aujourd'hui ».", ex:"« Malgré que » est condamné par la norme et courant dans l'usage", etymo:"Norme, du latin norma, « équerre, règle » ; usage, de us, « coutume »."},
  {name:"Le Bon Usage",              en:"Le Bon Usage (Grevisse)",    cat:"usage",       def:"La grammaire de référence du français, publiée par le Belge Maurice Grevisse en 1936, tenue à jour par André Goosse (17e édition, 2 000 pages) : elle décrit l'usage réel, avec des milliers d'exemples d'écrivains, plutôt que d'édicter. Avec le Bescherelle pour la conjugaison, la bible du correcteur.", ex:"« Voir le Grevisse » clôt les débats de rédaction", etymo:"Titre emprunté à Vaugelas, Remarques sur la langue française (1647), qui fondait la norme sur le « bon usage » de la cour."},
  {name:"Langage clair",             en:"Plain language",             cat:"usage",       def:"Manière d'écrire pour être compris du premier coup par le lecteur visé : phrases courtes, mots courants, structure visible, verbes plutôt que noms, exemples, pas de jargon ni de passif inutile. Né dans l'administration anglo-saxonne, imposé aux services publics français depuis 2019 (« dites-le nous une fois »).", ex:"« Vous devez envoyer le formulaire avant le 30 juin » plutôt que « Le formulaire devra être transmis dans les délais impartis »", etymo:"Calque de l'anglais plain language."},
  {name:"Lisibilité",                en:"Readability",                cat:"usage",       def:"Facilité avec laquelle un texte se lit et se comprend, mesurable par des formules (longueur des phrases et des mots : indice de Flesch) et améliorable par la typographie, la mise en page et le style. Une phrase de plus de 25 mots perd la moitié des lecteurs.", ex:"Un contrat, une notice ou un site public devraient viser la lisibilité d'un journal", etymo:"De lisible, du latin legibilis, de legere, « lire »."},
  {name:"Écriture inclusive",        en:"Inclusive writing",          cat:"usage",       def:"Ensemble de pratiques visant à rendre les femmes visibles dans la langue : féminisation des noms de métiers (autrice, cheffe), doublets (les étudiants et les étudiantes), mots épicènes (le personnel, les élèves), accord de proximité, et le point médian (les étudiant·es), le plus contesté. Interdit dans les textes officiels et à l'école (2017, 2021).", ex:"« Chères toutes et tous » ; « la directrice », « une ingénieure »", etymo:"Inclusif, du latin includere, « enfermer, comprendre »."},
  {name:"Féminisation des noms",     en:"Feminization of job titles", cat:"usage",       def:"Emploi de formes féminines pour les métiers, titres et fonctions : une ministre, une avocate, une écrivaine, une autrice, une pompière, une cheffe. Longtemps refusée par l'Académie, admise par elle en 2019 ; courante au Québec et en Suisse depuis les années 1980. L'usage hésite encore sur certaines (« professeure », « docteure »).", ex:"« Madame la Ministre » et non plus « Madame le Ministre »", etymo:"Féminin, du latin femininus, de femina, « femme »."},
  {name:"Style",                     en:"Style",                      cat:"usage",       def:"Manière propre d'écrire, reconnaissable : choix des mots, rythme des phrases, images, ton. « Le style est l'homme même » (Buffon). Il s'apprend par la lecture et la réécriture ; le style clair et simple est le plus difficile.", ex:"La phrase longue de Proust, la phrase courte de Camus, l'oralité de Céline", etymo:"Du latin stilus, poinçon pour écrire sur les tablettes de cire, puis « manière d'écrire »."},
  {name:"Concision",                 en:"Concision",                  cat:"usage",       def:"Qualité d'un texte qui dit tout en peu de mots : supprimer les redondances, les adverbes inutiles, les périphrases (« procéder à l'analyse » = analyser), les formules creuses (« il est à noter que »). « Je n'ai fait celle-ci plus longue que parce que je n'ai pas eu le loisir de la faire plus courte » (Pascal).", ex:"« Au niveau de la qualité, on constate une amélioration » → « La qualité s'améliore »", etymo:"Du latin concisio, « action de couper »."},
  {name:"Nominalisation",            en:"Nominalization",             cat:"usage",       def:"Transformation d'un verbe en nom : « il a décidé » → « sa décision » ; « nous analysons » → « l'analyse ». Utile pour condenser un titre, elle alourdit le texte quand elle se multiplie et cache qui fait quoi : le style administratif en abuse (« la mise en œuvre de la procédure de validation »).", ex:"« Procéder au nettoyage » → « nettoyer »", etymo:"De nominal, du latin nominalis, de nomen, « nom »."},
  {name:"Relecture",                 en:"Proofreading",               cat:"usage",       def:"Lecture attentive d'un texte terminé pour y traquer fautes, coquilles, lourdeurs, incohérences. À faire à froid, à voix haute ou sur papier, en plusieurs passes (sens, puis orthographe, puis typographie). Un correcteur automatique aide mais ne remplace pas : il ne voit ni le sens ni les homophones en contexte.", ex:"Lire à l'envers, phrase par phrase, pour ne pas se laisser porter par le sens", etymo:"De relire, du latin relegere."},
  {name:"Coquille",                  en:"Typo",                       cat:"usage",       def:"Faute de frappe ou d'impression : lettre manquante, inversée, en trop. Distincte de la faute d'orthographe, qui vient de l'ignorance. Le mot vient des typographes, chez qui une lettre glissée dans la mauvaise case de la casse produisait l'erreur. La plus redoutée est celle qui fait un mot existant.", ex:"« Le ministre a été très aplaudi » ; ou la fameuse lettre en moins dans « coquille »", etymo:"Selon la légende, de la casse (le meuble des caractères) et de ses cases, ou d'une erreur célèbre dans un menu où « coquilles » perdit son q."},
  {name:"Dictée",                    en:"Dictation",                  cat:"usage",       def:"Exercice scolaire où l'on écrit un texte lu à voix haute, pour vérifier l'orthographe. Institution française depuis le XIXe siècle (la dictée de Mérimée, chez Napoléon III, fit faire 75 fautes à l'empereur et 3 à l'ambassadeur d'Autriche), sport avec Bernard Pivot, retour obligatoire quotidien à l'école depuis 2015.", ex:"« Les gens de la ville et ceux de la campagne… » : la dictée de Mérimée commence ainsi", etymo:"Du latin dictare, « dire en répétant, dicter »."},
  {name:"Typographie",               cat:"usage", ref:"design"},
  {name:"Écriture",                  cat:"usage", ref:"connaissance"},
];
